insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (92,'قوانين','قانون العقوبات - مرسوم اشتراعي رقم 340 1 آذار 1943','1943-03-01','https://www.ppa.gov.lb/ar/pages/details/92','{"https://admin.ppa.gov.lb/storage/listing-pages/files/7YS88vVqmedn97mKLJmCTKEeV2HKzM3fW0ji-1760211107.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/7YS88vVqmedn97mKLJmCTKEeV2HKzM3fW0ji-1760211107.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=92),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "قانون العقوبات\n مرسوم اشتراعي رقم - ٣٤٠صادر في ١٩٤٣/٣/١\n إن رئيس الجمھورية اللبنانية،\n بناء على تصريح ٢٦تشرين الثاني سنة ،١٩٤١\n وبناء على اقتراح وزير العدلية،\n وبناء على قرار مجلس الوزراء تاريخ ٢٧شباط سنة ،١٩٤٣\n يرسم ما يأتي:\n الكتاب الأول -الأحكام العامة\n الباب الأول -في الشريعة الجزائية\nالفصل الأول -في تطبيق الشريعة الجزائية من حيث الزمان\n النبذة - ١في شريعة الجرائم\n\fالمادة -١ال تفرض عقوبة وال تدبير احترازي أو إصالحي من أجل جرم لم يكن القانون قد نص\n عليه حين اقترافه.\n ال تؤخذ على المدعى عليه األفعال التي تؤلف الجرم وأعمال االشتراك األصلي أو الفرعي التي\n أتاھا قبل أن ينص القانون على ھذا الجرم.\n المادة -٢ال يقمع جرم بعقوبة أو تدبير احترازي أو إصالحي إذا ألغاه قانون جديد .وال يبقى\n لألحكام الجزائية التي قضي بھا أي مفعول.\n على أن كل جرم اقترف خرقا ً للقانون موقت في خالل مدة تطبيقه ال تقف مالحقته وقمعه بعد\n انقضاء المدة المذكورة.\n المادة -٣معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥\nكل قانون يعدل شروط التجريم تعديالً ينفع المدعى عليه يطبق على األفعال المقترفة قبل نفاذه ما لم\n يكن قد صدر بشأنھا حكم مبرم.\n المادة -٤كل قانون يعدل حق المالحقة يطبق على الجرائم السابقة له إذا كان أكثر مراعاة\n للمدعى عليه.\n إذا عين القانون الجديد مھلة لممارسة حق المالحقة فال تجري ھذه المھلة إال من يوم نفاذ القانون.\n وإذا عدل القانون مھلة موضوعه من قبل فھي تجري وفاقا ً للقانون القديم على أن ال يتجاوز مداھا\n مھلة القانون الجديد محسوبة من يوم نفاذه.\nالمادة -٥إذ عدل قانون مدة مرور الزمن على جرم جرت ھذه المدة وفاقا ً للقانون القديم على أن\n ال يتجاوز مداھا المدة التي عينھا القانون الجديد محسوبة من يوم نفاذه.\n النبذة - ٢في شرعية العقوبات\n\f المادة -٦ال يقضي بأي عقوبة لم ينص القانون عليھا حين اقتراف الجرم."}, {"o": 1, "l": null, "b": "يعد الجرم مقترفا ً حالما تتم أفعال تنفيذه ،دون ما نظر إلى وقت حصول النتيجة.\nالمادة -٧كل قانون جديد ،ولو أشد ،يطبق على الجرائم المتمادية والمستمرة والمتعاقبة أو جرائم\n العادة التي ثوبر على تنفيذھا تحت سلطانه.\n المادة -٨معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥\n كل قانون جديد يلغي عقوبة أو يقضي بعقوبة أخف يطبق على الجرائم المقترفة قبل نفاذه ما لم يكن\n صدر بشأنھا حكم مبرم.\nالمادة -٩كل قانون جديد يقضي بعقوبات أشد ال يطبق على الجرائم المقترفة قبل نفاذه .على أنه\nإذا عدل القانون الجديد قواعد اجتماع الجرائم والتكرار ،تؤخذ بعين االعتبار ،عند قمع فعل تم تحت\n سلطانه ،الجرائم التي اقترفت والعقوبات التي قضي بھا قبل نفاذه.\n المادة -١٠كل قانون جديد يعدل طريقة تنفيذ إحدى العقوبات بأن يغير ماھيتھا ال يطبق على\n األفعال المقترفة قبل نفاذه ما لم يكن أكثر مراعاة للمدعى عليه أو المحكوم عليه.\nتتغير ماھية العقوبة عندما يعدل القانون الجديد القواعد الشرعية التي خصت بھا في فصل العقوبات\n من ھذا القانون.\n المادة -١١معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n كل قانون جديد يعدل مدة مرور الزمن على عقوبة يطبق وفاقا ً للشروط المعينة في المادة الخامسة.\n النبذة - ٣في شرعية التدابير الاحترازية والتدابير الإصلاحية\n المادة -١٢ال يقضي بأي تدبير احترازي أو أي تدبير إصالحي إال في الشروط واألحوال التي\n نص عليھا القانون.\n\fالمادة -١٣كل قانون جديد يضع تدابيراً احترازيا ً أو تدابيراً إصالحيا ً يطبق على الجرائم التي لم\n تفصل بھا آخر ھيئة قضائية ذات صالحية من حيث الوقائع.\n أما العقوبات التي فرضت قبل نفاذ القانون الجديد فتحسب عند قمع الفعل المقترف تحت سلطانه في\n تطبيق األحكام المتعلقة باعتياد اإلجرام.\nالمادة -١٤كل تدبير احترازي وكل تدبير إصالحي ألغاه القانون أو أبدل منه تدبيراً آخر ال يبقى\n له أي مفعول."}, {"o": 2, "l": null, "b": "فإذا كان قد صدر حكم مبرم أعيدت المحاكمة لتطبيق التدبير االحترازي أو اإلصالحي الجديد.\n الفصل الثاني -في تطبيق الشريعة الجزائية من حيث المكان\n النبذة -١في الصلاحية الإقليمية\nالمادة -١٥تطبق الشريعة اللبنانية على جميع الجرائم المقترفة في األرض اللبنانية .تعد الجريمة\n مقترفة في األرض اللبنانية.\n -١إذا تم على ھذه األرض أحد العناصر التي تؤلف الجريمة ،أو فعل من أفعال جريمة غير\n متجزئة أو فعل اشتراك أصلي أو فرعي.\n ً\n -٢إذا حصلت النتيجة في ھذه األرض أو كان متوقعا حصولھا فيھا.\n المادة -١٦تشمل األرض اللبنانية طبقة الھواء التي تغطيھا ،أي اإلقليم الجوي.\n المادة -١٧معدلة وفقا للقانون ٥١٣تاريخ ١٩٩٦/٦/٦\n يكون في حكم األرض اللبنانية ،ألجل تطبيق الشريعة الجزائية:\n\f -١البحر اإلقليمي إلى مسافة عشرين كيلو متراً من الشاطئ ابتداء من أدنى مستوى الجزر.\n -٢المدى الجوي الذي يغطي البحر اإلقليمي.\n -٣السفن والمركبات الھوائية اللبنانية.\n -٤األرض األجنبية التي يحتلھا جيش لبناني ،إذا كانت الجرائم المقترفة تنال من سالمة الجيش أو\n من مصالحه.\n -٥المنطقة المتاخمة والمنطقة االقتصادية المانعة والجرف القاري التابعة للبنان والمنصات الثابتة\n في ھذا الجرف القاري ،تطبيقا ً ألحكام اتفاقية األمم المتحدة لقانون البحار الموقعة بتاريخ\n ١٩٨٢/١٢/١٠في مونتيغوباي )الجاماييك( .الذي أجيز للحكومة االنضمام إليھا بموجب القانون\n رقم ٢٩تاريخ .١٩٩٤/٢/٢٢\n المادة -١٨معدلة وفقا لقانون ١٦٨تاريخ ١٩٤٦/١/١٢والمرسوم االشتراعي ١١٢\n تاريخ١٩٨٣/٩/١٦\n ال تطبق الشريعة اللبنانية:\n -١في اإلقليم الجوي اللبناني ،على الجرائم المقترفة على متن مركبة ھوائية أجنبية إذا لم تتجاوز\n الجريمة شفير المركبة.\n على أن الجرائم التي ال تجاوز شفير المركبة الھوائية تخضع للشريعة اللبنانية إذا كان الفاعل أو"}, {"o": 3, "l": null, "b": "المجنى عليه لبنانياً ،أو إذا حطت المركبة الھوائية في لبنان بعد اقتراف الجريمة.\n -٢في البحر اإلقليمي اللبناني أو في المدى الجوي الذي يغطيه ،على الجرائم المقترفة على متن\n سفينة أو مركبة ھوائية أجنبية إذا لم تجاوز الجريمة شفير السفينة أو المركبة الھوائية.\n -٣ملغاة.\n -و تخضع للشريعة اللبنانية جرائم االستيالء على السفن األجنبية أو على البضائع المنقولة عليھا،\n إذا دخلت ھذه السفن المياه اإلقليمية اللبنانية.\n -كل جرم يرتكب في او على السفينة و ھي في ھذه الحالة يخضع للشريعة اللبنانية مع مراعاة\n االتفاقيات الدولية الموافق عليھا من قبل السلطات اللبنانية.\n -و تخضع كذلك للشريعة اللبنانية جريمة االستيالء على البضائع من السفن ،الحاصلة خارج المياه\n اإلقليمية إذا تم إدخال ھذه البضائع إلى األرض اللبنانية لالستھالك المحلي أو على سبيل\n \"الترانزيت\".\n النبذة - ٢في الصلاحية الذاتية\n\f المادة -١٩معدلة وفقا للمرسوم االشتراعي رقم ١١٢تاريخ ١٩٨٣/٩/١٦القانون ٥١٣تاريخ\n ١٩٩٦/٦/٦\n ً ً ً\n تطبق القوانين اللبنانية على كل لبناني أو أجنبي أو عديم الجنسية ،فاعال أو شريكا أو محرضا أو\n متدخالً ،أقدم خارج األراضي اللبنانية أو على متن طائرة أو سفينة أجنبية:\n -١على ارتكاب جرائم مخلة بأمن الدولة أو تقليد خاتم الدولة أو تقليد أو تزوير أوراق العملة أو\nالسندات المصرفية اللبنانية أو األجنبية المتداولة شرعا ً أو عرفا ً في لبنان ،أو تزوير جوازات السفر\n وسمات الدخول وتذاكر الھوية ووثائق إخراج القيد اللبنانية .على أن ھذه األحكام ال تطبق على\n األجنبي الذي ال يكون عمله مخالفا ً لقواعد القانون الدولي.\n -٢على ارتكاب إحدى الجنايات ضد سالمة المالحة الجوية أو البحرية والمنصوص عليھا في\n المواد ٦٤١و ٦٤٢و ٦٤٣المعدلة من قانون العقوبات.\n -٣على ارتكاب إحدى الجرائم ضد سالمة المنصات الثابتة في الجرف القاري التابع إلحدى الدول"}, {"o": 4, "l": null, "b": "المتعاقدة في بروتوكول روما المعقود بتاريخ .١٩٨٨/٣/١٠\n -٤على ارتكاب جرائم بھدف إلزام لبنان القيام بأي عمل كان أو االمتناع عنه ،إذا حصل خالل\n ارتكابھا تھديد أو احتجاز أو جرح أو قتل لبناني.\n النبذة - ٣في الصلاحية الشخصية\nالمادة -٢٠تطبق الشريعة اللبنانية على كل لبناني ،فاعالً كان أو محرضا ً أو متدخالً ،أقدم خارج\n األراضي اللبنانية ،على ارتكاب جنحة أو جناية تعاقب عليھا الشريعة اللبنانية.\n ويبقى األمر كذلك ولو فقد المدعى عليه أو اكتسب الجنسية اللبنانية بعد ارتكاب الجناية أو الجنحة.\n المادة -٢١تطبق الشريعة اللبنانية خارج األرض اللبنانية.\n -١على الجرائم التي يقترفھا الموظفون اللبنانيون في أثناء ممارستھم وظائفھم أو في معرض\n ممارستھم لھا.\n -٢على الجرائم التي يقترفھا موظفو السلك الخارجي والقناصل اللبنانيون ما تمتعوا بالحصانة التي\n يخولھم إياھا القانون الدولي العام.\n\f المادة -٢٢ال تطبق الشريعة اللبنانية في األرض اللبنانية على الجرائم التي يقترفھا موظفو\n السلك الخارجي والقناصل األجانب ما تمتعوا بالحصانة التي يخلوھم إياھا القانون الدولي العام.\n النبذة - ٤في الصلاحية الشاملة\n المادة -٢٣معدلة وفقا للقانون ٥١٣تاريخ ١٩٩٦/٦/٦\n تطبق القوانين اللبنانية أيضا ً على كل أجنبي أو عديم الجنسية مقيم أو وجد في لبنان ،أقدم في\n الخارج فاعالً أو شريكا ً أو محرضا ً أو متدخالً ،على ارتكاب جناية أو جنحة غير منصوص عليھا\n في المواد ) ١٩البند (١و ٢٠و ،٢١إذا لم يكن استرداده قد طلب أو قبل.\nوكذلك إذا ارتكبت الجناية أو الجنحة من أي كان ضد أو على متن طائرة أجنبية مؤجرة بدون طاقم،\n إلى مستأجر له مركز عمل رئيسي أو محل إقامة دائم في لبنان ،إذا لم يكن استرداد الفاعل قد طلب\n أو قبل.\n النبذة - ٥في مدى الشريعة الأجنبية\n المادة -٢٤ال تطبق الشريعة اللبنانية على الجنح المشار إليھا في"}, {"o": 5, "l": "المادة ٢٠", "b": "المادة ٢٠والمعاقب عليھا\n بعقوبة حبس ال تبلغ الثالث سنوات ،وال على أي جريمة أشارت إليھا"}, {"o": 6, "l": "المادة ٢٣", "b": "المادة ٢٣إذا كانت شريعة\n الدولة التي اقترفت في أرضھا ھذه الجرائم ال تعاقب عليھا.\n المادة -٢٥إذا اختلفت الشريعة اللبنانية وشريعة مكان الجرم فللقاضي ،عند تطبيقه الشريعة\n اللبنانية وفاقا ً للمادتين ٢٠و ،٢٣أن يراعي ھذا االختالف لمصلحة المدعى عليه.\nإن تدابير االحتراز أو اإلصالح وفقدان األھلية واإلسقاط من الحقوق المنصوص عليھا في الشريعة\n اللبنانية تطبق دون ما نظر إلى شريعة مكان الجرم.\n\f المادة -٢٦فيما خص الجرائم المقترفة في لبنان أو في الخارج تراعى شريعة المدعى عليه\n الشخصية ألجل تجريمه.\n ً\n -١عندما يكون أحد العناصر المؤلفة للجرم خاضعا لشريعة خاصة باألحوال الشخصية أو باألھلية.\n -٢عندما يكون أحد أسباب التشديد أو األعذار الشرعية ماعدا القصر الجزائي ناشئا ً عن شريعة\n خاصة باألحوال الشخصية أو باألھلية.\n النبذة - ٦في مفعول الأحكام الأجنبية\n المادة -٢٧معدلة وفقا للقانون ٤٨٧تاريخ ١٩٩٥/١٢/٨\nفيما خال الجنايات المنصوص عليھا في"}, {"o": 7, "l": "المادة ١٩", "b": "المادة ١٩والجرائم المقترفة في األراضي اللبنانية ،ال تساق\n في لبنان مالحقة على لبناني أو أجنبي في إحدى الحاالت اآلتية:\n -١إذا كان قد لوحق بجريمة إفالس احتيالي أو إفالس تقصيري أو بجريمة ذات صلة بھاتين\nالجريمتين أو بإحداھما بسبب إفالس أو توقف شركة أو مؤسسة تجارية عن الدفع ،وكان مركز ھذه\n الشركة أو المؤسسة موجوداً خارج األراضي اللبنانية ،وكانت المالحقة قد جرت في البلد الذي يقع\n فيه ھذا المركز.\n -٢في جميع الجرائم األخرى ،إذا كان قد حكم نھائيا ً في الخارج وفي حالة الحكم عليه ،إذا كان\n الحكم قد نفذ فيه أو سقط عنه بمرور الزمن ،أو بالعفو.\n المادة -٢٨ال تحول األحكام الصادرة في الخارج دون مالحقة أي جريمة في لبنان نصت عليھا"}, {"o": 8, "l": "المادة ١٩", "b": "المادة ١٩أو اقترفت في األرض اللبنانية ،إال أن يكون حكم القضاء األجنبي قد صدر على أثر\n أخبار رسمي من السلطات اللبنانية.\n على أن العقوبة والتوقيف االحتياطي اللذين نفذا في الخارج يحسمان بالمقدار الذي يحدده القاضي\n من أصل العقوبة التي يقضي بھا.\n المادة -٢٩معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n\f إن األحكام الجزائية الصادرة عن قضاء أجنبي بشأن أفعال تصفھا الشريعة اللبنانية بالجنايات أو\n الجنح يمكن االستناد إليھا:\n -١ألجل تنفيذ ما ينجم عنھا من تدابير االحتراز وفقدان األھلية واإلسقاط من الحقوق ،ما دامت\n متفقة والشريعة اللبنانية وتنفيذ الردود والتعويضات والنتائج المدنية األخرى.\n -٢ألجل الحكم بما نصت عليه الشريعة اللبنانية من تدابير احترازية وفقدان أھلية وإسقاط حقوق،\n بردود وتعويضات ونتائج مدنية أخرى.\n -٣ألجل تطبيق األحكام الشريعة اللبنانية بشأن التكرار .واعتياد اإلجرام واجتماع الجرائم،\n ووقف التنفيذ وإعادة االعتبار.\n للقاضي اللبناني أن يتثبت من كون الحكم األجنبي منطبقا ً على القانون من حيث الشكل واألساس،\n وذلك برجوعه إلى وثائق القضية.\n النبذة - ٧تبيح في الاسترداد\nالمادة -٣٠ال يسلم أحد إلى دولة أجنبية ،فيما خال الحاالت التي نصت عليھا أحكام ھذا القانون،\n إال أن يكون ذلك تطبيقا ً لمعاھدة لھا قوة القانون.\n المادة -٣١تبيح االسترداد:\n -١الجرائم المقترفة في أرض الدولة طالبة االسترداد.\n -٢الجرائم التي تنال من أمنھا أو من مكانتھا المالية.\n -٣الجرائم التي يقترفھا أحد رعاياھا.\n المادة -٣٢ال تبيح االسترداد الجرائم الداخلة في نطاق صالحية الشريعة اللبنانية اإلقليمية\n والذاتية والشخصية كما حددتھا المواد ١٥إلى ،١٧ونھاية الفقرة األولى من"}, {"o": 9, "l": "المادة ١٨", "b": "المادة ١٨والمواد\n ١٩إلى .٢١\n المادة -٣٣معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n\f يرفض االسترداد:\n -١إذا كانت الشريعة اللبنانية ال تعاقب على الجريمة بعقوبة جنائية أو جناحية ويكون األمر على\n النقيض إذا كانت ظروف الفعل المؤلفة للجرم ال يمكن توفرھا في لبنان لسبب وضعه الجغرافي.\n -٢إذا كانت العقوبة المنصوص عليھا في شريعة الدولة طالبة االسترداد أو شريعة الدولة التي\n ارتكبت األفعال في أرضھا ال تبلغ سنة حبس عن مجمل الجرائم التي تناولھا الطلب.\n وفي حالة الحكم إذا كانت العقوبة المفروضة تنقص عن شھري حبس.\n -٣إذا كان قد قضي في الجريمة قضاء مبرما ً في لبنان ،أو كانت دعوى الحق العام أو العقوبة قد\n سقطتا وفاقا ً للشريعة اللبنانية أو شريعة الدولة طالبة االسترداد أو شريعة الدولة التي اقترفت\n الجريمة في أرضھا.\n المادة -٣٤كذلك يرفض االسترداد:\n -١إذا نشأ طلب االسترداد عن جريمة ذات طابع سياسي ،أو ظھر انه لغرض سياسي.\n -٢إذا كان المدعى عليه قد استرق في أرض الدولة طالبة االسترداد.\n -٣إذا كانت العقوبة المنصوص عليھا في شريعة الدولة طالبة االسترداد مخالفة لنظام المجتمع.\n المادة -٣٥معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n -يحال طلب االسترداد على النائب العام التمييزي الذي يتولى التحقيق حول توفر أو عدم توفر\nالشروط القانونية وفي مدى ثبوت التھمة ،ويمكنه أن يصدر مذكرة توقيف بحق الشخص المطلوب\n استرداده بعد استجوابه ثم يحيل الملف إلى وزير العدل مشفوعا ً بتقريره.\n -يبت بطلب االسترداد بمرسوم يتخذ بناء على اقتراح وزير العدل.\n المادة -٣٦معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\nالمدعى عليه الذي يتم استرداده ال يمكن مالحقته وجاھيا ً وال إنفاذ عقوبة فيه وال تسليمه إلى دولة\nثالثة من أجل أي جريمة سابقة لالسترداد غير الجريمة التي كانت سببا ً له ،إال أن توافق على ذلك"}, {"o": 10, "l": "المادة ١٨", "b": "حكومة الدولة المطلوبة منھا االسترداد ضمن الشروط الواردة في المادة السابقة.\n والموافقة في ھذه الحالة ليست مقيدة بأحكام الفقرة الثانية من المادة .٣٣\n الباب الثاني -في الأحكام الجزائية\n\fالفصل الأول -في العقوبات\nالنبذة -١في العقوبات العامة\n المادة -٣٧إن العقوبات الجنائية العادية ھي:\n -١اإلعدام.\n -٢األشغال الشاقة المؤبدة.\n -٣االعتقال المؤبد.\n -٤األشغال الشاقة المؤقتة.\n -٥االعتقال المؤقت.\n المادة -٣٨إن العقوبات الجنائية السياسية ھي:\n -١االعتقال المؤبد.\n -٢االعتقال المؤقت.\n -٣اإلبعاد.\n -٤اإلقامة الجبرية.\n -٥التجريد المدني.\n المادة -٣٩إن العقوبات الجناحية العادية ھي:\n -١الحبس مع التشغيل.\n -٢الحبس البسيط.\n -٣الغرامة.\n المادة -٤٠إن العقوبات الجناحية السياسية ھي:\n\f -١الحبس البسيط.\n -٢اإلقامة الجبرية.\n -٣الغرامة.\n المادة -٤١معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥\n إن عقوبتي المخالفات ھما:\n -١الحبس التكديري.\n -٢الغرامة.\n المادة -٤٢إن العقوبات الفرعية أو اإلضافية ھي:\n -١التجريد المدني.\n -٢الحبس المالزم للتجريد المدني المقضي به كعقوبة أصلية.\n -٣الغرامة الجنائية.\n -٤المنع من الحقوق المدنية.\n -٥نشر الحكم.\n -٦إلصاق الحكم.\n -٧المصادرة الشخصية.\n النبذة -٢في العقوبات الجنائية\n المادة -٤٣معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥\n ال ينفذ حكم اإلعدام إال بعد استطالع رأي لجنة العفو وموافقة رئيس الدولة بشنق المحكوم عليه\n باإلعدام في داخل بناية السجن أو في أي محل آخر يعينه المرسوم القاضي بتنفيذ العقوبة.\n يحظر تنفيذ اإلعدام أيام اآلحاد والجمع واألعياد الوطنية أو الدينية.\n يؤجل تنفيذ اإلعدام بالحامل إلى أن تضع حملھا.\nالمادة -٤٤إذا لم ينطو القانون على نص خاص كان الحد األدنى للحكم باألشغال الشاقة المؤقتة\n واالعتقال المؤقت واإلبعاد واإلقامة الجبرية والتجريد المدني ثالث سنوات والحد األعلى خمس\n عشرة سنة."}, {"o": 11, "l": "المادة ١٨", "b": "المادة -٤٥يجبر المحكوم عليھم باألشغال الشاقة على القيام بأشغال مجھدة تتناسب وجنسھم\n وعمرھم ،سواء في داخل السجن أو في خارجه.\n المادة -٤٦يشغل المحكوم عليھم باالعتقال في أحد األشغال التي تنظمھا إدارة السجن وفقا ً لما\n اختاروه عند بدء عقوبتھم.\n وال يمكن استخدامھم خارج السجن إال برضاھم وال يجبرون على ارتداء زي السجناء.\n المادة -٤٧معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n اإلبعاد ھو إخراج المحكوم عليه من البالد.\nإذا لم يغادر المبعد البالد في خالل خمسة عشر يوما ً أو إذا عاد إليھا قبل انقضاء أجل عقوبته أبدلت\nعقوبة االعتقال من عقوبة اإلبعاد لمدة أدناھا الزمن الباقي من العقوبة وأقصاھا ضعفاه على أن ال\n تتجاوز الحد األقصى لعقوبة االعتقال المؤقت.\n و اذا لم يستطع المبعد مغادرة البالد او اكره على العودة اليھا بسبب رفض جميع الدول اقامته على\n ارضھا ابدلت من عقوبة االبعاد عقوبة االعتقال او االقامة الجبرية لمدة اقصاھا الزمن الباقي من\n العقوبة.\n المادة -٤٨اإلقامة الجبرية ھي تعيين مقام المحكوم عليه يختاره القاضي من الئحة موضوعة\n بمرسوم وال يمكن في حال من األحوال أن يكون المقام المعين في مكان كان للمحكوم عليه محل\n إقامة فيه أو سكن أو في المكان الذي اقترفت فيه الجريمة أو في محل سكن المجنى عليه أو أنسبائه\n وأصھاره حتى الدرجة الرابعة.\n إذا غادر المحكوم عليه المقام المعين له ألي وقت كان أبدلت عقوبة االعتقال من اإلقامة الجبرية\n لمدة ال تتجاوز الزمن الباقي من العقوبة.\n المادة -٤٩معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n التجريد المدني يوجب حكما ً:\n -١العزل واإلقصاء عن جميع الوظائف والخدمات العامة والحرمان من أي معاش تجريه الدولة.\n -٢العزل واإلقصاء عن جميع الوظائف والخدمات في إدارة الطائفة أو النقابة التي ينتمي إليھا\n المحكوم عليه والحرمان من أي معاش أو مرتب تجريه ھذه الطائفة أو النقابة."}, {"o": 12, "l": "المادة ١٨", "b": "-٣الحرمان من حقه في أن يكون صاحب امتياز أو التزام من الدولة.\n -٤الحرمان من حقه في أن يكون ناخبا ً أو منخوبا ً ومن سائر الحقوق المدنية والسياسية والطائفية\n والنقابية.\n ً ً ً\n -٥عدم األھلية ألن يكون مالكا أو ناشرا أو محررا لجريدة أو ألي نشرة دورية أخرى.\n\f -٦الحرمان من حق تولي مدرسة وأي مھمة في التعليم العام والخاص.\n -٧الحرمان من حق حمل األوسمة واأللقاب الفخرية اللبنانية واألجنبية.\n المادة -٥٠معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n كل محكوم عليه باألشغال الشاقة أو باالعتقال يكون في خالل تنفيذ عقوبته في حالة الحجر وتنقل\n ممارسة حقوقه على أمالكه ،ما خال الحقوق المالزمة للشخص ،إلى وصي وفاقا ً ألحكام قانون\n األحوال الشخصية المتعلقة بتعيين األوصياء على المحجور عليھم ،وكل عمل او إدارة أو تصرف\n يقوم به المحكوم عليه يعتبر باطالً بطالنا ً مطلقا ً مع االحتفاظ بحقوق الغير من ذوي النية الحسنة،\n وال يمكن أن يسلم إلى المحكوم عليه أي مبلغ من دخله ما خال المبالغ التي تجيزھا الشريعة أو\n أنظمة السجن.\n تعاد إلى المحكوم عليه أمالكه عند اإلفراج عنه ويؤدي له الوصي حسابا ً عن إدارته.\n النبذة -٣في العقوبات الجناحية\n المادة -٥١تراوح مدة الحبس بين عشرة أيام وثالث سنوات إال إذا انطوى القانون على نص\n خاص.\n ويخضع المحكوم عليه بالحبس مع التشغيل للنظام الذي حددته"}, {"o": 13, "l": "المادة ٤٦", "b": "المادة ٤٦بشأن المحكوم عليھم\n باالعتقال.\nال يجبر المحكوم عليھم بالحبس البسيط على الشغل ،على أنه يمكنھم إذا طلبوا ذلك أن يستخدموا في\n أحد األشغال المنظمة في السجن وفقا ً لخيارھم فإذا اختاروا عمالً ألزموا به حتى انقضاء أجل\n عقوبتھم.\n المادة -٥٢تراوح مدة اإلقامة الجبرية في الجنح بين ثالثة أشھر وثالث سنوات ،وتنفذ في\n الشروط نفسھا التي تنفذ فيھا اإلقامة الجبرية في الجنايات ،فإذا غادر المحكوم عليه ألي مدة كانت\n المكان المعين له أبدل الحبس البسيط من اإلقامة الجبرية لمدة ال تتجاوز الزمن الباقي من العقوبة.\n المادة -٥٣معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\nتراوح الغرامة في الجنح بين خمسين ألف ليرة لبنانية ومليوني ليرة لبنانية إال إذا نص القانون على\n غير ذلك.\n\f ويمكن أداء الغرامة بناء على نص خاص في الفقرة الحكمية أقساطا ً تساوي على األقل حد العقوبة\n األدنى على شرط أن ال يجاوز أجل القسط األخير سنة واحدة تبتدىء من يوم أصبح الحكم مبرما ً.\n وإذا لم يدفع أحد األقساط في حينه استحقت الغرامة بتمامھا.\n المادة -٥٤معدلة وفقا لقانون تاريخ ١٩٤٨/٢/٥والقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n تستبدل الغرامة بالحبس البسيط إذا لم تؤد في مھلة ثالثين يوما ً تبتدىء من تاريخ انبرام الحكم دون\n تنبيه سابق وفقا ً لألصول المرعية.\nتعين في الحكم القاضي بالعقوبة وإال فبقرار خاص مدة الحبس المستبدل باعتبار أن يوما ً واحداً من\n ھذه العقوبة يوازي غرامة تراوح بين ألفي ليرة وعشرة آالف ليرة.\n وال يمكن أن يجاوز الحبس المستبدل سنة واحدة وال الحد األقصى لعقوبة الحبس األصلية التي\n تستوجبھا الجريمة.\n وإذا كان للمحكوم عليه دخل معروف قابل للحجز أمكن اللجوء إلى التنفيذ الجبري قبل الحبس.\n يحسم من أصل ھذه العقوبة بالنسبة التي حددھا الحكم كما ورد في الفقرة الثانية من ھذه المادة -كل\n أداء جزئي أدي قبل الحبس أو في أثنائه وكل مبلغ استوفي."}, {"o": 14, "l": "المادة ٤٦", "b": "المادة -٥٥معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n ال تنفذ عقوبة الحبس بالحامل غير الموقفة إال بعد أن تضع حملھا بستة أسابيع.\n إن الزوجين اللذين يحكم عليھما بھذه العقوبة مدة تنقص عن السنة وال يكونان موقوفين يعانيانھا\n على التتالي إذا كان في عھدتھما ولد دون الثامنة عشرة من عمره وأثبتا أن لھما محل إقامة أكيد.\n النبذة -٤أحكام مشتركة بين العقوبات المانعة للحرية في قضايا الجنايات والجنح\n المادة -٥٦يحبس في أماكن مختلفة:\n -١المحكوم عليھم باألشغال الشاقة المؤبدة والمؤقتة.\n -٢المحكوم عليھم باالعتقال المؤبد والمؤقت.\n -٣المحكوم عليھم بالحبس مع التشغيل.\n -٤المحكوم عليھم بالحبس البسيط.\n المادة -٥٧معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥\n\f كل محصول لعمل المحكوم عليه تجري قسمته بإشراف المدعي العام المولج بالتنفيذ بين كل من\nالمحكوم عليه واألشخاص الذين يعولھم المدعي الشخصي والدولة ألجل استيفاء الغرامات والنفقات\n القضائية ونفقات إدارة السجن وذلك بنسبة تحدد بحسب ماھية الحكم على أن ال تقل حصة كل من\n عائلة المحكوم عليه والمدعي الشخصي عن ثلث قيمة المحصول الشھري.\n عندما يستوفي المدعي الشخصي ما يعود له من التعويض تزاد الحصص المخصصة بالمحكوم\n عليه واألشخاص الذين يعولھم زيادة مطردة بقدر صالحه.\n المادة -٥٨كل محكوم عليه بعقوبة مانعة للحرية تبلغ ثالثة أشھر على األقل تحسن معاملته\n بالسجن بقدر صالحه .ويشتمل ھذا التحسين الطعام ونوع الشغل وعدد ساعاته ولزوم الصمت\n والتنزه والزيارات والمراسلة.\n وكل ذلك على نحو ما سيعينه قانون التنفيذ العقوبات.\n المادة -٥٩إذا ھرب المحكوم عليه تزاد من الثلث إلى النصف كل عقوبة مؤقتة قضي بھا على\n وجه مبرم من أجل جناية أو جنحة إال في الحاالت التي خصھا القانون بنص.\n النبذة -٥في العقوبات التكديرية\n المادة -٦٠معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥"}, {"o": 15, "l": "المادة ٤٦", "b": "تتراوح مدة الحبس التكديري بين يوم وعشرة أيام.\nوتنفذ بالمحكوم عليھم في أماكن مختلفة عن األماكن المخصصة بالمحكوم عليھم بعقوبات جنائية أو\n جناحية وال يجبر على العمل المحكوم عليھم بالتوقيف.\n المادة -٦١معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥وقانون تاريخ ١٩٦٠/١٢/١٠والقانون ٢٣٩\n تاريخ ١٩٩٣/٥/٢٧\n تراوح الغرامة التكديرية بين ستة آالف ليرة وخمسين ألف ليرة.\n المادة -٦٢معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥والقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n\f تستبدل الغرامة بالحبس البسيط إذا لم تؤد في مھلة ثالثين يوما ً من تاريخ انبرام الحكم دون تنبيه\n سابق:\n تعين في الحكم القاضي بالعقوبة وإال فبقرار خاص مدة التوقيف المستبدل باعتبار أن اليوم الواحد\n من ھذه العقوبة يوازي غرامة بين ألف ليرة وأربعة آالف ليرة.\nوال يمكن أن تجاوز العقوبة المستبدلة العشرة أيام وعلى كل الحد األقصى للتوقيف المنصوص عليه\n عقوبة أصلية للجريمة.\n يحسم من أصل ھذه العقوبة بالنسبة التي حددھا الحكم -كما ورد في الفقرة الثانية من ھذه المادة-\n كل أداء جزئي أدي قبل التوقيف أو في أثنائه.\n النبذة -٦في العقوبات الفرعية والإضافية\n المادة -٦٣معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n الحكم باألشغال الشاقة مؤبداً أو باالعتقال المؤبد يوجب التجريد المدني مدى الحياة.\n الحكم باألشغال الشاقة المؤقتة أو االعتقال المؤقت أو باإلبعاد أو باإلقامة الجبرية في الجنايات\nيوجب التجريد المدني منذ اليوم الذي أصبح فيه الحكم مبرما ً حتى انقضاء السنة العاشرة على تنفيذ\n العقوبة األصلية.\n ما عدا في حالة المحكوم الفار فھو يوجب التجريد المدني وإن كان الحكم الغيابي غير مبرم منذ\n تاريخ صدوره حتى تاريخ إلغائه وفقا ً ألحكام"}, {"o": 16, "l": "المادة ٣٤٦", "b": "المادة ٣٤٦من األصول الجزائية.\n المادة -٦٤معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n تراوح الغرامة الجنائية بين مئة ألف ليرة وستة ماليين ليرة.\n وھي تخضع ألحكام المادتين ٥٣و ٥٤المتعلقتين بالغرامة الجناحية.\n تستبدل من الغرامة عند عدم أدائھا إما عقوبة األشغال الشاقة أو عقوبة االعتقال حسبما تكون\nالعقوبة األصلية التي قضى بھا على المحكوم عليه ،ھي األشغال الشاقة أو أي عقوبة جنائية أخرى.\n المادة -٦٥كل محكوم عليه بالحبس أو باإلقامة الجبرية في قضايا الجنح يحرم طوال تنفيذ\n عقوبته من ممارسة حقوقه المدنية اآلتية:\n -١الحق في تولي الوظائف والخدمات العامة.\n -٢الحق في تولي الوظائف والخدمات في إدارة شؤون الطائفة المدنية أو إدارة النقابة التي ينتمي\n إليھا.\n ً ً\n -٣الحق في أن يكون ناخبا أو منتخبا في جميع مجالس الدولة.\n\f -٤الحق في أن يكون ناخبا ً أو منتخبا ً في جميع منظمات الطوائف والنقابات.\n -٥الحق في حمل أوسمة لبنانية أو أجنبية.\nالمادة -٦٦يمكن في الحاالت الخاصة التي عينھا القانون أن يحكم مع كل عقوبة جناحية بالمنع\n من ممارسة حق أو أكثر من الحقوق المذكورة في المادة السابقة.\n يقضى بھذا المنع لمدة تتراوح بين سنة وعشر سنوات.\n المادة -٦٧كل قرار ينطوي على عقوبة جنائية يلصق لمدة شھر على باب قاعة محكمة\nالجنايات وفي أقرب محلة من مكان الجناية وفي المحلة التي كان فيھا المحكوم عليه محل إقامة أو\n سكن.\nفي الحاالت التي يجيزھا القانون بنص خاص يمكن أن يلصق الحكم المنطوي على عقوبة جناحية\n مدة خمسة عشرة يوما ً في األماكن التي يعينھا القاضي.\n تلصق األحكام خالصات على نفقة المحكوم عليه.\n للقاضي أن يعين حجم اإلعالن وحروف الطبع.\n المادة -٦٨معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n لمحكمة الجنايات أن تأمر بنشر أي قرار جنائي في جريدة أو جريدتين تعينھما."}, {"o": 17, "l": "المادة ٣٤٦", "b": "كذلك يمكن نشر أي حكم قضى بعقوبة جناحية في جريدة أو جريدتين يعينھما القاضي إذا نص\n القانون صراحة على ذلك.\n إذا اقترفت الجناية أو الجنحة بواسطة جريدة أو أي نشرة دورية أخرى أمكن نشر إعالن إضافي\n فيھا.\n إذا لم يقض نص بنشر الحكم برمته نشرت خالصة منه.\n ويلزم المحكوم عليه بنفقات ذلك كله.\n يعاقب بغرامة تتراوح بين عشرين ألف ليرة ومئة ألف ليرة مدير النشر في الصحيفة التي اختيرت\n لنشر اإلعالن إذا رفض أو أرجأ نشرھا.\n المادة -٦٩معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥\n يمكن مع االحتفاظ بحقوق الغير ذي النية الحسنة مصادرة جميع األشياء التي نتجت عن جناية أو\n جنحة مقصودة أو التي استعملت أو كانت معدة القترافھما.\nويمكن مصادرة ھذه األشياء في الجنحة غير المقصودة أو في المخالفة إذا انطوى القانون على نص\n صريح.\nإذا لم يكن ما تجب مصادرته قد ضبط منح المحكوم عليه مھلة ألجل تسليمه تحت طائلة أداء قيمته\n حسبما يقدرھا القاضي.\n يمكن للمحكمة عند االقتضاء االستعانة بخبير لتقدير القيمة الواجب أداؤھا وتحصل القيمة المقدرة\n بالطريقة المتبعة في تحصيل الغرامة.\n\fالفصل الثاني -في تدابير الاحتراز\nالنبذة -١في تدابير الاحتراز عامة\n المادة -٧٠التدابير االحترازية المانعة للحرية ھي:\n -١الحجز في مأوى احترازي.\n -٢العزلة.\n -٣الحجز في دار للتشغيل.\n المادة -٧١التدابير االحترازية المقيدة للحرية ھي:\n -١منع ارتياد الخمارات.\n -٢منع اإلقامة.\n -٣الحرية المراقبة.\n -٤الرعاية.\n -٥اإلخراج من البالد.\n المادة -٧٢التدابير االحترازية المانعة للحقوق ھي:\n -١اإلسقاط من الوالية أو الوصاية.\n -٢المنع من مزاولة عمل.\n -٣المنع من حمل السالح.\n المادة -٧٣التدابير االحترازية العينية ھي:\n -١المصادرة العينية.\n -٢الكفالة االحتياطية.\n\f -٣إقفال المحل.\n -٤وقف ھيئة معنوية عن العمل أو حلھا.\n النبذة -٢في الحجز في مأوى احترازي"}, {"o": 18, "l": "المادة ٣٤٦", "b": "المادة -٧٤من قضي عليه بالحجز في مأوى احترازي أوقف في مستشفى يعين بمرسوم ويعني\n به العناية التي تدعو إليھا حالته.\nالمادة -٧٥على طبيب المأوى أن ينظم تقريراً بحالة المحكوم عليه كل ستة أشھر ويجب أيضا ً\n أن يعوده مرة في السنة على األقل طبيب تعينه المحكمة التي قضت بالحجز.\n المادة -٧٦من حكم عليه بعقوبة مانعة أو مقيدة للحرية أو بالعزلة أو بالحرية المراقبة أو بمنع\n اإلقامة أو بالكفالة االحتياطية وثبت أنه في أثناء تنفيذ الحكم قد أصيب بالجنون حجز عليه في\n مأوى احترازي حيث يعنى به العناية التي تدعو إليھا حالته.\nال يمكن أن تجاوز مدة الحجز ما بقي من زمن العقوبة أو التدبير االحترازي الذي علق تنفيذه إال أن\n يكون المحكوم عليه خطراً على السالمة العامة.\n عندما يقضي القاضي باإلفراج عنه يقرر ھل يجب حسم مدة الحجز كلھا أو بعضھا من مقدار\n العقوبة أو التدبير االحترازي.\n النبذة -٣في العزلة\n المادة -٧٧تراوح مدة العزلة بين ثالث سنوات وخمس عشرة سنة.\n تنفذ العزلة في مؤسسة للتشغيل أو في مستعمرة زراعية تعين بمرسوم.\n\f يأمر القاضي بوضع المحكوم عليه في إحدى ھاتين المؤسستين وفقا ً لمؤھالته ولنشأته المدنية أو\n القروية.\n تطبق على من قضي عليھم بالعزلة المادتان ٥٧و .٥٨\n المادة -٧٨إذا غادر المحكوم عليه ألي مدة كانت المؤسسة التي حجز فيھا تعرض للحبس مع\n التشغيل من سنة إلى ثالث سنوات.\n النبذة -٤في الحجز في دار للتشغيل\n المادة -٧٩ال يمكن أن تنقص مدة الحجز في دار للتشغيل عن ثالثة أشھر أو تزيد عن ثالث\n سنوات.\n يخضع المحكوم عليه للنظام المعين في المادتين ٥٧و .٥٨\nإذا غادر المحكوم عليه دار التشغيل ألي مدة كانت عوقب بالحبس مع التشغيل من ثالثة أشھر إلى\n سنة.\n النبذة -٥في منع ارتياد الخمارات\n المادة -٨٠إذا اقترفت جناية أو جنحة بتأثير المشروبات الكحولية فللقاضي أن يمنع المحكوم"}, {"o": 19, "l": "المادة ٣٤٦", "b": "عليه من ارتياد الحانات التي تباع فيھا ھذه المشروبات مدة تراوح بين سنة وثالث سنوات تحت\n طائلة الحبس من عشرة أيام إلى ثالثة أشھر.\nينزل العقاب نفسه بالبائع ومستخدميه الذين يعطون المحكوم عليه المشروبات الروحية على علمھم\n بالمنع النازل به.\n\f النبذة -٦في منع الإقامة\nالمادة -٨١منع اإلقامة ھو الحظر على المحكوم عليه أن يوجد بعد اإلفراج عنه في األمكنة التي\n عينھا الحكم.\n تمنع اإلقامة بحكم القانون ،في القضاء الذي اقترفت فيه الجناية أو الجنحة والقضاء الذي يسكن فيه\n المجني عليه أو أنسباؤه حتى الدرجة الرابعة ،إال إذا قرر القاضي خالف ذلك.\n المادة -٨٢تراوح مدة منع اإلقامة بين سنة وخمس عشرة سنة.\n من حكم عليه بعقوبة جنائية مانعة أو مقيدة للحرية يخضع حكما ً لمنع اإلقامة مدة توازي مدة\n العقوبة المقضي بھا.\nمن حكم عليه باإلعدام أو باألشغال الشاقة مؤبداً أو باالعتقال المؤبد وأعفي من عقوبته بعفو عام أو\nسقطت عنه العقوبة بمرور الزمن أو خفضت أو أبدلت منھا عقوبة مؤقتة يخضع حكما ً لمنع اإلقامة\n خمس عشرة سنة.\n ال يخضع المحكوم عليه بعقوبة جناحية لمنع اإلقامة إال إذا انطوى القانون على نص صريح\n يفرض ھذا المنع أو يجيزه.\n يطبق كل ذلك ما لم يقرر القاضي زيادة مدة المنع أو تخفيضھا ضمن النطاق المحدد في الفقرة\n األولى أو إعفاء المحكوم عليه منھا.\n المادة -٨٣كل مخالفة لمنع اإلقامة يعاقب عليھا بالحبس من ثالثة أشھر إلى ثالث سنوات،\n وللقاضي أن يبدل الحرية المراقبة من منع اإلقامة مدة ال تنقص عما بقي من منع اإلقامة.\n النبذة -٧في الحرية المراقبة\n المادة -٨٤الغاية من الحرية المراقبة التثبت من صالحية المحكوم عليه وتسھيل ائتالفه مع\n المجتمع.\n\fيخضع المراقب للمنع من ارتياد الخمارات ومنع اإلقامة .وعليه أن يمسك عن ارتياد المحالت التي\nتنھي عنھا القوانين واألنظمة وأن يتقيد باألحكام التي فرضھا عليه القاضي ،خشية المعاودة ،ويمكن"}, {"o": 20, "l": "المادة ٣٤٦", "b": "تعديل ھذه األحكام أثناء تنفيذ التدبير.\nالمادة -٨٥تراوح مدة الحرية المراقبة بين سنة وخمس سنوات ما لم يرد في القانون نص خاص\n مخالف.\n إذا لم تكن من ھيئات خاصة للمراقبة تولت أمرھا الشرطة.\n يقدم إلى القاضي تقرير عن سيرة المحكوم عليه مرة كل ثالثة أشھر على األقل.\n المادة -٨٦من قضي عليه بالمراقبة وخالف األحكام التي فرضھا عليه القانون أو القاضي أو\n اعتاد التملص من المراقبة حكم عليه بالحبس مع التشغيل من ثالثة أشھر إلى ثالث سنوات إال أن\n ينص القانون على جزاء آخر.\n النبذة -٨في الرعاية\n المادة -٨٧يعھد بالرعاية إلى مؤسسات خاصة اعترفت بھا الدولة.\n على المؤسسة أن توفر عمالً للمحكوم عليه.\n ويراقب مندوبوھا بحكمة طريقة معيشته ويسدون إليه النصح والمعونة .ويمكن أن يسلم إليھا قنوة\n السجن المسرح لتستعمل في مصلحته على أفضل وجه.\n ويجب أن يقدم إلى الھيئة القضائية التي قضت بالتدبير تقرير عن حالة المحكوم عليه وسلوكه مرة\n كل ثالثة أشھر على األقل.\n النبذة -٩في الإخراج من البلاد\n\f المادة -٨٨كل أجنبي حكم عليه بعقوبة جنائية يمكن طرده من األرض اللبنانية بموجب فقرة\n خاصة في الحكم.\n وإذا حكم عليه بعقوبة جناحية فال يمكن طرده إال في الحاالت التي ينص عليھا القانون.\n يقضي باإلخراج من البالد مؤبداً أو لمدة تراوح بين ثالث وخمس عشرة سنة.\n المادة -٨٩على األجنبي الذي قضي بإخراجه أن يغادر األرض اللبنانية بوسائله الخاصة في\n مھلة خمسة عشر يوما ً.\n يعاقب كل مخالف لتدبير اإلخراج قضائيا ً كان أو إداريا ً بالحبس من شھر الى ستة أشھر.\n النبذة -١٠في الإسقاط من الولاية أو من الوصاية\n المادة -٩٠اإلسقاط من الوالية أو من الوصاية يوجب الحرمان من جميع الحقوق على الولد أو\n اليتيم وعلى أمالكه.\n يكون اإلسقاط كامالً أو جزئياً ،ويكون عاما ً أو محصوراً بولد أو يتيم أو بعدة أوالد وأيتام."}, {"o": 21, "l": "المادة ٣٤٦", "b": "تنتقل ممارسة الوالية أو الوصاية إلى وصي وفاقا ً ألحكام األحوال الشخصية.\n المادة -٩١يمكن حرمان األب أو األم أو الوصي من الوالية أو الوصاية إذا حكم عليھم بعقوبة\n جنائية وتبين أنھم غير جديرين بممارسة سلطتھم على الولد أو اليتيم.\n المادة -٩٢يتعرض ھؤالء األشخاص للتدبير نفسه.\n -١إذا حكم عليھم بعقوبة جنائية أو جناحية من أجل جريمة اقترفوھا بحق الولد أو الفرع أو اليتيم أو\n باالشتراك معه.\n -٢إذا اقترف القاصر الذي في عھدتھم جناية أو جنحة تسببت عن تھاونھم في تھذيبه أو عن\n اعتيادھم إھمال مراقبته.\n المادة -٩٣يكون اإلسقاط من الوالية أو الوصاية لمدى الحياة أو ألجل يراوح بين ثالث سنوات\n وخمس عشرة سنة.\n\fوال يمكن في أي حال أن يقضي به لمدة أدنى لما حكم به على األب أو األم أو الوصي من عقوبة أو\n تدبير احترازي مانعين للحرية.\n النبذة -١١في المنع من مزاولة أحد الأعمال\n المادة -٩٤يمكن منع أي شخص من مزاولة فن أو مھنة أو حرفة أو أي عمل معلق على قبول\n السلطة أو على نيل شھادة إذا حكم عليه بعقوبة جنائية أو جناحية من أجل جريمة اقترفت خرقا ً\n لواجبات المھنة أو القروض المالزمة لذلك العمل.\n إذا كانت مزاولة العمل ممكنة بمعزل عن أي شرط أو ترخيص فال يمكن القضاء بالمنع من\n مزاولته إال في الحاالت التي نص عليھا القانون.\n يتعرض الناشر في قضايا المطبوعات للمنع وإن لم تكن مزاولته العمل منوطة بترخيص .والمنع\n الذي ينزل به أو بالمالك يؤدي إلى وقف الصحيفة مدة المنع نفسھا.\n المادة -٩٥معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n تراوح مدة المنع بين شھر وسنتين ،ويمكن الحكم بھا مدى الحياة إذا كان المجرم قد حكم عليه\n بالمنع المؤقت بقرار مبرم لم تمر عليه خمس سنوات أو إذا نص القانون صراحة على ذلك.\n مزاولة العمل الممنوع وإن تمت بالواسطة أو لحساب الغير يعاقب عليھا بالحبس حتى ثالثة أشھر\n وبالغرامة حتى مائتي ألف ليرة."}, {"o": 22, "l": "المادة ٣٤٦", "b": "النبذة -١٢في الحرمان من حق حمل السلاح\n المادة -٩٦يمكن الحكم بالحرمان من حق حمل السالح لمدى الحياة أو لمدة تراوح بين ثالث\n سنوات وخمس عشرة سنة.\n ال يمكن من تناوله ھذا التدبير أن يحصل على ترخيص القتناء السالح أو حمله ويلغى الترخيص\n الذي كان في حيازته.\n وال يرد إليه ما أداه من رسم.\n\fالمادة -٩٧كل حكم بعقوبة جنائية أو جناحية من أجل جريمة اقترفت بواسطة السالح أو بالعنف\n يوجب الحرمان من حق حمل السالح مدة ثالث سنوات إال أن ينطوي الحكم على خالف ذلك.\n النبذة -١٣في المصادرة العينية\n المادة -٩٨معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥\n يصادر من األشياء ما كان صنعه أو اقتناؤه أو بيعه أو استعماله غير مشروع وإن لم يكن ملكا ً\n للمدعى عليه أو المحكوم عليه أو لم تفض المالحقة إلى حكم.\n إذا لم يكن ما تجب مصادرته قد ضبط منح المحكوم عليه أو المدعى عليه مھلة لتقديمه تحت طائل\n أداء ضعفي قيمته حسبما يحددھا القاضي.\n يمكن للمحكمة عند االقتضاء االستعانة بخبير لتقدير القيمة الواجب أداؤھا وتحصل القيمة بالطريقة\n المتبعة في تحصيل الغرامة.\n النبذة -١٤في الكفالة الاحتياطية\n المادة -٩٩معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\nالكفالة االحتياطية في إيداع مبلغ من المال أو سندات عمومية أو ربط كفيل ذي سالمة أو عقد تأمين\n ضمانا ً لحسن سلوك المحكوم عليه أو تالفيا ً لجريمة أخرى.\nيمكن أن تفرض الكفالة لسنة على األقل ولخمس سنوات على األكثر ما لم يشتمل القانون على نص\n خاص.\n يعين القاضي في الحكم مقدار المبلغ الواجب إيداعه أو مقدار المبلغ الذي يجب أن يضمنه عقد\n التأمين أو الكفيل ،وال يمكن أن ينقص عن خمسة آالف ليرة أو يزيد على أربعمائة ألف ليرة.\n\f المادة -١٠٠تستبدل الحرية المراقبة حكما ً من الكفالة االحتياطية للمدة نفسھا إذا لم تؤد قبل\n التاريخ الذي حدده القاضي وعلى األكثر خالل عشرة أيام."}, {"o": 23, "l": "المادة ٣٤٦", "b": "إذا فرضت الكفالة االحتياطية على ھيئة معنوية أمكن استيفاؤھا بالحجز.\n فإذا كان ما وجد من األموال ال يفي بالقيمة المحددة إال بوقف عمل الھيئة الشرعي أمكن الحكم\n بحلھا.\n المادة -١٠١معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n يمكن فرض الكفالة االحتياطية:\n -١في حالة الحكم من أجل تھديد أو تھويل.\n -٢في حالة الحكم من أجل تحريض على جناية لم يفض إلى نتيجة.\n -٣إذا كان ثمة مجال للخوف من أن يعود المحكوم عليه إلى إيذاء المجنى عليه أو أفراد عائلته أو\n اإلضرار بأمالكھم.\n -٤في حالتي وقف التنفيذ أو وقف الحكم النافذ.\n -٥في حالة الحكم على ھيئة معنوية من أجل جريمة توجب فرض الحرية المراقبة.\n المادة -١٠٢معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n ترد الكفالة ويشطب التأمين ويبرأ الكفيل إذا لم يقترف خالل مدة التجربة الفعل الذي أريد تالفيه.\n وفي حالة العكس تحصل الكفالة وتخصص باألفضلية للتعويضات الشخصية فللرسوم فللغرامات\n وما يتبقى منھا يصادر لمصلحة الدولة.\n النبذة -١٥في إقفال المحل\nالمادة -١٠٣يمكن الحكم بأقفال المحل الذي اقترفت فيه جريمة بفعل صاحبه أو برضاه شھراً\n على األقل وسنتين على األكثر إذا أجاز القانون ذلك بنص صريح.\n ويوجب اإلقفال حكماً ،أيا ً كان سببه ،منع المحكوم عليه من مزاولة العمل نفسه على ما ورد في\n المادة .٩٤\n\fالمادة -١٠٤إن إقفال المحل الذي قضي به من أجل أفعال جرمية أو مخلة باآلداب يوجب منع\n المحكوم عليه أو أحد أفراد عائلته أو أي شخص تملك المحل أو استأجره على علمه بأمره من أن\n يزاول فيه العمل نفسه.\n ال يتناول المنع مالك العقار وجميع من لھم على المحل حق امتياز أو حق رھن أو دين إذا ظلوا\n بمعزل عن الجريمة.\n المادة -١٠٥إذا قضي بإقفال المحل ألن المستثمر قد باشر استثماره في محل إقامته دون\n ترخيص الزم بإخالء المحل ،وذلك مع االحتفاظ بحق المؤجر الحسن النية في فسخ عقد اإلجارة"}, {"o": 24, "l": "المادة ٣٤٦", "b": "وفي كل عطل وضرر.\n المادة -١٠٦إذا قضي بھذا التدبير بسبب عدم أھلية المستثمر اقتصرت مفاعليه عليه.\n المادة -١٠٧يتعرض للعقوبات المنصوص عليھا في"}, {"o": 25, "l": "المادة ٩٥", "b": "المادة ٩٥المحكوم عليه وكل شخص\n ثالث إذا خالف أحكام المواد السابقة.\n النبذة -١٦في وقف هيئة معنوية عن العمل أو حلها\n المادة -١٠٨يمكن وقف كل نقابة وكل شركة أو جمعية وكل ھيئة معنوية ما خال اإلدارات\nالعامة إذا اقترف مديروھا أو أعضاء إدارتھا أو ممثلوھا أو عمالھا باسمھا أو بإحدى وسائلھا جناية\n أو جنحة مقصودة يعاقب عليھا بسنتي حبس على األقل.\n المادة -١٠٩يمكن حل الھيئات المذكورة في الحاالت التي أشارت إليھا المادة السابقة.\n -١إذا لم تتقيد بموجبات التأسيس القانونية.\n -٢إذا كانت الغاية من تأسيسھا مخالفة للشرائع أو كانت تستھدف في الواقع مثل ھذه الغاية.\n -٣إذا خالفت األحكام القانونية المنصوص عليھا تحت طائل الحل.\n -٤إذا كانت قد أوقفت بموجب قرار مبرم لم تمر عليه خمس سنوات.\n\f المادة -١١٠يقضي بالوقف شھراً على األقل وسنتين على األكثر ،وھو يوجب وقف أعمال\n الھيئة كافة وأن تبدل االسم واختلف المديرون أو أعضاء اإلدارة ،ويحول دون التخلي عن المحل\n شرط االحتفاظ بحقوق الغير ذي النية الحسنة.\n ويوجب الحل تصفية أموال الھيئة المعنوية ،ويفقد المديرون أو أعضاء اإلدارة وكل مسؤول\n شخصيا ً عن الجريمة ،األھلية لتأسيس ھيئة مماثلة أو إدارتھا.\n المادة -١١١معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n يعاقب على كل مخالفة لألحكام السابقة بالحبس من شھر إلى ستة أشھر وبغرامة تتراوح بين مئة\n ألف ليرة ومليوني ليرة.\n النبذة -١٧في حساب العقوبات والتدابير الاحترازية\n ملغاة وفقا للقانون رقم ٢١٦تاريخ ٢٠١٢/٣/٣٠\n المادة -١١٢خالفا ً ألي نص آخر ،وما خال عقوبة الحبس المستبدل من الغرامة ،يحتسب يوم\nالعقوبة أو التدبير االحترازي ٢٤ساعة ،والشھر ٣٠يوما ً ما لم تكن العقوبة المقضي بھا دون السنة\n حبساً ،ففي ھذه الحالة يحتسب الشھر ٢٠يوماً ،أما إذا كانت العقوبة المقضي بھا ھي الحبس سنة"}, {"o": 26, "l": "المادة ٩٥", "b": "فأكثر فان ھذه السنة تحتسب تسعة أشھر من يوم إلى مثله وفقا ً للتقويم العربي.\n ال يستفيد من أحكام ھذا النص المحكومون بعقوبات غير محددة المدة ،كما ال يستفيد من أحكام ھذا\n النص مد نفاذ القانون ،معاندو اإلجرام والمكررون المعزفون وفقا ً ألحكام"}, {"o": 27, "l": "المادة ٢٥٨", "b": "المادة ٢٥٨وما يليھا من\n قانون العقوبات على أن ينص الحكم أو القرار الجاري تنفيذه على ھذا الوصف\n نص"}, {"o": 28, "l": "المادة ١٢٢", "b": "المادة ١٢٢قبل الغائھا بموجب القانون رقم ٢١٦تاريخ ٢٠١٢/٣/٣٠\nيوم العقوبة أو التدبير االحترازي أربع وعشرون ساعة ،والشھر ثالثون يوماً ،وما جاوز منھما الشھر حسب من يوم إلى مثله\n وفاقا ً للتقويم الغربي.\n فيما خال الحالة التي حكم بھا على الموقف لمدة أربع وعشرين ساعة يطلق سراحه قبل ظھيرة اليوم األخير.\nالمادة -١١٣كل عقوبة مانعة أو مقيدة للحرية تحسب من اليوم الذي بدىء فيه بتنفيذھا بموجب\n الحكم الذي أصبح مبرما ً.\n إذا اجتمعت عدة عقوبات مانعة للحرية نفذ أشدھا أوالً.\n إذا اجتمعت عقوبات مانعة للحرية وعقوبات مقيدة للحرية نفذت في البدء العقوبات األولى.\nالمادة -١١٤تجري مدة التجريد المدني منذ اليوم الذي أصبح فيه الحكم مبرماً ،وإذا كان القرار\n قد صدر غيابيا ً حسبت منذ تاريخ محضر اإللصاق األخير الذي تم عمالً بالمادة .٦٧\n\f إن المنع من بعض الحقوق المدنية الذي يقضي به على وجه إضافي وفاقا ً للمادة ،٦٦ينفذ منذ\n انقضاء مدة العقوبة األصلية المانعة أو المقيدة للحرية.\n المادة -١١٥تنفذ في الحال مفاعيل الحكم القاضي بالحجز في مأوى احترازي دون ما التفات\n إلى أية عقوبة أخرى أو أي تدبير احترازي آخر يمنعان الحرية أو يقيدانھا.\nإن التدابير االحترازية المانعة أو المقيدة للحرية ما عدا الحجز في مأوى احترازي تنفذ بعد العقوبات\n المانعة للحرية.\n تنفذ العقوبات المقيدة للحرية بعد التدابير االحترازية المانعة للحرية.\n إذا اجتمعت تدابير احترازية مانعة للحرية وتدابير احترازية مقيدة للحرية بدىء بتنفيذ األولى في\n الترتيب اآلتي:\n -الحجز في مأوى احترازي ،العزلة ،الحجز في دار التشغيل.\nعلى أن مفاعيل اإلخراج من البالد تنفذ دون التفات إلى أي تدبير احترازي آخر أو أية عقوبة مانعة\n من الحقوق.\nالمادة -١١٦أن المنع من مزاولة عمل من األعمال والمنع من حمل السالح والكفالة االحتياطية"}, {"o": 29, "l": "المادة ١٢٢", "b": "تنفذ بعد انقضاء مدة العقوبات والتدابير االحترازية المانعة للحرية.\nأما سائر التدابير االحترازية والعينية أو المانعة من الحقوق فتنفذ مفاعيلھا منذ اليوم الذي أصبح فيه\n الحكم مبرما ً.\n المادة -١١٧يحسب التوقيف االحتياطي دائما ً في مدة العقوبات المانعة أو المقيدة للحرية\n ويحسم من الغرامة بمقدار ما يقرره القاضي وفاقا ً ألحكام المواد ٥٤و ٦٢و.٦٤\n ويسقط من مدة التدابير االحترازية المانعة للحرية إذا قضى القاضي بذلك صراحة في الحكم.\n الفصل الثالث -في تدابير الإصلاح\n النبذة -١في تدابير الإصلاح عامة\n\fالمادة -١١٨ملغاة وفقا للمرسوم االشتراعي ١١٩تاريخ ١٩٨٣/٩/١٧\nالمادة -١١٩ملغاة وفقا للمرسوم االشتراعي ١١٩تاريخ ١٩٨٣/٩/١٧\nالمادة -١٢٠ملغاة وفقا للمرسوم االشتراعي ١١٩تاريخ ١٩٨٣/٩/١٧\nالمادة -١٢١ملغاة وفقا للمرسوم االشتراعي ١١٩تاريخ ١٩٨٣/٩/١٧\nالمادة -١٢٢ملغاة وفقا للمرسوم االشتراعي ١١٩تاريخ ١٩٨٣/٩/١٧\nالمادة -١٢٣ملغاة وفقا للمرسوم االشتراعي ١١٩تاريخ ١٩٨٣/٩/١٧\nالمادة -١٢٤ملغاة وفقا للمرسوم االشتراعي ١١٩تاريخ ١٩٨٣/٩/١٧\nالمادة -١٢٥ملغاة وفقا للمرسوم االشتراعي ١١٩تاريخ ١٩٨٣/٩/١٧\nالمادة -١٢٦ملغاة وفقا للمرسوم االشتراعي ١١٩تاريخ ١٩٨٣/٩/١٧\nالمادة -١٢٧ملغاة وفقا للمرسوم االشتراعي ١١٩تاريخ ١٩٨٣/٩/١٧\nالمادة -١٢٨ملغاة وفقا للمرسوم االشتراعي ١١٩تاريخ ١٩٨٣/٩/١٧\n الفصل الرابع -في الالزامات المدنية\n\f النبذة -١في أنواع الالزامات المدنية\n المادة -١٢٩االلزامات المدنية التي يمكن القاضي الجزائي القضاء بھا ھي:\n -١الرد.\n -٢العطل والضرر.\n -٣المصادرة.\n -٤نشر الحكم.\n -٥النفقات.\n المادة -١٣٠الرد عبارة عن إعادة الحال إلى ما كانت عليه قبل الجريمة.\n كلما كان الرد في اإلمكان وجب الحكم به عفواً.\n تجري أحكام القانون المدني على رد ما كان في حيازة الغير."}, {"o": 30, "l": "المادة ١٢٢", "b": "المادة -١٣١على المحكمة الجزائية الناظرة في إحدى الجرائم المنصوص عليھا في المواد\n ٦٨٩و ٦٩٢ومن ٦٩٥إلى ،٦٩٧أن تحكم عفواً ولو قضت بالتبرئة برد جميع األموال أو الحقوق\n أو األسھم المختلسة إلى كتلة الدائنين.\n المادة -١٣٢معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n -تسري أحكام المواد ١٣٤إلى ١٣٦ضمنا ً من قانون الموجبات والعقود على العطل والضرر\n ويقضى بھما بناء على طلب اإلدعاء الشخصي.\nوفي حالة التبرئة يمكن أن يقضي بھما بناء على طلب المدعى عليه أو طلب الفريق الذي استحضر\n كمسؤول مدنيا ً إذا تبين أن المدعي الشخصي تجاوز في دعواه.\n وللقاضي أن يقرر أن ما يمنحه من عطل وضرر ،من أجل جناية أو جنحة أدت إلى الموت أو إلى\n تعطيل دائم عن العمل ،يدفع دخالً مدى الحياة إلى المجنى عليه أو إلى ورثته إذا طلبوا ذلك.\n معدلة وفقا للقانون رقم ٨٧تاريخ ٢٠١٠/٣/٦\n\f المادة -١٣٣معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والمرسوم االشتراعي\n ٢١تاريخ ١٩٨٥ /٣ /٢٣\n -يسقط الحق العام ،تبعا ً إلسقاط الحق الشخصي ،إذا حصل ھذا اإلسقاط قبل الحكم المبرم في\nالدعوى وإذا كان صريحاً ،وغير معلق على شرط ،وصادراً عن جميع المدعين الشخصيين في حال\n تعددھم في الجرائم التالية:\n -١في القباحات الواقعة على األفراد أو على أموالھم.\n -٢في جرائم الذم والقدح الواقعة على األفراد غير موظفي اإلدارات والمؤسسات العامة والبلديات\n والجيش والھيئات المنظمة وقضاة الحكم بسبب وظائفھم أو صفاتھم وعلى النواب والوزراء ،وعلى\n رئيس الدولة في كل األحوال.\n -٣في جرائم الضرب والجرح واإليذاء الواقعة على األفراد إذا لم يفض الفعل إلى تعطيل أو\n أفضى إلى تعطيل عن العمل ال يتجاوز عشرة أيام.\n -٤في جميع الجنح الحاصلة بين الزوجين قبل افتراقھما قانونا ً إو الحاصلة بين األصول والفروع،\n أو بين األب واألم والولد المتبنى."}, {"o": 31, "l": "المادة ١٢٢", "b": "-٥في الجنح المنصوص عنھا في المواد ٦٥٠و ٦٥١و ٦٥٨و ٦٦٦والفقرة األولى من"}, {"o": 32, "l": "المادة ٦٦٧", "b": "المادة\n ٦٦٧و ٦٧٠و ٦٧١و٦٧٣\n نص الفقرة) (٥من"}, {"o": 33, "l": "المادة ١٣٣", "b": "المادة ١٣٣من قانون العقوبات قبل التعديل بموجب القانون رقم ٨٧تاريخ ٢٠١٠/٣/٦\n -٥في الجنح المنصوص عليھا في المواد ٦٤٧و ٦٥٠و ٦٥١و ٦٥٨و ٦٧٠و ٦٧١و.٦٧٣\nوفي الجرائم المبينة في الفقرة السابقة ،وعند تعدد المدعى عليھم يؤدي إسقاط الحق الشخصي عن أحدھم إلى إسقاط الحق العام\n عن جميع المدعى عليھم في الجرم نفسه .أما في سائر الجرائم فللمدعي الشخصي أن يحصر إسقاطه لحقوقه الشخصية بواحد\nأو أكثر من المدعى عليھم دون أن يؤثر ھذا اإلسقاط على دعوى الحق العام وإنما تترتب النتائج القانونية المنصوص عليھا في"}, {"o": 34, "l": "المادة ٣٢", "b": "المادة ٣٢من قانون الموجبات والعقود.\n المادة -١٣٤معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\nإن األشياء القابلة للمصادرة بموجب"}, {"o": 35, "l": "المادة ٦٩", "b": "المادة ٦٩يمكن الحكم بھا للمدعي الشخصي بناء على طلبه،\n من أصل ما يتوجب له من عطل وضرر وبمقدارھما.\n إذا كان الشيء الذي تقرر مصادرته لم يضبط فللقاضي أن يقضي -بناء على طلب المدعي\nالشخصي -بتأديته تحت طائلة الغرامة االكراھية المنصوص عليھا في"}, {"o": 36, "l": "المادة ٢٥١", "b": "المادة ٢٥١من قانون العقود\n والموجبات أو أن يحكم على المجرم بدفع بدل المثل.\n المادة -١٣٥يمكن القاضي إذا طلب المدعي الشخصي وكانت مصلحته توجب ذلك أن يأمر\n بنشر الحكم برمته أو بنشر خالصة عنه في جريدة أو عدة جرائد على نفقة المحكوم عليه.\n ويمكنه إذا طلب الظنين وكانت مصلحته توجب ذلك أن يأمر بنشر حكم البراءة في الشروط نفسھا\n على نفقة المدعي الشخصي إذا تبين أنه تجاوز في دعواه.\n\f المادة -١٣٦معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥\n النفقات على عاتق الفريق الخاسر.\n ً\n إذا تعدد المحكوم عليھم وجبت عليھم الرسوم أقساما متساوية إال أن يقرر القاضي خالف ذلك.\n تبقى جميع النفقات التي ال تفيد الدعوى على عاتق من سببھا دون سواه وإن لم يكن خاسراً.\n ال يمس ذلك أحكام قانون التجارة الخاصة بدعوى اإلفالس.\n تطبق النيابة العامة قاعدة التقسيط الواردة في"}, {"o": 37, "l": "المادة ٥٣", "b": "المادة ٥٣على الرسوم والنفقات القضائية.\n ويحكم بإعفاء الشاكي أو المدعي من الرسوم والنفقات إذا كانت الجريمة التي سببت التحقيق قد\n وقعت فعالً ولكن التحقيق لم يتمكن من معرفة فاعلھا.\n وفي حالة وفاة المحكوم عليه أو غيبته أو قصره فتحصل الرسوم والنفقات بمعرفة وزارة المالية\n وفقا ً لقاعدة تحصيل األموال األميرية.\n المادة -١٣٧إن المدعي الشخصي الذي أسقط دعواه في خالل األربع وعشرين ساعة ال يلزم\n بالنفقات التي صرفت منذ إبالغ النيابة العامة والمدعى عليه ھذا اإلسقاط.\n إن النفقات التي أوجبتھا دعوى حق شخصي تقرر عدم قبولھا يبقى منھا على عاتق المدعي\n الشخصي ما لم يفد القضية.\n النبذة -٢أحكام مشتركة\n المادة -١٣٨كل جريمة تلحق بالغير ضرراً ماديا ً كان أو معنويا ً تلزم الفاعل بالتعويض.\n تجب االلزامات المدنية على فاعل الجريمة الذي استفاد من أحد أسباب اإلعفاء.\n المادة -١٣٩معدلة وفقا للمرسوم االشتراعي ١١٩تاريخ١٩٨٣/٩/١٦\n المجنون الذي ارتكب الجريمة دون تمييز ال يلزم بالعطل والضرر إال إذا لم يكن ثمة شخص تقع\nعليه تبعة عمله أو كان ھذا الشخص غير ذي مالءة فيقدر القاضي العطل والضرر مراعيا ً في ذلك\n حالة الفريقين على ما ورد في"}, {"o": 38, "l": "المادة ١٢٢", "b": "المادة ١٢٢فقرتھا األخيرة من قانون الموجبات والعقود.\nالمادة -١٤٠الجريمة المقترفة في حالة االضطرار تلزم مدنيا ً من حصلت لمنفعته بقدر الضرر\n الذي اتقاه.\n\f المادة -١٤١موجب الرد ال يتجزأ.\n يتحمل االلزامات المدنية األخرى بالتضامن جميع األشخاص الذين حكم عليھم من أجل جريمة\n واحدة.\n ال يشمل التضامن الجرائم المتالزمة إال إذا اقترفت لغرض مشترك.\nوال يشمل التضامن النفقات ما لم يكن المحكوم عليھم من أجل جريمة واحدة قد حوكموا في الدعوى\n نفسھا وللقاضي في كل حال أن يعفي من التضامن المحكوم عليھم بالنفقات.\n المادة -١٤٢يدعى المسؤولون مدنيا ً إلى المحاكمة ويلزمون متضامنين مع فاعل الجريمة\nبالردود والنفقات المتوجبة للدولة ،ويحكم عليھم بسائر االلزامات المدنية إذا طلب المدعي الشخصي\n ذلك.\n المادة -١٤٣لمحكمة الجنح ولمحكمة االستئناف الجزائية عندما تنظران في إحدى الجنح\n المنصوص عليھا في فصلي التقليد واإلفالس ولمحكمة الجنايات الناظرة في أية جريمة كانت أن\n تحكم على الظنين أو المتھم عند قضائھا بالتبرئة بجميع االلزامات المدنية التي يطلبھا الفريق\n المتضرر إذا كان الفعل يؤلف جرما ً مدنيا ً أو شبه جرم مدني.\n المادة -١٤٤إذا اجتمعت الغرامة وااللزامات المدنية وكانت أمالك المحكوم عليه غير وافية\n جرى توزيع المال المحصل وفقا ً للترتيب التالي:\n -١االلزامات المدنية المحكوم بھا لمصلحة الفريق المتضرر.\n -٢النفقات المتوجبة للدولة.\n -٣الغرامة.\n المادة -١٤٥يمكن أداء العطل والضرر والنفقات أقساطا ً وفاقا ً ألحكام"}, {"o": 39, "l": "المادة ٣٠٠", "b": "المادة ٣٠٠من قانون\n العقود والموجبات.\n المادة -١٤٦معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥\n يمكن اللجوء إلى الحبس اإلكراھي عمالً بقانون المحاكمات المدنية تنفيذا لاللزامات المدنية غير\n ً\n النشر في الجرائد ورد ما حكم برده.\n وفي حالة الحكم بالتضامن ال يجوز حبس المحكوم عليه إال عن الجزء الذي يصيبه يوقف\n المحبوسون إكراھيا ً في أمكنة خاصة.\n\f الفصل الخامس -في سقوط الأحكام الجزائية\n النبذة -١أحكام عامة\n المادة -١٤٧معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n إن األسباب التي تسقط األحكام الجزائية أو تمنع أو تعلق تنفيذھا ھي التالية:\n -١وفاة المحكوم عليه.\n -٢العفو العام.\n -٣العفو الخاص.\n -٤ملغاة.\n -٥إعادة االعتبار.\n -٦مرور الزمن.\n -٧وقف التنفيذ.\n -٨ملغاة.\nفيما خال إعادة االعتبار ،يقرر النائب العام االستئنافي إسقاط األحكام الصادرة في نطاق صالحيته.\n المادة -١٤٨إن األسباب التي تسقط األحكام الجزائية أو تمنع تنفيذھا أو تعلقھا ال مفعول لھا\n على االلزامات المدنية التي تبقى خاضعة ألحكام قانون الموجبات والعقود.\n النبذة -٢في وفاة المحكوم عليه\n المادة -١٤٩تزول جميع نتائج الحكم الجزائية بوفاة المحكوم عليه.\n\f وتحول دون استيفاء الغرامات ونشر وإلصاق الحكم المقضي بھما وفاقا ً للمادتين ٦٧و.٦٨\nوال مفعول لھا على المصادرة الشخصية إذا كانت األشياء المصادرة قد حكم بھا للمدعي الشخصي\n وال على المصادرة العينية وال على إقفال المحل عمالً بالمادة .١٠٤\n النبذة -٣في العفو العام\n المادة -١٥٠يصدر العفو العام عن السلطة االشتراعية.\n ويسقط كل عقوبة أصلية كانت أو فرعية إضافية.\n وال يشمل التدابير االحترازية والتدابير اإلصالحية إال إذا نص قانون العفو صراحة على ذلك.\n ال ترد الغرامات المستوفاة واألشياء المصادرة بمقتضى المادة .٦٩\n المادة -١٥١ملغاة وفقا للقانون تاريخ ١٩٤٨/٢/٥\n النبذة -٤في العفو الخاص"}, {"o": 40, "l": "المادة ٣٠٠", "b": "المادة -١٥٢يمنح العفو الخاص رئيس الدولة بعد استطالع رأي لجنة العفو.\n ال يمكن للمحكوم عليه أن يرفض االستفادة من العفو.\n يمكن أن يكون العفو شرطيا ً وأن يناط بموجب واحد من الموجبات المعينة في"}, {"o": 41, "l": "المادة ١٧٠", "b": "المادة ١٧٠أو\n بأكثر.\n إذا كان الفعل المقترف جناية وجب التعويض على المدعي الشخصي بمقتضى الفقرة الثالثة من"}, {"o": 42, "l": "المادة ١٧٠", "b": "المادة ١٧٠في مھلة أقصاھا ثالث سنوات.\n المادة -١٥٣العفو الخاص شخصي ويمكن أن يكون بإبدال العقوبة أو بإسقاط مدة العقوبة أو\n التدبير االحترازي أو بتخفيضھا كليا ً أو جزئيا ً.\n\f وال يشمل العفو العقوبات الفرعية أو اإلضافية والتدابير االحترازية المقضي بھا باإلضافة إلى\n عقوبة أصلية إال بموجب نص صريح في المرسوم الذي يمنحه.\n المادة -١٥٤ال ينال العفو من لم يكن قد حكم عليه حكما ً مبرما ً.\n ال يحول وقف التنفيذ ووقف الحكم النافذ دون نيل العفو.\n المادة -١٥٥إسقاط العقوبة أو التدبير االحترازي بمثابة تنفيذھما.\nيستمر مفعول العقوبة المسقطة أو المستبدلة لتطبيق األحكام المتعلقة بوقف التنفيذ ووقف الحكم النافذ\n وإعادة االعتبار والتكرار واعتياد اإلجرام.\n المادة -١٥٦يفقد منحة العفو كل محكوم عليه أقدم ثانية على ارتكاب جريمة تعرضه لعقوبات\n التكرار أو ثبت عليه بحكم قضائي إنه أخل بأحد الواجبات التي تفرضھا المادة .١٥٢\n النبذة -٥في صفح الفريق المتضرر\n المادة -١٥٧ملغاة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n المادة -١٥٨ملغاة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n النبذة -٦في إعادة الاعتبار\n\f المادة -١٥٩كل محكوم عليه بعقوبة جنائية أو جناحية يمكن منحه إعادة االعتبار بقرار قضائي\n إذا وفى الشروط التالية:\n (١أن يكون قد انقضى سبع سنوات في الجناية وثالث سنوات في الجنحة على تنفيذه العقوبة وما\n قد يالزمھا من تدبير احترازي مانع للحرية أو على سقوطھا عنه بمرور الزمن.\nإذا كانت العقوبة المقضي بھا ھي التجريد المدني جرت المدة منذ اليوم الذي أصبح فيه القرار مبرما ً\n وعند الحكم بالحبس اإلضافي منذ انقضاء أجل ھذه العقوبة.\n إذا كانت العقوبة المقضي بھا ھي الغرامة جرت المدة منذ يوم األداء أو انقضاء أجل الحبس\n المستبدل.\n ً\n إذا كان المحكوم عليه مكررا بالمعنى القانوني أو سبق له أن منح إعادة االعتبار ضوعفت المدة."}, {"o": 43, "l": "المادة ١٧٠", "b": "(٢أال يكون صدر بحقه حكم الحق بعقوبة جنائية أو جناحية.\n كل حكم الحق بإحدى ھاتين العقوبتين يقطع مجرى المدة.\n (٣إن تكون االلزامات المدنية التي ينطوي عليھا الحكم قد نفذت أو أسقطت أو مر عليھا الزمن أو\n أن يثبت المحكوم عليه أنه كان في حالة لم يتمكن معھا من القيام بتلك االلزامات.\n على المفلس أن يثبت انه قضى الدين أصالً وفائدة ونفقات أو أنه أعفي منه.\n (٤أن يتبين من سجالت السجن ومن تحقيق عن سيرة المحكوم عليه بعد اإلفراج عنه أنه صلح\n فعالً.\n المادة -١٦٠كل محكوم عليه بعقوبة جناحية مانعة أو مقيدة للحرية يعاد اعتباره حكما ً إذا لم\n يقض عليه في خالل سبع سنوات منذ انقضاء عقوبته بحكم آخر بالحبس أو باإلقامة الجبرية أو\n بعقوبة أشد.\n ً\nكل محكوم عليه بالغرامة الجناحية يعاد اعتباره حكما إذا لم يقض عليه بحكم آخر بالغرامة الجناحية\n أو بعقوبة أشد في خالل خمس سنوات منذ األداء أو انتھاء مدة الحبس المستبدل.\n المادة -١٦١إعادة االعتبار تبطل للمستقبل مفاعيل جميع األحكام الصادرة وتسقط العقوبات\n الفرعية أو اإلضافية والتدابير االحترازية وما ينجم عنھا من فقدان أھلية.\n وال يمكن أن تحسب األحكام المذكورة فيما بعد للتكرار والعتياد اإلجرام أو أن تحول دون وقف\n التنفيذ.\n النبذة -٧في مرور الزمن\n\f المادة -١٦٢معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n مرور الزمن يحول دون تنفيذ العقوبات وتدابير االحتراز.\nعلى أن مرور الزمن ال يسري على العقوبات والتدابير االحترازية المانعة من الحقوق أو على منع\n اإلقامة والمصادرة العينية.\nمجرد صدور حكم في الدعوى ولو كان في الدرجة األولى يوقف مجرى مرور الزمن على دعوى\n الحق العام فال يعود يسري إال وفقا ً ألحكام"}, {"o": 44, "l": "المادة ١٦٣", "b": "المادة ١٦٣وما يليھا من قانون العقوبات.\n المادة -١٦٣معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n مدة مرور الزمن على عقوبة اإلعدام والعقوبات الجنائية المؤبدة خمس وعشرون سنة.\n مدة مرور الزمن على العقوبات الجنائية المؤقتة ضعف مدة العقوبة التي حكمت بھا المحكمة وال\n يمكن أن تجاوز عشرين سنة أو تنقص عن عشر سنوات.\nمدة مرور الزمن على أية عقوبة جنائية أخرى عشر سنوات وتطبق ھذه المدة أيضا ً على أية عقوبة\n جناحية قضي بھا من أجل جناية.\n يجري مرور الزمن من تاريخ الحكم إذا صدر غيابيا ً ومن تاريخ إنبرامه إذا صدر وجاھيا ً ولم يكن\n المحكوم عليه موقوفا ً وإال من يوم تملصه من التنفيذ.\n إذا تملص المحكوم عليه من تنفيذ عقوبة مانعة أو مقيدة للحرية أسقط نصف مدة العقوبة التي نفذت\n فيه مدة من مرور الزمن.\n المادة -١٦٤معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥\nمدة مرور الزمن على العقوبات الجناحية ضعف مدة العقوبة التي حكمت بھا المحكمة وال يمكن أن\n تجاوز عشر سنوات وتنقص عن خمس سنوات.\n مدة مرور الزمن على أي عقوبة جناحية أخرى خمس سنوات.\n تجري مدة مرور الزمن:\n في الحكم الوجاھي من تاريخ صدوره إذا كان في الدرجة األخيرة ،ومن تاريخ انبرامه إذا كان في\n الدرجة األولى.\n وفي الحكم الغيابي منذ تبليغ المحكوم علي بذاته أو في محل إقامته.\n وإذا كان المحكوم عليه موقوفا ً فمن يوم تفلته من التنفيذ ،وفي ھذه الحالة يسقط نصف مدة العقوبة\n التي نفذت فيه من مدة مرور الزمن.\nالمادة -١٦٥مدة مرور الزمن على عقوبات المخالفات سنتان تبدآن على نحو ما ذكر في المادة\n السابقة.\n المادة -١٦٦مدة مرور الزمن على التدابير االحترازية ثالث سنوات.\n\f ال يبدأ مرور الزمن إال منذ اليوم الذي أصبح فيه التدبير االحترازي نافذاً عمالً بالمادتين ١١٥و\n ١١٦أو بعد مرور الزمن على العقوبة التي كان ھذا التدبير مالزما ً لھا ،وكل ذلك ما لم يصدر عن"}, {"o": 45, "l": "المادة ١٦٣", "b": "القاضي قبل انقضاء سبع سنوات كما سبق قرار يثبت أن المحكوم عليه لم يزل خطراً على السالمة\n العامة ،ففي ھذه الحالة يؤمر بأن يصار إلى تنفيذ التدبير االحترازي.\n المادة -١٦٧ملغاة وفقا للمرسوم االشتراعي ١١٩تاريخ١٩٨٣/٩/١٦\n المادة -١٦٨يحسب مرور الزمن من يوم إلى مثله من دون اليوم األول.\nيوقف مرور الزمن كل حائل قانوني أو مادي حال دون تنفيذ العقوبة أو التدبير ولم ينشأ عن إرادة\n المحكوم عليه .ويقطع مرور الزمن:\n (١حضور المحكوم عليه أو أي عمل تجريه السلطة بغية التنفيذ.\n (٢ارتكاب المحكوم عليه جريمة أخرى معادلة للجريمة التي أوجبت العقوبة أو التدبير أو جريمة\n أھم.\n على أنه ال يمكن أن تطول مدة مرور الزمن في كل حال إلى أكثر من ضعفيھا.\n النبذة -٨في وقف التنفيذ\nالمادة -١٦٩للقاضي عند القضاء بعقوبة جناحية أو تكديرية أن يأمر بوقف تنفيذھا إذا لم يسبق\n أن قضي على المحكوم عليه بعقوبة من نوعھا أو أشد.\n ال يمنح المحكوم عليه وقف التنفيذ إذا لم يكن له في لبنان محل إقامة حقيقي أو إذا تقرر طرده\n قضائيا ً أو إداريا ً.\n ال يعلق وقف التنفيذ العقوبات اإلضافية أو الفرعية أو تدابير االحتراز.\n المادة -١٧٠للقاضي أن ينيط وقف التنفيذ بواجب أو أكثر من الواجبات اآلتية:\n (١أن يقدم المحكوم عليه كفالة احتياطية.\n (٢أن يخضع للرعاية.\n (٣أن يحصل المدعي الشخصي على تعويضه كله أو بعضه في مدة ال تتجاوز السنتين في الجنحة\n أو الستة أشھر في المخالفة.\n\f المادة -١٧١معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥\n يفقد منحة وقف التنفيذ كل شخص أقدم في مدة خمس سنوات أو سنتين حسبما يكون قد حكم عليه\n بعقوبة جناحية أو تكديرية على ارتكاب جريمة أخرى يقضى عليه من أجلھا بعقوبة من النوع نفسه\n أو بعقوبة أشد أو ثبت عليه بحكم أنه خرق الواجبات التي فرضھا القاضي بمقتضى المادة السابقة."}, {"o": 46, "l": "المادة ١٦٣", "b": "المادة -١٧٢إذا لم ينقض وقف التنفيذ عد الحكم عند انقضاء مدة التجربة الغياً ،وال يبقى\n مفعول للعقوبات اإلضافية والتدابير االحترازية ما خال الحجز في مأوى احترازي والمصادرة\n العينية وإقفال المحل المنصوص عليه في المادة .١٠٤\nعلى أن وقف التنفيذ يمكن نقضه ولو بعد انقضاء مدة التجربة إذا كانت قد بوشرت دعوى النقض أو\n مالحقة الجريمة الجديدة قبل انقضاء المدة المذكورة.\n النبذة -٩في وقف الحكم النافذ\n المادة -١٧٣معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥\n المادة -١٧٤أن وقف الحكم النافذ ال يمكن منحه إذا كان ثمة تدبير احترازي مانع للحرية يجب\n تنفيذه بالمحكوم عليه بعد انقضاء مدة عقوبته وال فعل له في العقوبات الفرعية واإلضافية.\n يبقى المحكوم عليه باألشغال الشاقة وباالعتقال في حالة الحجر حتى انقضاء عقوبته إال أن يقرر\n القاضي خالف ذلك.\n المادة -١٧٥ملغاة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n المادة -١٧٦ملغاة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n المادة -١٧٧ملغاة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n\f المادة -١٧٨ملغاة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n الباب الثالث -في الجريمة\n الفصل الأول -في عنصر الجريمة القانوني\n النبذة -١في الوصف القانوني\nالمادة -١٧٩الجريمة جناية أو جنحة أو مخالفة حسبما يعاقب عليھا بعقوبة جنائية أو جناحية أو\n تكديرية.\n يعتبر في الوصف القانوني الحد األعلى للعقوبة األشد المنصوص عليھا قانونا ً.\n المادة -١٨٠معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\nال يتغير الوصف القانوني إذا أبدلت من العقوبة المنصوص عليھا عقوبة أخف عند األخذ باألسباب\n المخففة أو األعذار المخففة.\n النبذة -٢في اجتماع الجرائم المعنوي\n\f المادة -١٨١إذا كان للفعل عدة أوصاف ذكرت جميعھا في الحكم على أن يحكم القاضي\n بالعقوبة األشد."}, {"o": 47, "l": "المادة ١٦٣", "b": "على أنه إذا انطبق على الفعل نص عام من الشريعة الجزائية ونص خاص أخذ بالنص الخاص.\n المادة -١٨٢ال يالحق الفعل الواحد إال مرة واحدة.\n ً\nغير أنه إذا تفاقمت نتائج الفعل الجرمية بعد المالحقة األولى فأصبح قابال لوصف أشد لوحق بھذا\n الوصف وأنفذت العقوبة األشد دون سواھا ،فإذا كانت العقوبة المقضي بھا سابقا ً قد أنفذت أسقطت\n من العقوبة الجديدة.\n النبذة -٣في أسباب التبرير\n ال يعد جريمة الفعل المرتكب في ممارسة حق بغير تجاوز. المادة -١٨٣\n المادة -١٨٤معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\nيعد ممارسة حق كل فعل قضت به ضرورة حالية لدفع تعرض غير محق وال مثار على النفس أو\n الملك أو نفس الغير أو ملكه ،ويستوي في الحماية الشخص الطبيعي والشخص المعنوي.\n إذا وقع تجاوز في الدفاع أمكن إعفاء فاعل الجريمة من العقوبة في الشروط المذكورة في المادة\n .٢٢٨\n المادة -١٨٥معدلة وفقا للقانون المنفذ بالمرسوم ١٥٧٣٩تاريخ ١٩٦٤ /٣ /١١\n ال يعد جريمة الفعل المرتكب انفاذاً لنص قانوني أو ألمر شرعي صادر عن السلطة.\n وإذا كان األمر الصادر غير شرعي برر الفاعل إذا لم يجز القانون له أن يتحقق من شرعيته.\n يعتبر أيضا ً من األوامر الشرعية األمر الخطي المعطى من:\n -١رئيس ھيئة التفتيش القضائي.\n -٢رئيس ھيئة التفتيش المركزي.\n -٣مدير عام قوى األمن الداخلي.\n -٤مدير عام األمن العام.\n كل ضمن صالحيته.\n\f إلى موظف بالتظاھر في اإلسھام في جريمة من جرائم الرشوة المعاقب عليھا في المواد من ٣٥١\nإلى ٣٥٦من قانون العقوبات بغية اكتشاف مرتكبي ھذه الجرائم ،شرط أن يكون مبرر ھذا اإلسھام\n ضبط ھذا النوع من الجرائم وأن ال يتعدى نشاط المكلف بھذا األمر الغاية المتوخاة.\n معدلة وفقا للقانون رقم ٢٨٦تاريخ ٢٠١٤/٤/٣٠\n المادة -١٨٦ال يعد جريمة الفعل الذي يجيزه القانون.\n يجيز القانون:"}, {"o": 48, "l": "المادة ١٦٣", "b": "(١أنواع التأديب غير العنفي التي يمارسھا اآلباء واألمھات على أوالدھم ،على أن ال تترك أي أثر\n على جسد األوالد أو تحدث ضرراً في صحتھم الجسدية أو النفسية.\n (٢العمليات الجراحية والعالجات الطبية المنطبقة على أصول الفن شرط أن تجري برضى العليل\n أو رضى ممثليه الشرعيين أو في حاالت الضرورة الماسة.\n (٣أعمال العنف التي تقع في أثناء األلعاب الرياضية إذا روعيت قواعد اللعب.\n البند ) (١من"}, {"o": 49, "l": "المادة ١٨٦", "b": "المادة ١٨٦من قانون العقوبات قبل الغائه بموجب القانون رقم ٢٨٦تاريخ ٢٠١٤/٤/٣٠\n (١ضروب التأديب التي ينزلھا باألوالد آباؤھم وأساتذتھم على نحو ما يبيحه العرف العام.\nالمادة -١٨٧إن الفعل الذي يعاقب عليه لتعرضه إلرادة الغير ال يعد جريمة إذا اقترف برضى\n منه سابق لوقوعه أو مالزم له.\n الفصل الثاني -في عنصر الجريمة المعنوي\n النبذة -١في النية\n المادة -١٨٨النية إرادة ارتكاب الجريمة على ما عرفھا القانون.\n المادة -١٨٩تعد الجريمة مقصودة وإن تجاوزت النتيجة الجرمية الناشئة عن الفعل أو عدم\n الفعل قصد الفاعل إذا كان قد توقع حصولھا فقبل بالمخاطرة.\n\f المادة -١٩٠يكون الخطأ إذا نجم الفعل الضار عن اإلھمال أو قلة االحتراز أو عدم مراعاة\n الشرائع واألنظمة.\nالمادة -١٩١تكون الجريمة غير مقصودة سواء لم يتوقع الفاعل نتيجة فعله أو عدم فعله أو عدم\n فعله المخطئين وكان في استطاعته أو من واجبه أن يتوقعھا وسواء توقعھا فحسب أن بإمكانه\n اجتنابھا.\n النبذة -٢في الدافع\n المادة -١٩٢معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n الدافع ھو العلة التي تحمل الفاعل على الفعل أو الغاية النھائية التي يتوخاھا.\n وال يكون عنصراً من عناصر التجريم إال في األحوال التي عينھا القانون.\n المادة -١٩٣معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n إذا تبين للقاضي أن الدافع كان شريفا ً قضى بالعقوبات التالية:\n -االعتقال المؤبد بدالً من اإلعدام.\n -االعتقال المؤبد أو لخمس عشرة سنة بدالً من األشغال الشاقة المؤبدة.\n -االعتقال المؤقت بدالً من األشغال الشاقة المؤقتة.\n -الحبس البسيط بدالً من الحبس مع التشغيل.\n وللقاضي فضالً عن ذلك أن يعفي المحكوم عليه من لصق الحكم ونشره المفروضين كعقوبة.\n ويكون الدافع شريفا ً إذا كان متسما ً بالمروءة والشھامة ومجرداً من األنانية واالعتبارات الشخصية\n والمنفعة المادية."}, {"o": 50, "l": "المادة ١٨٦", "b": "المادة -١٩٤إذا كانت الجريمة المعاقب عليھا باالعتقال المؤبد أو المؤقت أو بالحبس البسيط قد\n أوحى بھا دافع شائن أبدل القاضي:\n من االعتقال المؤبد األشغال الشاقة المؤبدة.\n من االعتقال المؤقت االشغال الشاقة المؤقتة.\n\f من الحبس البسيط الحبس مع التشغيل.\n المادة -١٩٥إذا اقترفت بدافع الكسب جريمة غير معاقب عليھا بالغرامة قضي بھذه العقوبة\n وبالعقوبة المنصوص عليھا في القانون معا ً.\n النبذة -٣في الجرائم السياسية\n المادة -١٩٦الجرائم السياسية ھي الجرائم المقصودة التي أقدم عليھا الفاعل بدافع سياسي.\n وھي كذلك الجرائم الواقعة على الحقوق السياسية العامة والفردية ما لم يكن الفاعل قد انقاد لدافع\n أناني دنيء.\n المادة -١٩٧تعد جرائم سياسية الجرائم المركبة أو المالزمة لجرائم سياسية ما لم تكن من أشد\n الجنايات خطورة من حيث األخالق والحق العام كالقتل والجرح الجسيم واالعتداء على األمالك\n إحراقا ً أو نسفا ً أو إغراقا ً والسرقات الجسيمة وال سيما ما ارتكب منھا بالسالح والعنف وكذلك\n الشروع في تلك الجنايات.\nأما في الحرب األھلية أو العصيان فال تعد الجرائم المركبة أو المتالزمة سياسية إال إذا كانت عادات\n الحرب ال تمنعھا ولم تكن من أعمال البربرية أو التخريب.\n المادة -١٩٨إذا تحقق القاضي أن للجريمة طابعا ً سياسيا ً قضى بالعقوبات التالية:\n االعتقال المؤبد بدالً من اإلعدام أو األشغال الشاقة المؤبدة.\n االعتقال المؤقت أو اإلبعاد أو اإلقامة الجبرية الجنائية أو التجريد المدني بدالً من األشغال الشاقة\n المؤقتة.\n الحبس البسيط أو اإلقامة الجبرية الجناحية بدالً من الحبس مع التشغيل.\n وال تطبق ھذه األحكام على الجرائم الواقعة على أمن الدولة الخارجي.\nالمادة -١٩٩إذا تحقق القاضي أن الجريمة المعاقب عليھا بعقوبة سياسية قد ارتكبت بدافع أناني\n دنيء أبدل من العقوبة المنصوص عليھا قانونا ً العقوبة التي تقابلھا في المادة السابقة."}, {"o": 51, "l": "المادة ١٨٦", "b": "على أن االعتقال المؤبد ال يمكن تحويله إلى غير أشغال شاقة مؤبدة.\n\f الفصل الثالث -في عنصر الجريمة المادي\n النبذة -١في المحاولة\n المادة -٢٠٠معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥\nكل محاولة الرتكاب جناية بدأت بأفعال ترمي مباشرة إلى اقترافھا تعتبر كالجناية نفسھا إذا لم يحل\n دون إتمامھا سوى ظروف خارجة عن إرادة الفاعل.\n على أنه يمكن أن تخفض العقوبات المعينة في القانون على الوجه اآلتي:\nيمكن أن تستبدل عقوبة اإلعدام باألشغال الشاقة المؤبدة أو باألشغال الشاقة المؤقتة من سبع سنوات\n إلى عشرين سنة.\n وأن تستبدل األشغال الشاقة المؤبدة باألشغال الشاقة المؤقتة لخمس سنوات على األقل.\n وأن يستبدل االعتقال المؤبد باالعتقال المؤقت لخمس سنوات على األقل.\n ويمكن أن يحط من أي عقوبة أخرى من النصف إلى الثلثين.\n ومن شرع في فعل ورجع عنه مختاراً ال يعاقب إال لألفعال التي اقترفھا وكانت تشكل بحد ذاتھا\n جرائم.\n المادة -٢٠١معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥\n إذا كانت جميع األعمال الرامية إلى اقتراف جناية قد تمت غير أنھا لم تفض إلى مفعول بسبب\n ظروف ال عالقة لھا بإرادة الفاعل أمكن تخفيض العقوبات على الوجه األتي:\n يمكن أن يستبدل اإلعدام باألشغال الشاقة المؤبدة أو المؤقتة من عشر سنوات إلى عشرين سنة.\n و ان تستبدل االشغال الشاقة المؤبدة باالشغال الشاقة المؤقتة من سبع سنوات الى عشرين سنة.\nوأن يستبدل االعتقال المؤبد باالعتقال المؤقت من سبع سنوات إلى عشرين سنة ويمكن أن يحط من\n اي عقوبة أخرى حتى نصفھا.\n يمكن أن تخفض العقوبات المذكورة في ھذه المادة حتى الثلثين إذا حال الفاعل بمحض إرادته دون\n نتيجة فعله.\n\f المادة -٢٠٢معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\nال يعاقب على المحاولة في الجنحة وعلى الجنحة الخائبة إال في الحاالت التي ينص عليھا القانون\n صراحة."}, {"o": 52, "l": "المادة ١٨٦", "b": "العقوبة المفروضة للجنحة التامة يمكن تخفيضھا حتى النصف في محاولة الجنحة وحتى الثلث في\n الجنحة الخائبة.\n المادة -٢٠٣معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\nيعاقب على المحاولة وإن لم يكن في اإلمكان بلوغ الھدف بسبب ظرف مادي يجھله الفاعل على أن\n الفاعل ال يعاقب في ھذه الحالة إذا أتى فعله عن غير فھم.\n وكذلك ال يعاقب من ارتكب فعالً وظن خطأ أنه يكون جريمة.\n النبذة -٢في اجتماع الأسباب\n المادة -٢٠٤إن الصلة السببية بين الفعل وعدم الفعل من جھة وبين النتيجة الجرمية من جھة\n ثانية ال ينفيھا اجتماع أسباب أخرى سابقة أو مقارنة أو الحقة سواء جھلھا الفاعل أو كانت مستقلة\n عن فعله.\n ً\n ويختلف األمر إذا كان السبب الالحق مستقال وكافيا ً بذاته ألحداث النتيجة الجرمية.\n وال يكون الفاعل في ھذه الحالة عرضة إال لعقوبة الفعل الذي ارتكبه.\n النبذة -٣في اجتماع الجرائم المادي\n المادة -٢٠٥إذا ثبتت عدة جنايات أو جنح قضى بعقوبة لكل جريمة ونفذت العقوبة األشد دون\n سواھا.\nعلى أن يمكن الجمع بين العقوبات المحكوم بھا بحيث ال تزيد مجموع العقوبات المؤقتة على أقصى\n العقوبة المعينة للجريمة األشد إال بمقدار نصفھا.\n\f إذا لم يكن قد قضي بإدغام أو بجمع العقوبات المحكوم بھا أحيل األمر على القاضي ليفصله.\n المادة -٢٠٦إذا وقعت الجريمة على غير الشخص المقصود بھا عوقب الفاعل كما لو كان\n اقترف الفعل بحق من كان يقصد.\n وإذا أصيب كالھما أمكن زيادة النصف على العقوبة المذكورة في الفقرة السابقة.\n المادة -٢٠٧تجمع العقوبات التكديرية حتما ً.\nالمادة -٢٠٨تجمع العقوبات اإلضافية والتدابير االحترازية وإن أدغمت العقوبات األصلية ما\n لم يقض القاضي بخالف ذلك.\n إذا اجتمعت العقوبات األصلية جمعت حكما ً العقوبات الفرعية التابعة لھا.\n النبذة -٤في النشر\n المادة -٢٠٩تعد وسائل نشر:"}, {"o": 53, "l": "المادة ١٨٦", "b": "-١األعمال والحركات إذا حصلت في محل عام أو مكان مباح للجمھور أو معرض لألنظار أو\n شاھدھا بسبب خطأ الفاعل من ال دخل له بالفعل.\n -٢الكالم أو الصراخ سواء جھر بھما أو نقال بالوسائل اآللية بحيث يسمعھا في كال الحالين من ال\n دخل له بالفعل.\n -٣الكتابة والرسوم والصور اليدوية والشمسية واألفالم والشارات والتصاوير على اختالفھا اذا\n عرضت في محل عام أو مكان مباح للجمھور أو معرض لألنظار أو بيعت أو عرضت للبيع أو\n وزعت على شخص أو أكثر.\n الباب الرابع -في التبعة\n\f القسم الأول -في الأشخاص المسؤولين\n الفصل الأول -في فاعل الجريمة\n المادة -٢١٠ال يحكم على أحد بعقوبة ما لم يكن قد أقدم على الفعل عن وعي وإرادة.\n إن الھيئات المعنوية مسؤولة جزائيا ً عن أعمال مديريھا وأعضاء إدارتھا وممثليھا وعمالھا عندما\n يأتون ھذه األعمال باسم الھيئات المذكورة أو بإحدى وسائلھا ،ال يمكن الحكم عليھا إال بالغرامة\n والمصادرة ونشر الحكم.\nإذا كان القانون ينص على عقوبة أصلية غير الغرامة أبدلت الغرامة من العقوبة المذكورة وأنزلت\n بالھيئات المعنوية في الحدود المعينة في المواد ٥٣و ٦٠و .٦٣\n المادة -٢١١ال ينزل بأحد تدبير احترازي ما لم يكن خطراً على السالم العام.\nيقضي بالتدابير االحترازية بعد التثبت من حالة الخطر إال في الحاالت التي يفترض القانون وجود\n الخطر فيھا.\n يعد خطراً على المجتمع كل شخص أو ھيئة معنوية اقترف جريمة إذا كان يخشى أن يقدم على\n أفعال أخرى يعاقب عليھا القانون.\n ال تتعرض الھيئات المعنوية لغير تدابير االحتراز العينية.\n الفصل الثاني -في الاشتراك الجرمي\n النبذة -١في الفاعل\n\fالمادة -٢١٢فاعل الجريمة ھو من أبرز إلى حيز الوجود العناصر التي تؤلف الجريمة أو ساھم\n مباشرة في تنفيذھا.\n المادة -٢١٣كل شريك في الجريمة عرضة للعقوبة المعينة لھا في القانون.\nتشدد وفاقا ً للشروط الواردة في"}, {"o": 54, "l": "المادة ٢٥٧", "b": "المادة ٢٥٧عقوبة من نظم أمر المساھمة في الجريمة أو أدار عمل\n من اشتركوا فيھا.\n المادة -٢١٤الشريكان في الجريمة المقترفة بالكالم المنقول بالوسائل اآللية ،على ما ورد في\n الفقرة الثانية من المادة ،٢٠٩أو في الجريمة المقترفة بإحدى الوسائل المذكورة في الفقرة الثالثة\n من المادة نفسھا ھما صاحب الكالم أو الكتابة والناشر إال أن يثبت األول أن النشر تم دون رضاه.\n المادة -٢١٥عندما تقترف الجريمة بواسطة الصحف يعد ناشراً مدير الغش ،فإذا لم يكن من\n مدير فالمحرر أو رئيس تحرير الصحيفة.\n المادة -٢١٦مفاعيل األسباب المادية التي من شأنھا تشديد العقوبة أو تخفيفھا أو اإلعفاء منھا\n تسري على كل من الشركاء في الجريمة والمتدخلين فيھا ،وتسري عليھم أيضا ً مفاعيل الظروف\n المشددة الشخصية أو المزدوجة التي سھلت اقتراف الجريمة.\n وأما ما سوى ذلك من الظروف فال يتناول مفعولھا إال الشخص الذي تتعلق به.\n النبذة -٢في المحرض\n المادة -٢١٧يعد محرضا ً من حمل أو حاول أن يحمل شخصا ً آخر بأي وسيلة كانت على\n ارتكاب جريمة.\n\f إن تبعة المحرض مستقلة عن تبعة المحرض على ارتكاب الجريمة.\nالمادة -٢١٨يتعرض المحرض لعقوبة الجريمة التي أراد أن تقترف سواء كانت الجريمة ناجزة\n أو مشروعا ً فيھا أو ناقصة.\n إذا لم يفض التحريض على ارتكاب جناية أو جنحة إلى نتيجة خففت العقوبة بالنسبة التي حددتھا"}, {"o": 55, "l": "المادة ٢٢٠", "b": "المادة ٢٢٠في الفقرات .٢،٣،٤\n التحريض على ارتكاب مخالفة ال يعاقب عليھا إذا لم يلق قبوالً.\n تنزل التدابير االحترازية بالمحرض كما لو كان فاعل الجريمة.\n النبذة -٣في المتدخلين والمخبئين\n المادة -٢١٩معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n يعد متدخالً في جناية أو جنحة.\n -١من أعطى إرشادات القترافھا وإن لم تساعد ھذه اإلرشادات على الفعل.\n -٢من شدد عزيمة الفاعل بوسيلة من الوسائل.\n -٣من قبل ،ابتغاء لمصلحة مادية أو معنوية ،عرض الفاعل أن يرتكب الجريمة.\n -٤من ساعد الفاعل أو عاونه على األفعال التي ھيأت الجريمة أو سھلتھا.\n -٥من كان متفقا ً مع الفاعل أو أحد المتدخلين قبل ارتكاب الجريمة وساھم في إخفاء معالمھا أو\n تخبئة أو تصريف األشياء الناجمة عنھا ،أو إخفاء شخص أو أكثر من الذين اشتركوا فيھا عن وجه\n العدالة.\n ً\n -٦من كان عالما بسيرة األشرار الجنائية الذين دأبھم قطع الطرق أو ارتكاب أعمال العنف ضد أمن\nالدولة أو السالمة العامة ،أو ضد األشخاص أو الممتلكات وقدم لھم طعاما ً أو مأوى أو مخبأ أو مكانا ً\n لالجتماع.\n المادة -٢٢٠المتدخل الذي لوال مساعدته ما ارتكبت الجريمة يعاقب كما لو كان ھو نفسه\n الفاعل.\n أما سائر المتدخلين فيعاقبون باألشغال الشاقة المؤبدة أو المؤقتة من عشر سنوات إلى عشرين سنة\n إذا كان الفاعل يعاقب باإلعدام.\nوإذا كان عقاب الفاعل األشغال الشاقة المؤبدة أو االعتقال المؤبد حكم على المتدخلين بالعقوبة نفسھا\n من سبع سنوات إلى خمس عشر سنة.\n وفي الحاالت األخرى تنزل بھم عقوبة الفاعل بعد أن تخفض مدتھا من السدس حتى الثلث.\n\f ويمكن إنزال التدابير االحترازية بھم كما لو كانوا ھم أنفسھم فاعلي الجريمة.\n المادة -٢٢١معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\nمن أقدم ،فيما خالل الحالة المنصوص عليھا في الفقرة الخامسة من"}, {"o": 56, "l": "المادة ٢١٩", "b": "المادة ٢١٩وھو عالم باألمر،\n على إخفاء أو تصريف األشياء الداخلة في ملكية الغير ،والتي نزعت أو اختلست أو حصل عليھا\n بجناية أو جنحة ،عوقب بالحبس من ثالثة أشھر إلى سنتين وبالغرامة من عشرين ألف ليرة إلى\n أربعمائة ألف ليرة.\n على أنه إذا كانت األشياء المخفية أو المصرفة ناجمة عن جنحة ،فال يمكن أن تتجاوز العقوبة ثلثي\n الحد األعلى لعقوبة الجنحة المذكورة.\n المادة -٢٢٢من أقدم فيما خال الحاالت المنصوص عليھا في الفقرتين ٥و ٦من"}, {"o": 57, "l": "المادة ٢١٩", "b": "المادة\n ٢١٩على إخفاء شخص يعرف أنه اقترف جناية ،أو ساعده على التواري عن وجه العدالة ،عوقب\n بالحبس من ثالثة أشھر إلى سنتين.\n يعفى من العقوبة أصول الجناة المختبئين أو فروعھم أو أزواجھم أو زوجاتھم حتى الطالقات ،أو\n أشقاؤھم أو شقيقاتھم أو أصھارھم من الدرجات نفسھا.\n القسم الثاني -في مانع العقاب\n الفصل الأول -في الغلط\n النبذة -١في الغلط القانوني\n المادة -٢٢٣ال يمكن أحد أن يحتج بجھله الشريعة الجزائية أو تأويله إياھا تأويالً مغلوطا ً فيه.\n\f غير انه يعد مانعا ً للعقاب:\n -١الجھل أو الغلط الواقع على شريعة مدنية أو إدارية يتوقف عليھا فرض العقوبة.\n -٢الجھل بشريعة جديدة إذا اقترف الجرم في خالل األيام الثالثة التي تلت نشرھا.\n -٣جھل األجنبي الذي قدم لبنان منذ ثالثة أيام على األكثر بوجود جريمة مخالفة للقوانين الوضعية\n ال تعاقب عليھا شرائع بالده أو شرائع البالد التي كان مقيما ً فيھا.\n النبذة -٢في الغلط المادي\n المادة -٢٢٤ال يعاقب كفاعل أو محرض أو متدخل في جريمة مقصودة من أقدم على الفعل\n بعامل غلط مادي واقع على أحد العناصر المكونة للجريمة.\n إذا وقع الغلط على أحد الظروف المشددة لم يكن المجرم مسؤوالً عنه ،وھو بعكس ذلك يستفيد من\n العذر الذي جھل وجوده.\n تطبق ھذه األحكام في حالة الغلط الواقع على ھوية المجنى عليه.\nالمادة -٢٢٥ال يكون الغلط الواقع على فعل مؤلف لجريمة غير مقصودة مانعا ً للعقاب إال إذا لم\n ينتج عن خطأ الفاعل.\n المادة -٢٢٦ال يعاقب الموظف العام ،أو العامل ،أو المستخدم في الحكومة الذي أمر بإجراء\n فعل أو أقدم على فعل يعاقب عليه القانون إذا اعتقد لسبب غلط مادي أنه يطيع أمر رؤسائه\n المشروع في أمور داخلة في اختصاصھم وجبت عليه طاعتھم فيھا.\n الفصل الثاني -في القوة القاهرة\n النبذة -١في القوة الغالبة وفي الإكراه المعنوي"}, {"o": 58, "l": "المادة ٢١٩", "b": "المادة -٢٢٧ال عقاب على من أكرھته قوة مادية أو معنوية لم يستطع إلى دفعھا سبيالً.\n من وجد في تلك الحالة بخطأ منه عوقب عند االقتضاء كفاعل جريمة غير مقصودة.\n المادة -٢٢٨ان المھابة وحاالت االنفعال والھوى ليست مانعة للعقاب.\n على أنه إذا افرط فاعل الجريمة في ممارسة حق الدفاع المشروع ال يعاقب إذا أقدم على الفعل في\n ثورة انفعال شديد إنعدمت معھا قوة وعيه أو إرادته.\n النبذة -٢في حالة الضرورة\n المادة -٢٢٩ال يعاقب الفاعل على فعل الجأته الضرورة إلى أن يدفع به عن نفسه أو عن غيره\nأو عن ملكه أو ملك غيره خطراً جسيما ً محدقا ً لم يتسبب ھو فيه قصداً شرط أن يكون الفعل متناسبا ً\n والخطر.\n المادة -٢٣٠ال يعتبر في حالة الضرورة من توجب عليه قانونا ً أن يتعرض للخطر.\n الفصل الثالث -في انتفاء التبعة وفي التبعة المنقوصة\n النبذة -١في الجنون\n\f المادة -٢٣١يعفى من العقاب من كان في حالة جنون أفقدته الوعي أو اإلرادة.\n المادة -٢٣٢من ثبت اقترافه جناية أو جنحة مقصودة عقابھا الحبس سنتين وقضي بعدم\n مسؤوليته بسبب فقدانه العقل حجز بموجب فقرة خاصة من حكم التبرئة في مأوى احترازي.\nإذا كانت الجنحة غير مقصودة أو كان عقابھا الحبس أقل من سنتين قضي بحجز الفاعل في المأوى\n االحترازي إذا ثبت أنه خطر على السالمة العامة.\n ويستمر الحجز إلى أن يثبت شفاء المجنون بقرار تصدره المحكمة التي قضت بالحجز ويمكن أن\n تفرض الحرية المراقبة على المحجوز عند تسريحه.\n النبذة -٢في العته\n المادة -٢٣٣من كان حين اقتراف الفعل مصابا ً بعاھة عقلية وراثية أو مكتسبة أنقصت قوة\nالوعي أو االختيار في أعماله يستفيد قانونا ً من إبدال عقوبته أو تخفيضھا وفقا ً ألحكام المادة .٢٥١\n المادة -٢٣٤من حكم عليه بعقوبة جنائية أو جناحية مانعة أو مقيدة للحرية واستفاد من إبدال\nالعقوبة أو تخفيضھا قانونا ً بسبب العته ،ومن حكم عليه بعقوبة من ھذه العقوبات وثبت أنه ممسوس"}, {"o": 59, "l": "المادة ٢١٩", "b": "أو مدمن المخدرات أو الكحول وكان خطراً على السالمة العامة قضي في الحكم بحجزه في مكان\n من المأوى االحترازي ليعالج فيه أثناء مدة العقوبة.\n إن المحكوم عليه الذي يسرح من المأوى االحترازي بعد شفائه المثبت بقرار من المحكمة التي\n قضت بحجزه تنفذ فيه المدة الباقية من عقوبته.\n ً\n إذا ظل المحكوم عليه بعد انتھاء مدة عقوبته خطرا على السالمة العامة ،يضبط في المأوى\n االحترازي بموجب قرار من المحكمة نفسھا لمدة ال تتجاوز الخمس سنوات إذا حكم عليه لجناية\n والسنتين إذا حكم عليه بجنحة ،ويسرح المحجور عليه قبل انقضاء األجل المحدد إذا صدر قرار\n الحق يثبت أنه لم يبق خطراً.\n ويمكن أن تفرض الحرية المراقبة على المحجور عليه بعد تسريحه.\n\f النبذة -٣في السكر والتسمم بالمخدرات\n المادة -٢٣٥يعفى من العقوبة من كان حين اقتراف الفعل ،بسبب طارىء أو قوة قاھرة ،في\n حالة تسمم ناتجة عن الكحول أو المخدرات أفقدته الوعي أو اإلرادة.\n إذا نتجت حالة التسمم عن خطأ الفاعل كان ھذا مسؤوالً عن كل جريمة غير مقصودة ارتكبھا.\nويكون مسؤوالً عن الجريمة المقصودة إذا توقع حين أوجد نفسه في تلك الحالة بسبب خطأه إمكان\n اقترافه أفعاالً جرمية.\n وإذا أوجد نفسه في تلك الحالة قصداً بغية ارتكاب الجريمة شددت عقوبته وفاقا ً للمادة .٢٥٧\nالمادة -٢٣٦إذا أضعفت حالة التسمم الناتجة عن قوة قاھرة أو حدث طارىء قوة وعي الفاعل\n أو إرادته إلى حد بعيد أمكن إبدال العقوبة أو تخفيضھا ،وفقا ً ألحكام المادة .٢٥١\n الفصل الرابع -في القصر\n النبذة -١أحكام شاملة\n المادة -٢٣٧ملغاة وفقا للمرسوم االشتراعي ١١٩تاريخ ١٩٨٣/٩/١٦\n المادة -٢٣٨ملغاة وفقا للمرسوم االشتراعي ١١٩تاريخ ١٩٨٣/٩/١٦\n\f المادة -٢٣٩ملغاة وفقا للقانون تاريخ ١٩٤٨/٢/٥\nالمادة -٢٤٠يعني ھذا القانون بالولد من أتم السابعة من عمره ولما يتم الثانية عشرة.\n وبالمراھق من أتم الثانية عشرة ولما يتم الخامسة عشرة."}, {"o": 60, "l": "المادة ٢١٩", "b": "وبالفتى من أتم الخامسة عشرة ولما يتم الثامنة عشرة.\n النبذة -٢في الأولاد\n المادة -٢٤١ملغاة وفقا للقانون تاريخ ١٩٤٨/٢/٥\n المادة -٢٤٢ملغاة وفقا للقانون تاريخ ١٩٤٨/٢/٥\n المادة -٢٤٣ملغاة وفقا للقانون تاريخ ١٩٤٨/٢/٥\n المادة -٢٤٤ملغاة وفقا للقانون تاريخ ١٩٤٨/٢/٥\n المادة -٢٤٥ملغاة وفقا للقانون تاريخ ١٩٤٨/٢/٥\n المادة -٢٤٦ملغاة وفقا للقانون تاريخ ١٩٤٨/٢/٥\n المادة -٢٤٧ملغاة وفقا للقانون تاريخ ١٩٤٨/٢/٥\n\f المادة -٢٤٨ملغاة وفقا للقانون تاريخ ١٩٤٨/٢/٥\n القسم الثالث -في أسباب الإعفاء من العقوبة ،أو تخفيفها ،أو تشديدها\n الفصل الأول -في الأعذار\n النبذة -١في الأعذار المحلة\n المادة -٢٤٩ال عذر على الجريمة إال في الحاالت التي عينھا القانون.\n المادة -٢٥٠إن العذر المحل يعفي المجرم من كل عقاب.\nعلى أنه يمكن أن تنزل به عند االقتضاء تدابير اإلصالح وتدابير االحتراز ما خال العزلة.\n النبذة -٢في الأعذار المخففة\n المادة -٢٥١معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n\f عندما ينص القانون على عذر مخفف:\n إذا كان الفعل جناية توجب اإلعدام أو األشغال الشاقة المؤبدة أو االعتقال المؤبد حولت العقوبة إلى\n الحبس سنة على األقل وسبع سنوات على األكثر.\n وإذا كان الفعل يؤلف إحدى الجنايات األخرى كان الحبس من ستة أشھر إلى خمس سنوات.\n و اذا كان الفعل جنحة فال تجاوز العقوبة ستة اشھر.\n وإذا كان الفعل مخالفة أمكن القاضي تخفيف العقوبة إلى نصف الغرامة التكديرية.\nيمكن أن تنزل بالمستفيد من العذر المخفف ما كان يتعرض له من تدابير االحتراز ما خال العزلة لو\n كان قضي عليه بالعقوبة التي نص عليھا القانون.\n المادة -٢٥٢يستفيد من العذر المخفف فاعل الجريمة الذي أقدم عليھا بثورة غضب شديد ناتج\n عن عمل غير محق وعلى جانب من الخطورة أتاه المجنى عليه.\n الفصل الثاني -في الأسباب المخففة\n المادة -٢٥٣معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥"}, {"o": 61, "l": "المادة ٢١٩", "b": "إذا وجدت في قضية أسباب مخففة قضت المحكمة:\nبدالً من اإلعدام باألشغال الشاقة المؤبدة أو األشغال الشاقة المؤقتة من سبع سنين إلى عشرين سنة.\n وبدالً من األشغال الشاقة المؤبدة باألشغال الشاقة المؤقتة ال أقل من خمس سنوات.\n وبدالً من االعتقال المؤبد باالعتقال المؤقت ال أقل من خمس سنوات ولھا أن ،تخفض كل عقوبة\n جنائية أخرى حتى ثالث سنوات إذا كان حدھا األدنى يجاوز ذلك .ولھا أن تخفض العقوبة إلى\n النصف إذا كان ال يجاوز حدھا األدنى ثالث سنوات أو أن تستبدلھا بقرار معلل بالحبس سنة على\n األقل فيما خال حالة التكرار.\n المادة -٢٥٤إذا أخذت المحكمة األسباب المخففة لمصلحة من ارتكب جنحة ،فلھا أن تخفض\n العقوبة إلى حدھا األدنى المبين في المواد ٥١و ٥٢و.٥٣\n و لھا ان تبدل الغرامة من الحبس و من االقامة الجبرية او ان تحول في ما خال حالة التكرار\n العقوبة الجناحية الى عقوبة تكديررية بقرار معلل.\n\fالمادة -٢٥٥يمكن الحكم بحد العقوبة األدنى المبين في المادتين ٦٠و ٦١أو بالغرامة على من\n ارتكب مخالفة تبين فيھا أسباب مخففة.\nالمادة -٢٥٦في حالة التكرار ،يجب أن يكون القرار المانح األسباب المخففة معلالً تعليالً خاصا ً\n سواء في الجنايات أو الجنح أو المخالفات.\n الفصل الثالث -في الأسباب المشددة\n النبذة -١في الأسباب المشددة عامة\n المادة -٢٥٧إذا لم يعين القانون مفعول سبب مشدد ،أوجب السبب المذكور تشديد العقوبة على\n الوجه التالي:\n يبدل اإلعدام من األشغال الشاقة المؤبدة وتزاد كل عقوبة مؤقتة من الثلث إلى النصف وتضاعف\n الغرامة.\n النبذة -٢في التكرار\n المادة -٢٥٨معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥\nمن حكم عليه باألشغال الشاقة المؤبدة حكما ً مبرما ً وارتكب جناية أخرى توجب العقوبة نفسھا قضي\n علي باإلعدام.\n\f ومن حكم عليه حكما ً مبرما ً باألشغال الشاقة المؤقتة أو االعتقال المؤقت وارتكب جناية أخرى"}, {"o": 62, "l": "المادة ٢١٩", "b": "توجب العقوبة نفسھا قبل مرور خمسة عشر عاما ً على انقضاء العقوبة أو مرور الزمن عليھا يحكم\n عليه بالعقاب الذي يستحقه مع إضافة مثله .ويمكن عند االقتضاء إبالغ الحد األقصى لھذا العقاب\n إلى ضعفيه أي ثالثين سنة.\n وإذا كانت الجريمة الثانية توجب الحكم باإلبعاد أو اإلقامة الجبرية أو بالتجريد المدني حكم على\n الفاعل بالعقوبة التي تعلوھا درجة واحدة حسب الترتيب الوارد في المادة .٣٨\n المادة -٢٥٩من حكم عليه لجناية حكما ً مبرما ً بعقوبة جنائية أو جناحية وارتكب ،قبل مضي\n سبعة أعوام على انقضاء العقوبة أو مرور الزمن عليھا ،جناية أو جنحة عقابھما الحبس ،يتعرض\n ألقصى العقوبة المنصوص عليھا حتى ضعفيھا.\n ويكون األمر كذلك إذا بلغ الحكم األول سنة حبس على األقل وقضي به في جنحة من فئة الجنحة\n الثانية.\n ً\n وإذا كانت العقوبة التي قضي بھا قبال دون السنة حكم على المكرر بالحبس مدة تعادل على األقل\n ضعفي العقوبة السابقة على أن ال يجاوز رفع الحد األدنى ھذا ضعفي العقوبة التي نص عليھا\n القانون.\n ويبدل الحبس البسيط من اإلقامة الجبرية إذا كان الحكم األول قد قضى بعقوبة جنائية أو بعقوبة\n جناحية غير الغرامة.\n وتضاعف الغرامة إذا كان قد سبقھا حكم بأي عقوبة جناحية كانت .وإذا وقع التكرار ثانية أمكن\n الحكم بالحبس حتى ثالثة أشھر وبالغرامة معا ً.\n المادة -٢٦٠تعتبر الجنح المبينة في كل بند من البنود التالية من فئة واحدة لتطبيق عقوبات\n التكرار الواردة في المادة السابقة ،سواء كان لمقترفھا صفة الفاعل ،أو المحرض أو المتدخل.\n (١الجنح المقصودة المنصوص عليھا في فصل واحد من ھذا القانون.\n (٢الجنح المنافية لألخالق )الباب السابع(.\n (٣الجنح المقصودة الواقعة على األشخاص )الباب الثامن(.\n (٤أعمال العنف من جسدية وكالمية الواقعة على األفراد أو رجال السلطة أو القوة العامة.\n (٥القتل والجرح غير المقصودين.\n (٦الجنح المذكورة في باب األشخاص الخطرين."}, {"o": 63, "l": "المادة ٢١٩", "b": "(٧الجنح المقصودة في واقعة على الملك.\n (٨إخفاء األشياء الناجمة عن جنحة أو إخفاء األشخاص الذين ارتكبوھا وتلك الجنحة نفسھا.\n (٩الجنح السياسية أو التي تعد سياسية وفقا ً للمادتين ١٩٦و .١٩٧\n (١٠الجنح المقترفة بدافع واحد غير شريف.\nالمادة -٢٦١إن المخالف الذي حكم عليه حكم مبرما ً من مدة لم تبلغ السنة للمخالفة نفسھا أو من\n أجل أي مخالفة أخرى ألحكام نظام واحد يعاقب بضعفي العقوبة التي نص عليھا القانون.\n\fإذا وقع التكرار ثانية في المدة نفسھا أمكن أن يقضي بالتوقيف وبالغرامة معا ً في جميع األحوال التي\n نص فيھا على الغرامة وحدھا.\n النبذة -٣في اعتياد الإجرام\n المادة -٢٦٢المجرم المعتاد ھو الذي ينم عمله اإلجرامي على استعداد نفسي دائم ،فطريا ً كان\n أو مكتسباً ،الرتكاب الجنايات أو الجنح.\n المادة -٢٦٣من قضي عليه بعقوبة غير الغرامة لجناية أو جنحة مقصودة ،وحكم عليه ،قبل\nانقضاء خمس سنوات على انتھاء مدة عقوبته أو مرور الزمن عليھا ،بعقوبة مانعة للحرية لمدة سنة\n على األقل في جناية أو جنحة مقصودة أخرى ،يحكم عليه بالعزلة إذا ثبت اعتياده لإلجرام وأنه\n خطر على السالمة العامة.\n المادة -٢٦٤كل مجرم معتاد محكوم عليه بعقوبة غير الغرامة عمالً بالمادتين ٢٥٨و ٢٥٩\n يعتبر حكما ً أنه خطر على السالمة العامة ويقضى عليه بالعزلة إذا حكم عليه بعقوبة مانعة للحرية\n من أجل تكرار قانوني آخر.\n واألمر كذلك في ما خص كل معتاد اإلجرام صدر عليه في خالل خمس عشرة سنة ال تحسب فيھا\n المدة التي قضاھا في تنفيذ العقوبات والتدابير االحترازية.\n أما أربعة أحكام بالحبس عن جنايات اقترفت بعذر أو عن جنح مقصودة شرط أن يكون كل من\n الجرائم الثالث األخيرة قد اقترفت بعد أن أصبح الحكم بالجريمة السابقة مبرما ً.\n وأما حكمان كاألحكام المبينة في الفقرة السابقة وحكم بعقوبة جنائية سواء وقعت الجناية قبل الجنحة\n أو بعدھا."}, {"o": 64, "l": "المادة ٢١٩", "b": "المادة -٢٦٥يستھدف للعزلة سبع سنوات على األقل كل محكوم عليه بالعزلة ارتكب في أثناء\n إقامته في السجن أو في خالل الخمس سنوات التي تلت اإلفراج عنه جناية أو جنحة مقصودة قضي\n عليه من أجلھا بالحبس سنة واحدة أو بعقوبة أشد.\n\f أحكام تشمل النبذات السابقة\n المادة -٢٦٦يمكن الحكم بالمنع من الحقوق المدنية ومنع اإلقامة واإلخراج من البالد على من\n ثبت اعتياده لإلجرام أو من حكم عليه كمكرر بعقوبة جناحية مانعة للحرية.\n المادة -٢٦٧ينزل بالمعتاد اإلجرام والمكرر المحكوم عليه باإلقامة الجبرية أو بالحبس أو\n بعقوبة أشد عند اإلفراج عنه تدبير الحرية المراقبة لمدة خمس سنوات إال أن يقرر القاضي زيادة\n مدتھا أو تخفيضھا أو إبدال اإلقامة الجبرية بھا ،أو إعفاء المحكوم عليه منھا.\nيدغم منع اإلقامة المحكوم به عمالً ب"}, {"o": 65, "l": "المادة ٨٢", "b": "المادة ٨٢فقرتھا ٢و ٣بتدبير الحرية المراقبة للمدة المقضي\n بھا.\n أحكام تشمل الفصول السابقة\n المادة -٢٦٨تسري أحكام األسباب المشددة أو المخففة للعقوبة على الترتيب التالي:\n األسباب المشددة المادية.\n األعذار.\n األسباب المشددة الشخصية.\n األسباب المخففة.\n المادة -٢٦٩يعين القاضي في الحكم مفعول كل من األسباب المشددة أو المخففة على العقوبة\n المقضي بھا.\n الكتاب الثاني -في الجرائم\n\f الباب الاول -في الجرائم الواقعة على امن الدولة\nالمادة -٢٧٠يدعى مؤامرة كل اتفاق تم بين شخصين أو أكثر على ارتكاب جناية بوسائل معينة.\n المادة -٢٧١معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦\n يتم االعتداء على أمن الدولة سواء كان الفعل المؤلف للجريمة تاما ً أو ناقصا أو في طور المحاولة.\n ً\n المادة -٢٧٢يعفى من العقوبة من اشترك بمؤامرة على أمن الدولة وأخبر السلطة بھا قبل البدء\n بأي فعل مھيأ للتنفيذ.\n إذا اقترف فعل كھذا أو بدئ به فال يكون العذر إال مخففاً.\n كذلك يستفيد من عذر مخفف المجرم الذي أخبر السلطة بمؤامرة أو بجناية أخرى على أمن الدولة\n قبل إتمامھا أو أتاح القبض -ولو بعد مباشرة المالحقات -على المجرمين اآلخرين أو على الذين\n يعرف مخبأھم.\n ال تطبق أحكام ھذه المادة على المحرض.\n الفصل الأول -في الجنايات الواقعة على أمن الدولة الخارجي\n النبذة -١في الخيانة\n\f المادة -٢٧٣كل لبناني حمل السالح على لبنان في صفوف العدو عوقب باإلعدام.\n كل لبناني وإن لم ينتم إلى جيش معاد ،أقدم في زمن الحرب على أعمال عدوان ضد لبنان عوقب\n باألشغال الشاقة المؤبدة.\n كل لبناني تجند بأي صفة كانت في جيش معاد ولم ينفصل عنه قبل أي عمل عدوان ضد لبنان\n عوقب باألشغال الشاقة المؤقتة وإن يكن قد اكتسب بتجنيده الجنسية األجنبية.\nالمادة -٢٧٤كل لبناني دس الدسائس لدى دولة أجنبية أو اتصل بھا ليدفعھا إلى مباشرة العدوان"}, {"o": 66, "l": "المادة ٨٢", "b": "على لبنان أو ليوفر لھا الوسائل إلى ذلك عوقب باألشغال الشاقة المؤبدة.\n وإذا أفضى فعله إلى نتيجة عوقب باإلعدام.\n المادة -٢٧٥كل لبناني دس الدسائس لدى العدو أو اتصل به ليعاونه بأي وجه كان على فوز\n قواته عوقب باإلعدام.\n المادة -٢٧٦يعاقب باألشغال الشاقة المؤبدة كل لبناني أقدم بأي وسيلة كانت قصد شل الدفاع\n الوطني ،على األضرار بالمنشآت والمصانع والبواخر والمركبات الھوائية واألدوات والذخائر\nواألرزاق وسبل المواصالت وبصورة عامة بكل األشياء ذات الطابع العسكري أو المعدة الستعمال\n الجيش أو القوات التابعة له.\n يقضى باإلعدام إذا حدث الفعل في زمن الحرب أو عند توقع نشوبھا أو أفضى إلى تلف نفس.\n المادة -٢٧٧يعاقب باالعتقال المؤقت خمس سنوات على األقل كل لبناني حاول بأعمال أو\n خطب أو كتابات أو بغير ذلك أن يقتطع جزءاً من األرض اللبنانية ليضمه إلى دولة أجنبية أو أن\n يملكھا حقا ً أو امتيازاً خاصا ً بالدولة اللبنانية.\n إذا كان الفاعل عند ارتكابه الفعل منتميا ً إلى إحدى الجمعيات أو المنظمات المشار إليھا في المادتين\n ٢٩٨و ٣١٨عوقب باالعتقال مؤبداً.\n المادة -٢٧٨معدلة وفقا للقانون ٧٥/٦تاريخ ١٩٧٥/٢/٢١\n كل لبناني قدم مسكنا ً أو طعاما ً أو لباسا ً لجاسوس أو لجندي من جنود األعداء يعمل لالستكشاف أو\n لعميل من عمالء األعداء أو ساعده على الھرب أو أجرى اتصاالً مع أحد ھؤالء الجواسيس أو\n الجنود أو العمالء وھو على بينة من أمره يعاقب باألشغال الشاقة المؤقتة.\n كل لبناني سھل فرار اسير حرب او احد رعايا العدو المعتقلين عوقب باالعتقال المؤقت.\n\f المادة -٢٧٩تفرض أيضا ً العقوبات المنصوص عليھا في ھذه النبذة إذا وقع الفعل على دولة\n تربطھا بلبنان معاھدة تحالف أو وثيقة دولية تقوم مقامھا.\nالمادة -٢٨٠ينزل منزلة اللبنانيين بالمعنى المقصود في المواد ٢٧٤إلى ٢٧٨األجانب الذين\n لھم في لبنان محل إقامة أو سكن فعلي.\n النبذة -٢في التجسس"}, {"o": 67, "l": "المادة ٨٢", "b": "المادة -٢٨١من دخل أو حاول الدخول إلى مكان محظور ،قصد الحصول على أشياء أو وثائق\n أو معلومات يجب أن تبقى مكتومة حرصا ً على سالمة الدولة عوقب بالحبس سنة على األقل وإذا\n سعى بقصد التجسس فباألشغال الشاقة المؤقتة.\nالمادة -٢٨٢من سرق أشياء أو وثائق أو معلومات كالتي ذكرت في المادة السابقة أو استحصل\n عليھا عوقب باألشغال الشاقة المؤقتة.\n إذا اقترفت الجناية لمنفعة دولة أجنبية كانت العقوبة األشغال الشاقة المؤبدة.\n المادة -٢٨٣من كان في حيازته بعض الوثائق أو المعلومات كالتي ذكرت في"}, {"o": 68, "l": "المادة ٢٨١", "b": "المادة ٢٨١\n فأبلغه أو أفشاه دون سبب مشروع عوقب بالحبس من شھرين إلى سنتين.\n ويعاقب باألشغال الشاقة المؤقتة خمس سنوات على األقل إذا أبلغ ذلك لمنفعة دولة أجنبية.\nإذا كان المجرم يحتفظ بما ذكر من المعلومات واألشياء بصفة كونه موظفا ً أو عامالً أو مستخدما في\n ً\n الدولة فعقوبته االعتقال المؤقت في الحالة المنصوص عليھا في الفقرة األولى واألشغال الشاقة\n المؤبدة في الحالة المنصوص عليھا في الفقرة الثانية.\n إذا لم يؤخذ على أحد األشخاص السابق ذكرھم إال خطأ غير مقصود كانت العقوبة الحبس من\n شھرين إلى سنتين.\n\f المادة -٢٨٤إذا اقترفت الجرائم المنصوص عليھا في ھذه النبذة لمصلحة دولة معادية شددت\n العقوبات وفاقا ً ألحكام المادة .٢٥٧\n النبذة -٣في الصلات غير المشروعة بالعدو\n المادة -٢٨٥معدلة وفقا للقانون الصادر بالمرسوم ١٥٦٩٨تاريخ ١٩٦٤/٣/٦والقانون ٢٣٩\n تاريخ ١٩٩٣/٥/٢٧\n يعاقب بالحبس سنة على األقل وبغرامة ال تنقص عن مائتي ألف ليرة لبنانية كل لبناني وكل\nشخص ساكن لبنان أقدم أو حاول أن يقدم مباشرة أو بواسطة شخص مستعار على صفقة تجارية أو\n أي صفقة شراء أو بيع أو مقايضة مع أحد رعايا العدو أو مع شخص ساكن بالد العدو.\n -يعاقب بذات العقوبة كل لبناني وكل شخص في لبنان من رعايا الدول العربية يدخل مباشرة أو\n بصورة غير مباشرة وبدون موافقة الحكومة اللبنانية المسبقة بالد العدو حتى وإن لم يكن المقصود\n من دخوله أحد األعمال المنصوص عليھا في الفقرة السابقة من ھذه المادة.\nالمادة -٢٨٦يستحق العقاب الوارد في المادة السابقة من ذكر فيھا من األشخاص إذا ساھموا في\n قرض أو اكتتاب لمنفعة دولة معادية أو سھلوا أعمالھا المالية بوسيلة من الوسائل.\n المادة -٢٨٧معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n من أخفى أو اختلس أموال دولة معادية أو أموال أحد رعاياھا المعھود بھا إلى حارس عوقب\n بالحبس من شھرين إلى سنتين وبغرامة أقلھا مائتي ألف ليرة."}, {"o": 69, "l": "المادة ٢٨١", "b": "النبذة -٤في الجرائم الماسة بالقانون الدولي\n المادة -٢٨٨يعاقب باالعتقال المؤقت:\n\f من خرق التدابير التي اتخذتھا الدولة للمحافظة على حيادھا في الحرب.\n من أقدم على أعمال أو كتابات أو خطب لم تجزھا الحكومة فعرض لبنان لخطر أعمال عدائية أو\n عكر صالته بدولة أجنبية أو عرض اللبنانيين ألعمال ثأرية تقع عليھم أو على أموالھم.\n المادة -٢٨٩كل اعتداء يقع في األرض اللبنانية أو يقدم عليه أحد الرعايا اللبنانيين قصد أن\n يغير بالعنف دستور دولة أجنبية أو حكومتھا أو يقتطع جزءاً من أرضھا يعاقب عليه باالعتقال\n المؤقت.\n إن المؤامرة التي ترمي إلى إحدى الجنايات السالفة الذكر توجب الحبس سنة على األقل.\n المادة -٢٩٠من جند في األرض اللبنانية دون موافقة الحكومة جنوداً للقتال في سبيل دولة\n أجنبية عوقب باالعتقال المؤقت أو باإلبعاد.\n المادة -٢٩١معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\nيعاقب بالحبس من ستة أشھر إلى سنتين وبغرامة ال تجاوز أربعمائة ألف ليرة على كل تحريض يقع\n في لبنان أو يقوم به لبناني بإحدى الوسائل المذكورة في"}, {"o": 70, "l": "المادة ٢٨٨", "b": "المادة ٢٨٨لحمل جنود دولة أجنبية من\n جنود البر أو البحر أو الجو على الفرار أو العصيان.\nالمادة -٢٩٢يعاقب بالعقوبات نفسھا بناء على شكوى الفريق المتضرر من أجل الجرائم التالية:\n تحقير دولة اجنبية او جيشھا او علمھا او شعارھا الوطني عالنية.\n تحقير رئيس دولة أجنبية أو وزرائھا أو ممثلھا السياسي في لبنان.\n القدح أو الذم الواقع عالنية على رئيس دولة أجنبية أو وزرائھا أو ممثلھا السياسي في لبنان .ال\n يجوز إثبات الفعل الذي كان موضوع الذم.\n المادة -٢٩٣إذا كانت الجريمة المقترفة في األرض اللبنانية أو بفعل لبناني على رئيس دولة\n أجنبية أو أحد وزرائه أو ممثله السياسي في لبنان ال تقع تحت طائلة عقوبة خاصة شددت العقوبة\n القانونية على نحو ما ذكر في المادة .٢٥٧\n المادة -٢٩٤ال تطبق أحكام مواد ٢٨٩إلى ٢٩٣إال إذا كان في قوانين الدولة ذات الشأن أو\n في االتفاق المعقود معھا أحكام مماثلة.\n\f النبذة -٥في النيل من هيبة الدولة ومن الشعور القومي\n المادة -٢٩٥من قام في لبنان في زمن الحرب أو عند توقع نشوبھا بدعاية ترمي إلى أضعاف\n الشعور القومي أو إيقاظ النعرات العنصرية أو المذھبية عوقب باالعتقال المؤقت.\nالمادة -٢٩٦يستحق العقوبة نفسھا من نقل في لبنان في األحوال عينھا أنباء يعرف أنھا كاذبة أو\n مبالغ فيھا من شأنھا أن توھن نفسية األمة.\n إذا كان الفاعل يحسب ھذه األنباء صحيحة فعقوبته الحبس ثالثة أشھر على األقل.\n المادة -٢٩٧معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\nكل لبناني يذيع في الخارج وھو على بينة من األمر أنباء كاذبة أو مبالغا ً فيھا من شأنھا أن تنال من\nھيبة الدولة أو من مكانتھا المالية يعاقب بالحبس ستة أشھر على األقل وبغرامة تتراوح بين مئة ألف\n ليرة ومليون ليرة.\n ويمكن المحكمة أن تقضي بنشر الحكم.\n المادة -٢٩٨معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧"}, {"o": 71, "l": "المادة ٢٨٨", "b": "من أقدم في لبنان دون إذن الحكومة على االنخراط في جمعية سياسية أو اجتماعية ذات طابع دولي\n أو في منظمة من ھذا النوع عوقب بالحبس أو اإلقامة الجبرية من ثالثة أشھر إلى ثالث سنوات\n وبغرامة تتراوح بين خمسين ألف وخمسمائة ألف ليرة.\n ال يمكن أن تنقص عقوبة من تولى في الجمعية أو المنظمة المذكورتين وظيفة عملية عن السنة\n حبسا ً أو إقامة جبرية وعن المائتي ألف ليرة غرامة.\n النبذة -٦في جرائم المتعهدين\n المادة -٢٩٩معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n\f من لم ينفذ في زمن الحرب أو عند توقع نشوبھا جميع الموجبات التي يفرضھا عليه عقد تعھد أو\n استصناع أو تقديم خدمات تتعلق بالدفاع الوطني ومصالح الدولة العامة أو تموين األھلين يعاقب\n باالعتقال المؤقت وبغرامة تراوح بين قيمة الموجب غير المنفذ وضعفيھا على أن ال تنقص عن\n مليون ليرة.\n ً ً\n إذا كان عدم التنفيذ ناجما عن خطأ غير مقصود عوقب الفاعل بالحبس فضال عن الغرامة المعينة\n في الفقرة السابقة.\n يخفض نصف العقوبات المنصوص عليھا في ھذه المادة إذا كان التنفيذ قد تأخر ليس إال.\n وتفرض ھذه العقوبات بفوارقھا السابقة على أي شخص آخر كان سببا ً في عدم تنفيذ العقد أو في\n تأخير تنفيذه.\n المادة -٣٠٠معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\nكل غش يقترف في األحوال نفسھا بشأن العقود المشار إليھا في المادة السابقة يعاقب عليه باألشغال\n الشاقة المؤقتة وبغرامة تتراوح بين ضعفي الربح غير المشروع الذي جناه المجرم وثالثة أضعاف\n على أن ال تنقص عن مليون ليرة.\n الفصل الثاني -في الجرائم الواقعة على أمن الدولة الداخلي\n النبذة -١في الجنايات الواقعة على الدستور\n المادة -٣٠١يعاقب على االعتداء الذي يستھدف تغيير دستور الدولة بطرق غير مشروعة\n باالعتقال المؤقت خمس سنوات على األقل.\n وتكون العقوبة االعتقال المؤبد إذا لجأ الفاعل إلى العنف."}, {"o": 72, "l": "المادة ٢٨٨", "b": "المادة -٣٠٢من حاول أن يسلخ عن سيادة الدولة جزءاً من األرض اللبنانية عوقب باالعتقال\n المؤقت أو باإلبعاد.\n وتكون العقوبة االعتقال المؤبد إذا لجأ الفاعل إلى العنف.\n\f المادة -٣٠٣كل فعل يقترف بقصد إثارة عصيان مسلح ضد السلطات القائمة بموجب الدستور\n يعاقب عليه باالعتقال المؤقت.\nإذا نشب العصيان عوقب المحرض باالعتقال المؤبد وسائر العصاة باالعتقال المؤقت خمس سنوات\n على األقل.\n المادة -٣٠٤االعتداء الذي يقصد منه منع السلطات القائمة من ممارسة وظائفھا المستمدة من\n الدستور أو يعاقب عليه باالعتقال المؤقت او االبعاد.\nالمادة -٣٠٥يعاقب على المؤامرة التي تستھدف ارتكاب احدى الجرائم المذكورة في ھذه النبذة\n باالبعاد او باالقامة الجبرية الجنائية.\n النبذة -٢في اغتصاب سلطة سياسية أو مدنية أو قيادة عسكرية\n المادة -٣٠٦يعاقب باالعتقال المؤقت سبع سنوات على األقل:\n من اغتصب سلطة سياسية أو مدنية أو قيادة عسكرية.\n من احتفظ خالفا ً ألمر الحكومة بسلطة مدنية أو قيادة عسكرية.\n كل قائد عسكري أبقى جنده محتشداً بعد أن صدر األمر بتسريحه أو بتفريقه.\n المادة -٣٠٧يستحق االعتقال المؤقت من أقدم دون رضى السلطة على تأليف فصائل مسلحة\n من الجند أو على قيد العساكر أو تجنيدھم أو على تجھيزھم أو مدھم باألسلحة والذخائر.\n النبذة -٣في الفتنة\n يعلق العمل باحكام"}, {"o": 73, "l": "المادة ٣٠٨", "b": "المادة ٣٠٨بموجب القانون -صادر في ١٩٥٨/١/١١\n\fالمادة -٣٠٨يعاقب باألشغال الشاقة مؤبداً على االعتداء الذي يستھدف إما إثارة الحرب األھلية\nأو االقتتال الطائفي بتسليح اللبنانيين أو بحملھم على التسلح بعضھم ضد البعض اآلخر وأما بالحض\n على التقتيل والنھب في محلة أو محالت ،ويقضي باإلعدام إذا تم االعتداء.\n يعلق العمل باحكام"}, {"o": 74, "l": "المادة ٣٠٩", "b": "المادة ٣٠٩بموجب القانون -صادر في ١٩٥٨/١/١١\n المادة -٣٠٩يعاقب باألشغال الشاقة مؤبداً من ترأس عصابات مسلحة أو تولى فيھا وظيفة أو\n قيادة أيا ً كان نوعھا إما بقصد اجتياح مدينة أو محلة أو بعض أمالك الدولة أو أمالك جماعة من\n االھلين وإما بقصد مھاجمة أو مقاومة القوة العامة العاملة ضد مرتكبي ھذه الجنايات.\n يعلق العمل باحكام"}, {"o": 75, "l": "المادة ٣١٠", "b": "المادة ٣١٠بموجب القانون -صادر في ١٩٥٨/١/١١\n المادة -٣١٠يعاقب باالشغال الشاقة المؤبدة المشتركون في عصابات مسلحة الفت بقصد\nارتكاب الجنايات المنصوص عليھا في المادتين ٣٠٨و ٣٠٩غير انه يعفى من العقوبة من لم يتول\n منھم في العصابة وظيفة او خدمة و لم يوقف في اماكن الفتنة و استسلم بسالحه دون مقاومة و قبل\n صدور اي حكم.\n يعلق العمل باحكام"}, {"o": 76, "l": "المادة ٣١١", "b": "المادة ٣١١بموجب القانون -صادر في ١٩٥٨/١/١١\n المادة -٣١١تشدد بمقتضى"}, {"o": 77, "l": "المادة ٢٥٧", "b": "المادة ٢٥٧عقوبة من أقدم على ارتكاب إحدى الجنايات\n المنصوص عليھا في المادتين ٣٠٩و.٣١٠\n إذا كان يحمل سالحا ً ظاھراً أو مخبأ.\n إذا كان يرتدي زيا ً أو يحمل شعاراً آخراً مدنيين كانا أو عسكريين.\n إذا أقدم على أعمال تخريب أو تشويه في أبنية مخصصة بمصلحة عامة أو في سبل المخابرات أو\n المواصالت أو النقل.\n يعلق العمل باحكام"}, {"o": 78, "l": "المادة ٣١٢", "b": "المادة ٣١٢بموجب القانون -صادر في ١٩٥٨/١/١١\n المادة -٣١٢من أقدم بقصد اقتراف أو تسھيل إحدى الجنايات المذكورة في ھذه النبذة أو أية\nجناية أخرى ضد الدولة على صنع أو اقتناء أو حيازة المواد المتفجرة أو الملتھبة والمنتجات السامة\n أو المحرقة أو األجزاء التي تستعمل في تركيبھا أو صنعھا يعاقب باألشغال الشاقة المؤقتة فضالً\n عن العقوبات األشد التي يستحقھا المتدخلون في تلك الجنايات إذا اقترفت أو شرع فيھا أو بقيت\n ناقصة.\n يعلق العمل باحكام"}, {"o": 79, "l": "المادة ٣١٣", "b": "المادة ٣١٣بموجب القانون -صادر في ١٩٥٨/١/١١\n المادة -٣١٣يعاقب باألشغال الشاقة المؤقتة على المؤامرة بقصد ارتكاب إحدى الجنايات\n المذكورة في ھذه النبذة.\n\f النبذة -٤في الإرهاب\n المادة -٣١٤يعنى باألعمال اإلرھابية جميع األفعال التي ترمي إلى إيجاد حالة ذعر وترتكب\n بوسائل كاألدوات المتفجرة والمواد الملتھبة والمنتجات السامة أو المحرقة والعوامل الوبائية أو\n المكروبية التي من شأنھا أن تحدث خطراً عاما ً.\n يعلق العمل باحكام"}, {"o": 80, "l": "المادة ٣١٥", "b": "المادة ٣١٥بموجب القانون -صادر في ١٩٥٨/١/١١\n المادة -٣١٥المؤامرة التي يقصد منھا ارتكاب عمل أو أعمال إرھاب يعاقب عليھا باألشغال\n الشاقة المؤقتة.\n كل عمل إرھابي يستوجب األشغال الشاقة لخمس سنوات على األقل.\n وھو يستوجب األشغال الشاقة المؤبدة إذا نتج عنه التخريب ولو جزئيا ً في بناية عامة أو مؤسسة\n صناعية أو سفينة أو منشآت أخرى أو التعطيل في سبل المخابرات والمواصالت والنقل.\n ويقضى بعقوبة اإلعدام إذا أفضى الفعل إلى موت إنسان أو ھدم البنيان بعضه أو كله وفيه شخص\n أو عدة أشخاص.\n المادة -٣١٦كل جمعية أنشئت بقصد تغيير كيان الدولة االقتصادي أو االجتماعي أو أوضاع\n المجتمع األساسية بإحدى الوسائل المذكورة في"}, {"o": 81, "l": "المادة ٣١٤", "b": "المادة ٣١٤تحل ويقضى على المنتمين إليھا\n باألشغال الشاقة المؤقتة.\n وال تنقص عقوبة المؤسسين والمديرين عن سبع سنوات.\nإن العذر المحل أو المخفف الممنوح للمتآمرين بموجب"}, {"o": 82, "l": "المادة ٢٧٢", "b": "المادة ٢٧٢يشمل مرتكبي الجناية المحددة\n أعاله."}, {"o": 83, "l": "المادة ٣١٦", "b": "المادة ٣١٦مكرر -مضافة وفقا ً للقانون رقم ٥٥٣تاريخ ٢٠٠٣/١٠/٢٠ووفقا للقانون رقم\n ٧٧تاريخ ٢٠١٦/١٠/٢٧\n كل من يقوم أو يحاول القيام أو يوجه أو يشترك عن قصد وبأية وسيلة ،مباشرة أو غير مباشرة،\nبتمويل كليا ً أو جزئيا ً أو المساھمة بتمويل االرھاب أو األعمال اإلرھابية ،أو تمويل شخص إرھابي\nأو المنظمات اإلرھابية ،أو االعمال المرتبطة بھا ،بما فيھا تقديم أو توفير أو جمع األموال المنقولة\nأو غير المنقولة ،من مصادر مشروعة أو غير مشروعة ،في لبنان أو في الخارج ،سواء استعملت\n األموال أم لم تستعمل ،وسواء تم العمل اإلرھابي أو لم يتم في لبنان أو في الخارج.\n\f تشمل جريمة تمويل اإلرھاب السفر ،محاولة السفر ،التجنيد ،التخطيط ،اإلعداد ،التنظيم ،التسھيل،\n المشاركة ،تقديم أو تلقي التدريب ،وأي عمل آخر مرتبط بھا بنية القيام بأعمال إرھابية ودون ان\n تكون تلك األعمال مرتبطة بعمل إرھابي محدد.\nيعاقب مرتكبو األفعال المحددة أعاله باألشغال الشاقة المؤقتة لمدة ال تقل عن ثالث سنوات وال تزيد\n عن سبع سنوات وبغرامة ال تقل عن مثل المبلغ المدفوع وال تزيد عن ثالثة أمثاله ،وال يحول ذلك\n دون تطبيق العقوبات المنصوص عليھا في المواد ٢١٢لغاية ٢٢٢ضمنا ً من قانون العقوبات«.\n نص"}, {"o": 84, "l": "المادة ٣١٦", "b": "المادة ٣١٦مكرر قيبل التعديل بموجب القانون رقم ٧٧تاريخ ٢٠١٦/١٠/٢٧\n تمويل االرھاب\n كل من يقوم عن قصد وبأية وسيلة مباشرة أو غير مباشرة بتمويل أو المساھمة بتمويل اإلرھاب أو األعمال اإلرھابية أو\nالمنظمات اإلرھابية يعاقب باألشغال الشاقة المؤقتة لمدة ال تقل عن ثالث سنوات وال تزيد عن سبع سنوات وبغرامة ال تقل عن\n مثل المبلغ المدفوع وال تزيد عن ثالثة أمثاله.\n النبذة -٥في الجرائم التي تنال من الوحدة الوطنية أو تعكر الصفاء بين عناصر الأمة\n المادة -٣١٧معدلة وفقا للقانون تاريخ ١٩٥٤/١٢/١والقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n كل عمل وكل كتابة وكل خطاب يقصد منھا أو ينتج عنھا إثارة النعرات المذھبية أو العنصرية أو\n الحض على النزاع بين الطوائف ومختلف عناصر األمة يعاقب عليه بالحبس من سنة إلى ثالث\n سنوات وبالغرامة من مئة إلى ثمانمائة ألف ليرة وكذلك بالمنع من ممارسة الحقوق المذكورة في\n الفقرتين الثانية والرابعة من"}, {"o": 85, "l": "المادة ٦٥", "b": "المادة ٦٥ويمكن للمحكمة أن تقضي بنشر الحكم.\n المادة -٣١٨معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n يتعرض للعقوبات نفسھا كل شخص ينتمي إلى جمعية أنشئت للغاية المشار إليھا في المادة السابقة.\n وال ينقص الحبس عن سنة واحدة والغرامة عن مائتي ألف ليرة إذا كان الشخص المذكور يتولى\n وظيفة عملية في الجمعية.\n ً\n كل ذلك فضالً عن الحكم بحل الجمعية ومصادرة أمالكھا عمال بالمادتين ١٠٩و.٦٩\n النبذة -٦في النيل من مكانة الدولة المالية\n\f المادة -٣١٩معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\nمن أذاع بإحدى الوسائل المذكورة في الفقرتين الثانية والثالثة من"}, {"o": 86, "l": "المادة ٢٠٩", "b": "المادة ٢٠٩وقائع ملفقة أو مزاعم\n كاذبة ألحداث التدني في أوراق النقد الوطنية أو لزعزعة الثقة في متانة نقد الدولة وسنداتھا وجميع\n اإلسناد ذات العالقة بالثقة المالية العامة يعاقب بالحبس من ستة أشھر إلى ثالث سنوات وبالغرامة\n من خمسمائة ألف ليرة إلى مليوني ليرة.\n ويمكن فضالً عن ذلك أن يقضي بنشر الحكم.\n المادة -٣٢٠يستحق العقوبات نفسھا كل شخص تذرع بالوسائل عينھا لحض الجمھور.\n إما على سحب األموال المودعة في المصارف والصناديق العامة.\n أو على بيع سندات الدولة وغيرھا من السندات العامة أو على اإلمساك عن شرائھا.\n أحكام شاملة\n المادة -٣٢١يمكن المحكمة عند الحكم في إحدى الجنح المنصوص عليھا في ھذا الباب أن\n تقضي بالمنع من الحقوق المدنية أو منع اإلقامة أو باإلخراج من البالد عمالً بالمواد ٦٥و٨٢\n و.٨٨\n الباب الثاني -في الجرائم الواقعة على السلامة العامة\n الفصل الأول -في الأسلحة والذخائر\n\f النبذة -١تعاريف\nالمادة -٣٢٢تعد العصابات والتجمھرات واالجتماعات مسلحة بالمعنى المقصود في ھذا القانون\n إذا كان شخص أو أكثر من األشخاص الذين تتألف منھم حاملين أسلحة ظاھرة أو مخبأة أو مخفية\n على أنه إذا كان بعضھم يحمل أسلحة غير ظاھرة .فال يؤخذ ھذا األمر على سائر األشخاص إذا\n كانوا على جھل به.\n المادة -٣٢٣يعد سالحا ً ألجل تطبيق المادة السابقة كل أداة أو آلة قاطعة أو ثاقبة أو راضة\n وكل أداة خطرة على السالمة العامة.\n إن سكاكين الجيب العادية والعصي الخفيفة التي لم تحمل لتستعمل عند الحاجة ال يشملھا ھذا\n التعريف إال إذا استعملت في ارتكاب جناية أو جنحة.\n النبذة -٢في حمل الأسلحة والذخائر وحيازتها دون إجازة\n المادة -٣٢٤ملغاة وفقا للقانون تاريخ ١٩٥٢/٦/١٨\n المادة -٣٢٥ملغاة وفقا للقانون تاريخ ١٩٥٢/٦/١٨\n المادة -٣٢٦معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧"}, {"o": 87, "l": "المادة ٢٠٩", "b": "إذا كانت الغاية من حمل األسلحة والذخائر أو من حيازتھا ارتكاب جناية كانت العقوبة ،في ما خال\n الحاالت التي يفرض معھا القانون عقوبة أشد ،الحبس مع التشغيل من سنة إلى ثالث سنوات\n والغرامة من مئة ألف ليرة إلى ستمائة ألف ليرة.\n\f النبذة -٣في حمل الأسلحة الممنوعة\n -٣٢٧ملغاة وفقا للقانون تاريخ ١٩٥٢/٦/١٨ المادة\n المادة -٣٢٨ملغاة وفقا للقانون تاريخ ١٩٥٢/٦/١٨\n الفصل الثاني -في التعدي على الحقوق والواجبات المدنية\n المادة -٣٢٩كل فعل من شأنه أن يعوق اللبناني عن ممارسة حقوقه أو واجباته المدنية يعاقب\nعليه بالحبس من شھر إلى سنة ،إذا اقترف بالتھديد والشدة أو بأي وسيلة أخرى من وسائل اإلكراه\n الجسدي أو المعنوي.\n إذا اقترف الجرم جماعة مسلحة مؤلفة من ثالثة أشخاص أو أكثر كانت العقوبة بالحبس من ستة\n أشھر إلى ثالث سنوات وإذا وقع الجرم بال سالح فالعقوبة الحبس من شھرين إلى سنتين.\nالمادة -٣٣٠إذا اقترف أحد األفعال المعينة في المادة السابقة عمالً لخطة مدبرة يراد تنفيذھا في\n أرض الدولة كلھا او في محلة أو محالت منھا عوقب كل من المجرمين باالعتقال المؤقت أو\n باإلبعاد.\n المادة -٣٣١معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\n من حاول التأثير في اقتراع أحد اللبنانيين بقصد إفساد نتيجة االنتخاب العام:\n إما بإخافته من ضرر يلحق بشخصه أو عيلته أو مركزه أو ماله.\n أو بالعروض أو العطايا أو الوعود.\n أو بوعد شخص معنوي أو جماعة من الناس بمنح إدارية.\n يعاقب بالحبس من شھر إلى سنة وبالغرامة من مئة ألف ليرة إلى مليون ليرة.\n\f ويستحق العقوبة نفسھا من قبل مثل ھذه العطايا أو الوعود أو التمسھا.\n المادة -٣٣٢كل موظف عام أو عامل أو مستخدم في الدولة استخدم سلطته للتأثير في اقتراع\n أحد اللبنانيين عوقب بالتجريد المدني.\n المادة -٣٣٣كل شخص غير أو حاول أن يغير بالغش نتيجة انتخاب عوقب بالحبس من"}, {"o": 88, "l": "المادة ٢٠٩", "b": "شھرين إلى سنتين.\n ً\nإذا كان المجرم مكلفا جمع األصوات أو أوراق االقتراع أو حفظھا أو فرزھا أو القيام بأي عمل آخر\n متعلق بانتخاب عام عوقب بالحبس من ستة أشھر إلى ثالث سنوات.\n المادة -٣٣٤ال شأن ألبطال االنتخاب في الجرائم التي تقترف في أثنائه أو بسببه.\n الفصل الثالث -في الجمعيات غير المشروعة\n النبذة -١في جمعيات الأشرار\n المادة -٣٣٥معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\nإذا أقدم شخصان أو أكثر على تأليف جمعية أو إجراء اتفاق خطي أو شفھي بقصد ارتكاب الجنايات\n على الناس أو األموال أو النيل من سلطة الدولة أو ھيبتھا أو التعرض لمؤسساتھا المدنية أو\n العسكرية أو المالية أو االقتصادية يعاقب باألشغال الشاقة المؤقتة وال تنقص ھذه العقوبة عن عشر\n سنوات إذا كانت غاية المجرمين االعتداء على حياة الغير أو حياة الموظفين في المؤسسات\n واإلدارات العامة.\nغير انه يعفى من العقوبة من باح بأمر الجمعية أو االتفاق وأفضى بما لديه من معلومات عن سائر\n المجرمين.\n\f المادة -٣٣٦كل جماعة من ثالثة أشخاص أو أكثر يسيرون في الطرق العامة واألرياف\n عصابات مسلحة بقصد سلب المارة والتعدي على األشخاص أو األموال أو ارتكاب أي عمل آخر\n من أعمال اللصوصية يستحقون األشغال الشاقة المؤقتة مدة أقلھا سبع سنوات.\n ويقضي عليھم باألشغال الشاقة المؤبدة إذا اقترفوا أحد األفعال السابق ذكرھا.\n ويستوجب عقوبة اإلعدام من أقدم منھم تنفيذاً للجناية على القتل أو حاوله أو أنزل بالمجنى عليھم\n التعذيب واألعمال البربرية.\n النبذة -٢في الجمعيات السرية\n المادة -٣٣٧تعد سرية كل جمعية أو جماعة لھا في الواقع صفة الجمعية إذا كان غرضھا\n منافيا ً للقانون وكانت تقوم بأعمالھا أو بالبعض منھا سراً.\n كذلك تعد سرية الجمعيات والجماعات نفسھا التي ثبت أن غرضھا مناف للقانون ولم تعلم السلطة."}, {"o": 89, "l": "المادة ٢٠٩", "b": "بعد أن طلب إليھا ذلك ،بأنظمتھا األساسية وبأسماء أعضائھا ووظائفھم وبموضوع اجتماعاتھم\n وبيان أمالكھا ومصدر مواردھا أو أعطت عن ھذه األمور معلومات كاذبة أو ناقصة.\n المادة -٣٣٨معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n تحل كل جمعية سرية وتصادر أموالھا.\nومن كان متوليا ً فيھا وظيفة إدارية أو تنفيذية عوقب بالحبس من ستة أشھر إلى سنتين وبالغرامة من\n مئة ألف إلى مليون ليرة .وأما سائر األعضاء فبنصف العقوبتين.\nالمادة -٣٣٩إذا اقترف عضو في جمعية سرية جريمة تنفيذاً لغرض ھذه الجمعية فالعضو الذي\n حضر االجتماع حيث تقررت الجريمة يعد محرضا ً ويعاقب بما فرضته المادة .٢١٨\nوالعضو الذي وجد في مكان الجريمة حين اقترافھا يكون في حكم المتدخل ويعاقب عقوبته على ما\n ورد في المادة .٢٢٠\n الفصل الرابع -في جرائم الاغتصاب والتعدي على حرية العمل\n\fالمادة -٣٤٠يستحق التجريد المدني الموظفون الذين يربطھم بالدولة عقد عام إذا أقدموا متفقين\nعلى وقف أعمالھم أو اتفقوا على وقفھا أو على تقديم استقالتھم في أحوال يتعرقل معھا سير إحدى\n المصالح العامة.\n المادة -٣٤١إذا توقف عن الشغل أحد أرباب األعمال أو رؤساء المشاريع أو المستخدمون أو\n العملة إما بقصد الضغط على السلطات العامة وإما احتجاجا ً على قرار أو تدبير صادرين عنھا\n عوقب كل من المجرمين بالحبس أو باإلقامة الجبرية مدة ثالثة أشھر على األقل.\n المادة -٣٤٢معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦\n يعاقب بالحبس وبالغرامة على كل اغتصاب يقوم به أكثر من عشرين شخصا ً ويتبعه المحاولة أو\n البدء بالتنفيذ بقصد توقيف:\n -١وسائل النقل بين أنحاء لبنان أو بينه وبين البلدان األخرى.\n -٢المواصالت البريدية والبرقية والتلفونية.\n -٣إحدى المصالح العامة المختصة بتوزيع الماء أو الكھرباء.\n ويستوجب العقوبة نفسھا ملتزم إحدى المصالح السابق ذكرھا إذا وقف عملھا دون سبب مشروع."}, {"o": 90, "l": "المادة ٢٠٩", "b": "إذا اقترف الجرم بأعمال العنف على األشخاص أو األشياء أو بالتھديد أو بغير ذلك من وسائل\nالتخويف أو بضروب االحتيال أو بمزاعم كاذبة من شأنھا أن تحدث أثراً في النفس أو بالتجمھر في\nالسبل والساحات العامة أو باحتالل أماكن العمل عوقب مرتكبو ھذه األفعال بالحبس ستة أشھر على\n األقل.\n المادة -٣٤٣معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n من تذرع بإحدى الوسائل المذكورة في الفقرة األخيرة من المادة السابقة فحمل اآلخرين أو حاول\n حملھم على أن يوقفوا عملھم باالتفاق فيما بينھم أو ثبتھم أو حاول أن يثبتھم في وقف ھذا العمل\n يعاقب بالحبس سنة على األكثر وبغرامة ال تزيد على مئة ألف ليرة.\n المادة -٣٤٤كل رب عمل أو رئيس مشروع وكل مستخدم أو عامل رفض أو أرجأ تنفيذ قرار\n التحكيم أو أي قرار آخر صادر عن إحدى محاكم العمل عوقب بالحبس من شھرين إلى سنة.\n\f الفصل الخامس -في تظاهرات وتجمعات الشغب\n النبذة -١في تظاهرات الشغب\n المادة -٣٤٥معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\nمن كان في اجتماع ليس له طابع االجتماع الخاص سواء من قبل غايته أو غرضه أو عدد المدعوين\n إليه أو الذين يتألف منھم أو من مكان انعقاده أو كان في مكان عام أو بمحل مباح للجمھور أو\n معرض ألنظاره فجھر بصياح أو أناشيد الشغب أو أبرز شارة من الشارات في حاالت يضطرب\n معھا األمن العام أو أقدم على أية تظاھرة شغب أخرى يعاقب عليھا بالحبس من شھر إلى سنة\n وبالغرامة من عشرين ألف ليرة إلى مائتي ألف ليرة.\n النبذة -٢في تجمعات الشغب\n المادة -٣٤٦كل حشد أو موكب على الطرق العامة أو في مكان مباح للجمھور يعد تجمعا ً\n للشغب ويعاقب عليه بالحبس من شھر إلى سنة:\n إذا تألف من ثالثة أشخاص أو أكثر بقصد اقتراف جناية أو جنحة وكان أحدھم على األقل مسلحا ً.\n إذا تألف من سبعة أشخاص على األقل بقصد االحتجاج على قرار أو تدبير اتخذتھما السلطات\n العامة بقصد الضغط عليھا."}, {"o": 91, "l": "المادة ٢٠٩", "b": "إذا أربى عدد األشخاص على العشرين وظھروا بمظھر من شأنه أن يعكر الطمأنينة العامة.\n المادة -٣٤٧إذا تجمع الناس على ھذه الصورة أنذرھم بالتفرق أحد ممثلي السلطة اإلدارية أو\n ضابط من الضابطة العدلية يعلن قدومه إذا دعت األحوال بقرع الطبل أو النفخ في البوق أو\n الصفارة أو بأية طريقة أخرى مماثلة.\n\f يعفى من العقوبة المفروضة آنفا ً الذين يتصرفون قبل إنذار السلطة أو يمتثلون في الحال إلنذارھا\n دون أن يستعملوا أسلحتھم أو يرتكبوا أي جنحة أخرى.\n المادة -٣٤٨إذا لم يتفرق المتجمعون بغير القوة كانت العقوبة الحبس من شھرين إلى سنتين.\n ومن استعمل السالح عوقب بالحبس من سنة إلى ثالث سنوات فضالً عن أي عقوبة أشد قد\n يستحقھا.\n أحكام شاملة\nالمادة -٣٤٩يمكن الحكم بالمنع من الحقوق المدنية وبمنع اإلقامة وبالطرد من البالد وفاقا ً للمواد\n ٦٥و ٨٢و ٨٨في الجنح المنصوص عليھا في الفصول ٢إلى ٥من ھذا الباب.\n الباب الثالث -في الجرائم الواقعة على الإدارة العامة\n أحكام عامة\n المادة -٣٥٠معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n يعد موظفا ً بالمعنى المقصود في ھذا الباب كل موظف في اإلدارات والمؤسسات العامة والبلديات\n والجيش والقضاء وكل عامل أو مستخدم في الدولة وكل شخص عين أو انتخب ألداء خدمة عامة\n ببدل أو بغير بدل.\n\f الفصل الأول -في الجرائم المخلة بواجبات الوظيفية\n النبذة -١في الرشوة\n المادة -٣٥١معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n كل موظف وكل شخص ندب إلى خدمة عامة سواء باالنتخاب أو بالتعيين ،وكل امرء كلف بمھمة\n رسمية كالحكم والخبير والسنديك التمس أو قبل لنفسه أو لغيره ھدية أو وعداً أو أي منفعة أخرى\n ليقوم بعمل شرعي من أعمال وظيفته عوقب بالحبس من ثالثة أشھر إلى ثالث سنوات وبغرامة\n أقلھا ضعفا قيمة ما أخذ أو قبل به.\n المادة -٣٥٢معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦"}, {"o": 92, "l": "المادة ٢٠٩", "b": "كل شخص من األشخاص السابق ذكرھم التمس أو قبل لنفسه أو لغيره ھدية أو وعداً أو أي منفعة\n أخرى ليعمل عمالً منافيا ً لوظيفته أو يدعي أنه داخل في وظيفته أو ليھمل أو يؤخر ما كان عمله\nواجبا ً عليه عوقب باألشغال الشاقة المؤقتة وبغرامة ال تنقص عن ثالثة أضعاف قيمة ما أخذ أو قبل\n به يقضي بالعقوبة نفسھا على المحامي إذا ارتكب ھذه األفعال.\n المادة -٣٥٣معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n إن العقوبات المنصوص عليھا في المواد ٣٥١و ٣٥٢تنزل أيضا ً بالراشي.\n ويعفى الراشي أو المتدخل من ھذه العقوبات إذا باح باألمر للسلطات ذات الصالحية أو اعترف به\n قبل إحالة القضية على المحكمة.\n المادة -٣٥٤معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\n -كل عامل في القطاع الخاص ،مستخدما ً كان أم خبيراً أم مستشاراً وكل من ارتبط مع صاحب\n عمل بعقد استخدام لقاء أجر ،التمس أو قبل لنفسه أو لغيره ،ھدية أو وعداً أو أي منفعة أخرى،\n لكشف أسرار أو معلومات تسيء إلى العمل أو للقيام بعمل أو االمتناع عنه بقصد إلحاق الضرر\n\f المادي أو المعنوي بصاحب أو بصالح العمل ،يعاقب بالحبس من شھرين إلى سنتين وبالغرامة من\n مئة ألف إلى مائتي ألف ليرة.\n -وتنزل العقوبة نفسھا بالراشي.\nالمادة -٣٥٥من عرض على شخص من األشخاص الوارد ذكرھم في"}, {"o": 93, "l": "المادة ٣٥١", "b": "المادة ٣٥١ھدية أو أي\nمنفعة أخرى أو وعده بھا على سبيل أجر غير واجب ليعمل أو ال يعمل عمالً من أعمال وظيفته أو\n ليؤخر تنفيذه عوقب إذا لم يالق العرض أو الوعد قبوالً بالحبس ثالثة أشھر على األقل وبغرامة ال\n تنقص عن ضعفي قيمة الشيء المعروض أو الموعود.\n المادة -٣٥٦كل شخص من األشخاص المشار إليھم في"}, {"o": 94, "l": "المادة ٣٥١", "b": "المادة ٣٥١يقبل بأجر غير واجب\n عن عمل قد سبق أجراؤه من أعمال وظيفته أو مھمته يعاقب بالحبس من شھر إلى سنة وبغرامة\n أقلھا ضعفا قيمة ما قبل به.\n النبذة -٢في صرف النفوذ\n المادة -٣٥٧من أخذ أو التمس أجراً غير واجب أو قبل أو الوعد به سواء كان لنفسه أو لغيره\n بقصد إنالة آخرين أو السعي ألنالتھم وظيفة أو عمالً أو مقاوالت أو مشاريع أو أرباحا ً غيرھا أو\n منحا ً من الدولة أو إحدى اإلدارات العامة أو بقصد التأثير في مسلك السلطات بأية طريقة كانت\n عوقب بالحبس من شھرين إلى سنتين وبغرامة أقلھا ضعفا قيمة ما أخذ أو قبل به.\n المادة -٣٥٨معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n إذا اقترف الفعل محام بحجة الحصول على عطف قاض أو حكم أو سنديك أو خبير في قضية\n عوقب بالحبس من سنة إلى ثالث سنوات ومنع من ممارسة مھنته مدى الحياة.\n النبذة -٣في الاختلاس واستثمار الوظيفة\n\f المادة -٣٥٩كل موظف اختلس ما وكل إليه أمر إدارته أو جبايته أو صيانته بحكم الوظيفة من\n نقود أو أشياء أخرى للدولة ألحد الناس عوقب بالحبس من ثالثة أشھر إلى ثالث سنوات وبغرامة\n أقلھا قيمة الردود.\nالمادة -٣٦٠إذا وقع االختالس بدس كتابات غير صحيحة في الفواتير أو الدفاتر أو بتحريف أو\n إتالف الحسابات واألوراق أو غيرھا من الصكوك وعلى صورة عامة بأية حيلة ترمي إلى منع\n اكتشاف االختالس قضي بعقوبة األشغال الشاقة المؤقتة فضالً عن الغرامة التي تفرضھا المادة\n السابقة.\nالمادة -٣٦١كل موظف أكره شخصا ً من األشخاص أو حمله على أداء أو الوعد بأداء ما يعرف\n أنه غير واجب عليه أو يزيد عما يجب عليه من الضرائب أو الرسوم وما سوى ذلك من العوائد\n يعاقب بالحبس سنة على األقل وبغرامة أدناھا قيمة الردود.\n المادة -٣٦٢يعاقب بالعقوبة نفسھا كل موظف يمنح إعفاء من الضرائب والرسوم والغرامات\n وسواھا من العوائد من غير أن يجيز القانون ذلك."}, {"o": 95, "l": "المادة ٣٥١", "b": "المادة -٣٦٣معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\n يعاقب بالحبس من ثالثة أشھر إلى ثالث سنوات وبالغرامة من مائتي ألف ليرة إلى مليون ليرة.\n -١من أوكل إليه بيع أو شراء أو إدارة أموال منقولة أو غير منقولة لحساب الدولة أو لحساب إدارة\nأو مؤسسة عامة أو بلدية أو ھيئة عامة أو مؤسسة ذات منفعة عامة أو تملك الدولة قسما ً من أسھمھا\n فاقترف الغش في أحد ھذه األعمال أو خالف األحكام التي تسري عليھا إما لجر مغنم ذاتي أو\nمراعاة لفريق أضراراً بالفريق اآلخر أو أضراراً بالمصلحة العامة أو األموال العمومية ،أو ارتكب\n الخطأ الفادح والجسيم.\n -٢من ارتبط ،في حالة السلم ،بعقد تعھد أعمال أو أشغال عامة أو نقل أو استصناع أو صيانة أو\n تصليحات أو تقديم خدمات أو لوازم أو تموين مع إحدى الجھات المبينة في الفقرة السابقة سواء\n كان العقد نتيجة مناقصة على أساس دفتر شروط أو بطريقة التراضي أو بأي طريقة أخرى فلجأ\n إلى ضروب المماطلة المقصودة أو الحيلة لعرقلة التنفيذ أو إطالة المدة بقصد األضرار بمشاريع\n الدولة أو جراً لنفع له أو لغيره أو اقترف الغش في نوع المواد المستعملة أو المقدمة أو في تركيبھا\n أو صنعھا أو مواصفاتھا الجوھرية.\n\f -٣المتعھدون الذين يتفقون بالتواطؤ فيما بينھم إلفساد عملية التلزيم أو لحصر االلتزام بواحد منھم\n أضراراً بالجھة الرسمية المتعاقدة.\n -٤الموظف المنوط به اإلشراف على المناقصة أو التكليف بالتراضي أو بأية طريقة أخرى أو\n مراقبة مراحل التنفيذ أو استالم األشغال بعد إنجازھا ،إذا قام بأعمال من شأنھا مراعاة فريق على\n آخر في التلزيم أو التكليف أو إذا ھو تغاضى عن ضبط المخالفة أو أھمل المراقبة أو لم يتخذ بحق\n المخالف التدابير التي تنص عليھا القوانين المختصة.\n -٥المتعھد أو الوسيط أو أي شخص آخر قدم نتيجة مناقصة أو تكليف بالتراضي أو بأية طريقة"}, {"o": 96, "l": "المادة ٣٥١", "b": "أخرى مواداً فاسدة أو غير صالحة لإلدارات والمؤسسات العامة والبلديات ،ويعتبر الموظف أو\n المستخدم الذي قبل أو استلم ھذه المواد شريكا ً بالجرم.\n ھذا فضالً عما يقضي به من عقوبات الرشوة في حال حصولھا.\n المادة -٣٦٤معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\nكل موظف حصل على منفعة شخصية من إحدى معامالت اإلدارة التي ينتمي إليھا سواء فعل ذلك\n مباشرة أو على يد شخص مستعار أو باللجوء إلى صكوك ظاھرية عوقب بالحبس من ثالث أشھر\n إلى سنتين وبغرامة أقلھا مائتي ألف ليرة.\n المادة -٣٦٥تفرض عقوبات المادة السابقة على القضاة وجباة المال وممثلي اإلدارة وضباط\nالدولة أو الشرطة وسائر متولي السلطة العامة الذين يجري عليھم معاش الدولة إذا أقدموا جھاراً أو\n باللجوء إلى صكوك ظاھرية مباشرة أو على يد شخص مستعار على االتجار في المنطقة التي\n يمارسون فيھا السلطة بالحبوب والمواد الغذائية وسائر الحاجات ذات الضرورة األولية غير ما\n أنتجته أمالكھم.\n المادة -٣٦٦معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n يخفض نصف العقوبات المنصوص عليھا في المواد ٣٥٩إلى ٣٦٢إذا كان الضرر الحاصل\n والنفع الذي توخاه المجرم زھيدين أو إذا عوض عن الضرر تعويضا ً تاما ً قبل إحالة القضية على\n المحكمة.\n وإذا حصل الرد أو التعويض في أثناء المحاكمة وقبل أي حكم في األساس ولو غير مبرم خفض\n من العقوبة ربعھا.\n النبذة -٤في التعدي على الحرية\n\f المادة -٣٦٧كل موظف أوقف أو حبس شخصا ً في غير الحاالت التي ينص عليھا القانون\n يعاقب باألشغال الشاقة المؤقتة.\nالمادة -٣٦٨إن مديري وحراس السجون أو المعاھد التأديبية أو االصالحيات وكل من اضطلع\nبصالحياتھم من الموظفين إذا قبلوا شخصا ً دون مذكرة قضائية أو قرار قضائي أو استبقوه إلى أبعد\n من األجل المحدد يعاقبون بالحبس من سنة إلى ثالث سنوات.\nالمادة -٣٦٩إن األشخاص السابق ذكرھم وبوجه عام جميع ضباط القوة العامة وأفرادھا وجميع"}, {"o": 97, "l": "المادة ٣٥١", "b": "الموظفين اإلداريين الذي يرفضون أو يؤخرون إحضار شخص موقف أو سجين أمام القاضي ذي\n الصالحية الذي يطلب إليھم ذلك يعاقبون بالحبس من شھر إلى سنة.\nومن لم يمتثل فوراً لما يطلبه القاضي من إبراز سجل السجن وجميع سجالت أمكنة التوقيف التي ھم\n ملحقون بھا يعاقبون بالعقوبة نفسھا.\n المادة -٣٧٠كل موظف يدخل بصفة كونه موظفا ً منزل أحد الناس أو ملحقات المنزل في غير\n الحاالت التي ينص عليھا القانون ودون مراعاة األصول التي يفرضھا يعاقب بالحبس من ثالثة\nأشھر إلى ثالث سنوات وال تنقص العقوبة عن ستة أشھر إذا رافق الفعل تحري المكان أو أي عمل\n تحكم آخر أتاه الفاعل.\n النبذة -٥في إساءة استعمال السلطة والإخلال بواجبات الوظيفة\nالمادة -٣٧١كل موظف يستعمل سلطته أو نفوذه مباشرة أو غير مباشرة ليعوق أو يؤخر تطبيق\nالقوانين أو األنظمة وجباية الرسوم أو الضرائب أو تنفيذ قرار قضائي أو مذكرة قضائية أو أي أمر\n صادر عن السلطة ذات الصالحية يعاقب بالحبس من ثالثة أشھر إلى سنتين.\n إذا لم يكن الشخص الذي استعمل سلطته أو نفوذه موظفا ً عاما ً فال تجاوز العقوبة السنة.\n\f المادة -٣٧٢معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n يعاقب بالحبس من شھر إلى سنة وبالغرامة من خمسين ألف إلى مائتي ألف ليرة كل موظف حض\n على االزدراء باألوضاع القومية أو بشرائع الدولة أو أشاد بذكر أعمال تنافي ھذه الشرائع أو\n األوضاع.\n ً\n يطبق ھذا النص أيضا على رجال الدين وعلى أفراد ھيئة التعليم العام أو الخاص.\n المادة -٣٧٣معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\n إذا ارتكب الموظف في اإلدارات أو المؤسسات العامة أو البلديات دون سبب مشروع إھماالً في\n القيام بوظيفته أو لم ينفذ األوامر القانونية الصادرة إليه عن رئيسه عوقب بالحبس حتى سنتين\n وبالغرامة من مائتي ألف ليرة إلى مليون ليرة أو بإحدى ھاتين العقوبتين."}, {"o": 98, "l": "المادة ٣٥١", "b": "وإذا نجم عن ھذا الفعل ضرر بمصالح اإلدارات والمؤسسات والبلديات المعنية تشدد العقوبة وفقا ً\n لنص المادة ،٢٥٧ويمكن أن يحكم عليه بغرامة تعادل قيمة الضرر.\n المادة -٣٧٤كذلك يعاقب بالحبس من شھر إلى سنة كل ضابط أو فرد من أفراد القوة العامة\n وكل قائد موقع أو فصيلة امتنع عن تلبية طلب قانوني صادر عن السلطة القضائية أو اإلدارية.\n المادة -٣٧٥كل موظف غير الذين ذكرتھم"}, {"o": 99, "l": "المادة ٣٠٦", "b": "المادة ٣٠٦عزل أو كفت يده وكل شخص ندب\nإلى خدمة عامة باالنتخاب أو بالتعيين وانتھت مدته يعاقب بالحبس من ثالثة أشھر إلى ثالث سنوات\n إذا مضى في ممارسة وظيفته خالفا ً للقانون.\n المادة -٣٧٦معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n كل موظف أقدم بقصد جلب المنفعة لنفسه أو لغيره أو بقصد األضرار بالغير على فعل لم يخص\n بنص في القانون ينافي واجبات مھنته يعاقب بالحبس من شھر إلى ثالث سنوات وبالغرامة من\n عشرين ألف إلى مائتي ألف ليرة.\n المادة -٣٧٧في ما خال الحاالت التي يفرض فيھا القانون عقوبات خاصة عن الجرائم التي\nيرتكبھا الموظفون فإن الذين يقدمون منھم بصفتھم المذكورة ،أو بإساءتھم استعمال السلطة أو النفوذ\n المستمدين من وظائفھم على ارتكاب أي جريمة كانت محرضين كانوا أو مشتركين أو متدخلين\n يستوجبون العقوبات المشددة التي تفرضھا المادة .٢٥٧\n\f أحكام شاملة\n المادة -٣٧٨يمكن القاضي عند قضائه في إحدى الجنح المنصوص عليھا في ھذا الفصل أن\n يحكم بالمنع من الحقوق المدنية.\n الفصل الثاني -في الجرائم الواقعة على السلطة العامة\n النبذة -١في التمرد\n المادة -٣٧٩معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥والقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\nمن ھاجم أو قاوم بالعنف موظفا ً يعمل على تطبيق الشرائع أو األنظمة أو جباية الرسوم والضرائب\n أو تنفيذ قرار قضائي أو مذكرة قضائية أو أي أمر صادر عن السلطة ذات الصالحية عوقب على\n الوجه اآلتي:\n -١إذا اقترف الفعل جماعة مسلحون يربي عدد أشخاصھا على العشرين عوقبوا بالحبس من ثالثة\n أشھر إلى ثالث سنوات وإذا كانوا عزالً كان الحبس من شھرين إلى سنتين.\n -٢وإذا اقترف الفعل أشخاص عددھم دون العشرين كانت العقوبة الحبس من شھرين إلى سنتين\nإذا كانوا مسلحين والحبس من عشرة أيام إلى ثالثة أشھر والغرامة من عشرين ألف إلى مائتي ألف\n ليرة إذا كانوا عزالً.\n المادة -٣٨٠معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥والقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧"}, {"o": 100, "l": "المادة ٣٠٦", "b": "كل مقاومة فعلية كانت أم سلبية توقف عمال شرعيا ً يقوم به أحد األشخاص الذين وصفتھم المادة\n السابقة يعاقب عليھا بالحبس شھراً على األكثر وبالغرامة حتى مئة ألف ليرة.\n النبذة -٢في أعمال الشدة\n المادة -٣٨١معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n -من ضرب موظفا ً أو عامله بالعنف والشدة في أثناء ممارسته الوظيفة أو في معرض ممارسته\n إياھا أو بسببھا ،يعاقب بالحبس من ستة أشھر إلى ثالث سنوات.\n وإذا وقع الفعل على قاض في أي وقت كان كانت العقوبة من سنة إلى ثالث سنوات.\n وتشدد العقوبات المفروضة في الفقرتين السابقتين على النحو المبين في"}, {"o": 101, "l": "المادة ٢٥٧", "b": "المادة ٢٥٧إذا اقترفت\n أعمال العنف عمداً أو إذا اقترفھا جماعة من ثالثة أشخاص على األقل أو نجم عنھا جراح أو\n مرض.\n وإذا كانت أعمال العنف من الخطورة بحيث تستوجب عقوبة أشد من العقوبات التي نصت عليھا\nھذه المادة رفعت العقوبة التي استحقھا الفاعل من جراء ذلك وفاقا ً للمادة ٢٥٧من قانون العقوبات.\n المادة -٣٨٢معدلة وفقا المرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\n ً ً ً\n من ھدد بأي وسيلة كانت ،قاضيا ،أو أي شخص يقوم بمھمة قضائية أو يؤدي واجبا قانونيا أمام\n القضاء ،كالحكم أو المحامي أو الخبير أو السنديك أو الشاھد ،بقصد التأثير على مناعته أو رأيه أو\nحكمه أو لمنعه من القيام بواجبه أو بمھمته ،يعاقب بالحبس من سنة إلى ثالث سنوات وبالغرامة من\n مائتي ألف إلى مليوني ليرة.\n وإذا انطوى التھديد على وعيد باستعمال السالح أو باالعتداء على األشخاص أو األموال ،أو إذا\n اقترن بأحد ھذه األفعال عوقب الفاعل باألشغال الشاقة المؤقتة.\n النبذة -٣في التحقير\n\f المادة -٣٨٣معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥\nالتحقير بالكالم والحركات أو التھديد الذي يوجه إلى موظف في أثناء قيامه بالوظيفة أو في معرض\n قيامه بھا أو يبلغه بإرادة الفاعل.\nوالتحقير بكتابة أو رسم أو مخابرة برقية أو تلفونية الذي يوجه إلى موظف في أثناء قيامه بوظيفته\n أو في معرض قيامه بھا.\n يعاقب عليه بالحبس مدة ال تزيد على ستة أشھر.\n إذا كان الموظف المحقر ممن يمارسون السلطة العامة كانت العقوبة من شھرين إلى سنة.\nوإذا وقع التحقير بالكالم أو الحركات أو التھديد على قاض في منصة القضاء كانت العقوبة الحبس\n من ستة أشھر إلى سنتين.\n ويراد بالموظف كل شخص عين أو انتخب ألداء وظيفة أو خدمة عامة ببدل أو بغير بدل.\n المادة -٣٨٤من حقر رئيس الدولة عوقب بالحبس من ستة أشھر إلى سنتين."}, {"o": 102, "l": "المادة ٢٥٧", "b": "وتفرض العقوبة نفسھا على من حقر العلم أو الشعار الوطني عالنية بإحدى الوسائل المذكورة في\n المادة .٢٠٩\n النبذة -٤في الذم والقدح\nالمادة -٣٨٥الذم ھو نسبة أمر إلى شخص ولو في معرض الشك أو االستفھام ينال من شرفه أو\n كرامته.\n ً\n وكل لفظة ازدراء أو سباب وكل تعبير أو رسم يشفان عن التحقير يعد قدحا إذا لم ينطو على نسبة\n أمر ما.\n وذلك دون التعرض ألحكام"}, {"o": 103, "l": "المادة ٣٨٣", "b": "المادة ٣٨٣التي تتضمن تعريف التحقير.\n المادة -٣٨٦معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n الذم بإحدى الوسائل المعينة في"}, {"o": 104, "l": "المادة ٢٠٩", "b": "المادة ٢٠٩يعاقب عليه:\n بالحبس من شھرين إلى سنتين إذا وقع على رئيس الدولة.\nبالحبس سنة على األكثر إذا وجه إلى المحاكم أو الھيئات المنظمة أو الجيش أو اإلدارات العامة ،أو\n وجه إلى موظف ممن يمارسون السلطة العامة من أجل وظيفته أو صفته.\n بالحبس ثالثة أشھر على األكثر أو بغرامة من عشرين ألف إلى مائتي ألف ليرة إذا وقع على أي\n موظف آخر بسبب وظيفته أو صفته.\n\fالمادة -٣٨٧في ما خال الذم الواقع على رئيس الدولة يبرأ الظنين إذا كان موضوع الذم عمالً ذا\n عالقة بالوظيفة وثبتت صحته.\n المادة -٣٨٨معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n القدح بإحدى الوسائل المبينة في"}, {"o": 105, "l": "المادة ٢٠٩", "b": "المادة ٢٠٩يعاقب عليه.\n بالحبس من شھر إلى سنة إذا وقع على رئيس الدولة.\n بالحبس ستة أشھر على األكثر إذا وجه إلى المحاكم أو الھيئات المنظمة أو الجيش أو اإلدارات\n العامة أو وجه إلى موظف ممن يمارسون السلطة العامة من أجل وظيفته أو صفته.\nبالغرامة من عشرين ألف إلى مئة ألف ليرة أو بالتوقيف التكديري إذا وقع على أي موظف آخر من\n أجل وظيفته أو صفته.\n المادة -٣٨٩معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n التحقير أو القدح أو الذم الموجه إلى القاضي دون أن يكون لوظيفته عالقة بذلك يعاقب عليه\n بالحبس ستة أشھر على األكثر.\n وللمحاكم أن تقضي بنشر كل حكم بجريمة تحقير أو ذم أو قدح واردة أعاله في النبذة األولى من\n الفصل الثاني.\n النبذة -٥في تمزيق الإعلانات الرسمية\n المادة -٣٩٠معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n من مزق إعالنا ً رسميا ً أو نزعه أو أتلفه وأن جزئيا ً عوقب بالغرامة من عشرين ألف ليرة إلى مئة\nألف ليرة ،وإذا ارتكب الفعل ازدراء بالسلطة أو احتجاجا ً على أحد أعمالھا كان عقابه الحبس مدة ال\n تجاوز الثالثة أشھر.\n النبذة -٦في انتحال الصفات أو الوظائف\n\f المادة -٣٩١معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n من أقدم عالنية ودون حق على ارتداء زي رسمي أو حمل وسام أو شارة من أزياء أو أوسمة أو\nشارات الدولة اللبنانية أو دولة أجنبية أو ارتدى ثوبا ً تخص به الشريعة اللبنانية فئة من الناس عوقب\n بالحبس ستة أشھر على األكثر أو بغرامة ال تزيد على مائتي ألف ليرة.\n يطبق ھذا النص بناء على شكوى السلطات المذھبية الصالحة على كل شخص يرتدي دون حق\n ألبسة خاصة بإحدى الوظائف الدينية.\nالمادة -٣٩٢من بدا منتحالً وظيفة عامة عسكرية أو مدنية أو مارس صالحياتھا عوقب بالحبس\n من شھرين إلى سنتين.\n إذا كان الفاعل مرتديا ً في أثناء العمل زيا ً أو شارة خاصين بالموظفين فال ينقص الحبس عن أربعة\n أشھر."}, {"o": 106, "l": "المادة ٢٠٩", "b": "وإذا اقترن الفعل بجريمة أخرى رفعت عقوبتھا وفاقا ً ألحكام المادة .٢٥٧\n المادة -٣٩٣معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n من زاول دون حق مھنة خاضعة لنظام قانوني عوقب بالحبس ستة أشھر على األكثر وبغرامة\n خمسين ألف إلى أربعمائة ألف ليرة.\n المادة -٣٩٤يمكن نشر الحكم في الجنح المنصوص عليھا في ھذه النبذة.\n النبذة -٧في فك الأختام ونزع الأوراق أو الوثائق الرسمية\n المادة -٣٩٥من أقدم قصداً على فك األختام الموضوعة بأمر السلطة العامة أو بطلب السلطات\nالروحية أو القنصلية العاملة ضمن حدود اختصاصھا القانوني في لبنان عوقب بالحبس من شھر إلى\n سنة وإذا لجأ إلى أعمال العنف على األشخاص فمن سنة إلى ثالث سنوات.\n\f المادة -٣٩٦من أخذ أو نزع أو أتلف إتالفا ً تاما ً أو جزئيا ً أوراقا ً أو وثائق أودعت خزائن\n المحفوظات أو أقالم المحاكم أو المستودعات العامة أو سلمت إلى أمين عام بصفته ھذه عوقب\n بالحبس من سنة إلى ثالث سنوات.\n إذا اقترف الفعل بواسطة فك األختام أو الخلع أو التسلق أو بواسطة أعمال العنف على األشخاص\n كانت العقوبة األشغال الشاقة المؤقتة.\nالمادة -٣٩٧يستحق عقوبات المادة السابقة بما اشتملت عليه من فوارق من أحرق أو أتلف وإن\n جزئيا ً سجالت أو مسودات أو أصول الصكوك الخاصة بالسلطة العامة.\n الباب الرابع -في الجرائم المخلة بالإدارة القضائية\n الفصل الأول -في الجرائم المخلة بسير القضاء\n النبذة -١في كتم الجنايات والجنح\n المادة -٣٩٨كل لبناني علم بجناية على أمن الدولة ولم ينبىء بھا السلطة العامة في الحال\n عوقب بالحبس من سنة إلى ثالث سنوات وبالمنع من الحقوق المدنية.\n المادة -٣٩٩معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\nكل موظف مكلف البحث عن الجرائم أو مالحقتھا فأھمل أو أرجأ األخبار عن جريمة اتصلت بعمله\n عوقب بالحبس من شھر إلى ثالث سنوات وبالغرامة من عشرين ألف إلى مائتي ألف ليرة."}, {"o": 107, "l": "المادة ٢٠٩", "b": "كل موظف أھمل أو أرجأ إعالم السلطة ذات الصالحية عن جناية أو جنحة عرف بھا في أثناء\n قيامه بالوظيفة أو في معرض قيامه بھا عوقب بالغرامة المحددة أعاله.\n وذلك كله ما لم تكن مالحقة الجريمة التي لم يخبر بھا موقوفة على شكوى أحد الناس.\n المادة -٤٠٠من قام حال مزاولته إحدى المھن الصحية بإسعاف شخص يبدو أنه وقعت عليه\nجناية أو جنحة تجوز مالحقتھا دون شكوى ولم ينبىء السلطة بھا عوقب بالغرامة المنصوص عليھا\n في المادة السابقة.\n النبذة -٢في انتزاع الإقرار والمعلومات\n المادة -٤٠١من سام شخصا ً ضروبا ً من الشدة ال يجيزھا القانون رغبة منه في الحصول على\n إقرار عن جريمة أو على معلومات بشأنھا عوقب بالحبس من ثالثة أشھر إلى ثالث سنوات.\n وإذا أفضت أعمال العنف عليه إلى مرض أو جراح كان أدنى العقاب الحبس سنة.\n النبذة -٣في اختلاق الجرائم والافتراء\n المادة -٤٠٢معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n من أخبر السلطة القضائية أو سلطة يجب عليھا إبالغ السلطة القضائية عن جريمة يعرف أنھا لم\n تقترف ومن كان سببا ً في مباشرة لتحقيق تمھيدي أو قضائي باختالقه أدلة مادية على جريمة كھذه\n عوقب بالحبس مدة ال تجاوز الستة أشھر وبغرامة ال تزيد على مئة ألف ليرة أو بإحدى العقوبتين.\n المادة -٤٠٣من قدم شكاية أو أخباراً إلى السلطة القضائية أو إلى سلطة يجب عليھا إبالغ\n السلطة القضائية فعزا إلى أحد الناس جنحة أو مخالفة يعرف براءته منھا أو اختلق عليه أدلة مادية\n على وقوع مثل ھذا الجرم عوقب بالحبس من شھر إلى ثالث سنوات.\n\f إذا كان الفعل المعزو يؤلف جناية عوقب المفتري باألشغال الشاقة المؤقتة عشر سنوات على\n األكثر.\n وإذا أفضى االفتراء إلى حكم باإلعدام أو بعقوبة مؤبدة فال تنقص عقوبة األشغال الشاقة عن عشر\n سنوات ويمكن إبالغھا إلى خمس عشرة سنة.\nالمادة -٤٠٤إذا رجع المفتري عن افترائه قبل أية مالحقة خففت العقوبات المنصوص عليھا في"}, {"o": 108, "l": "المادة ٢٠٩", "b": "ھذه النبذة وفاقا ً لما جاء في المادة .٢٥١\n النبذة -٤في الهوية الكاذبة\n المادة -٤٠٥معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\nمن استسماه قاض أو ضابط من ضباط الشرطة العدلية أو أحد رجالھا فذكر اسما أو صفة ليست له\n أو أدى إفادة كاذبة عن محل إقامته أو سكنه عوقب بالحبس ستة أشھر على األكثر أو بغرامة ال\n تجاوز المئة ألف ليرة.\nالمادة -٤٠٦من انتحل اسم غيره في تحقيق قضائي أو محاكمة قضائية عوقب بالحبس من ثالثة\n أشھر إلى ثالث سنوات.\n النبذة -٥في شهادة الزور\n المادة -٤٠٧الشاھد الذي يبدي عذراً كاذبا ً يستحق الحبس ثالثة أشھر على األكثر فضالً عن\n الغرامة التي يقضى بھا عليه بسبب تخلفه عن الحضور.\n\f المادة -٤٠٨من شھد أمام سلطة قضائية أو قضاء عسكري أو إداري فجزم بالباطل أو أنكر\n الحق أو كتم بعض أو كل ما يعرفه من وقائع القضية التي يسأل عنھا عوقب بالحبس من ثالثة\n أشھر إلى ثالث سنوات.\nإذا أديت شھادة الزور في أثناء تحقيق جنائي أو محاكمة جنائية قضي باألشغال الشاقة عشر سنوات\n على األكثر.\nوإذا نجم عن الشھادة الكاذبة حكم باإلعدام بعقوبة مؤبدة فال تنقص األشغال الشاقة عن عشر سنوات\n ويمكن إبالغھا إلى خمس عشرة سنة.\n إذا كان المجرم قد استمع دون أن يحلف اليمين خفض نصف العقوبة.\n المادة -٤٠٩يعفى من العقوبة:\n -١الشاھد الذي أدى الشھادة في أثناء تحقيق جزائي إذا رجع عن اإلفادة الكاذبة قبل أن يختم\n التحقيق ويقدم بحقه أخبار.\n -٢الشاھد الذي شھد في أية محاكمة إذا رجع عن قوله قبل أي حكم في أساس الدعوى ولو غير\n مبرم.\n المادة -٤١٠كذلك يعفى من العقوبة:\n -١الشاھد الذي يتعرض حتما ً إذا قال الحقيقة لخطر جسيم له مساس بالحرية أو الشرف أو يعرض\n له زوجة ولو طالقا ً أو أحد أصوله أو فروعه أو أخوته أو أخواته أو أصھاره من الدرجات نفسھا.\n -٢الشخص الذي أفضى أمام القاضي باسمه وكنيته وصفته ولم يكن من الواجب استماعه كشاھد أو"}, {"o": 109, "l": "المادة ٢٠٩", "b": "كان من الواجب أن ينبه إلى أن له أن يمتنع عن أداء الشھادة إذا شاء.\nأما إذا عرضت شھادة الزور شخصا ً آخر لمالحقة قانونية أو لحكم خفضت العقوبة من النصف إلى\n الثلثين.\nالمادة -٤١١يخفض نصف العقوبة عن الشخص الذي أديت شھادة الزور بتحريض منه إذا كان\n الشاھد يعرضه حتما ً لو قال الحقيقة أو يعرض أحد أقربائه لخطر جسيم كالذي أوضحته الفقرة\n األولى من المادة السابقة.\n النبذة -٦في التقرير الكاذب والترجمة الكاذبة\n\f المادة -٤١٢معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\nإن الخبير الذي تعينه السلطة القضائية ويجزم بأمر مناف للحقيقة أو يؤوله تأويالً غير صحيح على\n علمه بحقيقته يعاقب بالحبس ثالثة أشھر على األقل وبغرامة ال تنقص عن مئة ألف ليرة ويمنع\n فضالً عن ذلك أن يكون أبداً خبيراً.\n ويقضي باألشغال الشاقة إذا كانت مھمة الخبير تتعلق بقضية جنائية.\nالمادة -٤١٣يتعرض لعقوبات المادة السابقة بما اشتملت عليه من الفوارق المترجم الذي يترجم\n قصداً ترجمة غير صحيحة في قضية عدلية.\n ويقضى عليه فضالً عن ذلك بالمنع عن مزاولة الترجمة أبداً.\n المادة -٤١٤تطبق على الخبير والترجمان أحكام المادة .٤٠٩\n النبذة -٧في اليمين الكاذبة\n المادة -٤١٥معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\nمن حلف اليمين الكاذبة في قضية مدنية عوقب بالحبس من ستة أشھر إلى ثالث سنوات وبالغرامة\n من مئة ألف إلى مائتي ألف ليرة.\nويعفى من العقاب إذا رجع عن يمينه قبل أن يبت في الدعوى التي كانت موضوع اليمين بحكم ولو\n غير مبرم.\n النبذة -٨في التصرف بالأشياء المبرزة أمام القضاء\n المادة -٤١٦معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n\fمن تصرف بوثيقة أو بشيء آخر أو إخفاء أو أتلفه أو شوھه بعد أن أبرزه للقضاء عوقب بالغرامة\n من خمسين ألف إلى ستمائة ألف ليرة.\n ويطبق ھذا النص إذا كانت الوثيقة أو الشيء المبرز قد ترك على أن يقدم لدى كل طلب."}, {"o": 110, "l": "المادة ٢٠٩", "b": "النبذة -٩في الحصانة القضائية والأعمال التي تعرقل سير العدالة\n المادة -٤١٧ال تترتب أية دعوى ذم أو قدح على الخطب والكتابات التي تلفظ أو تبرز أمام\n المحاكم عن نية حسنة وفي حدود حق الدفاع المشروع.\n المادة -٤١٨معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n من وجد في مكان يجري فيه تحقيق قضائي وخالف أمر اإلخراج الصادر عن القاضي الذي يدير\nالجلسة أوقفه القاضي وحكم عليه بالتوقيف التكديري أربعا ً وعشرين ساعة فضالً عما يتعرض له\n من عقوبات أشد تنزلھا به المحكمة ذات الصالحية عند االقتضاء.\n المادة -٤١٩معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n من استعطف قاضيا ً كتابة كان أو مشافھة لمصلحة أحد المتداعين أو ضده عوقب بالغرامة من\n عشرين ألف إلى مئة ألف ليرة.\n النبذة -١٠في ما يحظر نشره\n المادة -٤٢٠معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n يعاقب بالغرامة من خمسين ألف إلى مائتي ألف ليرة من ينشر:\n -١وثيقة من وثائق التحقيق الجنائي أو الجناحي قبل تالوتھا في جلسة علنية.\n -٢مذكرات المحاكم.\n\f -٣محاكمات الجلسات السرية.\n -٤المحاكمات في دعوى نسب.\n -٥المحاكمات في دعاوى الطالق أو الھجر.\n -٦كل محاكمة منعت المحاكم نشرھا.\nال تطبق النصوص السابقة على األحكام المنشورة عن حسن نية بغير واسطة اإلعالنات أو األلواح.\n المادة -٤٢١معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\nيعاقب بالحبس ستة أشھر على األكثر وبغرامة ال تجاوز المئة ألف ليرة أو بإحدى ھاتين العقوبتين\n من يقدمون عالنية على فتح اكتتابات أو اإلعالن عنھا للتعويض عما قضت به محكمة جزائية من\n غرامات أو رسوم أو عطل وضرر.\n الفصل الثاني -في ما يتعرض نفاذ القرارات القضائية\n النبذة -١في الجرائم التي تمس قوة القرارات القضائية\n المادة -٤٢٢معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\nإن الحارس القضائي الذي يقدم قصداً على إلحاق الضرر أو التصرف بكل أو بعض ما أؤتمن عليه"}, {"o": 111, "l": "المادة ٢٠٩", "b": "من األشياء يعاقب بالحبس من شھرين إلى سنتين وبالغرامة من عشرين ألف إلى مائتي ألف ليرة.\n ويقضي عليه بالغرامة فقط إذا تضرر الشيء بإھماله.\n كل شخص آخر مالكا ً األشياء الموضوعة تحت يد القضاء أو مدعيا ملكيتھا يقدم قصدا على أخذھا\n ً ً\n أو إلحاق الضرر بھا أو يخبىء ما أخذ منھا أو تصرف به وھو عالم بأمره يعاقب بالحبس من شھر\n إلى سنة وبالغرامة من عشرين ألف ليرة إلى مئة ألف ليرة.\n المادة -٤٢٣معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n يعاقب بالحبس من شھر إلى سنة وبالغرامة من مئة ألف إلى مليون ليرة.\n -١من لبث في عقار غير معتد بقرار اإلخالء أو وضع يده على عقار أخرج منه.\n -٢من خالف التدابير التي اتخذھا القاضي صيانة للمكية أو وضع اليد.\n\f إذا اقترن الفعل بالعنف كان الحبس من ستة أشھر إلى سنتين.\n المادة -٤٢٤معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n من أخفى أو مزق ولو جزئيا ً إعالنا ً علق تنفيذاً لحكم باإلدانة عوقب بالغرامة من خمسين ألف إلى\n مائتي ألف ليرة.\nإذا كان المحكوم عليه بعقوبة إلصاق الحكم قد اقترف ھو نفسه الجرم المذكور آنفا ً أو كان محرضا ً\n عليه أو متدخالً فيه استحق فضالً عن الغرامة الحبس حتى ستة أشھر.\n النبذة -٢في فرار السجناء\nالمادة -٤٢٥من أتاح الفرار أو سھله لشخص أوقف أو سجن وفاقا ً للقانون عن جنحة أو مخالفة\n عوقب بالحبس ستة أشھر على األكثر.\n إذا كان الفار قد أوقف أو سجن من أجل جناية يعاقب عليھا بعقوبة جنائية مؤقتة حكم على المجرم\nبالحبس من سنة إلى ثالث سنوات وإذا كانت عقوبة الجناية أشد تعرض المجرم لألشغال الشاقة من\n ثالث إلى سبع سنوات.\n المادة -٤٢٦من كان مولجا ً بحراسة أو سوق السجين فأتاح له الفرار أو سھله يعاقب بالحبس\n من ثالثة أشھر إلى ثالث سنوات في الحالة األولى المذكورة في المادة السابقة ،وباألشغال الشاقة"}, {"o": 112, "l": "المادة ٢٠٩", "b": "من ثالث سنوات إلى سبع سنوات في الحالة الثانية وباألشغال الشاقة من خمس سنوات إلى خمس\n عشرة سنة في الحالة الثالثة.\nإذا حصل الفرار بسبب إھمال الحارس أو السائق كانت عقوبته الحبس من شھر إلى سنة في الحالة\nاألولى المذكورة آنفا ً والحبس من ستة أشھر إلى سنتين في الحالة الثانية ومن سنة إلى ثالث سنوات\n في الحالة الثالثة.\n المادة -٤٢٧من أوكل إليھم حراسة السجناء أو سوقھم وأمدوھم تسھيالً لفرارھم بأسلحة أو\n بآالت سواھا تؤاتيھم على ارتكابه بواسطة الكسر أو العنف يعاقبون عن ھذا الفعل وحده باألشغال\n الشاقة المؤقتة ال أقل عن خمس سنوات.\n وكل شخص غيرھم أقدم على ھذا الفعل يعاقب باألشغال الشاقة المؤقتة.\n\fالمادة -٤٢٨تخفض نصف العقوبة إذا أمن المجرم القبض على الفار أو حمله على تسليم نفسه\n خالل ثالثة اشھر من فراره دون أن يكون قد ارتكب جريمة أخرى توصف بالجناية أو الجنحة.\n الفصل الثالث -في استيفاء الحق تحكماً\n النبذة -١في منع استيفاء الحق بالذات\n المادة -٤٢٩معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\nمن أقدم استيفاء لحقه بالذات وھو قادر على مراجعة السلطة ذات الصالحية بالحال على نزع مال\n في حيازة الغير أو استعمال العنف باألشياء فاضر بھا عوقب بغرامة ال تجاوز المائتي ألف ليرة.\n المادة -٤٣٠إذا اقترف الفعل المذكور في المادة السابقة بواسطة العنف على األشخاص أو\nباللجوء إلى إكراه معنوي عوقب الفاعل بالحبس ستة أشھر على األكثر فضالً عن الغرامة المحددة\n أعاله.\n وتكون عقوبته الحبس من ثالثة أشھر إلى سنتين إذا استعمل العنف أو اإلكراه شخص مسلح أو\n جماعة من ثالثة أشخاص أو أكثر ولو غير مسلحين.\n المادة -٤٣١تتوقف المالحقة على شكوى الفريق المتضرر إذا لم تقترن الجنحة المذكورة\n بجريمة أخرى تجوز مالحقتھا بال شكوى.\n النبذة -٢في المبارزة\n\f المادة -٤٣٢عقوبة المبارزة من شھر إلى سنة.\n المادة -٤٣٣معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧"}, {"o": 113, "l": "المادة ٢٠٩", "b": "كل دعوة إلى المبارزة وإن رفضت ،عقوبتھا الغرامة من خمسين ألف إلى أربعمائة ألف ليرة.\nالمادة -٤٣٤يعاقب بالعقوبة نفسھا من أھان آخر عالنية أو استھدفه لالزدراء العام ألنه لم يتحد\n امرءاً للمبارزة أو لم يلب من تحداه.\nالمادة -٤٣٥إذا أفضت المبارزة إلى الموت أو إلى تعطيل دائم كانت العقوبة في الحالة األولى\n االعتقال من ثالث إلى سبع سنوات وفي الحالة الثانية الحبس من سنة إلى ثالث سنوات.\n المادة -٤٣٦يعفى من العقوبة الطبيب أو الجراح الذي أسعف المتبارزين.\n الباب الخامس -في الجرائم المخلة بالثقة العامة\n الفصل الأول -في تقليد خاتم الدولة والعلامات الرسمية والعملة والإسناد المالية العامة\n النبذة -١في تقليد خاتم الدولة والعلامات الرسمية\n\f المادة -٤٣٧معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n من قلد خاتم الدولة اللبنانية أو خاتم دولة أجنبية أو استعمل الخاتم المقلد وھو على بينة من األمر\n عوقب باألشغال الشاقة سبع سنوات على األقل.\n من استعمل دون حق خاتم الدولة اللبنانية أو قلد دمغة خاتمھا أو دمغة خاتم دولة أجنبية أخرى\n عوقب باألشغال الشاقة المؤقتة.\n ويستحق المجرم في كلتا الحالتين غرامة ال تنقص عن الخمسمائة ألف ليرة.\n المادة -٤٣٨معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n من قلد خاتما ً أو ميسما ً أو طابعا ً أو مطرقة خاصة بإدارة عامة لبنانية كانت أو أجنبية أو قلد دمغة\n تلك األدوات.\n ومن استعمل لغرض غير مشروع أي عالمة من العالمات الرسمية المذكورة في الفقرة السابقة\n صحيحة كانت أو مزورة.\n عوقب بالحبس من سنة إلى ثالث سنوات وبالغرامة من مئة ألف إلى ستمائة ألف ليرة.\n المادة -٤٣٩من اقترف التقليد المعاقب عليه في ھذه النبذة يعفى من العقاب إذا أتلف المادة\n الجرمية قبل أي استعمال أو مالحقة.\n النبذة -٢في تزوير العملة والإسناد العامة\n المادة -٤٤٠معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧"}, {"o": 114, "l": "المادة ٢٠٩", "b": "من قلد عملة ذھبية أو فضية متداولة شرعا ً أو عرفا ً في لبنان أو في دولة أخرى بقصد ترويجھا أو\nاشترك وھو على بينة من األمر بإصدار العملة المقلدة أو بترويجھا أو بإدخالھا إلى البالد اللبنانية أو\n بالد دولة أجنبية عوقب باألشغال الشاقة مدة ال تنقص عن خمس سنوات وبغرامة تبلغ الخمسمائة\n ألف ليرة على األقل.\n المادة -٤٤١معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n\fإذا كانت إحدى الجرائم المنصوص عليھا في المادة السابقة تتعلق بعملة معدنية غير الذھب والفضة\n كانت العقوبة األشغال الشاقة المؤقتة والغرامة من مائتي ألف ليرة إلى مليوني ليرة.\n المادة -٤٤٢يعاقب بالعقوبات المنصوص عليھا في المادة السابقة من أقدم بقصد ترويج عملة\n متداولة شرعا ً أو عرفا ً في لبنان أو في دولة أجنبية على تزييفھا إما بإنقاص وزنھا أو بطالئھا\n بطالء يتوھم معه أنھا أكثر قيمة أو اشترك وھو على بينة من األمر بإصدار عملة مزيفة على ھذه\n الصورة ،أو بترويجھا أو بإدخالھا إلى البالد اللبنانية أو إلى بالد دولة أجنبية.\n المادة -٤٤٣معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n من قلد أوراق النقد أو أوراق النقد المصرفية اللبنانية أو األجنبية الصادرة بإذن الدولة بقصد\n ترويجھا أو اشترك بإصدارھا أو بترويجھا عوقب بالعقوبات المنصوص عليھا في المادة .٤٤٠\nالمادة -٤٤٤من زور إسناداً كالتي ذكرت آنفا ً أو اشترك وھو عالم باألمر بإصدار أوراق مزيفة\n أو بترويجھا أو بإدخالھا إلى البالد اللبنانية أو إلى بالد دولة أخرى عوقب بالعقوبات المنصوص\n عليھا في المادة .٤٤١\n المادة -٤٤٥معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n ً ً\n يعاقب بالحبس والغرامة من صنع أو عرض أو نقل بقصد االتجار أو روج قطعا معدنية مقلدا بھا\nعملة متداولة شرعا ً أو عرفا ً في لبنان أو في بالد أخرى أو أوراقا ً مطبوعة قد يقع التباس بينھا وبين"}, {"o": 115, "l": "المادة ٢٠٩", "b": "الورق النقدي أو أوراق النقد المصرفية اللبنانية أو األجنبية الصادرة بإذن الدولة.\n المادة -٤٤٦معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\n من قبض عن نية حسنة قطعا ً من العملة أو أوراقا ً نقدية أو أوراق النقد المصرفية اللبنانية أو\n األجنبية الصادرة بإذن الدولة مقلدة أو مزيفة أو مزورة وروجھا بعد أن تحقق من عيوبھا عوقب\n بغرامة ال تجاوز المائتي ألف ليرة.\n المادة -٤٤٧معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n ً\n يستحق العقوبة نفسھا من أعاد إلى التعامل وھو عالم باألمر عملة أو أوراقا نقدية أو أوراق النقد\n المصرفية اللبنانية أو األجنبية الصادرة بإذن الدولة أو إسناداً لألمر بطل التعامل بھا.\n\f المادة -٤٤٨معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\nمن صنع آالت أو أدوات معدة لتقليد أو تزييف أو تزوير العملة أو أوراق النقد المصرفية اللبنانية أو\n األجنبية الصادر بإذن الدولة أو حصل عليھا بقصد استعمالھا على وجه غير مشروع عوقب\n باألشغال الشاقة المؤقتة وبالغرامة مائتي ألف ليرة على األقل.\n ومن اقتنى تلك اآلالت أو األدوات على علمه بأمرھا عوقب بالحبس سنة على األقل.\n المادة -٤٤٩معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n يعاقب بالعقوبات الجنائية المنصوص عليھا في المادة السابقة من وجد حائزاً آالت أو أدوات معدة\nلصنع العملة أو الورق النقدي أو أوراق النقد المصرفية اللبنانية واستعمالھا على وجه غير مشروع.\n النبذة -٣في تزوير الطوابع وأوراق التمغة\n المادة -٤٥٠معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n من قلد أو زور أوراق التمغة أو الطوابع األميرية وطوابع اإليصاالت أو طوابع البريد بقصد\nاستعمالھا على وجه غير مشروع أو روجھا على علمه بأمرھا عوقب باألشغال الشاقة المؤقتة حتى\n خمس سنوات وبغرامة أقلھا مئة ألف ليرة."}, {"o": 116, "l": "المادة ٢٠٩", "b": "المادة -٤٥١معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n يعاقب بالحبس من ثالثة أشھر إلى سنة وبالغرامة من خمسين ألف إلى مائتي ألف ليرة من استعمل\n وھو عالم باألمر أحد الطوابع المقلدة أو المزورة أو طابعا ً سبق استعماله.\n أحكام شاملة\n\f المادة -٤٥٢يعفى من العقوبة من اشترك بإحدى الجنايات المنصوص عليھا في النبذتين الثانية\n والثالثة من ھذا الفصل وانبأ السلطة بھذه الجناية قبل إتمامھا.\n أما المدعى عليه الذي يتيح القبض ،لو بعد بدء المالحقات ،على سائر المجرمين أو على الذين\n يعرف مختبأھم فتخفض عقوبته فقط على نحو ما نصت عليه المادة .٢٥١\n الفصل الثاني -في التزوير\n المادة -٤٥٣معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\nالتزوير ھو تحريف متعمد للحقيقة ،في الوقائع أو البيانات التي يثبتھا صك أو مخطوط يشكل مستنداً\n بدافع إحداث ضرر مادي أو معنوي أو اجتماعي.\n المادة -٤٥٤يعاقب بعقوبة مرتكب التزوير نفسھا من استعمل المزور وھو عالم بأمره.\n المادة -٤٥٥إذا ارتكب التزوير أو استعمل المزور بقصد إثبات أمر صحيح خفضت العقوبة\n وفاقا ً للمادة .٢٥١\n النبذة -١في التزوير الجنائي\n المادة -٤٥٦يعاقب باألشغال الشاقة المؤقتة خمس سنوات على األقل الموظف الذي يرتكب\n تزويراً ماديا ً في أثناء قيامه بالوظيفة:\n إما بإساءته استعمال إمضاء أو خاتم أو بصمة إصبع وإجماالً بتوقيعه إمضاء مزوراً .وإما بصنع\n صك أو مخطوط.\n وإما بما يرتكبه من حذف أو إضافة أو تغيير في مضمون صك أو مخطوط.\n\f وال تنقص العقوبة عن سبع سنوات إذا كان السند المزور من السندات التي يعمل بھا إلى أن يدعى\n تزويرھا.\n تطبق أحكام ھذه المادة في حال إتالف السند إتالفا ً كليا ً أو جزئياً.\n المادة -٤٥٧معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\nيعاقب بالعقوبات المنصوص عليھا في المادة السابقة مع الفارق المبين فيھا الموظف الذي ينظم سنداً"}, {"o": 117, "l": "المادة ٢٠٩", "b": "من اختصاصه فيحدث تشويھا ً في موضوعه أو ظروفه:\n إما بإساءته استعمال إمضاء على بياض أؤتمن عليه.\n أو بتدوينه مقاوالت أو أقواالً غير التي صدرت عن المتعاقدين أو التي أملوھا.\n أو بإثباته وقائع كاذبة على أنھا صحيحة أو وقائع غير معترف بھا على أنھا معترف بھا أو بتحريفه\n أي واقعة أخرى بإغفاله أمراً أو إيراده على وجه غير صحيح.\n المادة -٤٥٨معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n ينزل منزلة الموظفين العامين لتطبيق المواد السابقة رجال الدين في المعامالت التي يقومون بھا\n بحكم القانون والمتعلقة باألحوال الشخصية وباألوقاف وكذلك كل من أجيز له بحكم القوانين\n واألنظمة إعطاء الصفة الرسمية لسند أو إلمضاء أو لخاتم.\n المادة -٤٥٩يعاقب سائر األشخاص الذين يرتكبون تزويراً في األوراق الرسمية بإحدى\n الوسائل المذكورة في المواد السابقة باألشغال الشاقة المؤقتة في الحاالت التي ال ينص فيھا القانون\n على خالف ذلك.\n المادة -٤٦٠معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n تعد كاألوراق الرسمية لتطبيق المواد السابقة:\n -١األسھم والسندات وشھادات اإليداع وسائر سندات القيم المنقولة المنصوص عليھا في المواد\n ٤٥٣وما يليھا من قانون التجارة سواء كانت اسمية أو للحامل أو لألمر ،التي يجيز القانون\n للشركات أو المؤسسات إصدارھا في لبنان أو في دولة أخرى.\n -٢سجالت مصرف لبنان وقيوده ومستنداته وإسناده المالية.\n -٣الشھادة العلمية اللبنانية أو األجنبية ،الصادرة عن المراجع الرسمية أو المعاھد العليا أو\n الجامعات والمفروضة من أجل ممارسة مھنة أو عمل أو وظيفة أو من أجل االنتساب إلى مؤسسة\n علمية أخرى.\n -٤أوراق اليانصيب التي تصدرھا اإلدارات والھيئات الرسمية.\n\f النبذة -٢في تزوير السجلات والبيانات الرسمية\n المادة -٤٦١معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧"}, {"o": 118, "l": "المادة ٢٠٩", "b": "من وجب عليه قانونا ً أن يمسك سجالت خاضعة لمراقبة السلطة فدون فيھا أمورا كاذبة أو أغفل\n ً\n تدوين أمور صحيحة فيھا عوقب بالحبس من شھر إلى سنة وبالغرامة مئة ألف ليرة على األقل إذا\n كان الفعل من شأنه إيقاع السلطة في الغلط.\n المادة -٤٦٢يعاقب بالعقوبة نفسھا من أبرز وھو عالم باألمر وثيقة مقلدة أو محرفة أو منظمة\n على وجه يخالف الحقيقة ومعدة ألن تكون أساسا ً إما لحساب الضرائب أو الرسوم أو غير ذلك من\n العوائد المتوجبة للدولة أو إلحدى اإلدارات العامة وإما للمراقبة القانونية على أعمال المجرم\n المتعلقة بمھمته.\n النبذة -٣في الشهادات الكاذبة\n المادة -٤٦٣معدلة وفقا للقانون ٤٨٧تاريخ ١٩٩٥/١٢/٨\n من أقدم بأي وسيلة مادية أو معنوية من الوسائل المنصوص عليھا في المادتين ٤٥٦و٤٥٧\nعقوبات ،على تزوير تذكرة ھوية أو شھادة إخراج قيد أو جواز سفر أو سمة دخول يعاقب بالحبس\n من ستة أشھر إلى ثالث سنوات.\n المادة -٤٦٤معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\nيعاقب بالحبس من شھرين إلى سنتين من أقدم باالختالق أو التحريف أو التحويل على تزوير تذكرة\n مرور أو رخصة صيد أو حمل سالح أو قيادة سيارة أو تذكرة ناخب أو وثيقة نقل أو نسخة عن\n السجل العدلي.\n\f ويعاقب بالعقوبة نفسھا:\n -١من حصل على أحدى ھذه الوثائق بذكر ھوية كاذبة أو بانتحال اسم غير اسمه أو بأي وسيلة\n مضللة أخرى.\n -٢من استعمل احدى ھذه الوثائق المعطاة باسم غير اسمه او بھوية غير ھويته.\n -٣الموظف الذي يسلم إحدى ھذه الوثائق مع علمه بانتحال االسم أو الھوية.\n المادة -٤٦٥ملغاة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n المادة -٤٦٦معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\nمن أقدم حال ممارسته وظيفة عامة أو خدمة عامة أو مھنة طبية أو صحية على إعطاء شھادة كاذبة\n معدة لكي تقدم إلى السلطة العامة أو من شأنھا أن تجر على الغير منفعة غير مشروعة أو أن تلحق"}, {"o": 119, "l": "المادة ٢٠٩", "b": "الضرر بصالح أحد الناس.\n ومن اختلق بانتحاله اسم أحد األشخاص المذكورين في الفقرة السابقة أو زور بواسطة التحريف\n شھادة كالتي ألمحت إليھا المادة المذكورة.\n عوقب بالحبس من شھرين إلى سنتين.\n وإذا كانت الشھادة الكاذبة قد أعدت لكي تبرز أمام القضاء أو لتبرر اإلعفاء من خدمة عامة فال\n ينقص الحبس عن ستة أشھر.\n المادة -٤٦٧معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n إن أوراق التبليغ التي يحررھا المباشرون وسائر العاملين في الدولة واإلدارات العامة وكذلك\n المحاضر والتقارير التي يحررھا رجال الضابطة العدلية تنزل منزلة الوثائق المذكورة في المادة\n ،٤٦٣وتعاقب بالعقوبة المذكورة في ھذه المادة.\n المادة -٤٦٨من وضع تحت اسم مستعار أو زور شھادة حسن سلوك أو شھادة فقر عوقب\n بالحبس حتى ستة أشھر.\n وتكون العقوبة من شھر إلى سنة إذا وضعت الشھادة تحت اسم موظف أو تناول التزوير شھادة\n صادرة عن موظف.\n النبذة -٤في انتحال الهوية\n\f المادة -٤٦٩من تقدم إلى سلطة عامة بھوية كاذبة قصد جلب المنفعة لنفسه أو لغيره أو بنية\n األضرار بحقوق أحد الناس عوقب بالحبس من شھرين إلى سنتين فضالً عما قد يتعرض له من\n العقوبات الجنائية في حال تواطئه مع موظف عام.\nالمادة -٤٧٠تفرض العقوبة نفسھا على كل شخص يثبت عن علم منه في األحوال المذكورة آنفا ً\n ھوية أحد الناس الكاذبة أمام السلطات العامة.\n النبذة -٥في تزوير الأوراق الخاصة\n المادة -٤٧١معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n من ارتكب التزوير في أوراق خاصة بإحدى الوسائل المحددة في المادتين ٤٥٦و ٤٥٧عوقب\n بالحبس من سنة إلى ثالث سنوات وبغرامة أقلھا مئة ألف ليرة.\n المادة -٤٧٢إذا أقر المجرم بالفعل الجرمي قبل االستعمال والمالحقة أعفي من العقاب.\n أما إذا حصل اإلقرار عن الجرم بعد استعمال المزور وقبل الشكوى أو المالحقة فتخفض العقوبة\n على نحو ما جاء في المادة .٢٥١"}, {"o": 120, "l": "المادة ٢٠٩", "b": "الباب السادس -في الجرائم التي تمس الدين والعائلة\n الفصل الأول -في الجنح التي تمس الدين\n\f النبذة -١في ما يمس الشعور الديني\n المادة -٤٧٣من جدف على اسم الله عالنية عوقب بالحبس من شھر إلى سنة.\n المادة -٤٧٤معدلة وفقا للقانون تاريخ ١٩٥٤/١٢/١\n من أقدم بإحدى الطرق المنصوص عليھا في"}, {"o": 121, "l": "المادة ٢٠٩", "b": "المادة ٢٠٩على تحقير الشعائر الدينية التي تمارس\nعالنية أو حث على االزدراء بإحدى تلك الشعائر عوقب بالحبس من ستة أشھر إلى ثالث سنوات.\n المادة -٤٧٥ملغاة وفقا للقانون تاريخ ١٩٥٤/١٢/١\n يعاقب بالحبس من ستة أشھر إلى ثالث سنوات:\n -١من أحدث تشويشا ً عند القيام بإحدى الطقوس أو باالحتفاالت أو الرسوم الدينية المتعلقة بتلك\n الطقوس أو عرقلھا بأعمال الشدة أو التھديد.\n -٢من ھدم أو حطم أو شوه أو دنس أو نجس أبنية خصت بالعبادة أو أشعرتھا وغيرھا مما يكرمه\n أھل ديانة أو فئة من الناس.\n النبذة -٢في تغيير المذهب\n المادة -٤٧٦معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\n إذا خالف أحد رجال الدين األحكام القانونية المتعلقة بتغيير الدين أو المذھب أو احتفل بالزواج\nالديني دون أن يتثبت عند الحاجة من أن األحكام المذكورة قد روعيت عوقب بالغرامة من خمسين\n ألف إلى خمسمائة ألف ليرة.\n\f أحكام شاملة\n المادة -٤٧٧يمكن منع المجرم من الحقوق المذكورة في الفقرتين الثانية والرابعة من"}, {"o": 122, "l": "المادة ٦٥", "b": "المادة\n ٦٥إذا اقترف إحدى الجرائم الواردة في المواد ٤٧٤إلى .٤٧٦\n النبذة -٣في التعدي على حرمة الأموات وفي الجرائم المخلة بنظام دفنهم\nالمادة -٤٧٨من أحدث تشويشا ً في المآتم أو حفالت الموتى أو عرقلھا بأعمال الشدة أو التھديد\n عوقب بالحبس من شھرين إلى سنة.\n المادة -٤٧٩من سرق أو أتلف جثة كلھا أو بعضھا عوقب بالحبس من شھر إلى سنة ،وإذا\n حصلت السرقة بقصد إخفاء الموت أو الوالدة فمن شھرين إلى سنتين.\n المادة -٤٨٠معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n يعاقب بالغرامة من خمسين ألف إلى خمسمائة ألف ليرة وبالحبس مدة ال تزيد على ستة أشھر أو\n بإحدى العقوبتين من أقدم لغرض علمي أو تعليمي دون موافقة من له الحق على أخذ جثة أو\n تشريحھا أو على استعمالھا بأي وجه آخر.\n المادة -٤٨١يعاقب بالحبس من شھرين إلى سنتين:\n ً\n -١من ھتك أو دنس حرمة القبور أو أنصاب الموتى أو أقدم قصدا على ھدمھا أو تحطيمھا أو\n تشويھھا.\n -٢من دنس أو ھدم أو حطم أو شوه أي شيء آخر خص بشعائر الموتى أو بصيانة المقابر أو\n تزيينھا.\n\f المادة -٤٨٢معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n يعاقب بالتوقيف التكديري بالغرامة من عشرين ألف إلى مائتي ألف ليرة:\n من يقدمون على دفن ميت أو ترميده دون مراعاة األصول القانونية أو يخالفون بأي صورة كانت\n القوانين واألنظمة المتعلقة بالدفن أو الترميد.\n إذا وقع الفعل بقصد إخفاء الموت أو الوالدة كانت العقوبة من شھرين إلى سنتين.\n الفصل الثاني -في الجرائم التي تمس العيلة\n النبذة -١في الجرائم المتعلقة بالزواج\n المادة -٤٨٣معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n إذا عقد أحد رجال الدين زواج قاصر لم يتم الثامنة عشرة من عمره دون أن يدون في العقد رضى\n من له الوالية على القاصر أو أن يستعاض عنه بإذن القاضي عوقب بالغرامة من خمسين ألف إلى\n خمسمائة ألف ليرة."}, {"o": 123, "l": "المادة ٦٥", "b": "المادة -٤٨٤يستحق العقوبة نفسھا رجل الدين الذي يعقد زواجا ً قبل أن يتم اإلعالنات وسائر\n المعامالت التي ينص عليھا القانون أو األحوال الشخصية أو يتولى زواج امرأة قبل انقضاء عدتھا.\n المادة -٤٨٥معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\nمن تزوج بطريقة شرعية على علمه ببطالن زواجه بسبب زواج سابق عوقب بالحبس من شھر إلى\n سنة.\n ويستھدف العقوبة نفسھا رجل الدين الذي يتولى عقد الزواج المذكور على علمه بالرابطة الزوجية\n السابقة.\n -يعاقب باألشغال الشاقة المؤقتة كل لبناني يتزوج من أجنبية بھدف منحھا الجنسية اللبنانية ويحكم\n بإسقاط جنسية الزوجة المكتسبة بفعل ھذا الزواج وتنزل بھا العقوبة نفسھا.\n\f المادة -٤٨٦ينزل منزلة رجال الدين لتطبيق األحكام السابقة ممثلو المتعاقدين والشھود الذين\n حضروا الزواج بصفتھم ھذه.\n النبذة -٢في الجنح المخلة بالآداب العيلية\n معدلة وفقا للقانون رقم ٢٩٣تاريخ ٢٠١٤/٥/٧\n المادة -٤٨٧يعاقب على الزنا الذي يرتكبه أي من الزوجين بالحبس من ثالثة أشھر الى سنتين.\n ويقضى بالعقوبة نفسھا على شريك الزنى إذا كان متزوجا ً وإال فبالحبس من شھر الى سنة.\n نص المادة قبل التعديل بموجب القانون رقم ٢٩٣تاريخ ٢٠١٤/٥/٧\n تعاقب المرأة الزانية بالحبس من ثالثة أشھر إلى سنتين.\n ويقضى بالعقوبة نفسھا على شريك الزانية إذا كان متزوجا ً وإال فالحبس من شھر إلى سنة.\nفيما خال اإلقرار القضائي والجنحة المشھودة ال يقبل من أدلة الثبوت على الشريك إال ما نشأ منھا عن الرسائل والوثائق الخطية\n التي كتبھا.\n معدلة وفقا للقانون رقم ٢٩٣تاريخ ٢٠١٤/٥/٧\n المادة -٤٨٨يعاقب أي من الزوجين بالحبس من شھر الى سنة إذا إتخذ له خليالً جھاراً في أي\n مكان كان.\n وتنزل العقوبة نفسھا بالشريك.\n نص المادة قبل التعديل بموجب القانون رقم ٢٩٣تاريخ ٢٠١٤/٥/٧"}, {"o": 124, "l": "المادة ٦٥", "b": "يعاقب الزوج بالحبس من شھر إلى سنة إذا ارتكب الزنا في البيت الزوجي أو اتخذ له خليلة جھاراً في أي مكان كان.\n وتنزل العقوبة نفسھا بالمرأة الشريك.\n معدلة وفقا للقانون رقم ٢٩٣تاريخ ٢٠١٤/٥/٧\n المادة -٤٨٩\n  ال يجوز مالحقة فعل الزنا إال بشكوى أحد الزوجين وإتخاذ مقدم الشكوى صفة المدعي\n الشخصي.\n  ال يالحق الشريك أو المتدخل اال والزاني معاً.\n  ال تقبل الشكوى من الزوج الذي تم الزنا برضاه.\n  ال تقبل الشكوى بإنقضاء ثالثة أشھر على اليوم الذي اتصل فيه الجرم بعلم الشاكي.\n  إسقاط الحق عن الزوج أو الزوجة يسقط دعوى الحق العام والدعاوى الشخصية عن\n سائر المجرمين.\n  إذا رضي المدعي باستئناف الحياة المشتركة تسقط الشكوى«.\n نص المادة قبل التعديل بموجب القانون رقم ٢٩٣تاريخ ٢٠١٤/٥/٧\n ال يجوز مالحقة فعل الزنا إال بشكوى الزوج واتخاذه صفة المدعي الشخصي.\n\f ال يالحق الشريك أو المتدخل إال والزوج معا ً.\n ال تقبل الشكوى من الزوج الذي تم الزنا برضاه.\n ال تقبل الشكوى بانقضاء ثالثة أشھر على اليوم الذي اتصل فيه الجرم بعلم الزوج.\n إسقاط الحق عن الزوج أو الزوجة يسقط دعوى الحق العام والدعوى الشخصية عن سائر المجرمين.\n إذا رضي الرجل باستئناف الحياة المشتركة تسقط الشكوى.\n المادة -٤٩٠السفاح بين األصول والفروع شرعيين كانوا أو غير شرعيين أو بين األشقاء\n والشقيقات واألخوة واألخوات ألب أو ألم أو من ھم بمنزلة ھؤالء جميعا ً من األصھرة يعاقب عليه\n بالحبس من شھرين إلى سنتين.\n إذا كان ألحد المجرمين على اآلخر سلطة شرعية أو فعلية فالعقوبة من سنة إلى ثالث سنوات.\n يمكن منع المجرم من حق الوالية.\n المادة -٤٩١يالحق السفاح الموصوف في المادة السابقة بناء على شكوى قريب أو صھر أحد\n المجرمين حتى الدرجة الرابعة.\n وتباشر المالحقة بال شكوى إذا أدى األمر إلى الفضيحة.\n النبذة -٣في الجرائم المتعلقة بالولد وبنوته"}, {"o": 125, "l": "المادة ٦٥", "b": "المادة -٤٩٢معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n من خطف أو خبأ ولداً دون السابعة من عمره أو أبدل ولداً بآخر أو نسب إلى امرأة ولداً لم تلده\n عوقب باألشغال الشاقة المؤقتة.\nوال تنقص العقوبة عن خمس سنوات إذا كان الغرض من الجريمة أو كانت نتيجتھا إزالة أو تحريف\n البينة المتعلقة بأحوال الولد الشخصية أو تدوين أحوال شخصية صورية عن السجالت الرسمية.\n المادة -٤٩٣معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n من أودع ولداً مأوى اللقطاء وكتم ھويته حال كونه مقيداً في سجالت النفوس ولداً شرعيا ً أو غير\n شرعي معترف به عوقب باألشغال الشاقة المؤقتة.\n المادة -٤٩٤معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n\f كل عمل غير األعمال التي ذكرت في المواد السابقة يرمي إلى إزالة أو تحريف البينة المتعلقة\n بأحوال أحد الناس الشخصية يعاقب عليه باألشغال الشاقة المؤقتة.\n النبذة -٤في التعدي على حق حراسة القاصر\n المادة -٤٩٥معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n من خطف أو أبعد قاصراً دون الثامنة عشرة من عمره ولو برضاه قصد نزعه عن سلطة من له\nعليه الوالية أو الحراسة عوقب بالحبس من ستة أشھر إلى ثالث سنوات وبالغرامة من خمسين ألف\n إلى مائتي ألف ليرة.\n وإذا لم يكن القاصر قد أتم الثانية عشرة من عمره أو خطف أو أبعد بالحيلة أو القوة كانت العقوبة\n األشغال الشاقة المؤقتة.\n المادة -٤٩٦معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n األب واألم وكل شخص آخر ال يمتثل أمر القاضي فيرفض أو يؤخر إحضار قاصر لم يتم الثامنة\n عشرة من عمره يعاقب بالحبس من ثالثة أشھر إلى سنتين وبالغرامة من خمسين ألف إلى مائتي\n ألف ليرة.\n المادة -٤٩٧تخفض العقوبات المنصوص عليھا في المواد السابقة بالمقدار المعين في"}, {"o": 126, "l": "المادة ٢٥١", "b": "المادة\n ٢٥١عن المجرم الذي ارجع القاصر أو قدمه قبل صدوره أي حكم.\n ال يطبق ھذا النص في حالة التكرار.\n النبذة -٥في تسييب الولد أو العاجز\n\f المادة -٤٩٨من طرح أو سيب ولداً دون السابعة من عمره أو أي شخص آخر ال يملك حماية\n نفسه بسبب حالة جسدية أو نفسية عوقب بالحبس من ثالثة أشھر إلى سنة.\n إذا طرح الولد أو العاجز أو سيب في مكان قفر كان العقاب من سنة إلى ثالث سنوات.\n المادة -٤٩٩إذا سبب الجريمة للمجنى عليه مرضا ً أو أذى أو أفضت به إلى الموت أوخذ بھا\n المجرم وفاقا ً ألحكام"}, {"o": 127, "l": "المادة ١٩١", "b": "المادة ١٩١في حالة الطرح والتسييب في مكان غير مقفر إذا لم يكن قد توقع\n تلك النتيجة أو اعتقد أن بإمكانه اجتنابھا وأوخذ بھا وفاقا ً لحكام"}, {"o": 128, "l": "المادة ١٨٩", "b": "المادة ١٨٩في حالة الطرح أو\n التسييب في مكان مقفر كلما توقع النتيجة وقبل بالمخاطر.\n المادة -٥٠٠إذا كان المجرم أحد أصول الولد أو العاجز أو أحد األشخاص المولين حراسته أو\n مراقبته أو معالجته أو تربيته شددت العقوبة على نحو ما نصت عليه المادة .٢٥٧\n ال يطبق ھذا النص على الوالدة التي أقدمت محرضة أو فاعلة أو متدخلة على طرح مولودھا أو\n تسييبه صيانة لشرفھا."}, {"o": 129, "l": "المادة ٥٠٠", "b": "المادة ٥٠٠مكرر -مضافة وفقا للقانون ٢٢٤تاريخ ١٩٩٣ /٥ /١٣\n كل من تخلى أو حاول التخلي لفترة مؤقتة أو دائمة عن قاصر دون الثامنة عشرة من عمره ولو\n بقصد إعطائه للتبني لقاء مقابل مالي أو أي نفع آخر ،عوقب بالحبس من سنة إلى ثالث سنوات\n وبالغرامة من خمسة ماليين إلى عشرين مليون ليرة لينانية.\n تنزل العقوبة ذاتھا بالشريك والمتدخل .يعاقب بالعقوبة ذاتھا:\n -١كل من حمل أو حاول أن يحمل والدي قاصر أو أحدھما ،أو األب أو األم لولد غير شرعي\nمعترف به منھما أو من أحدھما ،أو كل من له سلطة والية أو وصاية للتخلي عن القاصر لقاء مبالغ\n مالية أو أية منفعة أخرى.\n -٢كل من حمل أو حاول أن يحمل بأية وسيلة مباشرة أو غير مباشرة والدي طفل ولد أو قد يولد\n على التعھد بالتخلي عن الطفل أو التعاقد للتخلي عنه ،وكل من يحوز ھذا التعھد أو يستعمله أو\n يحاول استعماله.\n -٣كل من يحمل أو يحاول أن يحمل أي شخص آخر على اإلنجاب بصورة شرعية أو الً ،بقصد\n بيع المولود.\n -٤كل من قدم أو حاول أن يقدم وساطته لقاء بدل مالي أو أي نفع آخر ،بغية الحصول على طفل\n أو تبنيه.\nتطبق العقوبة على التحريض في سائر الحاالت المذكورة أعاله بمعزل عن النتيجة التي يؤول إليھا.\n تشدد العقوبة وفقا ً للمادة ٢٥٧من قانون العقوبات في حال التكرار.\n\f النبذة -٦في إهمال الواجبات العائلية\n المادة -٥٠١معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n إن األب واألم اللذين يتركان في حالة احتياج ولدھما الشرعي أو غير الشرعي أو ولدا تبنياه سواء\nرفضا تنفيذ موجب اإلعالة الذي يقع على عاتقھما او اھمال الحصول على الوسائل التي تمكنھما من\n قضائه يعاقبان بالحبس مع التشغيل ثالثة أشھر على األكثر وبغرامة ال تتجاوز المائتي ألف ليرة.\n المادة -٥٠٢من قضى عليه بحكم اكتسب قوة القضية المحكمة بأن يؤدي إلى زوجه أو زوجه\n السابق أو إلى أصوله أو فروعه أو إلى أي شخص يجب عليه إعالته أو تربيته األقساط المعينة"}, {"o": 130, "l": "المادة ٥٠٠", "b": "فبقي شھرين ال يؤديھا عوقب بالحبس مع التشغيل من شھر إلى ستة أشھر وبغرامة توازي مقدار ما\n وجب عليه أداؤه.\n إن القرار الصادر عن محكمة أجنبية المقترن بالصيغة التنفيذية في لبنان يكون في حكم القرار\n الصادر عن القاضي اللبناني لتطبيق الفقرة السابقة.\n الباب السابع -في الجرائم المخلة بالأخلاق والآداب العامة\n الفصل الأول -في الاعتداء على العرض\n النبذة -١في الاغتصاب\n\f المادة -٥٠٣من أكره غير زوجه بالعنف والتھديد على الجماع عوقب باألشغال الشاقة لمدة\n خمس سنوات على األقل.\n و ال تنقص العقوبة عن سبع سنوات إذا كان المعتدى عليه لم يتم الخامسة عشرة من عمره.\n المادة -٥٠٤يعاقب باألشغال الشاقة المؤقتة من جامع شخصا ً غير زوجه ال يستطيع المقاومة\n بسبب نقص جسدي أو نفسي أو بسبب ما استعمل نحوه من ضروب الخداع.\n المادة -٥٠٥معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n من جامع قاصراً دون الخامسة عشرة من عمره يعاقب باألشغال الشاقة المؤقتة.\n وال تنقص العقوبة عن خمس سنوات إذا كان الولد لم يتم الثانية عشرة من عمره.\n ومن جامع قاصراً أتم الخامسة عشرة من عمره ولما يتم الثامنة عشرة عوقب بالحبس من شھرين\n إلى سنتين.\nالمادة -٥٠٦إذا جامع قاصراً بين الخامسة عشرة والثامنة عشرة من عمره أحد أصوله شرعيا ً\n كان أو غير شرعي أو أحد أصھاره لجھة األصول وكل شخص يمارس عليه سلطة شرعية أو\n فعلية أو أحد خدم أولئك األشخاص عوقب باألشغال الشاقة المؤقتة.\n ويقضي بالعقوبة نفسھا إذا كان المجرم موظفا ً أو رجل دين أو كان مدير مكتب استخدام أو عامالً\n فيه فارتكب الفعل مسيئا ً استعمال السلطة أو التسھيالت التي يستمدھا من وظيفته.\n النبذة -٢في الفحشاء\n المادة -٥٠٧من أكره آخر بالعنف والتھديد على مكابدة أو إجراء فعل مناف للحشمة عوقب\n باألشغال الشاقة مدة ال تنقص عن أربع سنوات."}, {"o": 131, "l": "المادة ٥٠٠", "b": "ويكون الحد األدنى للعقوبة ست سنوات إذا كان المعتدى عليه لم يتم الخامسة عشرة من عمره.\n\f معدلة وفقا قانون رقم - ١٦٤صادر في ٢٠١١/٨/٢٤\nالمادة -٥٠٨يعاقب باألشغال الشاقة المؤقتة عشر سنوات على األكثر من لجأ إلى ضروب الحيلة\n أو استفاد من علة امرىء في جسده أو نفسه فارتكب به فعالً منافيا ً للحشمة.\n نص"}, {"o": 132, "l": "المادة ٥٠٨", "b": "المادة ٥٠٨قبل التعديل بموجب القانون رقم ١٦٤تاريخ ٢٠١١/٨/٢٤\n يعاقب باألشغال الشاقة المؤقتة عشر سنوات على األكثر من لجأ إلى ضروب الحيلة أو استفاد من علة امرىء في جسده أو\n نفسه فارتكب به فعالً منافيا ً للحشمة أو حمله على ارتكابه.\n معدلة وفقا قانون رقم - ١٦٤صادر في ٢٠١١/٨/٢٤\n المادة -٥٠٩من ارتكب بقاصر دون الخامسة عشرة من عمره فعالً منافيا ً للحشمة عوقب\n باألشغال الشاقة المؤقتة.\n وال تنقص العقوبة عن أربع سنوات إذا لم يتم الولد الثانية عشرة من عمره.\n نص"}, {"o": 133, "l": "المادة ٥٠٩", "b": "المادة ٥٠٩قبل التعديل بموجب القانون رقم ١٦٤تاريخ ٢٠١١/٨/٢٤\n من ارتكب بقاصر دون الخامسة عشرة من عمره فعالً منافيا ً للحشمة أو حمله على ارتكابه عوقب باألشغال الشاقة المؤقتة.\n وال تنقص العقوبة عن أربع سنوات إذا لم يتم الولد الثانية عشرة من عمره.\n معدلة وفقا قانون رقم - ١٦٤صادر في ٢٠١١/٨/٢٤\nالمادة -٥١٠كل شخص من األشخاص الموصوفين في"}, {"o": 134, "l": "المادة ٥٠٦", "b": "المادة ٥٠٦يرتكب بقاصر بين الخامسة\n عشرة والثامنة عشرة من عمره فعالً منافيا ً للحشمة يعاقب باألشغال الشاقة مدة ال تزيد على عشر\n سنوات.\n نص"}, {"o": 135, "l": "المادة ٥١٠", "b": "المادة ٥١٠قبل التعديل بموجب القانون رقم ١٦٤تاريخ ٢٠١١/٨/٢٤\nكل شخص من األشخاص الموصوفين في"}, {"o": 136, "l": "المادة ٥٠٦", "b": "المادة ٥٠٦يرتكب بقاصر بين الخامسة عشرة والثامنة عشرة من عمره فعالً منافيا ً\n للحشمة أو يحمله على ارتكابه يعاقب باألشغال الشاقة مدة ال تزيد على عشر سنوات.\n أحكام الشاملة للنبذات السابقة\nالمادة -٥١١ترفع العقوبات المنصوص عليھا في المواد ٥٠٣إلى ٥٠٥و ٥٠٧إلى ٥٠٩على\n النحو الذي ذكرته"}, {"o": 137, "l": "المادة ٢٥٧", "b": "المادة ٢٥٧إذا كان المجرم أحد األشخاص المشار إليھم في المادة .٥٠٦\n المادة -٥١٢تشدد بمقتضى أحكام"}, {"o": 138, "l": "المادة ٢٥٧", "b": "المادة ٢٥٧عقوبات الجنايات المنصوص عليھا في ھذا\n الفصل:\n\f إذا اقترفھا شخصان أو أكثر اشتركوا في التغلب على مقاومة المعتدى عليه أو تعاقبوا على إجراء\n الفحش به.\n إذا أصيب المعتدى عليه بمرض زھري أو بأي مرض آخر أو أذى تسبب عنھما تعطيل تزيد مدته\n عن عشرة أيام أو كانت المعتدى عليھا بكراً فأزيلت بكارتھا.\n إذا أدت إحدى الجنايات السابق ذكرھا إلى موت المعتدى عليه ولم يكن الفاعل قد أراد ھذه النتيجة\n فال تنقص العقوبة عن اثنتي عشرة سنة.\nالمادة -٥١٣كل موظف راود عن نفسھا زوجة سجين أو موقوف أو شخص خاضع لمراقبته أو\n سلطته أو راود إحدى قريبات ذلك الشخص عوقب بالحبس من ثالثة أشھر إلى سنة.\nوتنزل العقوبة نفسھا بالموظف الذي يراود عن نفسھا زوجة أو قريبة شخص له قضية منوط فصلھا\n به أو برؤسائه.\n تضاعف العقوبة إذا نال المجرم أربه من إحدى النساء المذكورات آنفا ً.\n النبذة -٣في الخطف\n المادة -٥١٤من خطف بالخداع أو العنف فتاة أو امرأة بقصد الزواج عوقب بالحبس من سنة\n إلى ثالث سنوات.\n المادة -٥١٥من خطف بالخداع أو العنف أحد األشخاص ذكراً كان أو أنثى بقصد ارتكاب\n الفجور به عوقب باألشغال الشاقة المؤقتة وإذا ارتكب الفعل المذكور فال تنقص العقوبة عن سبع\n سنوات.\n المادة -٥١٦تفرض العقوبات السابقة إذا ارتكب الفعل دون خداع أو عنف على قاصر لم يتم\n الخامسة عشرة من عمره.\n المادة -٥١٧يستفيد من األسباب المخففة المنصوص عليھا في"}, {"o": 139, "l": "المادة ٢٥١", "b": "المادة ٢٥١المجرم الذي يرجع\n المخطوف من تلقاء نفسه في خالل ثماني وأربعين ساعة إلى مكان أمين ويعيد إليه حريته دون أن\n يرتكب به فعالً منافيا ً للحياء أو جريمة أخرى جنحة كانت أو جناية.\n\f النبذة -٤في الإغواء والتهتك وخرق حرمة الأماكن الخاصة بالنساء\n المادة -٥١٨معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n ً\nمن أغوى فتاة بوعد الزواج ففض بكارتھا عوقب إذا كان الفعل ال يستوجب عقابا أشد بالحبس حتى\n ستة أشھر وبغرامة أقصاھا مائتي ألف ليرة أو بإحدى العقوبتين.\n في ما خال اإلقرار ال يقبل من أدلة الثبوت على المجرم إال ما نشأ منھا عن الرسائل والوثائق\n األخرى التي كتبھا.\n المادة -٥١٩من لمس أو داعب بصورة منافية للحياء قاصراً دون الخامسة عشرة من عمره\n ذكراً كان أم أنثى أو امرأة أو فتاة لھما من العمر خمس عشرة سنة دون رضاھما عوقب بالحبس\n مدة التتجاوز الستة أشھر.\n المادة -٥٢٠معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n من عرض على قاصر دون الخامسة عشرة من عمره عمالً منافيا ً للحياء أو وجه إليه كالما ً مخالً\n بالحشمة عوقب بالتوقيف التكديري أو بغرامة ال تزيد عن مائتين وخمسين ألف ليرة أو بالعقوبتين\n معا ً.\n المادة -٥٢١كل رجل تنكر بزي امرأة قد خل مكانا ً خاصا ً بالنساء أو محظوراً دخوله وقت\n الفعل لغير النساء عوقب بالحبس ال أكثر من ستة أشھر.\n أحكام شاملة\n\f المادة -٥٢٢معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥\nإذا عقد زواج صحيح بين مرتكب إحدى الجرائم الواردة في ھذا الفصل وبين المعتدى عليھا أوقفت\n المالحقة وإذا كان صدر الحكم بالقضية علق تنفيذ العقاب الذي فرض عليه.\n يعاد إلى المالحقة أو تنفيذ العقوبة قبل انقضاء ثالث سنوات على الجنحة وانقضاء خمس سنوات\nعلى الجناية إذا انتھى الزواج إما بطالق المرأة دون سبب مشروع أو بالطالق المحكوم به لمصلحة\n المعتدى عليھا.\n الفصل الثاني -في الحض على الفجور والتعرض للأخلاق والآداب العامة"}, {"o": 140, "l": "المادة ٢٥١", "b": "النبذة -١في الحض على الفجور\n المادة -٥٢٣معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥والقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧ووفقا\n للقانون رقم ٢٩٣تاريخ ٢٠١٤/٥/٧\n من حض شخصا ً أو أكثر ذكراً كان أو أنثى لم يبلغ الحادية والعشرين من عمره على الفجور\n والفساد أو سھلھما له أو مساعدته على إتيانھما عوقب بالحبس من شھر الى سنة وبغرامة تتراوح\n بين الحد األدنى لألجور وثالثة أضعافه.\n يعاقب بالعقوبة ذاتھا من تعاطى الدعارة السرية أو سھلھا.\n ً\n مع اإلحتفاظ بأحكام"}, {"o": 141, "l": "المادة ٥٢٩", "b": "المادة ٥٢٩معطوفة على"}, {"o": 142, "l": "المادة ٥٠٦", "b": "المادة ٥٠٦تشدد العقوبة وفاقا ألحكام"}, {"o": 143, "l": "المادة ٢٥٧", "b": "المادة ٢٥٧\n من ھذا القانون إذا وقع الجرم ضمن األسرة وذلك دون اإلعتداد بسن الشخص الواقع عليه الجرم.\n نص المادة قبل التعديل بموجب القانون رقم ٢٩٣تاريخ ٢٠١٤/٥/٧\nمن اعتاد حض شخص أو أكثر ذكراً كان أو أنثى لما يبلغ الحادية والعشرين من عمره على الفجور او الفساد أو على تسھيلھما\n له أو مساعدته على إتيانھما عوقب بالحبس من شھر إلى سنة وبغرامة من خمسين ألف إلى خمسمائة ألف ليرة.\n ويعاقب العقاب نفسه من تعاطى الدعارة السرية أو سھلھا.\n المادة -٥٢٤معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧ومن ثم الغية بموجب القانون رقم\n - ١٦٤صادر في ٢٠١١/٨/٢٤\n يعاقب بالحبس سنة على األقل وبغرامة ال تنقص عن نصف قيمة الحد األدنى الرسمي لألجور من\n أقدم إرضاء ألھواء الغير على إغواء أو اجتذاب أو إبعاد شخص برضاه.\n\f نص"}, {"o": 144, "l": "المادة ٥٢٤", "b": "المادة ٥٢٤قبل الغائھا بموجب القانون رقم - ١٦٤صادر في ٢٠١١/٨/٢٤\n يعاقب بالحبس سنة على األقل وبغرامة ال تنقص عن مائتي ألف ليرة من أقدم إرضاء ألھواء الغير على إغواء أو اجتذاب أو\n إبعاد امرأة أو فتاة دون الحادية والعشرين من عمرھا ولو برضاھا أو امرأة أو فتاة في الحادية والعشرين من العمر باستعمال\n الخداع أو العنف أو التھديد أو صرف النفوذ أو غير ذلك من وسائل اإلكراه.\n المادة -٥٢٥معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧ومن ثم الغية بموجب القانون رقم\n - ١٦٤صادر في ٢٠١١/٨/٢٤\nيعاقب بالحبس من شھرين إلى سنتين وبالغرامة من عُشر إلى قيمة الحد األدنى الرسمي لألجور من\n أقدم على استبقاء شخص رغما عنه بسبب دين له عليه في بيت الفجور.\n نص"}, {"o": 145, "l": "المادة ٥٢٥", "b": "المادة ٥٢٥قبل الغائھا بموجب القانون رقم - ١٦٤صادر في ٢٠١١/٨/٢٤\nيعاقب بالحبس من شھر إلى سنتين وبالغرامة من خمسين ألف الى خمسماية الف ليرة من أقدم باستعماله الوسائل المذكورة في\n المادة السابقة على استبقاء شخص رغما ً عنه ولو بسبب دين له عليه في بيت الفجور أو اكرھه على تعاطي الدعارة.\n المادة -٥٢٦معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n من اعتاد أن يسھل بقصد الكسب إغواء العامة على ارتكاب الفجور مع الغير ومن استعمل إحدى\n الوسائل المشار إليھا في الفقرتين ٢و ٣من"}, {"o": 146, "l": "المادة ٢٠٩", "b": "المادة ٢٠٩الستجالب الناس إلى الفجور يعاقب\n بالحبس من شھر إلى سنة وبالغرامة من عشرين ألف ليرة إلى مائتي ألف ليرة.\n المادة -٥٢٧معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧ووفقا للقانون رقم ٢٩٣تاريخ\n ٢٠١٤/٥/٧\n كل امرئ يعتمد في كسب معيشته أو بعضھا على دعارة الغير عوقب بالحبس من ستة أشھر الى\n سنتين وبغرامة تتراوح بين الحد األدنى لألجور وضعفه.\n ً\nمع اإلحتفاظ بأحكام"}, {"o": 147, "l": "المادة ٥٢٩", "b": "المادة ٥٢٩معطوفة على"}, {"o": 148, "l": "المادة ٥٠٦", "b": "المادة ٥٠٦من ھذا القانون تشدد العقوبة وفقا ألحكام"}, {"o": 149, "l": "المادة ٢٥٧", "b": "المادة ٢٥٧من قانون العقوبات إذا وقع الجرم ضمن األسرة ،وتضاعف العقوبة إذا رافق الجرم أي\n شكل من أشكال العنف أو التھديد.\n نص المادة قبل التعديل بموجب القانون رقم ٢٩٣تاريخ ٢٠١٤/٥/٧\n كل امرىء ال يتعاطى مھنة بالفعل فاعتمد في كسب معيشته أو بعضھا على دعارة الغير عوقب بالحبس من ستة أشھر إلى\n سنتين وبغرامة من عشرين ألف إلى مائتي ألف ليرة.\n المادة -٥٢٨يعاقب على المحاولة في الجنح المنصوص عليھا في المواد ٥٢٣إلى .٥٢٥\n المادة -٥٢٩تشدد بمقتضى أحكام"}, {"o": 150, "l": "المادة ٢٥٧", "b": "المادة ٢٥٧العقوبات التي تنص عليھا المواد المذكورة إذا\n كان المجرمون ممن وصفوا في المادة .٥٠٦\n\f المادة -٥٣٠يمكن القضاء باإلخراج من البالد وبالحرية المراقبة عند الحكم في إحدى الجنح\n المنصوص عليھا في ھذه النبذة ،ويقضى أيضا ً بإقفال المحل.\n النبذة -٢في التعرض للآداب والأخلاق العامة\nالمادة -٥٣١يعاقب على التعرض لآلداب العامة بإحدى الوسائل المذكورة في الفقرة األولى من"}, {"o": 151, "l": "المادة ٢٠٩", "b": "المادة ٢٠٩بالحبس من شھر إلى سنة.\n المادة -٥٣٢معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\nيعاقب على التعرض لألخالق العامة بإحدى الوسائل المذكورة في الفقرتين الثانية والثالثة من"}, {"o": 152, "l": "المادة ٢٠٩", "b": "المادة\n ٢٠٩بالحبس من شھر إلى سنة وبالغرامة من عشرين ألف إلى مائتي ألف ليرة.\nالمادة -٥٣٣يعاقب بالعقوبات نفسھا من أقدم على صنع أو تصدير أو توريد أو اقتناء كتابات أو\n رسوم أو صور يدوية أو شمسية أو أفالم إشارات أو غير ذلك من األشياء المخلة بالحياء بقصد\n اإلتجار بھا أو توزيعھا أو أعلن أو أعلم عن طريقة الحصول عليھا.\n المادة -٥٣٤كل مجامعة على خالف الطبيعة يعاقب عليھا بالحبس حتى سنة واحدة.\n النبذة -٣في دعارة القاصرين\n المادة -٥٣٥ملغاة وفقا للمرسوم االشتراعي ١١٩تاريخ١٩٨٣/٩/١٦\n\f المادة -٥٣٦ملغاة وفقا المرسوم االشتراعي ١١٩تاريخ١٩٨٣/٩/١٦\n الفصل الثالث -في الوسائط المانعة للحبل وفي الإجهاض\n النبذة -١في الوسائط المانعة للحبل\n المادة -٥٣٧ملغاة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n المادة -٥٣٨ملغاة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n النبذة -٢في الإجهاض\n المادة -٥٣٩معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\nكل دعاوى بإحدى الوسائل المنصوص عليھا في الفقرتين ٢و ٣من"}, {"o": 153, "l": "المادة ٢٠٩", "b": "المادة ٢٠٩يقصد منھا نشر\n أو ترويج أو تسھيل استعمال وسائط اإلجھاض يعاقب عليھا بالحبس من شھرين إلى سنتين\n وبالغرامة من مئة ألف إلى خمسمائة ألف ليرة.\n المادة -٥٤٠يعاقب بالعقوبة نفسھا من باع أو عرض للبيع أو اقتنى بقصد البيع مواد معدة\n ألحداث اإلجھاض أو سھل استعمالھا بأي طريقة كانت.\n\f المادة -٥٤١كل امرأة طرحت نفسھا بما استعملته من الوسائل أو استعمله غيرھا برضاھا\n تعاقب بالحبس من ستة أشھر إلى ثالث سنوات.\n المادة -٥٤٢من أقدم بأي وسيلة كانت على تطريح امرأة أو محاولة تطريحھا برضاھا عوقب\n بالحبس من سنة إلى ثالث سنوات.\n إذا افضى اإلجھاض أو الوسائل التي استعملت في سبيله إلى موت المرأة عوقب الفاعل باألشغال\n الشاقة من أربع إلى سبع سنوات.\n وتكون العقوبة من خمس سنوات إلى عشرة سنوات إذا تسبب الموت عن وسائل أشد خطراً من\n الوسائل التي رضيت بھا المرأة.\n المادة -٥٤٣من تسبب عن قصد بتطريح امرأة دون رضاھا عوقب باألشغال الشاقة خمس\n سنوات على األقل.\n وال تنقص العقوبة عن عشر سنوات إذا افضى اإلجھاض أو الوسائل المستعملة إلى موت المرأة.\nالمادة -٥٤٤تطبق المادتان ٥٤٢و ٥٤٣ولو كانت المرأة التي أجريت عليھا وسائل التطريح\n غير حامل.\nالمادة -٥٤٥تستفيد من عذر مخفف المرأة التي تطرح نفسھا محافظة على شرفھا وكذلك يستفيد\n من العذر نفسه من ارتكب إحدى الجرائم المنصوص عليھا في المادتين ا لـ ٥٤٢و ٥٤٣للمحافظة\n على شرف أحد فروعه أو قريباته حتى الدرجة الثانية.\n أحكام شاملة\n المادة -٥٤٦إذا ارتكب إحدى الجنح المنصوص عليھا في ھذا الفصل طبيب أو جراح أو قابلة\nأو اجزائي أو صيدلي أو أحد مستخدميھم فاعلين كانوا أو محرضين أو متدخلين شددت العقوبة وفاقا ً\n للمادة .٢٥٧\n\f ويكون األمر كذلك إذا كان المجرم قد اعتاد بيع العقاقير وسائر المواد المعدة للتطريح.\n ويستھدف المجرم فضالً عن ذلك للمنع من مزاولة مھنته أو عمله وإن لم يكونا منوطين بإذن"}, {"o": 154, "l": "المادة ٢٠٩", "b": "السلطة أو نيل شھادة.\n ويمكن الحكم أيضا ً بإقفال المحل.\n معدلة وفقا للقانون رقم - ١٦٤صادر في ٢٠١١/٨/٢٤\n الباب الثامن -في الجنايات والجنح التي تقع على الأشخاص\n الفصل الأول -في الجنايات والجنح على حياة الإنسان وسلامته\n النبذة -١في القتل قصداً\n معدلة وفقا للقانون رقم ٢٩٣تاريخ ٢٠١٤/٥/٧\n المادة -٥٤٧من قتل إنسانا ً قصداً عوقب باألشغال الشاقة من خمس عشرة سنة إلى عشرين\n سنة.\n من قتل إنسانا ً قصداً عوقب باألشغال الشاقة من خمس عشرة سنة الى عشرين سنة.\n تكون العقوبة من عشرين سنة الى خمسة وعشرين سنة إذا ارتكب فعل القتل أحد الزوجين ضد\n اآلخر.\nالمادة -٥٤٨معدلة وفقا للقانون تاريخ ١٩٤٨ /٥ /٢٤وبالمرسوم االشتراعي ١١٠تاريخ /٣٠\n ١٩٧٧ /٦وبالمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n يعاقب باألشغال الشاقة المؤبدة على القتل قصداً إذا ارتكب:\n -١لسبب سافل.\n -٢للحصول على المنفعة الناتجة عن الجنحة.\n -٣بإقدام المجرم على التمثيل بالجثة بعد القتل.\n\f -٤على حدث دون الخامسة عشرة من عمره.\n -٥على شخصين أو أكثر.\n المادة -٥٤٩معدلة وفقا للقانون تاريخ ١٩٤٩ /٥ /٢٤والمرسوم االشتراعي ١١٠تاريخ\n ١٩٧٧ /٦ /٣٠وبالمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n يعاقب باإلعدام على القتل قصداً إذا ارتكب:\n -١عمداً.\n -٢تمھيداً لجناية أو لجنحة ،أو تسھيالً أو تنفيذاً لھا ،أو تسھيالً لفرار المحرضين على تلك الجناية أو\n فاعليھا أو المتدخلين فيھا أو للحيلولة بينھم وبين العقاب.\n -٣على أحد أصول المجرم أو فروعه.\n -٤في حالة إقدام المجرم على أعمال التعذيب أو الشراسة نحو األشخاص.\n -٥على موظف في أثناء ممارسته وظيفته أو في معرض ممارسته لھا أو بسببھا.\n -٦على إنسان بسبب انتمائه الطائفي أو ثأراً منه لجناية ارتكبھا غيره من طائفته أو من أقربائه أو\n من محازبيه.\n -٧باستعمال المواد المتفجرة.\n -٨من أجل التھرب من جناية أو جنحة أو إلخفاء معالمھا."}, {"o": 155, "l": "المادة ٢٠٩", "b": "المادة -٥٥٠من تسبب بموت إنسان من غير قصد القتل بالضرب أو العنف أو الشدة أو بأي\n عمل آخر مقصود عوقب باألشغال الشاقة خمس سنوات على األقل.\n وال تنقص العقوبة عن سبع سنوات إذا اقترن الفعل بإحدى الحاالت المنصوص عليھا في المادتين\n السابقتين.\nالمادة -٥٥١تعاقب باالعتقال المؤقت الوالدة التي تقدم ،اتقاء للعار ،على قتل وليدھا الذي حبلت\n به سفاحا ً.\n وال تنقص العقوبة عن خمس سنوات إذا وقع الفعل عمداً.\n المادة -٥٥٢يعاقب باالعتقال عشر سنوات على األكثر من قتل إنسانا ً قصداً بعامل اإلشفاق\n بناء على إلحاحه بالطلب.\n المادة -٥٥٣من حمل إنسانا ً بأي وسيلة كانت على االنتحار أو ساعده ،بطريقة من الطرق\n المذكورة في المادة -٢١٩الفقرات األولى والثانية والرابعة -على قتل نفسه ،عوقب باالعتقال\n عشر سنوات على األكثر إذا تم االنتحار.\n بالحبس من ثالثة أشھر إلى سنتين في حالة الشروع في االنتحار نجم عنه إيذاء أو عجز دائم.\n\f وإذا كان الشخص المحمول أو المساعد على االنتحار حدثا ً دون الخامسة عشرة من عمره أو\n معتوھا ً طبقت عقوبات التحريض على القتل أو التدخل فيه.\n النبذة -٢في إيذاء الأشخاص قصداً\n المادة -٥٥٤معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n من أقدم قصداً على ضرب شخص أو جرحه أو إيذائه ولم ينجم عن ھذه األفعال مرض أو تعطيل\n شخص عن العمل لمدة تزيد عن عشرة أيام عوقب بناء على شكوى المتضرر بالحبس ستة أشھر\nعلى األكثر أو بالتوقيف التكديري وبالغرامة من عشرة آالف إلى خمسين ألف ليرة أو بإحدى ھاتين\n العقوبتين.\n إن تنازل الشاكي يسقط الحق العام ،ويكون له على العقوبة ما لصفح المدعي الشخصي من\n المفعول.\n المادة -٥٥٥معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n إذا نجم عن األذى الحاصل مرض أو تعطيل شخص عن العمل مدة تزيد عن عشرة أيام عوقب\nالمجرم بالحبس مدة ال تتجاوز السنة وبغرامة مئة ألف ليرة على األكثر أو بإحدى ھاتين العقوبتين."}, {"o": 156, "l": "المادة ٢٠٩", "b": "وإذا تنازل الشاكي عن حقه خفضت العقوبة إلى النصف.\n المادة -٥٥٦إذا جاوز المرض أو التعطيل عن العمل العشرين يوما ً قضي بعقوبة الحبس من\n ثالثة أشھر إلى ثالث سنوات فضالً عن الغرامة السابق ذكرھا.\n المادة -٥٥٧معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n إذا أدى الفعل إلى قطع أو استئصال عضو أو بتر أحد األطراف أو إلى تعطيل أحدھما أو تعطيل\nإحدى الحواس عن العمل أو تسبب في إحداث تشويه جسيم أو أية عاھة أخرى دائمة أو لھا مظھر\n العاھة الدائمة عوقب المجرم باألشغال الشاقة المؤقتة عشر سنوات على األكثر.\n المادة -٥٥٨معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n\f يعاقب بالعقوبة نفسھا من تسبب بإحدى األفعال المذكورة في"}, {"o": 157, "l": "المادة ٥٥٤", "b": "المادة ٥٥٤بإجھاض حامل وھو\n على علم بحملھا.\n معدلة وفقا للقانون رقم ٢٩٣تاريخ ٢٠١٤/٥/٧\n المادة -٥٥٩تشدد العقوبات المذكورة في ھذه النبذة وفاقا ً ألحكام"}, {"o": 158, "l": "المادة ٢٥٧", "b": "المادة ٢٥٧إذا إقترف الفعل\nبإحدى الحاالت المبينة في الفقرة الثانية من"}, {"o": 159, "l": "المادة ٥٤٧", "b": "المادة ٥٤٧وفي المادتين ٥٤٨و ٥٤٩من ھذا القانون.\n نص المادة قبل التعديل بموجب القانون رقم ٢٩٣تاريخ ٢٠١٤/٥/٧\n تشدد العقوبات المذكورة في ھذه النبذة وفاقا ً ألحكام"}, {"o": 160, "l": "المادة ٢٥٧", "b": "المادة ٢٥٧إذا اقترف الفعل بإحدى الحاالت المبينة في المادتين ٥٤٨\n و.٥٤٩\n النبذة -٣في المشاجرة\n المادة -٥٦٠معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥\n إذا وقع قتل أو إيذاء شخص أثناء مشاجرة اشترك فيھا جماعة ولم تمكن معرفة الفاعل بالذات،\n عوقب جميع من حاولوا اإليقاع بالمجنى عليه بعقوبة الجريمة المقترفة بعد تخفيض العقوبة حتى\n نصفھا.\n وإذا كانت الجريمة تستوجب اإلعدام أو األشغال الشاقة المؤبدة أو االعتقال المؤبد فيقضى بالعقاب\n ال أقل من سبع سنوات.\n المادة -٥٦١تشدد العقوبات السابق ذكرھا وفاقا ً لما نصت عليه"}, {"o": 161, "l": "المادة ٢٥٧", "b": "المادة ٢٥٧على من تسبب\n مباشرة بالمشاجرة.\n النبذة -٤العذر في القتل والإيذاء\n ملغاة وفقا قانون رقم - ١٦٢صادر في ٢٠١١/٨/١٧\n المادة -٥٦٢معدلة وفقا للقانون رقم ٧تاريخ ١٩٩٩/٢/٢٠ومن ثم الغية بموجب القانون رقم\n ١٦٢تاريخ ٢٠١١/٨/١٧\n نص المادة قبل الغائھا بموجب القانون رقم ١٦٢تاريخ ٢٠١١/٨/١٧\n\f يستفيد من العذر المخفف من فاجأ زوجه أو أحد أصوله أو فروعه أو أخته في جرم الزنى المشھود أو في حالة الجماع غير\n المشروع فأقدم على قتل أحدھما أو إيذائه بغير عمد.\n المادة -٥٦٣تعد األفعال اآلتية من قبيل الدفاع عن النفس:\n -١فعل من يدافع عن نفسه أو عن أمواله أو عن نفس الغير أو عن أمواله تجاه من يقدم باستعمال\n العنف على السرقة أو النھب.\n ً\n -٢الفعل المقترف عند دفع شخص دخل أو حاول الدخول ليال إلى منزل أھل أو إلى ملحقاته\n المالصقة بتسلق السياجات أو الجدران أو المداخل أو ثقبھا أو كسرھا أو باستعمال مفاتيح مقلدة أو\n أدوات خاصة.\n ً ً\n وإذا وقع الفعل نھارا فال يستفيد الفاعل إال من العذر المخفف عمال بالمادة .٢٥١\nوال يعتبر المجرم في حالة الدفاع المشروع إذا لم يكن على اعتقاد بأن االعتداء على األشخاص أو\n األموال كان غرض المعتدي المباشر أو بنتيجة ما قد يلقاه من المقاومة في تنفيذ مآربه.\n النبذة -٥في القتل والإيذاء عن غير قصد\nالمادة -٥٦٤من تسبب بموت أحد عن إھمال أو قلة احتراز أو عدم مراعاة القوانين أو األنظمة\n عوقب بالحبس من ستة أشھر إلى ثالث سنوات.\n المادة -٥٦٥معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n إذا لم ينجم عن خطأ المجرم إال إيذاء كالذي نصت عليه المواد ٥٥٦إلى ٥٥٨كان العقاب من\n شھرين إلى سنة.\nيعاقب على كل إيذاء آخر غير مقصود بالحبس ستة أشھر على األكثر أو بغرامة ال تتجاوز المائتي\n ألف ليرة.\n وتعلق المالحقة على شكوى المجني عليه إذا لم ينجم عن اإليذاء مرض أو تعطيل عن العمل لمدة"}, {"o": 162, "l": "المادة ٢٥٧", "b": "تجاوز العشرة أيام ،ويكون لتنازل الشاكي عن حقه نفس المفاعيل المبينة في المادتين ٥٥٤و\n .٥٥٥\n المادة -٥٦٦معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\n كل سائق مركبة تسبب بحادث ولو مادي ولم يقف من فوره أو لم يعن بالمجنى عليه أو حاول\nالتملص من التبعة بالھرب يعاقب بالحبس لمدة ال تتجاوز الشھر وبغرامة ال تتجاوز المئة ألف ليرة.\n\fويزاد على العقوبات المذكورة في المادتين ٥٦٤و ٥٦٥نصفھا إذا اقترف المجرم أحد ھذه األفعال.\n المادة -٥٦٧معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\n من وجد بمواجھة شخص في حال الخطر بسبب حادث طارىء أو بسبب صحي ،وكان بوسعه\n إغاثته أو إسعافه ،بفعل شخصي أو بطلب النجدة ودون أن يعرض نفسه أو غيره للخطر وامتنع\n بمحض إرادته عن ذلك يعاقب بالحبس من شھر إلى سنة وبالغرامة من مائتي ألف إلى مليوني\n ليرة ،أو بإحدى ھاتين العقوبتين.\nويعاقب بالعقوبة نفسھا ،من كان عالما ً بوجود أدلة تثبت براءة شخص موقوف أو موضوع محاكمة\n في قضية من نوع الجناية أو الجنحة ولم يبادر تلقائيا ً إلى الشھادة بذلك أمام القضاء أو سلطات\n األمن.\n وفي ھذه الحالة يعفى الفاعل من العقوبة إذا عاد وتقدم تلقائيا ً في وقت الحق.\nويعفى من العقوبة أيضا ً فاعل الجريمة موضوع المالحقة وشركاؤه والمتدخلون معه وأقاربھم حتى\n الدرجة الرابعة.\n النبذة -٦في القتل والإيذاء الناجمين عن تعدد الأسباب\nالمادة -٥٦٨إذا كان الموت واإليذاء المرتكبان عن قصد أو غير قصد نتيجة عدة أسباب جھلھا\n الفاعل وكانت مستقلة عن فعله أمكن تخفيض العقوبة بالمقدار المبين في المادة .٢٠٠\n الفصل الثاني -في الجرائم الواقعة على الحرية والشرف\n النبذة -١في حرمان الحرية\n\f المادة -٥٦٩معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦"}, {"o": 163, "l": "المادة ٢٥٧", "b": "من حرم آخر حريته الشخصية بالخطف أو أي وسيلة أخرى ،عوقب باألشغال الشاقة المؤقتة.\n ويعاقب الفاعل باألشغال الشاقة المؤبدة في كل من الحاالت التالية:\n -١إذا جاوزت مدة حرمان الحرية الشھر.\n -٢إذا أنزل بمن حرم حريته تعذيب جسدي أو معنوي.\n -٣إذا وقع الجرم على موظف أثناء قيامه بوظيفته أو في معرض قيامه بھا ،أو بسبب انتمائه إليھا.\n -٤إذا كانت دوافع الجريمة طائفية أو حزبية أو ثأراً من المجنى عليه لفعل ارتكبه غيره من طائفته\n أو محازبيه أو أقاربه.\n -٥إذا استعمل الفاعل ضحيته رھينة للتھويل على األفراد أو المؤسسات أو الدولة بغية ابتزاز\n المال أو اإلكراه على تنفيذ رغبة أو القيام بعمل أو االمتناع عنه.\n -٦إذا وقع المجرم تبعا ً لالعتداء على إحدى وسائل النقل اآللية الخاصة أو العامة كالسيارة أو\n القطار أو الباخرة أو الطائرة.\n -٧إذا حصل الجرم بفعل جماعة من شخصين أو أكثر ،كانوا عند ارتكابه مسلحين.\n وتشدد العقوبة وفقا ً للمادة ٢٥٧إذا نجم عن الجرم موت إنسان نتيجة الرعب أو أي سبب آخر له\n عالقة بالحادث.\n المادة -٥٧٠معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n إذا أطلق سراح من حرم حريته عفواً وخالل مدة أقصاھا ثالثة أيام ودون أن ترتكب به جريمة\n أخرى جناية كانت أم جنحة يعاقب الفاعل بالحبس من ستة أشھر إلى ثالث سنوات.\n ً\n وتخفض ھذه العقوبة إلى النصف لمصلحة الفاعل أن ھو أطلق سراح المجنى عليه عفوا خالل\n أربع وعشرين ساعة على األكثر ودون أن يرتكب فيه أي جريمة أخرى جناية كانت أم جنحة.\n النبذة -٢في خرق حرمة المنزل\n المادة -٥٧١من دخل منزل أو مسكن آخر أو ملحقات مسكنه أو منزله ،خالفا ً إلرادته ،وكذلك\nمن مكث في األماكن المذكورة خالفا ً إلرادة من له الحق في إقصائه ،عوقب بالحبس مدة ال تتجاوز\n الستة أشھر.\n ً\n ويقضي بالحبس من ثالث أشھر إلى ثالث سنوات إذا وقع الفعل ليال ،أو بواسطة الكسر أو العنف"}, {"o": 164, "l": "المادة ٢٥٧", "b": "على األشخاص أو باستعمال السالح ،أو ارتكبه عدة أشخاص مجتمعين.\n\f ال تجري المالحقة في الحالة المنصوص عليھا في الفقرة األولى إال بناء على شكوى الفريق\n المتضرر.\n المادة -٥٧٢معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n يعاقب بالتوقيف التكديري أو بغرامة ال تتجاوز المئة ألف ليرة من تسلل بواسطة الكسر أو العنف\nعلى األشخاص إلى أماكن تخص الغير وليست مباحة للجمھور ،أو مكث فيھا على الرغم من إرادة\n من له الحق في إقصائه.\n وال يالحق المجرم إال بناء على شكوى الفريق المتضرر.\n النبذة -٣في التهديد\n المادة -٥٧٣من ھدد آخر بالسالح عوقب بالحبس مدة ال تتجاوز الستة أشھر .وتراوح العقوبة\n بين شھرين وسنة إذا كان السالح ناريا ً واستعمله الفاعل.\nالمادة -٥٧٤من توعد آخر بجناية عقوبتھا اإلعدام أو األشغال الشاقة المؤبدة أو أكثر من خمس\n عشرة سنة أو االعتقال المؤبد سواء بواسطة كتابة ولو مغفلة أو بواسطة شخص ثالث عوقب\n بالحبس من سنة إلى ثالث سنوات إذا تضمن الوعيد األمر بإجراء عمل ولو مشروعا ً أو باالمتناع\n عنه.\n المادة -٥٧٥إذا لم يتضمن التھديد بإحدى الجنايات المذكورة أعاله أمراً أو تضمن أمراً إال أنه\n حصل مشافھة دون واسطة شخص آخر قضي بالحبس من ثالثة أشھر إلى سنتين.\n المادة -٥٧٦يعاقب بالحبس من شھر إلى سنة على التھديد بجناية أخف من الجنايات المذكورة\n في"}, {"o": 165, "l": "المادة ٥٧٤", "b": "المادة ٥٧٤إذا ارتكب بإحدى الوسائل المبينة في المادة نفسھا.\n المادة -٥٧٧التھديد بجنحة المتضمن أمراً إذا وقع كتابة أو بواسطة شخص ثالث يعاقب عليه\n بالحبس مدة ال تتجاوز الستة أشھر.\n\f المادة -٥٧٨معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n كل تھديد آخر بإنزال ضرر غير محق إذا حصل بالقول أو بإحدى الوسائل المذكورة في المادة\n ،٢٠٩وكان من شأنه التأثير في نفس المجنى عليه تأثيراً شديداً يعاقب عليه ،بناء على الشكوى،\n بغرامة ال تتجاوز المئة ألف ليرة.\n النبذة -٤في إفشاء الأسرار\nالمادة -٥٧٩معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\n من كان بحكم وضعه أو وظيفته أو مھنته أو فنه ،على علم بسر وأفشاه دون سبب شرعي أو\n استعمله لمنفعته الخاصة أو لمنفعة آخر عوقب بالحبس سنة على األكثر وبغرامة ال تتجاوز\n األربعمائة ألف ليرة إذا كان الفعل من شأنه أن يسبب ضرراً ولو معنويا ً.\nالمادة -٥٨٠يعاقب بالحبس من شھرين إلى سنتين كل شخص ملحق بمصلحة البريد والبرق\n يسيء استعمال صفته ھذه بأن يطلع على رسالة مختومة أو يتلف أو يختلس إحدى الرسائل أو\n يفضي بمضمونھا إلى غير المرسل إليه.\n وتنزل العقوبة نفسھا بمن كان ملحقا ً بمصلحة الھاتف وأفشى مخابرة ھاتفية اطلع عليھا بحكم\n وظيفته أو عمله.\n المادة -٥٨١معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n كل شخص آخر يتلف أو يفض قصداً رسالة أو برقية غير مرسلة إليه ،أو يطلع بالخدعة على\n مخابرة ھاتفية ،يعاقب بغرامة ال تتجاوز المئة ألف ليرة.\n ويقضى بالعقوبة نفسھا على من اطلع على رسالة أو على مخابرة برقية أو ھاتفية في إذاعتھا\n إلحاق ضرر بآخر فاعلم بھا غير من أرسلت إليه.\n\f النبذة -٥في الذم والقدح\n المادة -٥٨٢معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\nيعاقب على الذم بأحد الناس المقترف بإحدى الوسائل المذكورة في المادة ) (٢٠٩بالحبس حتى ثالثة"}, {"o": 166, "l": "المادة ٥٧٤", "b": "أشھر وبالغرامة حتى المائتي ألف ليرة أو بإحدى ھاتين العقوبتين.\n ويقضي بالغرامة وحدھا إذا لم يقع الذم عالنية.\n المادة -٥٨٣ال يسمح لمرتكب الذم تبريراً لنفسه بإثبات حقيقة الفعل بموضوع الذم أو إثبات\n اشتھاره.\n المادة -٥٨٤معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥والقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n يعاقب على القدح في أحد الناس المقترف بإحدى الوسائل في"}, {"o": 167, "l": "المادة ٢٠٩", "b": "المادة ٢٠٩وكذلك على التحقير\n الحاصل بإحدى الوسائل المذكورة الواردة في"}, {"o": 168, "l": "المادة ٣٨٣", "b": "المادة ٣٨٣بالحبس من أسبوع إلى ثالثة أشھر أو\n بالغرامة من خمسين ألف إلى أربعمائة ألف ليرة.\n ويقضي بالغرامة وحدھا إذا لم يقترف القدح عالنية.\n المادة -٥٨٥للقاضي أن يعفي الفريقين أو أحدھما من العقوبة إذا كان المعتدى عليه قد تسبب\n بالقدح بعمل غير محق أو كان القدح متبادالً.\n المادة -٥٨٦تتوقف الدعوى على اتخاذ المعتدى عليه صفة المدعي الشخصي.\n إذا وجه الذم أو القدح إلى ميت جاز ألقربائه حتى الدرجة الرابعة دون سواھم استعمال حق\n المالحقة .ھذا مع االحتفاظ بحق كل قريب أو وريث تضرر شخصيا ً من الجريمة.\n *الفصل الثالث الاتجار بالأشخاص*\n\f الـمادة (١) ٥٨٦ــ »االتجار باألشخاص« ھو:\n أ .اجتذاب شخص أو نقله أو استقباله أو احتجازه أو إيجاد مأوى له.\n ب .بواسطة التھديد بالقوة أو استعمالھا ،أو االختطاف أو الخداع ،أو استغالل السلطة أو\n استغالل حالة الضعف ،أو إعطاء أو تلقي مبالغ مالية أو مزايا ،أو استعمال ھذه الوسائل\n على من له سلطة على شخص آخر.\n ج .بھدف استغالله أو تسھيل استغالله من الغير.\n ال يُعت ّد بموافقة الـمجني عليه في حال استعمال أي من الوسائل الـمبينة في ھذه الـمادة.\n ــ »ضحية االتجار»:\n ألغراض ھذا القانون ،ضحية االتجار« تعني أي شخص طبيعي ممن كان موضوع اتجار\n باألشخاص أو ممن تعتبر السلطات الـمختصة على نحو معقول بأنه ضحية اتجار باألشخاص،\n ض عليه أو حُوكم أو أُدين. بصرف النظر عما إذا كان مرتكب الجرم قد ع ُِرفت ھويته أو قُ ِب َ\n يعتبر استغالال وفقا ألحكام ھذه الـمادة إرغام شخص على االشتراك في أيّ من األفعال التالية:\n أ .أفعال يعاقب عليھا القانون.\n ب .الدعارة ،أو استغالل دعارة الغير.\n ج .االستغالل الجنسي.\n د .التسوّ ل.\n ه .االسترقاق ،أو الـممارسات الشبيھة بالرق.\n و .العمل القسري أو اإللزامي.\n ز .بما في ذلك تجنيد األطفال القسري أو اإللزامي الستخدامھم في النزاعات الـمسلحة."}, {"o": 169, "l": "المادة ٣٨٣", "b": "ح .التورط القسري في األعمال اإلرھابية.\n ط .نزع أعضاء أو أنسجة من جسم الـمجنى عليه.\n  ال تأخذ باالعتبار موافقة الـمجنى عليه أو احد أصوله أو وصيّه القانوني أو أي\n شخص آخر يمارس عليه سلطة شرعية أو فعلية على االستغالل الـمنوي ارتكابه\n الـمبيّـن في ھذه الفقرة.\n  يعتبر اجتذاب الـمجنى عليه أو نقله أو استقباله أو احتجازه أو تقديم الـمأوى له،\nلغرض االستغالل بالنسبة لـمن ھم دون سن الثامنة عشرة ،اتجارا باألشخاص ،حتى\nفي حال لـم يترافق ذلك مع استعمال أي من الوسائل الـمبينة في الفقرة )) (١ب( من\n ھذه الـمادة.\n الـمادة :(٢) ٥٨٦يعاقب على الجريمة الـمنصوص عليھا في الـمادة( ، 586 (1وفقا لـما يلي:\n -١باالعتقال لـمدة خمس سنوات ،وبالغرامة من مئة ضعف إلى مئتي ضعف الحد األدنى الرسمي\nلألجور في حال تمّت ھذه األفعال لقاء منح مبالغ مالية أو أية منافع أخرى أو الوعد بمنحھا أو\n تلقيھا.\n -٢باالعتقال لـمدة سبع سنوات ،وبالغرامة من مئة وخمسين ضعفا إلى ثالثمائة ضعف الحد\n األدنى الرسمي لألجور في حال تمّت ھذه األفعال باستعمال الخداع أو العنف أو أعمال الشدة\n أو التھديد أو صرف النفوذ على الـمجنى عليه أو احد أفراد عائلته.\n الـمادة :(٣) ٥٨٦يعاقب باالعتقال لـمدة عشر سنوات ،وبالغرامة من مئتي ضعف إلى أربعمائة\nضعف الحد األدنى الرسمي لألجور في حال كان فاعل الجريمة الـمنصوص عليھا في الـمادة ٥٨٦\n ) (١أو الشريك أو الـمتدخل فيھا أو الـمحرّ ض عليھا:\n -٣موظفا عاما أو أي شخص مكلفا بخدمة عامة أو مدير مكتب استخدام أو عامال فيه.\n\f -٤أحد أصول الـمجنى عليه ،شرعيا كان أو غير شرعي ،أو أحد أفراد عائلته أو أي شخص\n يمارس عليه سلطة شرعية أو فعلية مباشرة أو غير مباشرة.\n الـمادة :(٤) ٥٨٦يعاقب باالعتقال لـمدة خمس عشرة سنة ،وبالغرامة من ثالثمائة ضعف إلى"}, {"o": 170, "l": "المادة ٣٨٣", "b": "ستمائة ضعف الحد األدنى الرسمي لألجور إذا ار ُتكبت الجريمة الـمنصوص عليھا في الـمادة ٥٨٦\n )(:١\n -٥بفعل جماعة ،من شخصين أو أكثر ،ترتكب أفعاال جرمية سواء في لبنان أو في أكثر من دولة.\n -٦إذا تناولت الجريمة أكثر من مجنى عليه.\n الـمادة :(٥) ٥٨٦في حال توافر أي من الظروف التالية يُعاقب على األفعال الجرمية الواردة في\n الـمادة (١) ٥٨٦بالحبس من عشر سنوات إلى اثنتي عشرة سنة وبالغرامة من مئتي ضعف إلى\n أربعمائة ضعف الحد األدنى الرسمي لألجور:\n أ .حين ينطوي الجرم على أذى خطير للضحية أو لشخص آخر أو على وفاة الضحية أو\n شخص آخر بما في ذلك الوفاة الناتجة عن االنتحار.\n ب .حين يتعلق الجرم بشخص في حالة استضعاف بصفة خاصة ،بما في ذلك الـمرأة الحامل.\n ج .حين يُعرّ ض الجرم الشخص الضحية لإلصابة بمرض يھدد حياته ،بما في ذلك اإلصابة\n بفيروس نقص الـمناعة البشرية /متالزمة نقص الـمناعة الـمكتسبة )االيدز).\n د .حين يكون الضحية معوّ قا جسديا أو عقليا.\n ه .حين يكون الضحية دون الثامنة عشرة من عمره.\n الـمادة :(٦) ٥٨٦يعفى من العقوبات كل من بادر إلى إبالغ السلطة اإلدارية أو القضائية عن\n الجرائم الـمنصوص عليھا في ھذا الفصل وزوّ دھا بمعلومات أتاحت إما كشف الجريمة قبل وقوعھا\n وإما القبض على مرتكبيھا أو شركاء أو متدخلين فيھا أو محرّ ضين عليھا إذا لـم يكن الشخص الذي\n يقوم بالتبليغ مسؤوال بصفته مرتكب الجريمة الـمبينة في الـمادة ).١) ٥٨٦\n الـمادة :(٧) ٥٨٦يستفيد من العذر الـمخفف من زوّ د السلطات الـمختصة ،بعد اقتراف الجرائم\n الـمنصوص عليھا في ھذا الفصل بمعلومات أتاحت منع تماديھا.\n ُ\n الـمادة :(٨) ٥٨٦يعفى من العقاب الـمجنى عليه الذي يثبت أنه أرغم على ارتكاب أفعال معاقب\n عليھا في القانون أو خالف شروط اإلقامة أو العمل.\nيجوز لقاضي التحقيق أو القاضي الناظر في ملف الدعوى ،بموجب قرار بصدره ،أن يجيز للـمجنى"}, {"o": 171, "l": "المادة ٣٨٣", "b": "عليه اإلقامة في لبنان خالل الـمدة التي تقتضيھا إجراءات التحقيق.\n الـمادة :(٩) ٥٨٦لوزير العدل أن يعقد اتفاقات مع مؤسسات أو جمعيات متخصصة لتقديم\n الـمساعدة والحماية لضحايا الجرائم الـمنصوص عليھا في ھذا الفصل.\n تحدد الشروط الواجب توافرھا في ھذه الـمؤسسات والجمعيات وأصول تقديم الـمساعدة والحماية\n بمرسوم يتخذ في مجلس الوزراء بناء على اقتراح وزير العدل.\n الـمادة :(١٠) ٥٨٦تصادر الـمبالغ الـمتأتية عن الجرائم الـمنصوص عليھا في ھذا الفصل وتودع\n في حساب خاص في وزارة الشؤون االجتماعية لـمساعدة ضحايا ھذه الجرائم.\nتحدد بمرسوم يتخذ في مجلس الوزراء ،بناء على اقتراح وزير الشؤون االجتماعية ،األنظمة العائدة\n للحساب.\n الـمادة :(١١) ٥٨٦تكون الـمحاكم اللبنانية مختصة في حال ارتكاب أي من األفعال الـمكوّ نة\n للجريمة على األراضي اللبنانية.\n\f الباب التاسع -في الجنايات التي تشكل خطراً شاملاً\n الفصل الأول -في الحريق\n المادة -٥٨٧من أضرم النار قصداً في أبنية أو مصانع أو ورش ،أو مخازن ،أو أي عمارات\n آھلة أو غير آھلة واقعة في مدينة أو قرية ،أو أضرمھا في مركبات السكة الحديدية أو عربات تقل\n شخصا ً أو أكثر غير المجرم أو تابعة لقطار فيه شخص أو أكثر من شخص أو أضرمھا في سفن\n ماخرة أو راسية في أحد المرافىء أو في مركبات ھوائية طائرة أو جاثمة في مطار سواء أكانت\n ملكه أم ال ،عوقب باألشغال الشاقة المؤقتة مدة ال تقل عن سبع سنوات.\nالمادة -٥٨٨يعاقب بالعقوبة نفسھا من يضرم النار قصداً في أبنية مسكونة أو معدة للسكن واقعة\n خارج األمكنة اآلھلة أو في إحراج أو في غابات لالحتطاب أو في بساتين أو مزروعات قبل\n حصادھا سواء أكانت ملكه أم ال.\n المادة -٥٨٩يعاقب باألشغال الشاقة المؤقتة من يضرم النار قصداً في أبنية غير مسكونة وال\n مستعملة للسكن واقعة خارج األمكنة اآلھلة أو في مزروعات أو أكداس من القش أو في حصيد"}, {"o": 172, "l": "المادة ٣٨٣", "b": "متروك في مكانه او في حطب مكدس او مرصوف او متروك في مكانه ،سواء كان ال يملك ھذه\n األشياء أو كان يملكھا فامتدت النار أو كان يمكن أن تمتد منھا إلى ملك الغير.\n المادة -٥٩٠كل حريق أو محاولة حريق غير ما ذكر اقترف بقصد إلحاق ضرر مادي بالغير\n أو جر مغنم غير مشروع للفاعل أو آلخر يعاقب عليه بالحبس والغرامة.\n المادة -٥٩١معدلة وفقا للقانون ٤٨٧تاريخ ١٩٩٥/١٢/٨\n يعاقب باإلعدام كل من يقتل إنسانا ً قصداً \"تمھيداً\" الرتكاب جرائم الحريق المنصوص عليھا في\n المواد السابقة أو تسھيالً أو تنفيذ لھا.\n\f ويعاقب باألشغال الشاقة المؤبدة إذا توقع مضرم النار وفاة إنسان أو إصابته بعاھة دائمة فقبل\n بالمخاطرة.\n المادة -٥٩٢تطبق األحكام السابقة في الشروط نفسھا على من يتلف أو يحاول أن يتلف ،ولو\n جزئياً ،أحد األشياء المذكورة فيھا بفعل مادة متفجرة.\n المادة -٥٩٣من تسبب بإھماله أو بقلة احترازه أو عدم مراعاته للقوانين أو األنظمة بحريق\n شيء يملكه الغير عوقب بالحبس سنة على األكثر.\n وإذا كان الجرم تافھا ً فال تتجاوز العقوبة الثالثة أشھر.\n المادة -٥٩٤معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n يعاقب بالحبس من ثالثة أشھر إلى سنتين من نزع آلة مركبة إلطفاء الحرائق أو غير مكانھا أو\n جعلھا غير صالحة للعمل.\n ً\nويعاقب بالعقوبة نفسھا فضال عن غرامة تتراوح بين مائتي ألف ومليون ليرة من كان مجبراً بحكم\n القانون أو األنظمة على اقتناء آلة إلطفاء الحريق فأغفل تركيبھا وفاقا ً لألصول أو لم يبقھا صالحة\n للعمل دائما ً.\n الفصل الثاني -في الاعتداء على سلامة طرق النقل والمواصلات والأعمال الصناعية\n النبذة -١في طرق النقل والمواصلات\n المادة -٥٩٥معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n من أحدث تخريبا ً عن قصد في طريق عام أو في إحدى المنشآت العامة أو ألحق بھا ضرراً عن"}, {"o": 173, "l": "المادة ٣٨٣", "b": "قصد عوقب بالحبس من ستة أشھر إلى سنتين إذا نشأ عن فعله خطر على سالمة السير أو على\n السالمة العامة.\n\fويعاقب بالحبس حتى سنة على األكثر المتعھد أو المنفذ أو الوكيل أو المشرف على إشغال الكھرباء\n أو المياه أو الھاتف أو المجارير أو ترميم الطرقات أو إصالحھا عند ترك بقايا أو مواد أو حفر أو\n فجوات أو آثار على الطرقات أثناء األعمال أو بعد إنجازھا من شأنھا أن تعرقل دون مبرر حرية\n السير عليھا أو تحد من اتساعھا السابق بشكل يصعب معه السير ويعرض السالمة العامة للخطر.\nويفرض العقاب نفسه على الموظف أو المستخدم المسؤول عن الرقابة واإلشراف على ھذه األعمال\n وحسن تنفيذھا.\n ً\n كما ويعاقب بالحبس حتى سنة كل من يجري أشغاال خاصة أو عامة على الطرقات العامة دون أن\n يكون لديه ترخيص ذلك من السلطات المختصة.\nالمادة -٥٩٦من عطل خطا ً حديديا ً أو آالت الحركة أو اإلشارة أو وضع شيئا ً يحول دون السير\n أو استعمل وسيلة ما ألحداث التصادم بين القطارات أو انحرافھا عن الخط عوقب باألشغال الشاقة\n المؤقتة مدة ال تنقص عن الخمس سنوات.\nالمادة -٥٩٧يعاقب بالعقوبة نفسھا من حطم أو عطل آالت اإلشارة أو استعمل إشارات مغلوطة\n أو أي وسيلة خاصة أخرى بقصد إغراق سفينة أو إسقاط مركبة ھوائية.\n وإذا نجم عن الفعل غرق السفينة أو سقوط المركبة الھوائية كانت العقوبة عشر سنوات على األقل.\n المادة -٥٩٨من أقدم قصداً على قطع سير المخابرات البرقية أو الھاتفية أو إذاعات الراديو\n سواء بإلحاق الضرر باآلالت أو األسالك أو بأية طريقة أخرى عوقب بالحبس حتى ستة أشھر.\n وإذا نجم عن الفعل خطر على السالمة العامة قضي بالحبس من ثالثة أشھر إلى سنتين.\nالمادة -٥٩٩يزاد على العقوبات المذكورة في المواد السابقة نصفھا إذا أصيب أحد الناس بعاھة\n دائمة ويقضي باإلعدام إذا أدى األمر إلى موت أحد الناس.."}, {"o": 174, "l": "المادة ٣٨٣", "b": "المادة -٦٠٠من تسبب خطأ بالتخريب والتھديم وسائر األفعال المذكورة في المواد السابقة\n عوقب بالحبس مدة ال تتجاوز الستة أشھر.\n النبذة -٢في الأعمال الصناعية\n\f المادة -٦٠١معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n كل صناعي أو رئيس ورشة أغفل وضع آالت أو إشارات لمنع طوارىء العمل ولو لم يبقھا دائما ً\n صالحة لالستعمال عوقب بالحبس من ثالثة أشھر إلى سنتين وبالغرامة من مئة ألف إلى مليون\n ليرة.\n المادة -٦٠٢من تسبب عن قلة احتراز أو إھمال أو عدم مراعاة القوانين أو األنظمة في تعطيل\n اآلالت أو اإلشارات السابقة الذكر عوقب بالحبس مدة ال تتجاوز الستة أشھر.\n المادة -٦٠٣من نزع قصداً إحدى ھذه األدوات أو جعلھا غير صالحة لالستعمال ،عوقب\n بالحبس من ستة أشھر إلى ثالث سنوات.\n ويقضى باألشغال الشاقة المؤقتة إذا نجم عن الفعل حادثة جسيمة وباألشغال الشاقة المؤبدة إذا\n أفضى إلى تلف نفس.\n الفصل الثالث -في الجرائم المضرة بصحة الإنسان والحيوان\n النبذة -١في الأمراض الوبائية\n المادة -٦٠٤معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n من تسبب عن قلة احتراز أو إھمال أو عدم مراعاة القوانين أو األنظمة في انتشار مرض وبائي\n من أمراض اإلنسان عوقب بالحبس حتى ستة أشھر.\nوإذا أقدم الفاعل على فعله وھو عالم باألمر من غير أن يقصد موت أحد عوقب بالحبس من سنة إلى\n ثالث سنوات فضالً عن الغرامة.\n المادة -٦٠٥معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n\f من تسبب عن إھمال أو قلة احتراز أو عدم مراعاة للقوانين أو األنظمة في انتشار سواف بين\n الدواجن أو جرثومة خطرة على المزروعات أو الغابات .عوقب بغرامة تراوح بين عشرين ألف\n ومائتي ألف ليرة.\n وإذا أقدم قصداً على فعله عوقب بالحبس عالوة على الغرامة.\n المادة -٦٠٦معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n يعاقب بالحبس حتى ستة أشھر وبالغرامة حتى مائتي ألف ليرة من ال يراعي األنظمة الخاصة"}, {"o": 175, "l": "المادة ٣٨٣", "b": "لمكافحة األوبئة والسواف وأمراض النبات والجراد وسائر الحيوانات الضارة.\n النبذة -٢في الغش\n المادة -٦٠٧معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n يعاقب بالحبس من ثالثة أشھر إلى سنة وبالغرامة من خمسين ألف إلى ستمائة ألف ليرة أو بإحدى\n ھاتين العقوبتين.\n -١من غش مواد مختصة بغذاء اإلنسان أو الحيوان أو عقاقير أو أشربة أو منتجات صناعية أو\n زراعية أو طبيعية معدة للبيع.\n -٢من عرض أحد المنتجات أو المواد السابق ذكرھا أو طرحھا للبيع أو باعھا وھو على علم بأنھا\n مغشوشة أو فاسدة.\n -٣من عرض منتجات من شأنھا إحداث الغش أو طرحھا للبيع أو باعھا وھو عالم بوجه استعمالھا.\n -٤من حرض بإحدى الوسائل التي نصت عليھا"}, {"o": 176, "l": "المادة ٢٠٩", "b": "المادة ٢٠٩بالفقرتين ٣و ٢على استعمال\n المنتجات أو المواد المذكورة في الفقرة الثالثة.\n وعند التكرار يمنع المجرم من ممارسة العمل الذي كان واسطة الرتكاب الجرم.\n المادة -٦٠٨معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n إذا كانت المنتجات أو المواد المغشوشة أو الفاسدة ضارة بصحة اإلنسان أو الحيوان ،قضي\n بالحبس من ثالثة أشھر إلى سنتين وبالغرامة من مئة ألف إلى مليون ليرة.\n تطبق ھذه العقوبات ولو كان البائع أو الشاري على علم بالغش أو الفساد الضارين.\n المادة -٦٠٩معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n\f يعاقب بغرامة تراوح بين عشرين ألف ومئة ألف ليرة وبالحبس ثالثة أشھر على األكثر أو بإحدى\n ھاتين العقوبتين من ابقوا في حيازتھم في أي مكان كان بدون سبب مشروع منتجات أو مواد من\n تلك التي وصفتھا المادة السابقة.\nويقضي بالحبس من ثالثة أشھر إلى سنة وبالغرامة من خمسين ألف إلى ستمائة ألف ليرة .إذا كانت\n إحدى المواد أو أحد المنتجات المزغولة أو المغشوشة ضاراً بصحة اإلنسان أو الحيوان.\n الباب العاشر -في الجرائم التي يرتكبها أشخاص خطرون بسبب عادات حياتهم\n الفصل الأول -في المتسولين والمتشردين\n النبذة -١في المتسولين\n المادة -٦١٠من كانت له موارد ،أو كان يستطيع الحصول على موارد بالعمل واستجدى\nلمنفعته الخاصة اإلحسان العام في أي مكان كان ،أما صراحة أو تحت ستار أعمال تجارية ،عوقب\n بالحبس مع التشغيل لمدة شھر على األقل وستة أشھر على األكثر.\n يمكن فضالً عن ذلك ،أن يوضع في دار للتشغيل وفاقا ً للمادة .٧٩\n ويقضي بھذا التدبير وجوبا ً في حالة التكرار.\n المادة -٦١١من أصبح بسبب كسله أو إدمانه السكر أو المقامرة مجبراً على استجداء المعونة\n العامة أو اإلحسان من الناس عوقب بالحبس مع التشغيل من شھر إلى ستة أشھر.\n وللقاضي ،فضالً عن ذلك ،أن يحكم بوضع المحكوم عليه بإحدى دور التشغيل ومنعه من ارتياد"}, {"o": 177, "l": "المادة ٢٠٩", "b": "الحانات التي تباع فيھا المشروبات على ما نصت عليه المادتان ٧٩و .٨٠\n\f المادة -٦١٢من غادر مؤسسة خيرية تعنى به وتعاطى التسول ،عوقب ،ولو كان عاجزاً\n بالحبس للمدة المذكورة أعاله.\n المادة -٦١٣إن المتسول الذي يستجدي في أحد الظروف التالية:\n -١بالتھديد أو أعمال الشدة.\n -٢بحمل شھادة فقر كاذبة.\n -٣بالتظاھر بجراح أو عاھات.\n -٤بالتنكر على أي شكل كان.\n -٥باستصحاب ولد غير ولده أو أحد فروعه ممن ھو دون السابعة من العمر.\n -٦بحمل أسلحة أو أدوات خاصة باقتراف الجنايات أو الجنح.\n -٧بحالة االجتماع ما لم يكن الزوج وزوجته أو العاجز وقائده.\nيعاقب بالحبس من ستة أشھر إلى سنتين مع التشغيل فضالً عن وضعه في دار للتشغيل إذا كان غير\n عاجز وبالحبس البسيط للمدة نفسھا إذا كان عاجزاً.\n ويمكن كذلك أن يفرض عليه تدبير الحرية المراقبة.\n النبذة -٢في المتشردين\n المادة -٦١٤يعد متشرداً ويعاقب على ذلك بالحبس مع التشغيل من شھر إلى ستة أشھر كل\n صحيح ال مسكن له وال وسيلة للعيش وال يمارس عمالً من شھر على األقل ولم يثبت أنه سعى\n السعي الكافي للحصول على شغل.\n ً\n ويمكن كذلك وضع المتشردين في دار للتشغيل ويوضعون فيھا وجوبا عند التكرار.\nالمادة -٦١٥يقضى بالعقوبات والتدابير االحترازية المنصوص عليھا في"}, {"o": 178, "l": "المادة ٦١٣", "b": "المادة ٦١٣على كل\nمتشرد يحمل سالحا ً أو أدوات خاصة باقتراف الجنايات أو الجنح ،أو يقومون أو يھددون بالقيام بأي\n عمل من أعمال العنف على األشخاص أو يتنكرون على أي شكل من األشكال أو يتشردون\n مجتمعين ،شخصين فأكثر.\n النبذة -٣في الأحداث المتشردين أو المتسولين\n\f المادة -٦١٦ملغاة وفقا للمرسوم االشتراعي ١١٩تاريخ١٩٨٣/٩/١٦\n المادة -٦١٧معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n يعاقب بالحبس من شھر إلى ستة أشھر وبالغرامة من عشرين ألف إلى مئة ألف ليرة أبوا القاصر\n الذي لم يتم الخامسة عشرة من عمره أو أھله المكلفون إعالته وتربيته إذا لم يقوموا بأوده رغم\n اقتدارھم وتركوه متشرداً.\n المادة -٦١٨معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧ووفقا للقانون رقم ٢٩٣تاريخ\n ٢٠١٤/٥/٧\nمن دفع قاصراً دون الثامنة عشرة من عمره الى التسول عوقب بالحبس من ستة أشھر الى سنتين\n وبغرامة تتراوح بين الحد األدنى لألجور وضعفه.\n نص المادة قبل التعديل بموجب القانون رقم ٢٩٣تاريخ ٢٠١٤/٥/٧\n من دفع قاصراً دون الثامنة عشرة من عمره إلى التسول جراً لمنفعة شخصية عوقب بالحبس من ستة أشھر إلى سنتين\n وبالغرامة من عشرين ألف إلى مائتي ألف ليرة.\n النبذة -٤في الرحل\n المادة -٦١٩يعد رحالً بالمعنى المقصود في ھذه النبذة النور والبدو لبنانيين كانوا أو غرباء\n المتجولين في لبنان دون مقر ثابت ولو كانت لھم موارد ويزاولون إحدى الحرف.\n المادة -٦٢٠معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n ً\n كل فرد من الرحل يتجول في األرض اللبنانية من شھر على األقل وال يكون حامال تذكرة الھوية\nالمحتوية على قياساته الجسدية أو ال يثبت أنه طلبھا من السلطة يعاقب بالحبس من ثالثة أشھر إلى\n سنة وبالغرامة من عشرين ألف ليرة إلى مائتي ألف ليرة.\n ويمكن أيضا ُ أن يوضع تحت المراقبة.\n\f أحكام شاملة\n المادة -٦٢١كل غريب حكم عليه بمقتضى المواد الواردة في ھذا الفصل يمكن أن يقضي في"}, {"o": 179, "l": "المادة ٦١٣", "b": "الحكم بطرده من البالد اللبنانية.\n الفصل الثاني -في تعاطي المسكرات والمخدرات\n النبذة -١في المسكرات\n المادة -٦٢٢معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n من وجد في حالة سكر ظاھر في محل عام أو مكان مباح للجمھور عوقب بالغرامة من ستة آالف\n ليرة إلى عشرين ألف ليرة.\nالمادة -٦٢٣يستحق المدعي عليه عند التكرار التوقف التكديري ويمنع من ارتياد الحانات تحت\n طائل العقوبة المفروضة في المادة .٨٠\n ً\n وإذا كرر ثانية عوقب بالحبس من شھر إلى ستة أشھر وقضي عليه فضال عن ذلك بالمنع من\n الحقوق المدنية واإلسقاط من الوالية والوصاية.\n\f المادة -٦٢٤إذا ثبت أن المدعي عليه سكيراً مدمنا ً قضي -وإن يكن مكرراً للمرة األولى-\n بحجزه في جناح خاص من المأوى االحترازي ليعالج فيه.\n ومدة الحجز ستة أشھر على األقل تنتھي بقرار من الھيئة القضائية التي قضت به يثبت فيه شفاء\n المحكوم عليه وال يمكن أن تتجاوز ھذه المدة السنتين.\n تسري مدة العقوبة المانعة للحرية في خالل مدة الحجز.\n المادة -٦٢٥معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n من قدم لقاصر دون الثامنة عشرة من عمره أشربة روحية حتى أسكره عوقب بالغرامة من ستة\n آالف إلى عشرين ألف ليرة.\n المادة -٦٢٦معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n يعاقب بالتوقيف التكديري وبالغرامة من عشرة آالف إلى عشرين ألف ليرة صاحب الحانة أو\n صاحب محل آخر مباح للجمھور وھكذا مستخدموه إذا قدموا إلى شخص أشربة روحية حتى\n أسكروه أو قدموھا إلى شخص بحالة سكر ظاھر أو إلى قاصر دون الثامنة عشرة من عمره.\n المادة -٦٢٧يستحق العقوبات نفسھا صاحب الحانة الذي يستخدم في حانته بنات أو نساء من\n غير عيلته دون الحادية والعشرين من العمر.\n المادة -٦٢٨عند تكرار أي جنحة من الجنح المنصوص عليھا في المادتين ٦٢٦و ٦٢٧يمكن\n الحكم بإقفال المحل نھائيا ً.\n المادة -٦٢٩تضاعف العقوبات المنصوص عليھا في المادتين ٦٢٥و ٦٢٦إذا ترك المجرم"}, {"o": 180, "l": "المادة ٦١٣", "b": "الشخص السكران يجول في حالة سكر أو لم يؤمن رجوعه إلى منزله أو تسليمه إلى رجال السلطة.\n النبذة -٢في المخدرات\n المادة -٦٣٠ملغاة وفقا للقانون تاريخ ١٩٤٦/٦/١٨\n\f المادة -٦٣١ملغاة وفقا للقانون تاريخ ١٩٤٦/٦/١٨\n الفصل الثالث -في المقامرة\n المادة -٦٣٢ألعاب القمار ھي التي يتسلط فيھا الحظ على المھارة أو الفطنة.\n تعد خاصة ألعاب مقامرة ،الروليت والبكارا والفرعون والبتي شفو والبوكر المكشوف ،وكذلك\n األلعاب التي تتفرع عنھا أو تماثلھا بصورة عامة.\n المادة -٦٣٣معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥والقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n من تولى محالً للمقامرة أو نظم ألعاب مقامرة ممنوعة سواء في محل عام أو مباح للجمھور أو في\n منزل خاص اتخذ لھذه الغاية.\n والصرافون ومعاونوھم والمدراء والعمال والمستخدمون.\n يعاقبون بالحبس من ثالثة أشھر إلى سنتين وبالغرامة من مائتي ألف ليرة إلى مليوني ليرة.\n ويستھدف المجرمون منع اإلقامة ،وإذا كانوا غرباء استھدفوا الطرد من البالد اللبنانية.\n تصادر فضالً عن األشياء التي نتجت عن الجرم أو استعملت أو كانت معدة الرتكابه األثاث وسائر\n األشياء المنقولة التي فرش المكان وزين بھا.\n ويمكن القضاء بإقفال المحل.\n المادة -٦٣٤معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥والقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\nكل شخص اشترك باللعب في األماكن المذكورة أعاله أو فوجيء فيھا أثناء اللعب يعاقب بغرامة من\n خمسين ألف إلى أربعمائة ألف ليرة.\n الباب الحادي عشر -الجرائم التي تقع على الأموال\n\f الفصل الأول -في أخذ مال الغير\n النبذة -١في السرقة\n المادة -٦٣٥معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n -السرقة ھي أخذ مال الغير المنقول خفية أو عنوة بقصد التملك تنزل الطاقات المحرزة منزلة\n األشياء المنقولة في تطبيق النصوص الجزائية.\n المادة -٦٣٦معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧"}, {"o": 181, "l": "المادة ٦١٣", "b": "-السرقة ،التي لم تحدد لھا عقوبة خاصة بموجب أحد نصوص ھذا القانون االخرى ،يعاقب عليھا\n بالحبس من شھرين إلى ثالث سنوات وبالغرامة من مئة ألف إلى أربعمائة ألف ليرة.\n وتشدد ھذه العقوبة وفقا ً للمادة ٢٥٧إذا ارتكبت السرقة في إحدى الحاالت التالية:\n -١في المعابد واألبنية المأھولة.\n -٢بنشل المارة أكان ذلك في الطرق أو في األماكن العامة األخرى أو في القطارات أو في السفن\n أو الطائرات أو غيرھا من وسائل النقل.\n -٣بفعل موظف أنيط به حفظ األمن أو الحراسة حتى وإن ارتكبت السرقة في غير أوقات الدوام.\n -٤بفعل خادم مأجور يسرق مال مخدومه أو يسرق مال الغير من منزل مخدومه أو بفعل مستخدم\n أو عامل يسرق من محل أو مصنع مخدومه أو في المستودعات أو األماكن األخرى التابعة للعمل\n أو المصنع.\n -٥بفعل شخصين أو أكثر.\n المادة -٦٣٧معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\n -من سرق شيئا ً من محصوالت األرض أو من ثمار شجرھا ،مما تقل قيمته عن المائة ليرة يعاقب\n بالغرامة حتى مئة ألف ليرة.\n وفي ھذه الحالة تتوقف المالحقة على شكوى الفريق المتضرر.\n\f المادة -٦٣٨معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٤٨٧تاريخ\n ١٩٩٥/١٢/٨\n -يعاقب باألشغال الشاقة من ثالث سنوات إلى عشرة سنوات على السرقة في إحدى الحاالت التالية:\n -١إذا وقعت السرقة على أموال أو موجودات مؤسسة حكومية أو أي مركز أو مكتب إلدارة رسمية\n أو ھيئة عامة.\n -٢إذا وقعت السرقة على أموال أو موجودات مصرف أو محل للصياغة أو للصيرفة.\n -٣إذا وقعت السرقة على أحد معتمدي القبض أو على أي موظف عام أو على أي مستخدم في\n مؤسسة خاصة ،وھو يحمل ماالً لإلدارة أو المؤسسة التي يعمل فيھا وكان القصد سرقة ھذا المال،\n وتفرض العقوبة نفسھا على معتمد القبض أو الموظف العام أو المستخدم إذا تواطأ مع الجناة."}, {"o": 182, "l": "المادة ٦١٣", "b": "-٤إذا وقعت السرقة على سيارة أو أي مركبة برية ذات محرك.\n -٥بفعل شخص مقنع أو يحمل سالحا ً ظاھراً أو خفيا ً.\n -٦إذا وقعت السرقة باستعمال العنف على األشخاص.\n المادة -٦٣٩معدلة وفقا للقانون ٤٨٧تاريخ ١٩٩٥/١٢/٨\nيعاقب باألشغال الشاقة من ثالث سنوات إلى سبع سنوات كل من يرتكب السرقة في إحدى الحاالت\n اآلتية:\n -١بواسطة الخلع أو الكسر في األماكن المقفلة المصانة بالجدران ،مأھولة أم غير مأھولة ،أو\n بتسلقھا في الداخل أو الخارج أو باستعمال المفاتيح المصنعة أو أي أداة أخرى أو بعد الدخول إليھا\n بالحيلة أو بانتحال صفة موظف أو بالتذرع بمھمة رسمية أو بأي طريقة أخرى غير مألوفة.\n -٢في خالل وقوع أعمال شغب أو ثورة أو حرب أو حريق أو اضطراب أمني أو غرق سفينة أو\n أي نائبة أخرى.\n -٣بالتھديد بالسالح أن لتھيئة الجريمة أم لتسھيلھا أم لالستيالء على المسروق أم لتأمين الھرب.\n المادة -٦٤٠معدلة وفقا للقانون ٤٨٧تاريخ ١٩٩٥/١٢/٨\n -إذا رافق إحدى األفعال المذكورة في المادة السابقة عنف على األشخاص أن لتھيئة الجريمة أم\n لتسھيلھا أم لالستيالء على المسروق أم لتأمين الھرب ،أو إذا تم أحد األفعال ليالً فترفع العقوبة إلى\n األشغال الشاقة المؤبدة.\n وإذا أقدم الفاعل على قتل إنسان لسبب ذي صلة بالسرقة المذكورة فيعاقب باإلعدام.\n المادة ) -٦٤١معدلة وفقا للقانون ٥١٣تاريخ ١٩٩٦/٦/٦\n يعاقب باألشغال الشاقة المؤقتة كل من:\n\f -استولى بصورة غير مشروعة وبأية وسيلة كانت على سفينة راسية أو ماخرة أو على البضائع\n التي تنقلھا ،أو مارس أية عملية من عمليات الغش البحري أو القرصنة ،أو سيطر على السفينة أو\n تحكم بقيادتھا أو حمل ربانھا أو قائدھا على تغيير وجھة سيرھا بالتھديد أو بالعنف.\n -استولى بصورة غير مشروعة وبأية وسيلة كانت على منصة ثابتة في الجرف القاري أو سيطر\n عليھا بالتھديد أو بالعنف."}, {"o": 183, "l": "المادة ٦١٣", "b": "-ارتكب بصورة غير مشروعة وعن قصد أحد األفعال اآلتية ،التي من شأنھا تعريض سالمة\n مالحة السفينة أو سالمة المالحة البحرية أو سالمة المنصة الثابتة في الجرف القاري للخطر:\n أ -إتالف السفينة أو إحداث أضرار فادحة بھا أو بحمولتھا.\n ب -وضع أو حمل الغير على وضع جھاز أو مادة على سفينة أو على منصة ثابتة بأية وسيلة\n كانت وكان من شأن ذلك تعريض السفينة أو المنصة الثابتة ،للتدمير أو إللحاق الضرر بالسفينة\n أو بحمولتھا أو بالمنصة الثابتة.\n ج -إحداث أضرار فادحة بمرفأ يستخدم للمالحة البحرية أو بمنشآت أو تجھيزات أو خدمات\n المالحة البحرية ،أو عرقلة عملھا بصورة جسيمة.\n د -إبالغ معلومات مع علمه بأنھا غير صحيحة.\n وتشدد العقوبة وفقا ً للمادة ٢٥٧عقوبات بحق ربان السفينة إذا كان ھو الفاعل إلحدى ھذه\n الجرائم أو كان مشتركا ً أو متدخالً فيھا أو محرضا ً عليھا.\n ويمكن أن يحكم على الربان أيضا ً بالمنع من ممارسة المھنة نھائيا ً ويحكم بھذا المنع كذلك على\n سائر الفاعلين والمشتركين والمتدخلين والمحرضين إذا كانت مھنتھم ذات عالقة بالمالحة أو\n التجارة البحرية.\n المادة -٦٤٢معدلة وفقا للقانون ٥١٣تاريخ ١٩٩٦/٦/٦\n يعاقب باألشغال الشاقة المؤبدة إذا تم ارتكاب أي من الجرائم المنصوص عليھا في"}, {"o": 184, "l": "المادة ٦٤١", "b": "المادة ٦٤١\nالمعدلة من قانون العقوبات ،بفعل شخصين مسلحين أو أكثر استعملوا السالح أو ھددوا باستعماله أو\n إذا رافق ارتكاب الجريمة عنف على أحد.\n ويعاقب باإلعدام إذا أدى ارتكاب الجريمة إلى غرق السفينة وموت أحد ركابھا أو أدى إلى تدمير\nالمنصة الثابتة وموت أحد ممن عليھا ،وباألشغال الشاقة المؤقتة إذا أدى ارتكاب الجريمة إلى تدمير\nمنشآت أو تجھيزات أو خدمات المالحة البحرية أو موت أحد األشخاص نتيجة الرعب أو أي سبب\n آخر له صلة بالجريمة.\n المادة -٦٤٣معدلة وفقا للقانون ٥١٣تاريخ ١٩٩٦/٦/٦\n يعاقب باألشغال الشاقة المؤقتة كل من:\n\f -استولى بصورة غير مشروعة وبأية وسيلة كانت على طائرة أثناء طيرانھا أو سيطر عليھا أو\n تحكم بقيادتھا أو حمل قائدھا على تغيير وجھة سيرھا بالتھديد أو العنف.\n -ارتكب بصورة غير مشروعة وعن قصد أحد األفعال اآلتية ،إذا كان من شأنه تعريض سالمة\n المالحة الجوية أو سالمة مالحة الطائرة للخطر:\n أ -إنزال أضرار متعمدة بطائرة في الخدمة تجعلھا غير صالحة للطيران.\n ب -إنزال أضرار متعمدة فادحة بمنشآت أو تجھيزات أو خدمات المالحة الجوية ،أو إنزال\n أضرار متعمدة فادحة بمنشآت مطار يستخدم للمالحة الجوية.\n ج -إبالغ معلومات مع علمه بأنھا غير صحيحة.\nويعاقب باألشغال الشاقة المؤبدة إذا تم ارتكاب أي من الجرائم المنصوص عليھا في ھذه المادة\n بفعل شخصين مسلحين أو أكثر استعملوا السالح أو ھددوا باستعماله أو إذا رافق ارتكاب\n الجريمة عنف على أحد األشخاص.\n ويعاقب باإلعدام إذا قام الفاعل ،بأية وسيلة كانت ،بعمل تخريبي في الطائرة يعرضھا لخطر\n السقوط أو التدمير أو إذا نجم عن الفعل موت إنسان نتيجة الرعب أو أي سبب آخر له صلة\n بالحادث.\n المادة -٦٤٤ملغاة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦\n المادة -٦٤٥ملغاة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦\n المادة -٦٤٦ملغاة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦"}, {"o": 185, "l": "المادة ٦٤١", "b": "المادة -٦٤٧ملغاة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦\n المادة -٦٤٨ملغاة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦\n النبذة -٢في الاغتصاب والتهويل\n\f )(Chantage\n المادة -٦٤٩معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\n -يعاقب بالحبس سنة على األقل وبالغرامة من مئة ألف ليرة إلى ستمائة ألف ليرة لبنانية:\n -١من أقدم بالتھديد أو بالعنف وبقصد اجتالب نفع غير مشروع له أو لغيره ،على اغتصاب كتابة\n تتضمن تعھداً أو إبراء أو اغتصاب توقيع عليھا.\n -٢من أكره شخصا ً على إجراء عمل أو االمتناع عن إجرائه أضراراً بثروته وبثروة غيره.\n -٣تفرض عقوبة األشغال الشاقة المؤقتة في جميع الحاالت المبينة في الفقرتين السابقتين إذا كان\n الفاعل حامالً سالحا ً ھدد به المجني عليه.\n المادة -٦٥٠معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\n -كل من ھدد شخصا ً بفضح أمر أو إفشائه أو اإلخبار عنه وكان من شأنه أن ينال من قدر ھذا\n الشخص أو شرفه أو من قدر أحد أقربائه أو شرفه لكي يحمله على جلب منفعة له أو لغيره غير\n مشروعة عوقب بالحبس من شھرين إلى سنتين وبالغرامة حتى ستمائة ألف ليرة لبنانية.\nتشدد العقوبة وفقا ً للمادة ٢٥٧عقوبات بحق الفاعل إذا كان األمر الذي يھدد بفضحه قد اتصل بعمله\n بحكم وظيفته أو مھنته أو فنه.\n النبذة -٣في استعمال أشياء الغير بدون حق\n المادة -٦٥١معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\nكل من استعمل بدون حق شيئا ً يخص غيره بصورة تلحق به ضرراً ولم يكن قاصداً اختالس الشيء\n عوقب بالحبس حتى ستة أشھر وبالغرامة من خمسين ألف إلى مائتي ألف ليرة أو بإحدى ھاتين\n العقوبتين.\n\f أحكام شاملة -للنبذات السابقة\n المادة -٦٥٢يتناول العقاب الشروع بارتكاب الجنح المنصوص عليھا في ھذا الفصل."}, {"o": 186, "l": "المادة ٦٤١", "b": "المادة -٦٥٣يمكن أن يوضع تحت الحرية المراقبة أو أن يمنع من اإلقامة كل من حكم عليه\n بعقوبة مانعة للحرية من أجل سرقة أو محاولة سرقة.\n المادة -٦٥٤يعفى من العقوبة كل شخص ارتكب جريمة إخفاء األشياء المسروقة أو جريمة\nتخبئة الشركاء المنصوص عليھما في المادتين ٢٢١و ٢٢٢إذا أخبر السلطة عن أولئك الشركاء\n قبل اية مالحقة أو أتاح القبض ولو بعد مباشرة المالحقات على من يعرف مختبأھم.\n ال تسري أحكام ھذه المادة على المكررين.\n الفصل الثاني -في الاحتيال وسائر ضروب الغش\n النبذة -١في الاحتيال\n المادة -٦٥٥معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\n ً ً ً\nكل من حمل الغير بالمناورات االحتيالية على تسليمه ماال منقوال أو غير منقول أو أسنادا تتضمن\nتعھداً أو إبراء أو منفعة واستولى عليھا يعاقب بالحبس من ستة أشھر إلى ثالث سنوات وبالغرامة\n من مئة ألف إلى مليون ليرة.\n وتعتبر من المناورات االحتيالية:\n\f -١األعمال التي من شأنھا إيھام المجني عليه بوجود مشروع وھمي أو التي تخلق في ذھنه أمالً\n بربح أو تخوفا ً من ضرر.\n -٢تلفيق أكذوبة يصدقھا المجني عليه نتيجة تأييد شخص ثالث ولو عن حسن نية أو نتيجة ظرف\n مھد له المجرم أو ظرف استفاد منه.\n -٣التصرف بأموال منقولة أو غير منقولة ممن ليس له حق أو صفة للتصرف بھا أو ممن له حق\n أو صفة للتصرف فأساء استعمال حقه توسالً البتزاز المال.\n -٤استعمال اسم مستعار أو صفة كاذبة للمخادعة والتأثير .ويطبق العقاب نفسه في محاولة ارتكاب\n ھذا الجرم.\n المادة -٦٥٦معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n تضاعف العقوبة إذا ارتكب الجرم في إحدى الحاالت اآلتية:\n -١بحجة تأمين وظيفة أو عمل في إدارة عمومية.\n -٢بفعل شخص يلتمس من العامة ماالً إلصدار أسھم أو سندات أو غيرھا من الوثائق لشركة أو\n لمشروع ما."}, {"o": 187, "l": "المادة ٦٤١", "b": "-٣بفعل أي مفوض بالتوقيع عن شركة أو جمعية أو مؤسسة أو أي شخص معنوي آخر.\n المادة -٦٥٧معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n كل من استغل احتياجات أو عدم خبرة أو أھواء قاصر دون الثامنة عشرة من عمره أو مجذوب أو\nمعتوه فحمله على إجراء عمل قانوني من شأنه اإلضرار بمصالحه أو مصالح الغير ،عوقب بالحبس\n من شھرين إلى سنتين وبغرامة توازي قيمة الضرر وال تنقص خمسين ألف ليرة.\n النبذة -٢فيما جرى مجرى الاحتيال\n المادة -٦٥٨معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n كل من حمل الغير على تسليمه بضاعة من حق الخيار أو لوعدة وھو ينوي عدم دفع ثمنھا أو كان\n يعرف أنه ال يمكنه الدفع ،عوقب بالحبس ،حتى ستة أشھر وبغرامة حتى مائتي ألف ليرة إذا لم\n يردھا أو لم يدفع ثمنھا بعد إنذاره.\n\f المادة -٦٥٩معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n كل من وفر لنفسه منامة أو طعاما ً أو شرابا ً في محل عام وھو ينوي عدم الدفع أو يعلم أنه ال يمكنه\n أن يدفع ،عوقب بالتوقيف التكديري وبالغرامة من عشرين ألف إلى مئة ألف ليرة.\nالمادة -٦٦٠يقضى بالعقوبة نفسھا على كل من اتخذ بالغش واسطة نقل برية أو بحرية أو جوية\n دون أن يدفع أجرة الطريق.\n النبذة -٣في المراباة والقروض لقاء رهن\n المادة -٦٦١معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n كل عقد قرض مالي ،لغاية غير تجارية ،يفرض على المستقرض فائدة إجمالية ظاھرة أو خفية،\n بمعدل يزيد عن ١٢بالمائة سنويا ً يؤلف قرض ربا.\n المادة -٦٦٢كل من رابى شخصا ً الستغالل ضيق ذات يده عوقب بغرامة يمكن أن تبلغ نصف\n رأس المال المقرض وبالحبس على أن ال يتجاوز السنة أو بإحدى ھاتين العقوبتين.\n المادة -٦٦٣معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n كل من رابى في اقل من ثالث سنوات مرتين أو أكثر مديونا ً واحداً أو مديونين مختلفين ،عوقب\n لجريمة اعتياد المراباة بالعقوبات المعينة في المادة السابقة."}, {"o": 188, "l": "المادة ٦٤١", "b": "-يعاقب المحرض أو المتدخل في ھذا الجرم ،عند تكرار فعله مرتين على األقل خالل ثالث سنوات\n سواء كان ذلك بمعرض قرض ربا أجري بين المرابي والضحية ذاتھما أو بين أشخاص آخرين.\n المادة -٦٦٤إن جرم اعتياد المراباة يستنتج من قرض واحد بالربى إذا ارتكب في أقل من\n خمس سنوات بعد الحكم بإحدى الجنح المنصوص عليھا في المواد السابقة.\n المادة -٦٦٥معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥\n\f يعاقب بالحبس حتى ستة أشھر وبغرامة يمكن أن تبلغ ربع رأس المال المقرض:\n -١كل من فتح محالً لإلقراض لقاء رھن بدون أذن ولو أجرى عقداً واحداً.\n -٢كل من استحصل على أذن لإلقراض لقاء رھن ولم يمسك دفتراً يتضمن قيمة المبالغ المقرضة\n واسم المستقرض وصفته وصفته ونوع المرھون وقيمته الحقيقية.\nال تسري أحكام ھذه المادة على القروض لقاء رھن المعقودة لمصلحة التجار ألجل تسھيل العمليات\n التجارية.\n النبذة -٤في الشك بدون مقابل\nمعدلة وفقا للقانون ٦٧/٣٠تاريخ ١٩٦٧/٥/١٦والقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧ومعدلة وفقا\n للقانون رقم ٨٧تاريخ ٢٠١٠/٣/٦\n المادة -٦٦٦\n -كل من أقدم على سحب شك دون مؤونة سابقة ومعدة للدفع أو بمؤونة غير كافية.\n -كل من استرجع كل المؤونة أو بعضھا بعد سحب الشك.\n -كل من أصدر منعا ً عن الدفع للمسحوب عليه في غير الحاالت المنصوص عليھا في"}, {"o": 189, "l": "المادة ٤٢٨", "b": "المادة ٤٢٨\n من قانون التجارة.\n يعاقب بالحبس من ثالثة أشھر إلى ثالث سنوات وبالغرامة من مليون ليرة إلى أربع ماليين ليرة\n ويحكم عليه بدفع قيمة الشك مضافا ً إليه بدل العطل والضرر إذا اقتضى األمر.\n وفي حال التكرار تطبق أيضا ً باإلضافة إلى عقوبات التكرار أحكام المادتين ٦٦و.٦٨\n إن إسقاط الحقوق الشخصية في الجرائم المذكورة يؤدي إلى سقوط دعوى الحق العام.\nال ينطبق على ھذه الجرائم وصف الجرم الشائن المستعمل في سائر القوانين المرعية اإلجراء ،وال\n تترتب على من يُحكم عليه بإحداھا أي من النتائج المحددة في تلك القوانين والتي تترتب على من\n يُحكم عليه بجرم شائن\nمعدلة وفقا للقانون ٦٧/٣٠تاريخ ١٩٦٧/٥/١٦ومعدلة وفقا للقانون رقم ٨٧تاريخ ٢٠١٠/٣/٦\n المادة -٦٦٧\n -يعاقب بعقوبات التدخل في الجرم المعين أعاله من أقدم عن معرفة على استالم شك دون مؤونة.\nتضاعف ھذه العقوبات إذا كان حامل الشك قد استحصل عليه لتغطية قرض بالربا حتى ولو لم يكن\n متدخالً.\n باستثناء حالة االستحصال على شيك لتغطية قرض بالربا ،إن إسقاط الحقوق الشخصية يؤدي إلى\n سقوط دعوى الحق العام.\n النبذة -٥في الغش بالمهاجرة\n\f المادة -٦٦٨معدلة وفقا للقانون تاريخ ١٩٤٨/٢ /٥\n كل من اجتلب أو استوعد لنفسه أو لغيره نفعا ً ما باختالقه أخباراً أو بتلفيقه أكاذيب لحمل شخص\nعلى السفر أو لتوجيه مسافر إلى بلد غير البلد الذي كان يقصد إليه قضي عليه بالعقوبة المنصوص\n عليھا في المادة .٦٥٥\n ويطبق العقاب نفسه في محاولة ارتكاب ھذا الجرم.\n أحكام شاملة\nالمادة -٦٦٩يمكن أن يؤمر بنشر الحكم عند القضاء بإحدى الجنح المنصوص عليھا في"}, {"o": 190, "l": "المادة ٦٥٦", "b": "المادة\n ٦٥٦و ٦٦٣أوعند تكرار أية جريمة من الجرائم المعينة في ھذا الفصل.\n الفصل الثالث -في إساءة الائتمان والاختلاس\n المادة -٦٧٠معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\nكل من أقدم قصداً على كتم أو اختالس أو تبديد أو إتالف أو تمزيق سند يتضمن تعھداً أو إبراء ،أو\nشيء منقول آخر سلم إليه على وجه الوديعة أو الوكالة أو اإلجارة أو على سبيل عارية االستعمال\n أو الرھن ،أو إلجراء عمل لقاء أجرة أو بدون أجرة شرط أن يعيده أو يقدمه أو يستعمله في أمر\nمعين يعاقب بالحبس من شھرين إلى سنتين وبغرامة تراوح بين ربع قيمة الردود والعطل والضرر\n وبين نصفھا على أن ال تنقص عن خمسين ألف ليرة.\n\f المادة -٦٧١معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n كل من تصرف بمبلغ من المال أو بأشياء أخرى من المثليات سلمت إليه لعمل معين وھو يعلم أو\n كان يجب أن يعلم أنه ال يمكنه إعادة مثلھا ولم يبرىء ذمته رغم اإلنذار يعاقب بالحبس حتى سنة\nوبالغرامة حتى ربع قيمة الردود والعطل والضرر على أن ال تنقص الغرامة عن خمسين ألف ليرة.\n المادة -٦٧٢معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n يعاقب بالحبس من ثالثة أشھر إلى ثالث سنوات األشخاص المذكورين فيما يلي عندما يقدومون\n على إساءة األمانة باألموال المسلمة إليھم أو المناط أمرھا بھم وفقا ً لنص إحدى المادتين ٦٧٠\n و ٦٧١السابقتين:\n -١متولي الوقف.\n -٢مدير مؤسسة أو جمعية خيرية وكل مسؤول عن أموالھا.\n -٣وصي القاصر وفاقد األھلية أو ممثله.\n -٤منفذ الوصية أو عقد الزواج.\n -٥كل محام أو كاتب عدل أو وكيل أعمال مفوض.\n -٦كل مستخدم أو خادم مأجور وكل مرتبط بعقد عمل لقاء أجر مع أي مؤسسة خاصة.\n -٧كل شخص مستناب من السلطة إلدارة أموال تخص الدولة أو األفراد أو لحراستھا.\n ويمكن أن يمنع على المجرم ممارسة العمل الذي ارتكب بسبب الجرم."}, {"o": 191, "l": "المادة ٦٥٦", "b": "المادة -٦٧٣معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n كل من استملك أو اختلس أو رفض أن يرد أو كتم لقطة أو أي شيء منقول دخل في حيازته غلطا ً\n أو بصورة طارئة أو بقوة قاھرة ،يعاقب بالحبس حتى سنة وبغرامة حتى ربع قيمة الردود والعطل\n والضرر على أن ال تقل الغرامة عن عشرين ألف ليرة.\n تسري أحكام ھذه المادة على من أصاب كنزاً بما يتعلق بالنصيب العائد لغيره.\n أحكام شاملة -للفصل الأول والثاني والثالث\n المادة -٦٧٤معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n إن مرتكبي الجرائم المنصوص عليھا في الفصول السابقة يعفون من العقاب إذا أقدموا عليھا\n إضراراً باألصول أو الفروع أو األب أو األم أو االبن المتبنى أو الزوج غير المفترق عن زوجه\n قانونا ً.\n\f إذا عاود المجرم جرمه في خالل خمس سنوات قضي عليه بناء على شكوى المتضرر بالعقوبة\n المنصوص عليھا في القانون مخفضا ً منھا الثلث.\n المادة -٦٧٥ال تالحق إال بناء على شكوى الفريق المتضرر -ما لم يكن مجھوالً ،أو تكن\n الشكوى مردودة ،الجنح المنصوص عليھا في المواد ٦٤٧و ٦٥٠و ٦٥١و ٦٥٨و ٦٦٠و٦٧٠\n و ٦٧١و.٦٧٣\n ً\n إن إساءة االئتمان المعاقب عليھا بموجب المادتين ٦٧٠و ٦٧١تالحق عفوا إذا رافقتھا إحدى\n الحاالت المشددة المنصوص عليھا في المادة .٦٧٢\nالمادة -٦٧٦تخفض إلى النصف العقوبات الجناحية المعينة في المواد التي تؤلف الفصل األول\n والثاني والثالث إذا كان الضرر الناتج عنھا أو النفع الذي قصد الفاعل اجتالبه منھا تافھين أو إذا\n كان الضرر قد أزيل كله قبل إحالة الدعوى إلى المحكمة.\n أما إذا حصل الرد أو أزيل الضرر أثناء الدعوى ولكن قبل أي حكم باألساس ولو غير مبرم\n فيخفض ربع العقوبة.\n الفصل الرابع -الغش في المعاملات\n النبذة -١في العيارات والمكاييل غير القانونية أو المغشوشة وفي الغش في كمية البضاعة\n المادة -٦٧٧معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧"}, {"o": 192, "l": "المادة ٦٥٦", "b": "كل من استعمل أو اقتنى في مخزنه أو دكانه أو في عربات البيع أو في غيرھا من األماكن المعدة\n للتجارة عيارات أو مكاييل أو غيرھا من عدد الوزن أو الكيل تختلف عن العيارات والمكاييل\nالمعينة في القانون أو غير موسومة ،يعاقب بالتوقيف التكديري وبالغرامة من عشرين ألف إلى مئة\n ألف ليرة أو بإحدى ھاتين العقوبتين.\n\f المادة -٦٧٨معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n كل من اقتنى في األماكن المذكورة أعاله عيارات أو مكاييل و عدد وزن أو كيل مغشوشة أو غي\nمضبوطة ،يعاقب بالحبس ثالثة أشھر على األكثر وبغرامة من خمسين ألف إلى أربعمائة ألف ليرة.\n المادة -٦٧٩معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\n كل من أقدم باستعماله عن معرفة عيارات أو مكاييل أو عدد وزن أو كيل مغشوشة أو غير\n مضبوطة على غش العاقد في كمية الشيء المسلم ،يعاقب بالحبس مع الشغل من ثالثة أشھر إلى\n سنتين وبالغرامة من مئة ألف ليرة إلى ستمائة ألف ليرة.\n المادة -٦٨٠معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n كل غش آخر سواء في كمية الشيء المسلم أو ماھيته إذا كانت ھذه الماھية ھي السبب الدافع\nللصفقة ،يعاقب بالحبس مع الشغل من ثالثة أشھر إلى سنة وبالغرامة من خمسين ألف إلى خمسمائة\n ألف ليرة أو بإحدى ھاتين العقوبتين.\nالمادة -٦٨١تصادر وفقا ً ألحكام"}, {"o": 193, "l": "المادة ٩٨", "b": "المادة ٩٨العيارات والمكاييل وعدد الوزن والكيل المغشوشة\n أو التي تختلف عن العيارات والمكاييل المعينة في القانون.\n النبذة -٢في الغش في نوع البضاعة\n المادة -٦٨٢معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n كل من غش العاقد:\n سواء في طبيعة البضاعة أو صفاتھا الجوھرية أو تركيبھا أو الكمية التي تحتويھا من العناصر\n المفيدة.\n أو في نوعھا أو مصدرھا عندما يكون تعيين النوع والمصدر معتبراً بموجب االتفاق أو العادات\n السبب الرئيسي للبيع.\n يعاقب بالحبس مع الشغل من شھر إلى سنة وبالغرامة من أربعين ألف إلى خمسمائة ألف ليرة أو\n بإحدى ھاتين العقوبتين.\n\f المادة -٦٨٣ترفع عقوبة الحبس إلى سنتين إذا ارتكب الجرم:\n إما بدسائس أو بوسائل ترمي إلى إفساد عمليات التحليل أو التركيب أو الكيل أو إلى تغيير بقصد\n الغش في تركيب البضاعة أو وزنھا أو حجمھا حتى قبل إجراء ھذه العمليات.\n وإما ببيانات مغشوشة ترمي إلى اإلقناع بوجود عملية سابقة صحيحة.\n النبذة -٣في عرقلة حرية البيوع بالمزايدة\n المادة -٦٨٤معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\nكل من أقدم أثناء مزايدة علنية على عرقلة حرية المزايدة أو االلتزامات وذلك بالتھديد أو العنف أو\n األكاذيب أو على إقصاء المتزايدين والملتزمين بھبات أو وعود عوقب بالحبس من شھر إلى ستة\n أشھر وبغرامة من مئة ألف إلى مليون ليرة.\n النبذة -٤في المضاربات غير المشروعة\n المادة -٦٨٥معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n يعاقب بالحبس مع الشغل من ستة أشھر إلى سنتين وبالغرامة من مليون إلى ستة ماليين ليرة كل\n من توصل بالغش لرفع أو تخفيض أسعار البضائع أو األسھم التجارية العامة أو الخاصة المتداولة\n في البورصة وال سيما بإعالن وقائع مختلفة أو ادعاءات كاذبة أو بتقديم عروض للبيع أو الشراء\n قصد بلبلة األسعار أو باإلقدام على أي عمل من شأنه إفساد قاعدة العرض والطلب في السوق."}, {"o": 194, "l": "المادة ٩٨", "b": "المادة -٦٨٦تضاعف العقوبة إذا حصل ارتفاع األسعار أو ھبوطھا:\n -١على الحبوب والطحين والسكر والزيت واللحوم أو الذبائح أو غير ذلك من المواد الغذائية.\n -٢أو على مواد خارجة عن حرفة المجرم.\n\f -٣أو من جماعة مؤلفة من ثالثة أشخاص أو أكثر.\n أحكام شاملة -للنبذات السابقة\n المادة -٦٨٧يتناول العقاب الشروع في ارتكاب الجرائم المنصوص عليھا في المواد ٦٧٩وما\n يليھا.\n المادة -٦٨٨تأمر المحكمة عند الحكم على مكرر في إحدى الجرائم المذكورة في ھذا الفصل\n بتعليق الحكم أو نشره\n ويستوجب التكرار عدا ذلك الحرمان من ممارسة المھنة أو العمل ولو لم تكن ممارستھا معلقة على\n نيل شھادة أو إذن من السلطة.\nويمكن أن يؤمر بالتعليق والنشر ولو حكم على الفاعل للمرة األولى إذا استوجب ذلك خطورة الفعل.\n الفصل الخامس -في الإفلاس والغش أضراراً بالدائن\n النبذة -١في الإفلاس\n المادة -٦٨٩معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n يعتبر مفلسا ً محتاالً ويعاقب باألشغال الشاقة المؤقتة حتى سبع سنوات كل تاجر مفلس أخفى دفاتره\n أو اختلس أو بدد قسما ً من ماله أو اعترف مواضعة بديون غير متوجبة عليه سواء في دفاتر أو\n صكوك رسمية أو عادية أو بموازنته.\n\f المادة -٦٩٠معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n يعتبر مفلسا ً مقصراً ويعاقب بالحبس من شھر إلى سنة كل تاجر متوقف عن الدفع:\n -١إذا كان قد استھلك مبالغ باھظة سواء في عمليات وھمية على البضائع أو بالبورصة.\n -٢إذا أقدم بعد التوقف عن الدفع وفي سبيل تأخير اإلفالس على شراء بضائع لبيعھا بأقل من ثمنھا\n أو عقد للغاية نفسھا قروضا ً أو تداول سندات أو توسل بطرق أخرى مبيدة للحصول على المال.\n -٣إذا أقدم بعد التوقف عن الدفع على إيفاء دائن أضراراً بكتلة الدائنين.\n -٤إذا وجدت نفقاته الشخصية أو نفقات بيته زائدة عن الحد."}, {"o": 195, "l": "المادة ٩٨", "b": "المادة -٦٩١يمكن أن يعتبر مفلسا ً مقصراً ويعاقب بالحبس المفروض أعاله كل تاجر مفلس:\n -١إذا عقد لمصلحة الغير بدون عوض تعھدات جسيمة بالنسبة لوضعيته عندما تعھد بھا.\n -٢إذا لم يتقيد بالقواعد المتعلقة بتنظيم سجل التجارة.\n -٣إذا لم يقدم في خالل عشرين يوما ً من توقفه عن الدفع التصريح الالزم بمقتضى قانون التجارة\n إلى قلم المحكمة أو إذا كان ھذا التصريح ال يتضمن أسماء جميع الشركاء المتضامنين.\n -٤إذا لم يمسك دفاتر تجارية أو لم ينظم الجردة بالضبط أو إذا كانت دفاتره أو جردته ناقصة أو\n غير أصولية أو ال تبين حقيقة ما له وما عليه ولم يكن مع ذلك ثمة غش.\n -٥إذا تكرر إفالسه ولم يتم شروط عقد الصلح السابق.\n المادة -٦٩٢معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n عند إفالس شركة تجارية ينال العقاب المنصوص عليه في"}, {"o": 196, "l": "المادة ٦٨٩", "b": "المادة ٦٨٩عدا الشركاء في شركات\n التضامن والشركاء الموصون في شركات التوصية.\n -١الشركاء الموصون الذين اعتادوا التدخل في أعمال الشركة.\n -٢مديرو شركة التوصية باألسھم والشركات المحدودة المسؤولية.\n -٣المديرون وأعضاء مجلس اإلدارة والوكالء المفوضون وأعضاء مجالس المراقبة ومفوضو\n المحاسبة وعمال الشركات المذكورة والشركات المغفلة.\n إذا أقدموا بنفسھم على ارتكاب عمل من أعمال اإلفالس االحتيالي أو سھلوا أو أتاحوا ارتكابه عن\n قصد منھم أو إذا نشروا بيانات أو موازنات غير حقيقية أو وزعوا أنصبة وھمية.\n المادة -٦٩٣إذا أفلست شركة تجارية يعاقب بعقوبة اإلفالس التقصيري كل من أقدم من\n االشخاص المذكورين اعاله في إدارة الشركة أو العمل لمصلحتھا على ارتكاب جرم من الجرائم\n المنصوص عليھا في"}, {"o": 197, "l": "المادة ٦٩٠", "b": "المادة ٦٩٠فقراتھا األولى و الثانية و الثالثة.\n و يمكن ان ينال ھذا الشخص العقاب نفسه اذا اقدم في ادارة الشركة او العمل لمصلحتھا على\n ارتكاب جرم من الجرائم المذكورة في"}, {"o": 198, "l": "المادة ٦٩١", "b": "المادة ٦٩١فقراتھا االولى حتى الرابعة.\n\f المادة -٦٩٤تستھدف الشركة التجارية في الحاالت المعينة في المادتين ٦٩٢و ٦٩٣ما نصت\n عليھا المادتان ٢١٠و ٢١١من العقوبات والتدابير االحترازية خال الغرامة.\n المادة -٦٩٥يستحق عقوبة اإلفالس االحتيالي:\n -١من أقدم لمصلحة المفلس على اختالس أو إخفاء أو كتم أمواله كلھا أو بعضھا الثابتة منھا\n والمنقولة.\n ً\n -٢من تقدم احتياال باسمه أو باسم مستعار لتثبيت ديون وھمية في طابق اإلفالس.\n -٣من ارتكب ھو بتعاطى التجارة باسم وھمي جريمة اإلفالس االحتيالي.\n ھذا بقطع النظر عن المسؤولية المترتبة من جراء أعمال التحريض أو التدخل الفرعي.\n المادة -٦٩٦معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\nإن الدائن الذي يشترط لنفسه سواء مع المفلس أو مع أي شخص آخر نفعا ً خاصا ً بسبب اشتراكه في\n اقتراع أرباب الديون أو يجري اتفاقا ً خصوصيا ً ليستجلب نفعا ً لمصلحته من أموال المفلس ،يعاقب\n بالحبس مع الشغل من شھر إلى سنة وبغرامة ال تتجاوز الستمائة ألف ليرة ويمكن أن ترفع عقوبة\n الحبس إلى سنتين إذا كان الدائن سنديك الطابق.\nالمادة -٦٩٧إن زوج المفلس وفروعه وأصوله وأصھاره من الدرجات نفسھا الذين يختلسون أو\n يسرقون أو يخفون سندات تخص الطابق دون أن يكونوا على اتفاق مع المفلس أو يتدخلوا تدخالً\n فرعيا ً معه يعاقبون بعقوبة السرقة المنصوص عليھا في المادة .٦٤٨\n المادة -٦٩٨يمكن أن يؤمر بتعليق القرار ونشره من أجل إحدى الجرائم المنصوص عليھا في\n ھذا الفصل.\nمن حكم عليه باإلفالس االحتيالي ومن حكم عليه تكراراً باإلفالس التقصيري يستھدف المنع المؤقت\n أو المؤبد من ممارسة التجارة أو القيام في شركة بإحدى الوظائف المعينة في"}, {"o": 199, "l": "المادة ٦٩٢", "b": "المادة ٦٩٢فقرتيھا\n الثانية والثالثة.\n النبذة -٢في ضروب الغش الأخرى المرتكبة إضراراً بالدائنين\n\f المادة -٦٩٩معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n إن المدين الذي يقوم بقصد إضاعة حقوق الدائنين أو منع التنفيذ في أمواله المنقولة أو الثابتة على\n إنقاص أمواله بأي شكل كان وال سيما:\n بتوقيع سندات وھمية أو باإلقرار كذبا ً بوجود موجب أو بإيفائه كله أو بعضه.\n أو بكتم بعض أمواله أو تھريبھا.\n أو ببيع بعض أمواله أو إتالفھا أو تعييبھا.\nيعاقب بالحبس مع الشغل من شھر إلى ستة أشھر وبغرامة من خمسين ألف إلى ستمائة ألف ليرة.\n المادة -٧٠٠إذا ارتكبت الجريمة باسم شركة أو لحسابھا فإن ھذه الشركة تستھدف العقوبات\n والتدابير االحترازية على ما ھو معين في"}, {"o": 200, "l": "المادة ٢١٠", "b": "المادة ٢١٠و ٢١١بقطع النظر عن العقوبات التي\n يستحقھا ،وفقا ً ألحكام المادة ،٦٩٢من ذكر فيھا من األشخاص الذين يساھمون في الفعل أو\n يسھلون أو يتيحون ارتكابه عن قصد منھم.\n الفصل السادس -في التقليد\n النبذة -١في تقليد العلامات الفارقة للصناعة والتجارة\nالمادة -٧٠١تعتبر عالمات فارقة للصناعة أو التجارة بالمعنى المقصود في ھذه النبذة األسماء\n المكتوبة على شكل يميزھا عن غيرھا ،واأللقاب والرموز ،واألختام ،والدمغات ،والحروف\n والسمات ،والرسوم البارزة ،والتصويرات واألرقام ،وباإلجمال كل إشارة ترمي -في مصلحة\n المستھلك وصاحب المعمل أو التاجر -إلى إظھار ماھية بضاعة ما ومصدرھا أو ماھية محصول\n صناعي أو تجاري ،أو زراعي ،أو محاصيل الغابات والمناجم إذا سجلت ھذه العالمات ونشرت\n وفقا ً للقوانين المرعية اإلجراء.\n المادة -٧٠٢معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\n\f كل من أقدم عن معرفة:\n ً\n على تقليد عالمة فارقة تخص الغير ولو أضاف إليھا ألفاظا أخرى مثل تشبيه ،أو مشبه ،أو صنف\n أو نوع ،أو وصفة.\n أو على وضع عالمة تخص غيره مقلدة على محصوالته أو سلعه التجارية.\n أو على بيع محصول يحمل عالمة مغتصبة أو مقلدة أو عرضه للبيع.\n فإن كان عمله من شأنه أن يغش المشتري ،يعاقب بالغرامة من مئة ألف إلى مليون ليرة وبالحبس\n مع الشغل من ثالثة اشھر إلى ثالث سنوات أو بإحدى ھاتين العقوبتين.\n المادة -٧٠٣معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n كل من شبه عالمة بغيرھا بنية الغش ،دون أن يقلدھا.\n وكل من استعمل ھذه العالمة أو باع أو عرض للبيع محصوالً وضعھا عليه فإذا كان عمله من\nشأنه أن يغش المشتري يعاقب بالغرامة من مئة ألف إلى خمسمائة ألف ليرة وبالحبس مع الشغل من\n شھرين إلى سنتين أو بإحدى ھاتين العقوبتين.\nالمادة -٧٠٤إن األشخاص الذين يبيعون أو يعرضون للبيع أو الذين يستعملون عالمة مقلدة ،أو"}, {"o": 201, "l": "المادة ٢١٠", "b": "مشبھة بنية الغش ،يمكنھم دون سواھم أن يتذرعوا بحجة جھلھم تسجيل العالمة إذا كانوا لم يرتكبوا\n الفعل باالتفاق مع من قلدھا أو شبھھا.\nالمادة -٧٠٥يقضى بالعقوبة المنصوص عليھا في"}, {"o": 202, "l": "المادة ٧٠٣", "b": "المادة ٧٠٣على كل من صور على العالمة\n أوسمة وطنية أو أجنبية أو كلمات أو صوراً أو سمات أو رموزاً مثيرة أو مخالفة لالنتظام العام أو\n اآلداب.\n ويمكن للقاضي أن يأمر بمصادرة العالمة باالستناد إلى المادة الثامنة والتسعين ولو لم تقترن\n المالحقة بحكم.\n المادة -٧٠٦يقضى بالعقوبة نفسھا على كل من لم يضع على محصوالته العالمة الفارقة\n الواجب وضعھا بمقتضى القانون واألنظمة.\n أو كل من باع أو عرض للبيع محصوالً ال يحمل العالمة الفارقة الواجب وضعھا عليه وتأمر\n المحكمة بوضع العالمة المذكورة تنفيذاً ألحكام المادة .١٣٠\n النبذة -٢في شهادات الاختراع\n\f المادة -٧٠٧ملغاة وفقا للقانون رقم ٢٤٠الصادر في ٢٠٠٠/٨/٧\n المادة -٧٠٨ملغاة وفقا للقانون رقم ٢٤٠الصادر في ٢٠٠٠/٨/٧\n المادة -٧٠٩ملغاة وفقا للقانون رقم ٢٤٠الصادر في ٢٠٠٠/٨/٧\n النبذة -٣في الرسوم والنماذج الصناعية\n المادة -٧١٠معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n كل من يلحق عن معرفة ضرراً في رسوم ونماذج صناعية مسجلة ومنشورة حسب األصول\n مضمونة بالقوانين المرعية اإلجراء ،يعاقب بالغرامة من خمسين ألف إلى خمسمائة ألف ليرة.\nالمادة -٧١١إذا كان المجرم مساعداً أو ساعد في الماضي بأي صفة كانت الشخص المتضرر،\n عوقب عالوة على الغرامة بالحبس مع التشغيل من شھرين إلى ستة أشھر.\n المادة -٧١٢يعفى من العقوبة كل من أثبت جھله التسجيل.\n أحكام شاملة -النبذات السابقة\n\f المادة -٧١٣إذا كانت العالمة الفارقة أو شھادة االختراع أو الرسوم والنماذج الصناعية\n المسجلة وفقا ً لألصول لم تنشر وقت ارتكاب الفعل يستحق الفاعل العقوبة فيما لو ثبت أنه علم أو\n كان عالما ً بالتسجيل.\n النبذة -٤معدلة وفقا للقانون تاريخ ١٩٤٨/٢/٥في المزاحمة الاحتيالية\n المادة -٧١٤معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\nكل من أقدم بوسائل الغش أو االدعاءات الكاذبة أو بالتلميح عن سوء قصد على تحويل زبائن الغير"}, {"o": 203, "l": "المادة ٧٠٣", "b": "إليه ،يعاقب بناء على شكوى المتضرر بالغرامة من مئة ألف إلى خمسمائة ألف ليرة.\n يتناول العقاب الشروع في ارتكاب ھذه الجريمة.\n النبذة -٥في اغتصاب الاسم التجاري\n المادة -٧١٥معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n ينعت باالسم التجاري:\n -١كل اسم لتاجر أو صاحب مصنع أو مزارع أو مستثمر إذا لم يكن قد أصبح اللقب الضروري\n والوحيد للمحصول.\n -٢كل عنوان تجاري ليس له طابع انتسابي.\n -٣االسم المستعار الذي يتكنى به التاجر أو صاحب المصنع أو المزارع أو المستثمر.\n -٤االسم المميز الذي اعتنقه فريق من الناس ممن ذكر أعاله ولو لم يكن ھذا الفريق يؤلف ھيئة\n ذات كيان قانوني.\n المادة -٧١٦يستحق العقوبة المنصوص عليھا في"}, {"o": 204, "l": "المادة ٧٠٢", "b": "المادة ٧٠٢كل من اغتصب اسم الغير\n التجاري:\n\fإما بوضعه أو إظھاره بأي شكل كان على المحصوالت الطبيعية أو المصنوعة أو توابعھا أو على\n الغالفات أو الشارات.\n أو بإذاعته منشورات أو إعالنات أو فواتير أو رسائل أو ما شاكلھا.\nتطبق ھذه األحكام وإن كان االسم المغتصب محرفا ً ولو قليالً أو مقرونا بكنية غير كنية صاحبه أو\n ً\n بأية عبارة أخرى تبقى حروف االسم المميزة وتحمل على االلتباس.\n يتناول العقاب الشروع في ارتكاب ھذه الجريمة.\n المادة -٧١٧يفترض حتى ثبوت العكس سوء النية في اغتصاب االسم التجاري.\n النبذة -٦في الجوائز الصناعية والتجارية\n المادة -٧١٨معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n يعاقب بالغرامة من عشرين ألف إلى خمسمائة ألف ليرة وبالحبس من ثالثة أشھر إلى سنتين أو\n بإحدى ھاتين العقوبتين ،على أن ال تنقص الغرامة عن مئة ألف ليرة إذا لم يحكم بعقوبة مانعة\n للحرية:\n كل من نسب لنفسه بنية الغش جوائز صناعية أو تجارية حقيقية كانت أو وھمية واستعملھا عالنية\nوذلك بوضعھا على الشارات التجارية وعلى غالفات البضائع أو األوراق التجارية أو بكتابتھا على\n األرمات.\n وكل من حاول إيھام العامة أنه يحمل جوائز تجارية أو صناعية.\n المادة -٧١٩يقضى بالغرامة المنصوص عليھا في المادة السابقة.\nعلى كل من يستعمل جائزة صناعية أو تجارية دون أن يعين بالضبط اسم المعرض أو السلطة التي\n منحتھا والتاريخ الكامل الذي أعطيت فيه.\n وعلى كل من يستعمل جائزة تجارية أو صناعية نالھا بصفة كونه مساعداً دون أن يبين اسم المحل\n الذي استخدمه.\n أحكام شاملة\n\f المادة -٧٢٠تقدر المحاكم التقليد والتشبيه بالنظر إليھما من ناحية المستھلك أو المشتري،\n وباعتبار التشابه اإلجمالي أكثر من اعتبار الفروق الجزئية.\nالمادة -٧٢١يقضى بالحرمان من الحقوق المعينة في الفقرتين الثالثة والرابعة من"}, {"o": 205, "l": "المادة ٦٥", "b": "المادة ٦٥\n وبنشر الحكم وتعليقه وفاقا ً ألحكام المادتين ٦٧و ٦٨إذا حكم بإحدى الجنح المذكورة في ھذا\n الفصل.\n وعند تكرارھا يمكن أن يقضي بمنع المجرم من ممارسة التجارة أو الصناعة التي حصل الجرم\n أثناء ممارستھا.\n الفصل السابع -في الملكية الأدبية والفنية\n النبذة -١أحكام عامة\n المادة -٧٢٢ملغاة وفقا ً للقانون رقم ٧٥تاريخ ١٩٩٩/٤/٣\n المادة -٧٢٣ملغاة وفقا ً للقانون رقم ٧٥تاريخ ١٩٩٩/٤/٣\n المادة -٧٢٤ملغاة وفقا ً للقانون رقم ٧٥تاريخ ١٩٩٩/٤/٣\n المادة -٧٢٥ملغاة وفقا ً للقانون رقم ٧٥تاريخ ١٩٩٩/٤/٣\n\f النبذة -٢في العقوبات\n المادة -٧٢٦ملغاة وفقا ً للقانون رقم ٧٥تاريخ ١٩٩٩/٤/٣\n المادة -٧٢٧ملغاة وفقا ً للقانون رقم ٧٥تاريخ ١٩٩٩/٤/٣\n المادة -٧٢٨ملغاة وفقا ً للقانون رقم ٧٥تاريخ ١٩٩٩/٤/٣\n المادة -٧٢٩ملغاة وفقا ً للقانون رقم ٧٥تاريخ ١٩٩٩/٤/٣\n الفصل الثامن -الأضرار الملحقة بأملاك الدولة والأفراد\n النبذة -١في الهدم والتخريب\n المادة -٧٣٠معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n كل من ھدم أو خرب قصداً األبنية واألنصاب التذكارية والتماثيل أو غيرھا من اإلنشاءات المعدة\nلمنفعة الجمھور أو للزينة العامة يعاقب بالحبس من ستة أشھر إلى ثالث سنوات وبالغرامة من مئة\n ألف إلى ستمائة ألف ليرة.\n\fالمادة -٧٣١يستحق العقوبة نفسھا كل من أقدم قصداً على ھدم أو تخريب نصب تذكاري أو أي\n شيء منقول أو غير منقول له قيمة تاريخية أو تمثال أو منظر طبيعي مسجل سواء أكان ملكا ً له أم\n لغيره.\n المادة -٧٣٢معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n كل من أقدم قصداً على ھدم أي بناية كلھا أو بعضھا مع علمه أنھا ملك غيره يعاقب بالحبس من\n ثالثة أشھر إلى سنتين وبالغرامة من خمسين ألف إلى أربعمائة ألف ليرة.\n وإذا وقع الھدم ولو جزئيا ً على األكواخ والجدر غير المطينة أو الحيطان المبنية بالدبش دون طين"}, {"o": 206, "l": "المادة ٦٥", "b": "كانت عقوبة الحبس من شھر إلى ستة أشھر والغرامة من عشرين ألف إلى مئة ألف ليرة.\n المادة -٧٣٣معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n كل من ھدم أو خرب قصداً شيئا ً يخص غيره مما لم يعين في ھذا الباب يعاقب بغرامة ال تتجاوز\n قيمة الضرر على أن ال تنقص عن عشرين ألف ليرة.\n وإذا كانت قيمة الشيء المتلف أو الضرر الناجم يتجاوز العشرين ألف ليرة فيمكن عالوة على\n الغرامة أن يحبس الفاعل مدة ال تفوق الستة أشھر.\n المادة -٧٣٤إذا أدت إحدى الجنح المذكورة في ھذه النبذة إلى قتل إمرىء أو جرحه عوقب\n المجرم على ھذا الفعل مع مراعاة أحكام المادتين ١٨٩و.١٩١\n النبذة -٢في نزع التخوم واغتصاب العقار\n المادة -٧٣٥من أقدم ولو جزئيا ً على طم حفرة أو ھدم سور من أي المواد بني أو على قطع\n سياج أو نزعه أخضراً كان أم يابسا ً ومن ھدم أو خرب أو نقل أية عالمة تشير إلى الحدود بين\n مختلف األمالك يعاقب بالحبس مدة ال تتجاوز الستة أشھر.\nتنزل العقوبة نفسھا بمن ھدم أو خرب أو نقل تخوم المساحة أو عالمات االستھداء أو نصب التحديد\n أو عالمات تسوية األرض.\n\f المادة -٧٣٦معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n إذا ارتكب الجرم المذكور تسھيالً لغصب أرض أو بالتھديد أو الجبر الواقع على األشخاص عوقب\n الفاعل بالحبس من شھرين إلى سنة فضالً عن الغرامة من خمسين ألف إلى أربعمائة ألف ليرة.\n المادة -٧٣٧معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\n ً ً\n -من ال يحمل سندا رسميا بالملكية أو بالتصرف واستولى على عقار أو قسم من عقار بيد غيره\n عوقب بالحبس من شھر إلى سنة وبالغرامة من مائتي ألف إلى مليون ليرة.\n تشدد العقوبة وفقا ً للمادة ٢٥٧في كل من الحالتين التاليتين:\n -١إذا رافق الفعل تھديد أو عنف على األشخاص أو األشياء.\n -٢إذا وقع الغصب على كل أو قسم من الطرقات العامة أو أمالك الدولة أو األمالك المشاعية."}, {"o": 207, "l": "المادة ٦٥", "b": "المادة -٧٣٨معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\n -من استولى دون مسوغ شرعي على عقار أو قسم من عقار ،بقصد السكن أو األشغال أو\n االستثمار أو االستعمال ألي غاية أخرى ،يعاقب بالحبس من شھر إلى سنة وبالغرامة من مائتي\n ألف إلى مليون ليرة.\n تشدد العقوبة وفقا ً للمادة ٢٥٧في كل من الحاالت التالية:\n -١إذا رافق الفعل تھديد أو عنف على األشخاص أو األشياء.\n -٢إذا وقع االستيالء على بناء تشغله إحدى إدارات الدولة أو إحدى الھيئات اإلدارية أو إحدى\n المؤسسات العامة أو ذات المنفعة العامة.\n -٣إذا لم يبادر الفاعل إلى ترك العقار وإخالئه ضمن مھلة أسبوع من تاريخ تبلغه إنذاراً خطيا ً أو\n إذا استمر في وضع يده عليه مدة تزيد عن الشھرين.\n النبذة -٣في التعدي على المزروعات والحيوانات وآلات الزراعة\n المادة -٧٣٩من قطع أو قصف أو أتلف مزروعات قائمة أو أشجاراً أو شجيرات نبت الطبيعة\nأو نصب يد اإلنسان أو غير ذلك من االغراس مع علمه أنھا تخص غيره عوقب بالحبس حتى ثالثة\n أشھر.\n\f المادة -٧٤٠معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n إذا وقع فعل اإلتالف على مطاعيم أو أشجار مثمرة أو فسائلھا أو على شجرة أخرى ثمينة من\n الوجھة الزراعية أو التجارية أو الصناعية عوقب الفاعل بالغرامة من أربعين ألف إلى ستمائة ألف\n ليرة وبالحبس من عشرة أيام إلى شھر عن كل مطعوم أو شجرة أو فسيلة على أن ال يتجاوز\n مجموع العقوبة الثالثة سنوات.\n المادة -٧٤١إذا اقتصر الجرم على تقليم المطاعيم أو األشجار أو الفسائل خفضت العقوبة\n المنصوص عليھا في المادة السابقة إلى النصف.\n المادة -٧٤٢من أقدم قصداً غير مضطر على قتل حيوان جر أو حمل أو ركوب أو مواشي من\n مختلف األنواع تخص غيره يعاقب بالتوقيف التكديري إذا وقع الجرم في ما ھو جار على ملك\nالفاعل أو بإجارته أو حيازته بأي صفة كانت من األراضي أو اإلسطبالت أو الحظائر أو األبنية وما"}, {"o": 208, "l": "المادة ٦٥", "b": "يتبعھا.\n وبالحبس حتى ستة أشھر إذا وقع الجرم في مكان جار على ملك صاحب الحيوان أو بإجارته أو\n حيازته بأي صفة كانت.\n ً\n وبالحبس من خمسة عشر يوما إلى شھرين إذا ارتكب المجرم في أي مكان آخر.\n وإذا قتل بالتسميم أحد الحيوانات المذكورة أعاله كانت العقوبة في كل حال الحبس من ثالثة أشھر\n إلى سنتين.\n المادة -٧٤٣معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\nمن أقدم قصداً على إتالف األدوات الزراعية أو كسرھا أو تعطيلھا عوقب بالحبس من شھرالى ستة\n أشھر وبالغرامة من عشرين ألف إلى مئة ألف ليرة.\n المادة -٧٤٤معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n إذا أقدمت عصابة مسلحة ال تنقص عن خمسة أشخاص على نھب بعض األمالك الموصوفة أعاله\n أو إتالفھا قوة وإقتداراً عوقب كل من الفاعلين باألشغال الشاقة المؤقتة وبالغرامة من خمسين ألف\n إلى أربعمائة ألف ليرة.\n الفصل التاسع -في الجرائم المتعلقة بنظام المياه\n\f المادة -٧٤٥معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\n يعاقب بالحبس حتى سنة وبالغرامة حتى خمسمائة ألف ليرة أو بإحدى ھاتين العقوبتين من أقدم\n بدون إذن:\n -١على القيام بأعمال التنقيب عن المياه الكائنة تحت األرض أو المتفجرة أو على حصرھا ما لم\n يكن المقصود حفر آبار غير متفجرة في األمالك الخاصة ال يتجاوز عمقھا مئة وخمسين متراً.\n -٢على إجراء حفريات تبعد عن حد ضفاف مجاري المياه ومعابرھا وأقنية الري والتجفيف\n والتصريف مسافة أقل من عمق ھذه الحفريات وفي كل حال أقل من ثالثة أمتار.\n -٣على نزع حجارة أو تراب أو رمل أو أشجار أو شجيرات أو أعشاب عن تلك الضفاف أو من\n أحواض مجاري المياه المؤقتة أو الدائمة أو من البحيرات والمستنقعات والبرك والغدران.\n -٤على الغرس أو الزرع أو وضع شيء ما على ضفاف البحيرات والمستنقعات والبرك والغدران"}, {"o": 209, "l": "المادة ٦٥", "b": "أو على ضفاف مجاري المياه المؤقتة أو الدائمة أو في أحواضھا أو بين حدود ممرات أقنية الري\n والتجفيف والتصريف أو قساطل المياه ومعابرھا أو المصرح بإنشائھا للمنفعة العامة.\n -٥على التعدي بأي شكل كان على ضفاف الينابيع ومجاري المياه المؤقتة أو الدائمة والمستنقعات\n والبحيرات والبرك والغدران أو على حدود ممرات أقنية الري والتجفيف والتصريف أو معابر\n المياه أو قساطلھا المصرح بإنشائھا للمنفعة العامة.\n -٦على منع جري المياه العمومية جريا ً حراً وعلى قطع مياه الشرب عن المستفيدين منھا.\n -٧على القيام بأي عمل دائم أو مؤقت من شأنه التأثير على كمية المياه العمومية وجريھا.\nالمادة -٧٤٦يعاقب بالغرامة المنصوص عليھا في المادة السابقة من أقدم بدون إذن على تنظيف\n مجاري المياه المؤقتة أو الدائمة أو تعميقھا أو تقويمھا أو تنظيمھا.\n المادة -٧٤٧معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\n يعاقب بالحبس حتى سنتين وبالغرامة حتى خمسمائة ألف ليرة من ھدم أو قلب أو خرب كل أو\n بعض اإلنشاءات المشيدة لالنتفاع بالمياه العمومية لحفظھا أو في سبيل االحتماء من طغيان ھذه\n المياه وخصوصا ً الجسور والسدود والمعابر وأقنية الري والتجفيف أو التصريف وقساطل المياه\n الظاھرة أو المطمورة سواء كان قد منح بالمياه امتياز أم ال.\n وتنزل العقوبة نفسھا بكل من يقدم على التعدي بأي شكل كان على مصادر مياه مشاريع الري التي\n أنشأتھا الدولة أو اإلدارات أو الھيئات العامة بغية التأثير على كمية المياه العمومية وجريھا وعلى\n أقنية الري وحدود ممراتھا وعلى حرمھا أو على كافة منشآت المشروع التي أقيمت للمنفعة\n\fالعمومية وكذلك على من يغرس أو يزرع ھذه األماكن أو يقوم بالحفر فيھا أو البناء عليھا ،ويحكم\n بإعادة الحال إلى ما كان عليه على نفقة المخالف.\n المادة -٧٤٨يقضى بالعقوبة نفسھا على من:"}, {"o": 210, "l": "المادة ٦٥", "b": "-١سيل في المياه العمومية الممنوح بھا امتياز أم ال أو سكب أو رمى فيھا سوائل أو مواد ضارة\n بالصحة أو الراحة العامة أو مانعه من حسن االنتفاع بھذه المياه.\n -٢ألقى أسمدة حيوانية أو وضع أقذاراً في األراضي الداخلة ضمن النطاق الذي حددته السلطة\n لحماية نبع تنتفع منه العامة.\n -٣أجرى أي عمل من شأنه تلويث النبع أو المياه التي يشرب منھا الغير.\n المادة -٧٤٩معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n من أقدم قصداً على تلويث نبع أو ماء يشرب منه الغير يعاقب بالحبس من سنة إلى ثالث سنوات\n وبالغرامة من خمسين ألف إلى ستمائة ألف ليرة.\n الباب الثاني عشر -في القباحات\n الفصل الأول -في حماية الطرق العامة والأماكن المأهولة\nالمادة -٧٥٠معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\nيعاقب بالحبس حتى ستة أشھر وبالغرامة من مئة ألف إلى مليون ليرة ،أو بإحدى ھاتين العقوبتين\n من أقدم على:\n -١تخريب الساحات والطرق العامة أو تعييبھا.\n -٢نزع اللوحات واألرقام الموضوعة في منعطفات الشوارع أو على األبنية والعالمات\n الكيلومترية والصوى أو تخريبھا أو تعييبھا.\n\f المادة -٧٥١معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\n يعاقب بالحبس حتى ستة أشھر بالغرامة من مئة ألف إلى مليون ليرة أو بإحدى ھاتين العقوبتين:\n -١من أقدم على تطويف الطرق العامة أو ملك الغير برفعه مصب مياھه عن المستوى المحدد\n بموجب األنظمة أو بإرتكابه أي خطأ آخر.\n -٢من سدم الطريق العامة دون داع وال إذن من السلطة بوضعه أو تركه عليھا أي شيء يمنع\n حرية المرور وسالمته أو يضيقھما.\n ً\n -٣من أھمل التنبيه نھاراً والتنوير ليال أمام الحفريات وغيرھا من األشغال المأذون له بإجرائھا أو\n أمام سائر المواد وغيرھا من األشياء المأذون له بوضعھا في الساحات وعلى الطرق العامة."}, {"o": 211, "l": "المادة ٦٥", "b": "-٤من أطفأ القناديل أو الفوانيس المستعملة لتنوير الطريق العامة أو نزعھا أو أتلفھا.\n -٥من رمى أو وضع أقذاراً أو كناسة أو أي شيء آخر على الطريق العامة.\n -٦من رمى أو أسقط على أحد الناس أقذاراً أو غيرھا من األشياء الضارة عن غير انتباه.\n -٧من وضع إعالنات على األنصاب التاريخية واألبنية العامة والمقابر واألبنية المعدة للعبادة.\n تنزع على نفقة الفاعل أو بواسطته اإلعالنات أو المواد التي تسد الطريق.\nالمادة -٧٥٢معدلة وفقا للقانون ١٩٥٢/٦/١٨والمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n يستحق العقوبة المذكورة في المادة السابقة من أقدم في األماكن المأھولة:\n -١على اركاض حيوانات الجر والحمل والركوب وغيرھا من الماشية أو على إطالقھا.\n -٢على إطالق أسھم نارية بصورة يحتمل معھا وقوع خطر على األشخاص أو األشياء .تصادر\n األسلحة واألسھم المضبوطة.\n ويمكن في الحالة المنصوص عليھا في الفقرة الثانية ،إنزال عقوبة التوقيف التكديري.\n الفصل الثاني -في حماية المحلات العامة\n المادة -٧٥٣معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\nإن مديري المسارح والسينما ومستخدميھم الذين يقبلون عند عرض مسرحية أو فيلم مما ھو محظر\n على األوالد ،ولداً أو مراھقا ً ذكراً كان أم أنثى أو ابنة لم تبلغ الثامنة عشرة من عمرھا غير\n مصحوبة بأبيھا أو أمھا أو وليھا أو أحد أقاربھا األدنين البالغين ،يعاقبون بالحبس حتى ثالثة أشھر\n على األكثر وبالغرامة من أربعين ألف إلى أربعمائة ألف ليرة ،أو بإحدى ھاتين العقوبتين.\n في حالة التكرار يمكن أن يؤمر بإقفال المحل لمدة تتراوح بين الثالثة أيام والثالثة أشھر.\n\f المادة -٧٥٤معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\nمن أھمل من أصحاب الفنادق والخانات والبيوت المفروشة المعدة لإليجار أن يمسك حسب األصول"}, {"o": 212, "l": "المادة ٦٥", "b": "دفتراً يدون فيه بالتسلسل وبدون بياض اسم كل شخص نام أو قضى الليل في نزله وصنعته ومحل\n والدته وتاريخھا وتاريخ دخوله وخروجه ،ومن لم يبرز ھذا الدفتر عند كل طلب من السلطة ذات\n االختصاص يعاقب بالحبس حتى ثالثة أشھر على األكثر وبالغرامة من أربعين ألف إلى أربعمائة\n ألف ليرة ،أو بإحدى ھاتين العقوبتين.\n المادة -٧٥٥معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\nيقضى بالعقوبة نفسھا على األشخاص ذوي الصفة المشار إليھا في المادة السابقة ،ومديري المسارح\n والسينما وغيرھا من المحالت العامة الذين ال يعنون بتنظيف محالتھم.\n المادة -٧٥٦معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\n يعاقب بالحبس حتى ثالثة أشھر على األكثر وبالغرامة من أربعين ألف إلى أربعمائة ألف ليرة ،أو\n بإحدى ھاتين العقوبتين من أھمل االعتناء بالوجاقات ومداخن األفران والمعامل وغيرھا من\n المحالت التي تستخدم فيھا النار أو أھمل تنظيفھا وتصليحھا.\n الفصل الثالث -في المخالفات ضد الآداب والراحة العامة\n المادة -٧٥٧معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\nمن استحم على مرأى من المارة بوضع مغاير للحشمة ومن ظھر في محل عام أو مباح للعامة بمثل\n ذلك الوضع يعاقب بالحبس حتى ثالثة أشھر على األكثر وبالغرامة من أربعين ألف إلى أربعمائة\n ألف ليرة أو بإحدى ھاتين العقوبتين.\n المادة -٧٥٨معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ١٩٨٣/٩/١٦\n\f يعاقب بالحبس حتى ثالثة أشھر على األكثر وبالغرامة من أربعين ألف إلى أربعمائة ألف ليرة أو\n بإحدى ھاتين العقوبتين:\n ً\n -١من أحدث ضوضاء أو لغطا على صورة تسلب راحة اآلھلين وھكذا من حرض على ھذا العمل\n أو اشترك فيه.\n ً\n -٢من رمى قصدا بحجارة أو نحوھا من األجسام الصلبة أو باألقذار العجالت واألبنية ومساكن\n الغير أو أسواره والجنائن واألحواش."}, {"o": 213, "l": "المادة ٦٥", "b": "-٣من أفلت حيوانا ً مؤذيا ً أو أطلق مجنونا كانا في حراسته.\n ً\n -٤من حث كلبه عند مھاجمته المارة أو اللحاق بھم أو من لم يمسكه عن ذلك ولو لم يحدث أذى أو\n ضررا.\n المادة -٧٥٩معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\nمن طبع أو باع أو عرض للبيع نقوشا ً أو صوراً أو رسوما ً تعطي عن اللبنانيين فكرة غير صحيحة\nمن شأنھا أن تنال من كرامتھم واعتبارھم ،عوقب بالحبس حتى ثالثة أشھر على األكثر وبالغرامة\n من أربعين ألف إلى أربعمائة ألف ليرة أو بإحدى ھاتين العقوبتين.\n وتصادر تلك النقوش والصور والرسوم.\n المادة -٧٦٠معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\n ً\n من عرض على الطريق العام بدون ترخيص يانصيبا أو أي لعب آخر عوقب بالحبس حتى ثالثة\n أشھر على األكثر وبالغرامة من أربعين ألف إلى أربعمائة ألف ليرة أو بإحدى ھاتين العقوبتين.\n وتصادر األشياء التي استخدمت الرتكاب الفعل أو التي كانت معدة الرتكابه.\n الفصل الرابع -في إساءة معاملة الحيوانات\n المادة -٧٦١يعتبر داجنا ً بالمعنى المقصود في ھذه النبذة كل حيوان يعيش في حراسة من\n استملكه ورباه.\n المادة -٧٦٢معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n\f يعاقب بالتوقيف التكديري وبالغرامة من عشرة آالف إلى عشرين ألف ليرة كل شخص يقدم بدون\n داع على إساءة معاملة حيوان داجن أو على إرھاقه.\n المادة -٧٦٣يعاقب بالغرامة المنصوص عليھا أعاله من أساء علنا ً وبدون داع معاملة حيوان\n غير داجن.\n الفصل الخامس -في الأضرار بأملاك الدولة والناس\n المادة -٧٦٤معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n يعاقب بالتوقيف التكديري وبالغرامة من ستة آالف إلى عشرين ألف ليرة من يستخرج من أمالك\n الدولة بدون أذن عشبا ً أو ترابا ً أو حجارة أو غيرھا من المواد.\n المادة -٧٦٥معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧"}, {"o": 214, "l": "المادة ٦٥", "b": "يعاقب بالغرامة من ألفي إلى عشرين ألف ليرة.\n -١من أقدم على دخول أرض الغير المحرزة أو المزروعة أو التي فيھا محصوالت دون أن يكون\n له حق المرور.\n -٢من رعى أو أطلق ماشية أو سائر حيوانات الجر والحمل والركوب في ما كان لغيره من أرض\nمحرزة أو مغروسة أشجاراً مثمرة أو مزروعة أو التي فيھا محصوالت ،باإلجمال كل من أتى إلى\n أرض ال تخصه أو ليس له عليھا حق المرور أو الرعي بحيوانات يمكن أن تحدث ضرراً فيھا.\n -٣من سبب بخطأه موت حيوانات الغير وجرحھا أو إيذائھا.\n الفصل السادس -في المخالفات التي تمس بالثقة العامة\n المادة -٧٦٦معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n\f من أقدم على بيع بضاعة أو طلب أجراً بما يزيد عن الثمن المعين في التسعيرة المنشورة وفقا ً\n للقانون يعاقب بالتوقيف التكديري وبالغرامة من عشرة آالف ليرة إلى عشرين ألف إذا لم يكن قد\n فرض القانون عليه عقوبة أشد.\n المادة -٧٦٧معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\nمن أبى قبول النقود الوطنية بالقيمة المحددة لھا يعاقب بالغرامة من ألف ليرة إلى عشرة آالف ليرة.\n المادة -٧٦٨معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n يعاقب بالتوقيف التكديري وبالغرامة من عشرة آالف إلى عشرين ألف ليرة من يتعاطى ،بقصد\nالربح ،مناجاة األرواح ،والتنويم المغناطيسي ،والتنجيم وقراءة الكف وقراءة ورق اللعب وكل ما له\n عالقة بعلم الغيب ،وتصادر األلبسة والعدد المستعملة.\n يعاقب المكرر بالحبس حتى ستة أشھر وبالغرامة حتى المائتي ألف ليرة ،ويمكن إبعاده إذا كان\n أجنبيا ً.\n الفصل السابع -في مخالفة التدابير الصادرة عن السلطة\n المادة -٧٦٩معدلة وفقا للقانون ٢٣٩تاريخ ١٩٩٣/٥/٢٧\n يعاقب بالغرامة من عشرة آالف إلى عشرين ألف ليرة:\n -١من أھمل أو رفض إطاعة أوامر السلطة اإلدارية بإصالح أو ھدم األبنية المتداعية.\n -٢كل شخص سواء أكان من أھل الفن أم ال يستنكف أو يتوانى بدون عذر عن اإلغاثة أو عن"}, {"o": 215, "l": "المادة ٦٥", "b": "إجراء أي عمل أو خدمة يطلبھا منه رجال السلطة عند حصول حادث أو غرق أو فيضان أو حريق\n أو أي غائلة أخرى أو عند قطع الطريق أو السلب أو الجرم المشھود أو االستنجاد أو عند تنفيذ\n األحكام القضائية.\n ويمكن في الحالة المنصوص عليھا في الفقرة األولى فرض عقوبة التوقيف التكديري.\n المادة -٧٧٠معدلة وفقا للمرسوم االشتراعي ١١٢تاريخ ١٩٨٣/٩/١٦والقانون ٢٣٩تاريخ\n ١٩٩٣/٥/٢٧\n من خالف األنظمة اإلدارية أو البلدية الصادرة وفقا ً للقانون عوقب بالحبس حتى ثالثة أشھر\n وبالغرامة من مئة ألف إلى ستمائة ألف ليرة ،أو بإحدى ھاتين العقوبتين.\n\f المادة -٧٧١ينشر ھذا القانون فوراً في الجريدة الرسمية ويوضع موضع اإلجراء في أول\n تشرين األول سنة .١٩٤٤\n المادة -٧٧٢مضافة وفقا للقانون تاريخ ١٩٤٨/٢/٥\nألغي قانون الجزاء العثماني والقانون الصادر في ٢٣كانون الثاني سنة ١٩٤٦و"}, {"o": 216, "l": "المادة ١٧٣", "b": "المادة ١٧٣من\n قانون العقوبات وجميع النصوص االشتراعية األخرى المخالفة ألحكام ھذا القانون.\n بيروت في أول آذار سنة ١٩٤٣\n الفرد نقاش\n صدر عن رئيس الجمھورية\n رئيس مجلس الوزراء\n سامي الصلح\n وزير العدل\n أحمد الحسيني"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (93,'قوانين','قانون حماية كاشفي الفساد - رقم 83 - 10 تشرين الأول 2018','2018-10-10','https://www.ppa.gov.lb/ar/pages/details/93','{"https://admin.ppa.gov.lb/storage/listing-pages/files/aLi6wfkFY0WcIRs3teicvNSfKprIggr4rk8J-1760210659.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/aLi6wfkFY0WcIRs3teicvNSfKprIggr4rk8J-1760210659.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=93),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "الجمهورية اللبنانية\n مجلس النواب\n قانون رقم 38تاريخ 8103/01/01\n (ج .ر .عدد 54تاريخ )8103/01/03\n قانون\n حماية كاشفي الفساد\n الفصل األول\n عامة\n أحكام ّ\n المادة االولى :مصطلحات\n يقصد بالعبارات التالية ألغراض هذا القانون ما يلي:\n متوجبة قانونًا. استغالل الموظف للسلطة أو الوظيفة أو العمل بهدف تحقيق مكاسب أو منافع غير أ -الفساد:\n الوطنية لمكافحة الفساد ،المنصوص عليها في قوانينها الخاصة\n ّ الهيئة ب -الهيئة:\n ٍ\nبمعزل عن الصفة أي شخص طبيعي او معنوي يدلي للهيئة بمعلومات يعتقد بأنها تتعلق بالفساد ج -الكاشف:\n والمصلحة وفق أحكام هذا القانون.\nالمدون في متنه من قبل الكاشف (مثال :كشف ،اخبار، ٍ\n أي كتاب او مستند ،بمعزل عن وصفه أو عنوانه ّ د -الكشف:\n شكوى ،رسالة) يتضمن معلومات تتعلق بالفساد وفق أحكام هذا القانون.\nهـ -الموظف :أي شخص يشغل منصباً تشريعياً أو قضائياً أو تنفيذياً أو إدارياً أو عسكرياً أو أمنياً أو إستشارياً،\nسواء أكان معيناً أم منتخباً ،دائماً أم مؤقتاً ،مدفوع األجر أم غير مدفوع األجر ،وأي شخص يؤدي\nوظيفة عامة ،بما في ذلك أي مركز من مراكز السلطات الدستورية أو في أية وظيفة أو خدمة عامة\nيؤدى لصالح ملك عام أو منشأة عامة أو مرفق عام أو مؤسسة عامة أو مصلحة عامة\n أو عمل ّ\n اء توّّلها بصو ٍرة قانونية أم واقعية.\n لصالح منشأة عامة أو مرفق عام ،سو ً\n المهنية.\n ّ ّ -ل يعتبر قيام شخص بكشف الفساد خرقاً لموجب السرّية\n المادة :8شروط االستفادة من الحماية والحوافز\nأ -يستفيد من الحماية والحوافز المنصوص عنها في هذا القانون الشخص الذي يقوم بكشف معلومات عن عمل أو\nامتناع عن عمل ،حصل أو يحصل أو قد يحصل ،ويعتقد بأنها تتعلق أو تدل أو تساعد في إثبات الفساد ،على أن\n يقدم كشفه أمام الهيئة حص اًر وفقاً لألصول المحددة في هذا القانون.\n ّ\n 1\n\f المادة :8صالحيات الهيئة"}, {"o": 1, "l": null, "b": "أ -إضاف ًة إلى صالحياتها في اإلستقصاء والتحقيق والمالحقة المنصوص عنها في قوانينها الخاصة تعطى الهيئة\n الصالحيات اإلضافية التالية:\n .0حماية كاشفي الفساد وظيفياً وجسدياً.\n .8تقرير المكافآت والمساعدات لكاشفي الفساد.\n .8التقدم بشكوى إلى السلطة التأديبية أو القضائية المختصة بحق ِّّ\nأي شخص ألحق بالكاشف ضر اًر وظيفياً أو\n غير وظيفي واّلشخاص المعنيين بالمادة 21من هذا القانون.\nب -تجري الهيئة اإلستقصاءات والتحقيقات المناسبة في المعلومات التي يتضمنها الكشف وتتخذ الق اررات بشأن\n الحماية والمكافآت والمساعدات وفق الصالحيات واألصول المحددة في قوانينها وأنظمتها.\n الفصل الثاني\n أصول تقديم الكشف\n المادة :5أصول تقديم الكشف\nأ -على الكاشف التقدم بكشفه بواسطة ّأية وسيلة معتبرة قانوناً وأن يطلب اّلستفادة من أحكام هذا القانون عفواً أو\n بعد لفت نظره من قبل الجهة مستلمة الكشف.\nخطياً يؤكد\n ّ ب -على مستلم الكشف في الهيئة تسجيل تاريخ حصول الكشف ومكانه وتسليم الكاشف إشعا اًر\n اإلستالم.\n المادة :4المعلومات التي يجب أن يتضمنها الكشف\n يجب أن يتضمن الكشف المعلومات التالية:\n أ -اّلسم الكامل للكاشف ونشاطه المهني وعنوانه وعنوان عمله ورقم هاتفه.\n ب -طبيعة الفساد موضوع الكشف.\n المعنيين بالكشف.\n ّ ج -اسم الشخص أو األشخاص\n د -المكان والزمان اللذان حصل أو يحصل أو قد يحصل فيهما الفساد.\nيرفق بالطلب أية وسيلة أخرى من الوسائل المتاحة لتعزيز الكشف في حال توافرها (كالمستندات ،وأسماء الشهود\n وعناوينهم ،والتسجيالت الصوتية ،وسواها).\n 2\n\f وهوية الكاشف\n ّ سرّية اسم\n المادة ّ :6\nظر على الهيئة وعلى أي عضو من أعضائها أو من العاملين فيها أو أي شخص آخر اإلفصاح عن اسم\n يح ّ\nالكاشف وهويته بصفته هذه من دون موافقته المسبقة ،أو ما لم يكن هذا الكشف في إطار اإلجراءات اآليلة إلى"}, {"o": 2, "l": null, "b": "حمايته وفي حدود ما تقتضيه هذه الحماية ،ويبقى هذا الحظر قائماً حتى بعد إحالة القضية على الهيئات القضائية\nأو التأديبية المختصة .إّل أنه يعود للهيئة إدراج اسم الكاشف بصفة شاهد في قائمة الشهود المحالة على الهيئات\n المختصة في حال موافقته.\nيعاقب كل من يخالف الموجبات المحددة في هذه المادة بالعقوبة المنصوص عليها في المادة 975من قانون\n العقوبات.\n الفصل الثالث\n الحماية التي يحصل عليها كاشفو الفساد\n المادة :7تعريف \"الضرر\"\n يقصد بالضرر ألغراض هذا القانون:\nوظيفياً للكاشف ،المتخذة بسبب الكشف ومنها\n ّ أي من اإلجراءات التي تسبب ضر اًر\n أ -الضرر في اإلطار الوظيفيّ :\n على سبيل المثال:\n المقنعة.\n -2اإلجراءات التأديبية الصريحة أو ّ\n -1الصرف من الخدمة أو إنهاؤها أو وقفها مؤقتاً أو تعليق ممارستها أو تخفيض الرتبة أو الراتب أو الترهيب أو\nالتمييز أو رفض الترقية أو رفض إعطاء إفادة عمل أو إعطاء الكاشف إفادة تلحق به ضر اًر أو فرض شروط من\n شأنها تعديل شروط العمل بما يضر بمصلحته أو فسخ تعاقده أو عدم تجديد عقده أو تسريحه من الخدمة.\n -8أي عمل ،أو امتناع ،أو التهديد بأي من اإلجراءات المذكورة سابقاً ،يؤثّر سلباً على وظيفة الكاشف أو عمله،\n بما فيه كل ما يتعلق بفرص التوظيف وسالمة العمل.\nتقدمه\n ب -الضرر خارج اإلطار الوظيفي :التعرض للكاشف أو ألحد أفراد عائلته أو ألحد العاملين لديه بسبب ّ\n بالكشف ،بواسطة أي من األفعال التالية:\n -2الضغوطات أو اإلجراءات الثأرية أو التهديدات.\n التعرض لضرر جسدي أو معنوي أو التعرض لضرر مادي باألمالك أو باألموال الشخصية.\n ّ -1\n 3\n\f المادة :3أصول النظر في طلب الحماية\nبناء على طلب كاشف الفساد ،ويسري اعتبا اًر من تاريخ تقديم طلب\n أ -يتخذ قرار الحماية عفواً من قبل الهيئة ،أو ً\n الكشف.\nب -تقوم الهيئة باإلستقصاء المناسب للتحقق من وجود الرابطة السببية بين الضرر الوظيفي الحاصل والكشف،"}, {"o": 3, "l": null, "b": "حيث تنشأ أم ام الهيئة قرينة لمصلحة الكاشف بأن الضرر الوظيفي ناجم عن الكشف الذي قام به ،وينتقل عبء\n إثبات العكس على اإلدارة حيث يعمل الكاشف.\n ج -للهيئة أن تستدعي كل األشخاص ذوي العالقة وتستمع إليهم ،وعليهم المثول أمامها والتجاوب مع طلباتها.\nد -إذا كان طالب الحماية أجي اًر في القطاع الخاص ووجدت الهيئة أن طلب الحماية الوظيفية محق ،فتصدر تقري اًر\nبناء على طلب المتضرر يبين العالقة السببية بين الضرر الوظيفي وقيام الشاكي بكشف فساد ،وتقترح له تعويضاً\n ً\nعن هذا الضرر يقدر في حاّلت الصرف التعسفي ما بين أجرة إثني عشر شه اًر وأربعة وعشرين شه اًر .يستند مجلس\nالعمل التحكيمي إلى هذا التقرير في الدعوى التي يقيمها المتضرر أمامه ّلعتبار صرفه من العمل تعسفياً أو أي\n تدبير آخر متخذ بحقه تعسفياً\nهـ -إذا كان طالب الحماية موظفاً ،على الهيئة أن توجه طلبها في تصحيح الوضع واعادة األمور إلى ما كانت عليه\nباألولوية وافادة الهيئة عن\n ّ المعنية النظر بالطلب\n ّ المختصة .وعلى اإلدارة\n ّ إلى مجلس الخدمة المدنية أو إلى اإلدارة\nالنتيجة التي اقترن بها هذا الطلب خالل مهلة شهر من تاريخ وروده إليها ،وذلك بكتاب معّلل خاضع لموجب\n السرّية.\n ّ\nو -في كلتا الحالتين ،للكاشف مراجعة القضاء المختص بمهلة شهرين من تاريخ تبّلغه قرار الهيئة حول العالقة\n السببية بين الضرر الوظيفي الحاصل وقيام الشاكي بكشف فساد.\nالمعنية انتفاء الرابطة السببية مع\n ّ زّ -ل يمكن الرجوع عن قرار الحماية المتخذ إّل إذا تبين لهيئة مكافحة الفساد\nاء أو عن طريق الغش أو بإختالق مستندات أو وقائع\n تم افتر ً\n اإلبقاء على السرّية .أما إذا كان طلب الحماية قد ّ\n فيسقط مفعول هذه السرية.\n المادة :9الحماية الشخصية للكاشف\nالمختصة اتخاذ\n ّ المختصة أو القوى األمنية\n ّ بناء على طلب كل ذي مصلحة أن تطلب من النيابة العامة\n للهيئة عفواً أو ً\nتبين لها أنهم"}, {"o": 4, "l": null, "b": "ألمنية المناسبة لحماية الكاشف وأحد أفراد عائلته والعاملين لديه أو الخبراء والشهود إذا ّ\n اإلجراءات ا ّ\n شخصية من ضغوط أو أعمال ثأرّية حصلت أو يخشى حصولها.\n ّ بحاجة إلى حماية\n على النيابة العامة والقوى األمنية اّلستجابة للطلب فور استالمه بالوسائل المتاحة.\n 4\n\f الم لحّلة والمخ ّففة\n المادة :01في األعاار ح\n ّلسيما قانون العقوبات المتعلّقة باألعذار المحّلة والمخّففة:\n مع مراعاة أحكام القوانين واألنظمة المرعية اّلجراءّ ،\n أ -يستفيد الكاشف الذي يؤدي كشفه إلى تبيان حالة فساد قام بها أو شارك فيها مباشرًة أو غير مباشرٍة ،من ٍ\nعذر\nم ِّح ّل وّل تفرض عليه أية عقوبة قضائية أو مسلكية ،بعد استرداد الدولة حقوقها ،شرط أن يكون قد بادر قبل مباشرة\nالهيئة أو القضاء ،أو أي جهة إدارية بأية تدابير استقصاء أو تحقيق مسلكية أو قضائية أو أي عمل من أعمال\n المالحقة والمحاكمة.\n ب -يكتفى بالعذر المخفف عمالً بأحكام المادة 192من قانون العقوبات إذا ّ\nتم الكشف بعد بدء أي من إجراءات\n اّلستقصاء والتحقيق والمحاكمة المشار إليها أعاله ،وقبل صدور أي حكم أو قرار قضائي أو تأديبي.\n المادة :00عقوبة إلحاق الضرر بكاشفي الفساد\nأ -كل من ألحق ضر اًر في اإلطار الوظيفي بكاشف الفساد أو بأحد األشخاص المذكورين في المادة 21من هذا\nالقانون يعاقب بغرامة تتراوح ما بين عشرة ماليين ليرة لبنانية ( 2101110111ل.ل) ومئة مليون ليرة لبنانية\n( 21101110111ل.ل) ،مع مراعاة حق الموظف المتضرر بالتعويض وفق األصول وبإعادة الحال إلى ما كانت\n عليه قبل الكشف.\nالمعينة المنصوص\n ّ ب -اذا كان الضرر خارج اإلطار الوظيفي ،تطبق عليه األحكام الجزائية المتعّلقة باألفعال\n تشدد من الثلث إلى النصف بسبب ارتباطها بكشف الفساد.\n عليها في القوانين النافذة ،على أن ّ\n المادة :08عقوبة مخالفة طلبات الهيئة\n لبنانية:"}, {"o": 5, "l": null, "b": "ّ يعاقب بغرامة تتراوح بين سبعة ماليين وخمسة عشر مليون ليرة\nأ -الشخص الذي يرفض اّلستجابة لمطالب الهيئة في إطار اّلستقصاءات والتحقيقات المنصوص عنها في هذا\n القانون.\nب -رئيس الجهة المحققة الذي يرفض اّلستجابة لطلب الهيئة بالقيام بالتحقيق من دون أسباب جدية ،بالرغم من تبلغه اً\nإنذار\n بهذا الخصوص من الهيئة وانقضاء المهلة التي تحددها فيه.\n 5\n\f الفصل الرابع\n المكافآت والمساعدات\n المادة :08االعتماد الخاص بالمكافآت والمساعدات\n يفتح بموجب هذا القانون إعتماد خاص بموازنة و ازرة المالية ،وتصرف منه األموال كمكافآت ومساعدات لكاشفي\nالفساد وفق أحكام هذا القانون ،تعقد وتصفى وفق األصول .وتعتبر ق اررات الهيئة لهذه الجهة ملزمة وواجبة التنفيذ\n وتبّلغ بهذه الصيغة إلى وزير المالية.\n المادة :05المكافآت والمساعدات\n أ -للهيئة اتخاذ القرار بمنح المكافآة و/أو المساعدة لكاشف الفساد في إحدى الحالتين التاليتين:\n -2إذا أدى الكشف إلى حصول اإلدارة على مبالغ أو مكاسب مادية ،مثل تحصيل الغرامات واستعادة األموال.\n -1إذا أدى الكشف إلى تجنيب اإلدارة خسارة أو ضر اًر مادياً.\nالمحصلة أو المكاسب المادية\n ّ بّ -ل يمكن أن تتعدى قيمة المكافأة و/أو المساعدة خمسة بالمائة من قيمة المبالغ\n جنبه الكشف لإلدارة.\n التي حّققتها اإلدارة كحد أقصى أو الخسارة أو الضرر المادي الذي ّ\nبمبلغ يتناسب مع\n ٍ ج -إذا لم يكن باإلمكان تقييم مردود الكشف ،فللهيئة أن تتخذ ق ار اًر بمنح المكافأة و/أو المساعدة\n أهمية الكشف الحاصل ،شرط أّلّ يتعدى خمسين ضعف للحد األدنى لألجور.\n المادة :04مساعدة الكاشف\nوبناء على طلبه ،مساعدة\n ً أ -للهيئة أن تقرر مساعدة الكاشف المتضرر مادياً أو جسدياً نتيجة كشفه عبر منحه،\n قانونية أو مادية مناسبة مع الحالة.\nب -للدولة حق الرجوع على مسبب الضرر أو أية جهة ضامنة ّلستعادة قيمة المساعدات المسددة ،كما يبقى"}, {"o": 6, "l": null, "b": "للكاشف حق مالحقة مسبب الضرر بما له من حقوق.\n جّ -ل يستفيد من المكافآت و/أو المساعدات كاشفو الفساد المشاركون بأية وسيلة في الفساد المكشوف عنه.\n 6\n\f الفصل الخامس\n وختامية\n ّ متفرقة\n أحكام ّ\n المادة :06جرم القدح والام\nال يتعلق بفساد قام به موظف ،بحسب مفهومهما\n يب أر الظنين وفقًا ّلحكام المادة 787عقوبات ،إذا كان موضوع الذم عم ً\n المحدد في المادة األولى من هذا القانون ،وثبتت صحته.\n المادة :07بطالن األحكام التي تعيق تطبيق هاا القانون\nأّ -ل تسري جميع األحكام القانونية والتنظيمية والق اررات اإلدارية التي تتعارض مع أحكام هذا القانون أو ّل تأتلف\n معه.\nب -كما يعتبر باطالً كل بند يدرج في عقد العمل أو التوظيف أو في أي اتفاق آخر من أي نوٍع كان يتعارض مع\n أحكام هذا القانون أو يكون من شأنه إعاقة تطبيقه.\n المادة :03دقائق تطبيق القانون\nبناء على اقتراح وزير العدل. ن\n تحدد ،عند اّلقتضاء ،دقائق تطبيق أحكام هذا القانو بمراسيم تتخذ في مجلس الوزراء ً\n ّ\n المادة :09بدء العمل بهاا القانون\n يعمل بأحكام هذا القانون فور نشره في الجريدة الرسمية.\n 7\n\f األسباب الموجبة\n القتراح قانون حماية كاشفي الفساد\nلما كان لبنان يعاني من مشكلة فساد تنخر كل مؤسساته وتشكل عائقاً أمام تقدم البلد ونهوضه بشكل سليم\nإذ إن الفساد يتسبب بالفقر وينتهك حقوق اإلنسان ويقوض الديمقراطية ويشكل عائقاً أمام النمو اّلقتصادي ويتسبب\n بالضرر البيئي وبالصحة العامة ،كما أنه إحدى أدوات الجريمة المنظمة.\nولما كان الفساد آفة ،أصعب ما فيه ،أنه بذاته يشكل العائق أمام محاربته ،ويصبح في بعض األحيان\nالطريقة الوحيدة للحصول على الخدمات المتوجبة لكل مواطن ،فيبدو وكأنه أمر طبيعي ّل يستفز الناس ،على الرغم\n من وجود قوانين تلزم الشخص الذي يعرف بحصول أعمال فساد باإلبالغ عنها."}, {"o": 7, "l": null, "b": "ولما كان لبنان قد صادق على اتفاقية األمم المتحدة لمكافحة الفساد بموجب القانون رقم 77تاريخ\n ،1118/21/21\nولما كانت المادة 77من اّلتفاقية المذكورة نصت على وجوب «حماية المبلغين» ،أي كاشفي الفساد ،وقد\n جاء فيها ما يلي:\n«تنظر كل دولة طرف في أن تدخل في صلب نظامها القانوني الداخلي تدابير مناسبة لتوفير الحماية من أي معاملة ال\nجرمة وفقاً\n مسوغ لها ألي شخص يقوم ،بحسن نية وألسباب وجيهة ،بإبالغ السلطات المختصة بأي وقائع تتعلق بأفعال حم ّ\n لهاه االتفاقية».\nولما كانت الدولة اللبنانية ملزمة بإدخال المبادئ والقواعد التي تنص عليها المعاهدة المذكورة بشكل عملي\nوسن قوانين تج ّسد التزاماتها وتعهداتها الدوليةّ ،ل سيما لجهة محاربة الفساد وانزال العقاب\n في التشريع اللبناني ّ\n بمرتكبي أعمال الفساد.\nولما كان عليها اتخاذ عدد من التدابير الداخلية ،تبدأ بالتثقيف حول ضرر الفساد ،جاعلة من محاربة الفساد\nإحدى أسمى المعارك الوطنية ،ومن موضوع عدم اإلفالت من العقاب صلب أولوياتها لقيام دولة حكم الحق والقانون\n والشفافية وتصبح واجباً وطنياً بالنسبة إلى كل فرد.\nولما كان على الدولة أيضاً اتخاذ جميع التدابير الوقائية من الفساد للحؤول دون حصوله ،كوضع أنظمة\nسلوكيات لكل مؤسسات القطاع العام ،وتشجيع مؤسسات القطاع الخاص على أن تتبنى بدورها أنظمة أخالقيات\n خاصة بكل واحدة منها يحاسب مخالفوها ويلقون العقاب التأديبي.\n 8\n\f واذا كان على الدولة مكافحة الفساد والقبض على مرتكبي الفساد ومحاكمتهم.\nواذا كان كشف الفساد واجباً في القطاعين العام والخاص ،إّل أن مكافحته تستوجب إثبات حصوله أوّلً،\nمكن من إلقاء القبض على الفاسدين ومحاكمتهم ثانياً ،لكن الموضوع فيه من الخطورة ما\n والحصول على أدّلة ت ّ\nيجعل المواطنين يحجمون عن اّلقدام عليه ،فيجب تشجيع الناس على التحرك واإلدّلء بمعلوماتهم حول الفساد ،كما"}, {"o": 8, "l": null, "b": "ثبتت ضرورة تأمين الحماية الالزمة لكاشفي الفساد إضاف ًة إلى تحفيزهم على القيام بالكشف.\n من أجل كل ذلك،\n عد اقتراح قانون حماية كاشفي الفساد وبني بشكله الحالي وفقاً لالعتبارات التالية:\n أ ّ\n الهدف من القانون\n يهدف هذا القانون إلى:\nتم وضع آلية للتعويض عن الضرر الذي أصاب كاشف الفساد وبرنامج مكافآت في\n أوالً -التشجيعّ :\n استرجاع المال العام المهدور ،كما أعطى للكاشف مكافآت في حاّلت معينة.\n ثانياً -الحماية :على مستويين:\n )2حماية كاشف الفساد من الضرر الوظيفي أو غير الوظيفي الذي قد يصيبه من جراء قيامه بكشف\n الفساد ،ولذلك يتضمن القانون آلية للحماية ورفع الضرر والتعويض.\n )1حماية المعلومات المتعلقة بكاشف الفساد التي تعتبر سرية ،ولهذا السبب حصرت بالهيئة ،خالفاً\n للمعلومات التي تؤول إلى اإلعالم ،إضاف ًة إلى حماية المعلومات المصنفة سرية.\nثالثاً -فاعلية المالحقة :بحيث تعطى للهيئة صالحيات واسعة شبيهة بصالحيات النيابة العامة .وعليه ،تم\nإعطاء صالحية اّلستقصاء هذه إلى الهيئة الوطنية لمكافحة الفساد عوضاً عن إنشاء هيئة جديدة .فال يكفي\nحث الناس على القيام بكشف الفساد ،إنما ما يحدث بعد الكشف من مالحقات جدية هو الذي يعطي\n ّ\n المصداقية للتشريع ويشجع المواطنين فعلياً على القيام بالكشف والتعرض للمخاطر والمشاكل المختلفة.\n 9\n\f المبادئ األساسية التي حبني عليها هاا القانون\n في أصول الكشف المحمي أمام الهيئة الوطنية لمكافحة الفساد: أوالً-\n -2يعطي القانون صالحية استالم الكشوفات المحمية للهيئة الوطنية لمكافحة الفساد منعاً إلساءة استعمال\nالحق وللتحقق من جدية المعلومات المكشوف عنها قبل المباشرة بتحريك الحق العام ،إذ قد يتقدم أحدهم\nبكشف معلومات عن سوء نية ،أو قد يتبين بأن المعلومات عارية من الصحة .فتقوم الهيئة الوطنية لمكافحة\n الفساد بدور المصفاة."}, {"o": 9, "l": null, "b": "-1حدد القانون أصوّلً دقيقة للقيام بالكشف وللحصول على الحماية إذ يجب من جهة تشجيع المواطن على\nإبالغ الهيئة الوطنية لمكافحة الفساد عن أعمال فساد ،ومن جهة أخرى الحؤول دون أن يؤدي الكشف القائم\nعلى أساس غير وجيه أو الذي يكون مبنياً على سوء النية ،إلى أي عواقب سلبية خاصة لجهة فضح\nالمجرمين .لذلك ،حدد مشروع القانون هذا الشرط المفروض للحصول على الحماية التي يؤمنها ،وهو القيام\nبالكشف أمام الهيئة الوطنية لمكافحة الفساد حصرياً .ويبقى بإمكان كاشف الفساد أن يدلي بمعلوماته إلى\nأي جهة أخرى كالقضاء أو حتى اإلعالم ،لكنه لن يحصل على الحماية التي يؤمنها هذا القانون ،بل\n تؤمنها القوانين العادية األخرى فقط.\n يحصل على الضمانات العادية التي ّ\n ثانياً :بالنسبة إلى أعمال االستقصاء وأصولها ،يركز القانون على ما يلي:\n -2تأمين السرية التامة لجهة هوية الكشف ،والمعلومات المكشوف عنها ،والمستندات التي تصبح بحوزة\nالهيئة ،والنص على عقوبات شديدة في حال مخالفة هذه الموجبات ،وذلك تماشياً مع المبادئ التي ذكرناها\n آنفاً ،وحفاظاً على أمن الدولة واّلستقرار في البلد.\n -1تأمين الجدية في التعاطي مع الكشوفات للحؤول دون إساءة استعمال هذا الحق ،تقوم الهيئة باستقصاءات\n أولية للتأكيد من أسس التحرك الجدية .وللهيئة أن تحفظ الكشف إذا لم تتحقق جديته.\n ثالثاً :بالنسبة إلى اإلحالة على القضاء المختص:\nبعدما تتأكد الهيئة من جدية المعلومات ،بإمكانها إحالة الملف إما إلى النيابة العامة أو إلى هيئات تفتيش\nأخرى ،ويمكنها اللجوء إلى اّلدعاء المباشر إذا كانت المعلومات كافية وموثقة وثابتة .فليس دور الهيئة أن تحل\n محل القضاء بل تفعيله والعمل على حسن سير التحقيقات.\n 10\n\f رابعاً -في تنظيم الحماية التي يحصل عليها كاشفو الفساد:\nالحماية الفعالة هي ركن أساسي في هذا القانون .بدونها لن يتشجع المواطنون على القيام بكشف الفساد .لذلك"}, {"o": 10, "l": null, "b": "ارتأى واضعو القانون وجوب تأمين الحماية الضرورية لكاشف الفساد لجهة ما قد يتعرض له من ضرر وظيفي\n أو مادي أو جسدي أو معنوي ،وتأمين الحماية نفسها ألفراد عائلته أو أقربائه أو معاونيه أو العاملين لديه.\n خامساً -بالنسبة إلى التعويضات والمكافآت:\nعرض الكاشف إلى كثير من المتاعب أو المشاكل أو األخطار التي قد\n إن كشف معلومات متعلقة بالفساد قد ي ّ\nتهدد حياته وحياة أفراد عائلته أو أقربائه أو معاونيه أو حتى العاملين لديه .من هنا كانت ضرورة تأمين آلية\nللتعويض عن الضرر الذي قد يصيب الكاشف من جراء قيامه بكشف فساد .هذا الضرر يمكن أن يكون ضر اًر\n وظيفياً أو مادياً أو جسدياً أو معنوياً .وّل يمكن التعويض عن الضرر الحاصل من دون عالقة سببية مباشرة مع\n عملية الكشف.\nلكن من جهة أخرى ،ونظ اًر إلى خطورة المواقف وشجاعة بعض الكاشفين الذين قد يقومون بأعمال شجاعة،\nفتكرم كاشفي الفساد تكريماً علنياً يحّفز اآلخرين\n يمكن الحصول على مكافآت إذا ارتأت الهيئة بأنها مستحقةّ .\nعلى القيام بمثل هذه الخطوات الجريئة .ولقد أثبتت التجربة العالمية أهمية هذا العامل .وللحؤول دون أن يصبح\nعامل الحصول على المكافأة هو الدافع األساسي للقيام بالكشفّ ،ل يحصل الكاشف على المكافآت حكماً ،بل\nستقدر ما إذا كان الكاشف يستحق المكافأة ،فضالً عن أن مقدار المكافأة لن يتعدى مبلغاً معيناً .فلن\n هناك لجنة ّ\n تكون المكافأة رمزية ،لكنها لن تكون باهظة هي عرفان بالعمل الشجاع الذي يكون الكاشف قد قام به.\n سادس ًا -في العقوبات التي يلحظها هاا القانون:\nحددت العقوبات التي بدونها يظل هذا القانون هذا القانون حب اًر على ورق ،وارتكزت الخيارات في تحديد\n العقوبات واألعمال التي تؤدي إليها على المبادئ التالية:\n -0فعالية العقوبات :نظ اًر إلى أهمية موضوع مكافحة ومحاربة الفساد ،أرادت مجموعة العمل أن تكون\n العقوبات فعالة لذلك جاءت المبالغ مرتفعة نسبياً."}, {"o": 11, "l": null, "b": "-8الموجبات المعاقب على خرقها هي التالية:\n )2موجبات تتعلق بالكاشف وبالمحافظة عليه:\n 11\n\f إن أهم موجب في عمل الهيئة هو موجب السرية الذي بدونه لن يتشجع المواطنون ويساهمون في\n مكافحة الفساد .لذلك لحظت عقوبات على تسريب معلومات ذات طابع خاص عن الكاشف.\n إن اطمئنان الكاشف عنصر هام .فلحظ القانون عقوبات لمن ي ِّ\nلحق الضرر من أي نوع كان\n بكاشف الفساد.\nتم تسريب\n )1حرصاً على أمن الدولة وحفاظاً على المعلومات المصنفة سرية ،شددت العقوبات في حال ّ\n معلومات مصنفة سرية.\n )7لحظ عقوبة في حال مخالفة طلبات الهيئة الوطنية لمكافحة الفساد ،ضماناً ّلحترام وتنفيذ طلبات الهيئة\n والحؤول دون إمكانية تعطيل عملها من أي جهة كانت.\n بناء عليه ،نتقدم من المجلس النيابي الكريم باقتراح القانون هذا راجين إق ارره.\n 12"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (94,'قوانين','قانون مكافحة الفساد في القطاع العام وانشاء الهيئة الوطنية لمكافحة الفساد - رقم 175 8 أيار 2020','2020-05-08','https://www.ppa.gov.lb/ar/pages/details/94','{"https://admin.ppa.gov.lb/storage/listing-pages/files/IwVEn2TPg7Iqb8d92e87jr4WakdiA66GxjKE-1760210717.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/IwVEn2TPg7Iqb8d92e87jr4WakdiA66GxjKE-1760210717.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=94),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "الجمهورية اللبنانية\n مجلس النواب\n قانون رقم 175تاريخ 2020/5/8\n (ج .ر .رقم 20تاريخ )2020/5/14\n قانون\n مكافحة الفساد في القطاع العام\n وانشاء الهيئة الوطنية لمكافحة الفساد\n مادة وحيدة:\nالمعاد إلى مجلس النواب بموجب بالمرسوم رقم 5272تاريخ 25تموز صدق القانون\n ّ -\n ُ\n 2019والمتعلق بمكافحة الفساد في القطاع العام وإنشاء الهيئة الوطنية لمكافحة الفساد ،كما\n عدلته اللجان النيابية المشتركة ومجلس النواب.\n ّ\n ُ -يعمل بهذا القانون فور نشره في الجريدة الرسمية.\n 1\n\f الجمهورية اللبنانية\n مجلس النواب\n قانون\n مكافحة الفساد في القطاع العام\n وانشاء الهيئة الوطنية لمكافحة الفساد\n الباب األول :تعريفات\n المادة االولى :تعريفات\n تعتمد ،من أجل تطبيق أحكام هذا القانون ،التعاريف والمصطلحات التالية:\nأ -الفساد :استغالل السلطة أو الوظيفة أو العمل المتصل بالمال العام بهدف تحقيق مكاسب أو\n منافع غير مشروعة لنفسه أو لغيره ،سواء بصورة مباشرة أو غير مباشرة.\nوتعتبر من أفعال الفساد الجرائم الواقعة على اإلدارة العامة والمنصوص عليها في الفصل األول من\nالباب الثالث من الكتاب الثاني من قانون العقوبات ما خال النبذة الرابعة منه ،واإلثراء غير المشروع،\nوأفعال الفساد التي ترد في االتفاقيات والمعاهدات الدولية التي انضم وسينضم إليها لبنان والتي تعنى\n بمكافحة الفساد.\nالمدون في متنه من قبل الكاشف، ٍ\n ب -الكشف :أي كتاب او مستند ،بمعزل عن وصفه أو عنوانه ّ\n كالكشف أو االخبار أو الشكوى أو الرسالة المتضمن أي منها معلومات تتعلق بالفساد.\n الهيئة :الهيئة الوطنية لمكافحة الفساد ج-\n الباب الثاني :مكافحة الفساد\n الفصل االول :جرائم الفساد\n المادة :2\nاللبنانية تتعّلق بفعل فساد وفق تعريف\n ّ تعتبر جريمة فساد كل جريمة منصوص عليها في القوانين\n المادة األولى من هذا القانون.\n 2\n\f المادة :3\n أ -تعتبر أيضًا جرائم فساد األفعال التالية:"}, {"o": 1, "l": null, "b": "-1نيل االلت ازمات أو سوء تنفيذها أو االستحصال على الرخص من احد أشخاص الحق العام\n جلبًا للمنفعة الخاصة إذا حصل أي منها خالفًا للقانون.\n -2استخدام االموال العامة ،ووسائل الدولة وسائر اشخاص الحق العام ،خالفًا للقانون جلبًا لمنفعة\n خاصة.\n -3شراء او بيع شخص ما ألموال منقولة او غير منقولة اذا حصل بناء على معلومات غير متاحة\nللعموم وسابقة للشراء او البيع بأن قيمتها سترتفع او تنخفض بسبب قوانين أو انظمة قيد االصدار ا و\nمشاريع ُم َخطط القيام بها ،حصل عليها هذا الشخص بحكم وظيفته او سلطته او صلة قرابته او\n شراكته او عمله او خدمته وأ ّدت الى كسب محقق.\nب -ال يشترط أ ن تحصل المنفعة الخاصة التي تتأتى عن جرائم الفساد المحددة في الفقرات 1 :و2\nو 3من البند (أ) من هذه المادة ،مباشرة أو فو ًار ،بل يمكن ان تنشأ عن االستفادة من المشاريع\n المنوي تنفيذها وان لم تنفذ.\nيعاقب كل من يرتكب أيا من األفعال المنصوص عليها في هذه المادة بالحبس من ثالثة ج-\nاشهر حتى ثالث سنوات وبغرامة تتراوح بين ضعفي وثالثة اضعاف قيمة المنفعة المادية المتوقعة أو\n المحققة.\n الفصل الثاني :أصول خاصة لالستقصاء والتحقيق والمحاكمات في جرائم الفساد\n المادة :4\n تخضع جرائم الفساد لألصول الخاصة التالية:\nأ– خالفًا ألي نص قانوني آخر ،يمكن إجراء االستقصاءات والتحقيقات والمالحقات الجزائية في\nجرائم الفساد من دون حاجة لالستحصال على أي من األذونات أو التراخيص المسبقة الملحوظة في\n بناء على طلب من الهيئة الوطنية لمكافحة الفساد. ن\n القانو متى تمت هذه المالحقة ً\n ب -ال تحول المالحقة الجزائية دون المالحقة التأديبية.\nج -ال تسقط المالحقة الج ازئية في جرائم الفساد في حالة االستقالة او الصرف من الخدمة او\nاالحالة على التقاعد او انتهاء الخدمة او الوضع بالتصرف او ما شابهها من اوضاع وظيفية ،او\n انتهاء مدة تولي الخدمة العامة.\n 3"}, {"o": 2, "l": null, "b": "د -يجوز الحكم بااللتزامات ذات الطابع المالي على كل من آ لت إليه األموال باإلرث أو باإليصاء\n أو بالهبة ،ضمن حدود هذه األموال.\nه -يجوز الحكم باإللزامات ذات الطابع المالي على ا لخلفاء الخاصين من غير المعددين في الفقرة\n(د) من هذه المادة ،في حال ثبوت أنهم كانوا عالمين أو من واجبهم أن يعلموا بأن األموال التي آل ت\n إليهم متأتية عن أفعال فساد.\nو -يجوز الحكم باإللزامات ذات الطابع المالي على مديري ورؤساء وأعضاء مجلس اإلدارة\nوالشركاء وأعضاء الشخص المعنوي ،الذين آلت إليهم األموال المتأتية عن الفساد ،بصورة مباشرة أو\nغير مباشرة ،بعد حل الشخص المعنوي ،في حال ثبوت أنهم كانوا على علم أو من واجبهم أن\n يعلموا بأن األموال التي آلت إليهم متأتية عن أفعال فساد.\n الباب الثالث :إنشاء وتنظيم الهيئة الوطنية لمكافحة الفساد\n المادة :5إنشاء الهيئة\nتسمى \"الهيئة الوطنية لمكافحة الفساد\" ،تتمتع بالشخصية المعنوية\n أ -تنشأ هيئة إدارية مستقلة ّ\n وباالستقالل المالي واالداري يشار اليها في هذا القانون بـ \"الهيئة\".\nب -يؤدي أعضاء الهيئة والموظفون وسائر العاملين لديها مهامهم باستقالل كامل عن أية سلطة\n اخرى في اطار أحكام هذا القانون.\n المادة :6تشكيل الهيئة\nويعينون بمرسوم يتخذ في مجلس\n تشكل الهيئة من ستة أعضاء بمن فيهم الرئيس ونائب الرئيس ّ\n أّ -\n الوزراء ،لمدة ست سنوات غير قابلة للتجديد.\nب -يتم اختيار األعضاء من بين األشخاص ذوي السيرة األخالقية العالية المشهود لهم بالنزاهة،\nبناء على سيرة ذاتية موثّقة ،على أن تتوفر في المرشح الشروط\n العلمية والخبرةً ،\n ّ وذوي الكفاءة\n الواجبة لتعيين موظفي الفئة األولى وعلى أن تتوفر الشروط اإلضافية التالية:\n -1أال يقل عمر المرشح عن األربعين عامًا وأال يتجاوز الرابعة والسبعين عامًا لدى التعيين.\n 4\n\f -2أن ال يكون ،عند التعيين وخالل الخمس السنوات السابقة ،متوليًا أي منصب سياسي أو حزبي،"}, {"o": 3, "l": null, "b": "وأال يكون حاليًا وخالل الفترة المذكورة عضوًا في أي جمعية تمارس العمل السياسي أو عضوًا في\n أحد األحزاب.\n -3أن ال يكون في أية حالة من حاالت التمانع المنصوص عليها في"}, {"o": 4, "l": "المادة 7", "b": "المادة 7أدناه أو مرشحًا لها.\n ج -تشكل الهيئة على النحو التالي:\n -1قاضيان متقا عدان بمنصب الشرف ،يتم انتخابهما وفق األصول التي ترعى انتخاب أعضاء\nمجلس القضاء األعلى ،على أن تتألف الهيئة الناخبة من مجمل القضاة األصيلين في القضاء\nالعدلي واإلداري والمالي ،وعلى أن تتم الدعوة واإلشراف على االنتخابات من قبل القاضي األعلى\n درجة من بين رئيس مجلس القضاء األعلى ورئيس مجلس شورى الدولة ورئيس ديوان المحاسبة.\n يرفع وزير العدل اسمي القاضيين المنتخبين إلى مقام مجلس الوزراء.\n -2محا ٍم أو حقوقي من بين أربعة أسماء يرشح اثنين منهم مجلس نقابة المحامين في بيروت واثنين\n مجلس نقابة المحامين في طرابلس.\n -3خبير محاسبة ،من بين ثالثة أسماء يرشحها مجلس نقابة خبراء المحاسبة المجازين في لبنان.\nترشحهم هيئة الرقابة على\n -4خبير في األمور المصرفية أو االقتصادية ،من بين ثالثة أسماء ّ\n المصارف.\n -5خبير في شؤون االدارة العامة أو المالية العامة أو مكافحة الفساد من بين ثالثة اسماء يرشحهم\n وزير الدولة لشؤون التنمية اإلدارية.\nد -يشترط في االعضاء الخبراء المنصوص عليهم أعاله حيازة شهادات عليا (ماجيستر وما فوق)\n في اختصاصهم باإلضافة الى خبرة ال تقل عن عشر سنوات.\nعلى الهيئات المذكورة اعاله ان تقوم باالقتراح أو االنتخاب للمرة االولى في مهلة ثالثة ه-\n اشهر من تاريخ نشر هذا القانون في الجريدة الرسمية.\nكما يجب أن تتم هذه العملية في المرات الالحقة قبل انتهاء والية أعضاء الهيئة بشهرين على األقل.\nو -يجب أن تكتمل عملية التعيين ،في المرة االولى ،خالل مهلة أقصاها شهر واحد تلي المهلة\nالثالثة اشهر المنصوص عليها في هذه المادة .كما يجب ان تتم هذه العملية في المرات الالحقة\n قبل انتهاء والية اعضاء الهيئة بشهر على األقل.\n 5\n\fز – يكون القاضي االعلى درجة ،عند التقاعد ،الرئيس الحكمي للهيئة ،وإذا تساوت درجات"}, {"o": 5, "l": "المادة 7", "b": "القاضيين المنتخبين يكون القاضي االكبر سنًا رئيسًا.\nظم أعضاء الهيئة التصاريح المنصوص عليها في قانون اإلثراء غير المشروع خالل مهلة\n ح – ين ّ\nأسبوعين من تاريخ أدائهم اليمين ،ويرفعون السرية المصرفية عن حساباتهم وحسابات زوجاتهم\n واوالدهم القاصرين ،وتنشر الهيئة هذه التصاريح فو اًر على الموقع االلكتروني للهيئة.\nط -يمارس االعضاء مهامهم بصفتهم الشخصية وباستقالل تام وال يتقيدون بتوجيهات من أي\n مرجع بما فيه الجهة التي سمتهم او انتخبتهم.\n التفرغ\n المادة :7حاالت التمانع و ّ\nظر على اعضاء الهيئة ممارسة أي عمل آخر عام أو خاص ،مأجور أو غير مأجور ،خالل\n أ -يح ّ\nتوّليهم مهامهم ،بما فيه ،على سبيل المثال ،رئاسة أو عضوية الو ازرة أو مجلس النواب ،ورئاسة أو\nعضوية مجلس إدارة مؤسسة عامة او شركة خاصة او مصرف ،ورئاسة أو عضوية هيئة عامة،\n ّ\nورئاسة أو عضوية مجلس بلدي أو شركة خاصة تتوّلى إدارة مرفق عام و رئاسة أو عضوية مجالس\n النقابات أو الهيئات المرشحة لألعضاء.\nب -ال يجوز لعضو الهيئة أن يكون له ّأية مصلحة مباشرة أو غير مباشرة في أي مؤسسة خاضعة\n لرقابة الهيئة.\nيترشح\n عضويته ،أن ّ\n ّ ج -ال يجوز لعض و الهيئة ،قبل انقضاء ست سنوات كاملة على انتهاء\nالبلدية او االختيارية أو أن يتولى أي منصب عام سياسي أو إداري أو أمني\n ّ النيابية او\n ّ لالنتخابات\n أو نقابي.\n ظفون العامون بحكم المستقيلين بم ّ\nجرد قبولهم التعيين د -يعتبر أساتذة التعليم العالي األصيلون والمو ّ\n في الهيئة.\n المادة :8قسم اليمين\n يقسم أعضاء الهيئة أمام رئيس الجمهورية اليمين التالية:\n\" أقسم باهلل العظيم أن أقوم بمهامي في الهيئة الوطنية لمكافحة الفساد بأمانة وإخالص واستقالل ،وأن\n طد حكم القانون\".يعزز الثقة بالهيئة ويو ّ أتصرف في كل ما أقوم به بنز ٍ\n اهة بما ّ\n 6\n\f المادة :9النظام الداخلي"}, {"o": 6, "l": "المادة 7", "b": "تضع الهيئة نظاماً داخليًا يتضمن القواعد واألصول التفصيلية التي ترعى تنظيمها وسير أ-\nالعمل لديها وإدارتها المالية بما فيها صالحيات كل من الرئيس ونائب الرئيس وغيرها من الوظائف\nفي مهلة ثالثة أشهر من تاريخ صدور مرسوم تعيين أعضاء الهيئة بموجب قرار تنظيمي يصدر عن\n الهيئة بغالبية ثلثي األعضاء الذين يحق لهم التصويت وبعد موافقة مجلس شورى الدولة.\n ب -للهيئة تعديل النظام الداخلي وفق األصول عينها.\n تطبق في أعمالها.\n ج -تضع الهيئة وفقًا لألصول المحددة أعاله مدونة سلوك إلزامية ّ\n د – للهيئة ان تنشئ لجانا ألداء مهمات دائمة او مؤقتة وفق ما يحدده النظام الداخلي.\n المادة :10الشغور\n أ -يستمر أعضاء الهيئة في ممارسة مهامهم بالرغم من انقضاء الوالية ألي ٍ\nسبب كان إلى حين\n تعيين بدالء عنهم وأدائهم اليمين القانونية.\nب -إذا شغر مركز في الهيئة بالوفاة أو االستقالة أو انعدام األهلية أو ألي سبب آخر قبل انتهاء\nتتثبت الهيئة من حصول الشغور وتُبّلغ األمر خالل أسبوع إلى مجلس\n واليتها بستة أشهر على االقلّ ،\nالوزراء ألخذ العلم واتخاذ اإلجراءات الالزمة الختيار البديل للمدة المتب ّقية من الوالية الشاغرة ،على أن\nيجري االختيار خالل 15يوماً من تاريخ أخذ العلم وفق االصول المنصوص عليها في"}, {"o": 7, "l": "المادة 6", "b": "المادة 6من\n هذا القانون.\n المادة :11حصانة األعضاء\nفي ما خال الجرائم المشهودة ،ال يجوز مالحقة أي عضو من أعضاء الهيئة ،بدعوى جزائية أ-\nأو اتخاذ أي إجراء جزائي بحقهم أو القبض عليهم أو توقيفهم طوال مدة واليتهم إال بعد الحصول\nعلى إذن من الهيئة بأكثرية ثلثي األعضاء الذين يحق لهم التصويت على األقل باستثناء العضو\n ّ\n المعني الذي يستمع إليه وال يشارك في جلسة التصويت.\nب -في ما خال الجرائم المشهودة ،ال يجوز مالحقة أي من العاملين لدى الهيئة أو المنتدبين من\nقبلها ،بدعوى جزائية أو اتخ اذ أي إجراء جزائي بحقهم أو القبض عليهم طوال مدة عملهم في الهيئة،\nألفعال تتعلق بهذا العمل إال بعد الحصول على إذن من الهيئة بأكثرية ثلثي األعضاء الذين يحق\n ّ\n 7\n\fصالحية الهيئة في هذه الحالة بتحديد ما إذا كان الفعل المطلوب\n ّ لهم التصويت على األقل .تنحصر\nإجراء المالحقة بشأنه متعّلقاً بالعمل لديها ،وال يجوز لها رفض إعطاء اإلذن ،إال متى رأت أن الفعل\n مرتبط بالعمل لديها والمالحقة بشأنه كيدية وغير مسندة إلى أي سبب جدي.\nج -ال يجوز تفتيش مكاتب الهيئة أو اتخاذ أي إجراء قضائي أو إداري بشأنها إال بعد موافقة\nيوجه المرجع القضائي المعني كتابًا سريًا إلى رئيس الهيئة بهدف إعطاء\n رئيسها .ولهذا الغرض ّ\nيبت بالطلب خالل خمسة أيام من تاريخ وروده .في حال انقضاء المهلة دون\n اإلذن .على الرئيس أن ّ\n البت في الطلب صراح ًةُ ،يعتبر أنه أعطى اإلذن.\nفي الجرائم المشهودة ،يتم تفتيش مكاتب الهيئة بأمر من النائب العام لدى محكمة التمييز أو بق ارر\n من قاضي التحقيق األول ،على أن يتم ذلك بحضور رئيس الهيئة أو من ينتدبه لهذه الغاية.\nد -تكون ق اررات رئيس الهيئة بشأن تفتيش المكاتب أو أي إجراء قضائي آخر قابلة للطعن أمام\n الهيئة العامة لمحكمة التمييز خالل مهلة 15يوم من تاريخ تبليغها للمرجع الذي طلب المالحقة.\n المادة :12عدم جواز إقالة األعضاء"}, {"o": 8, "l": "المادة 6", "b": "أ -ال يجوز إقالة عضو أو أكثر من اعضاء الهيئة إال بقرار من مجلس الوزراء بعد موافقة ثلثي\nأعضاء الهيئة الذين يجوز لهم التصويت دون الشخص المعني ،وذلك اما بناء لطلب مجلس الوز ارء\nأو بنا ًء لطلب نصف أعضاء الهيئة وبعد استماع الهيئة الى العضو المشكو منه ،وذلك فقط في\n الحاالت التالية:\n التفرغ .\n -1إذا فقد األهلية ،أو أي شرط من شروط التعيين أو التمانع أو ّ\n -2إذا حال وضعه الصحي أو العقلي دون قيامه بمهامه.\n -3إذا ارتكب خطأ جسيمًا في تأدية مهامه.\nب -تتم اإلقالة حكمًا عند صدور حكم مبرم على العضو بجناية أو جنحة شائنة .كما يعود للهيئة\nأن تقرر بأكثرية ثلثي أعضائها الذين يجوز لهم التصويت ،دون الشخصي المعني ،أن تعلق عضويته\n فور صدور قرار ظني أو أي حكم بحقه بالجرائم المذكورة آنفاً.\nج -يبّلغ مجلس الوزراء بالقرار لتعيين عضو بديل من العضو المقال او المستقيل وفق األصول\n وضمن المهل المحددة في هذا القانون.\nد -ال يجوز لمج لس الوزراء اتخاذ القرار بتعليق عمل الهيئة أو بوقفه او بحلها في اي ظرف من\n الظروف ،بما في ذلك حاالت الطوارئ والحروب.\n 8\n\f المادة :13اجتماعات الهيئة\nبناء على دعوة من رئيسها أو ثلث\n أ -تجتمع الهيئة مرة كل اسبوع على األقل وكلما دعت الحاجة ً\n اعضائها.\n ب -يكون االجتماع قانونيًا بحضور األكثرّية المطلقة من األعضاء الذين يحق لهم التصويت\n ج -تتخذ ق اررات الهيئة باألكثرية المطلقة من عدد األعضاء الذين يحق لهم التصويت.\n أي من اجتماعات الهيئة إال ٍ\nبعذر مشروٍع وألسباب قاهرة، التغيب عن ٍّ\n د -ال يحق ألي عضو ّ\nيتغيب عن ثالثة اجتماعات غير مبررة خالل ثالثة أشهر مستقيالً حكمًا\n ويعتبر العضو الذي ّ\n ويصار إلى تعيين بديل عنه وفق األصول.\nه -تعتبر الهيئة مستقيلة حكماً عندما تمتنع عن عقد اجتماعاتها األسبوعية لثالث مرات متتالية إال\n ألسباب قاهرة.\n المادة :14الجهاز االداري\n أ -يعاون الهيئة جهاز اداري ّ"}, {"o": 9, "l": "المادة 6", "b": "متفرغ على رأسه أمين عام ،يتم تعيينه من قبل الهيئة بعد مباراة\n يجريها مجلس الخدمة المدنية.\nب -تحدد أصول تعيين األمين العام ومهامه وأصول تنظيم وتعيين الجهاز اإلداري ومهامه في\n النظام الداخلي.\n ج -للهيئة أن تستعين بمن تشاء من الخبراء من خارج الهيئة وموظفيها.\n د -يخضع األمين العام وأعضاء الجهاز اإلداري إلى نظام الموظفين.\n المادة :15التمويل\nيكون للهيئة موازنة سنوية خاصة تدرج في باب خاص ضمن الموازنة العامة وتكون كافية أ-\nلتغطية مصاريف الهيئة ونشاطاتها .تعد الهيئة مشروع الموازنة ويرفعه رئيسها إلى وزير المال الذي\nيضمه الى مشروع الموازنة العامة المرفوعة الى مجلس الوزراء الذي يتولى احالتها الى الجهات\n المختصة حسب األصول.\nيفتح للهيئة حساب خاص ل دى مصرف لبنان ،ويتولى رئيس الهيئة عقد نفقاتها ومراقبة ب-\nعقدها وفقاً لألصول المنصوص عليها في قانون المحاسبة العمومية .وفي نهاية السنة المالية ،يرسل\n 9\n\fرئيس الهيئة جداول باالعتمادات المصروفة إلى و ازرة المالية مصدقة منه ،وتطبق في شأن هذه\n الجداول أحكام النظام المالي الخاص بالهيئة.\nتخضع حسابات الهيئة لنظام التدقيق الداخلي وللتدقيق المستقل من قبل مكاتب التدقيق ج-\nوالمحاسبة وفقا ألحكام"}, {"o": 10, "l": "المادة 73", "b": "المادة 73من القانون رقم 326تاريخ ( 2001/6/28قانون موازنة العام\n ، (2001وتنشر الحسابات وتقارير التدقيق العائدة لها في الجريدة الرسمية وعلى الموقع الرسمي\n االلكتروني للهيئة.\nالتشغيلية األولى بعد دخول هذا القانون\n ّ يفتح اعتماد إضافي في الموازنة العامة للهيئة للسنة د-\n لبنانية.\n ّ حيز النفاذ ،قيمته عشرة مليارات ليرة\n المادة :16مخصصات األعضاء\nيتقاضى رئيس وأعضاء الهيئة تعويضًا شهريًا مقطوعًا موازيا لراتب رئيس وأعضاء المجلس\n الدستوري.\n المادة :17حق تلقي المستندات والمعلومات\nأجنبية تزويدها بالمستندات أو المعلومات التي تراها مفيدة\n ّ لبنانية أو\n ّ للهيئة أن تطلب من أية جهة\nالمعنية االستجابة للطلب دون إبطاء ضمن االصول\n ّ اللبنانية\n ّ لحسن ممارسة مهامها .وعلى الجهات\n القانونية.\n يمكن ان يوجه الطلب مباشرة الى الموظف المختص على ان ُيعلم رؤساءه بذلك.\n في حال عدم االستجابة من قبل االدارة المعنية للهيئة مراجعة القضاء المختص بهذا الشأن.\n 10\n\f وصالحيات الهيئة\n ّ الباب الرابع :مهام\n المادة :18تعريف مهام الهيئة\nاالتفاقيات والمعاهدات الدولية\n ّ أ -تعمل الهيئة على مكافحة الفساد والوقاية منه وكشفه ،وعلى تطبيق\nمنضماً إليها ،وأداء المهام الخاصة المناطة بها المحددة في هذا القانون\n ّ ذات الصلة التي يكون لبنان\n وغيره من القوانين.\n ب -ب ٍ\n شكل خاص ،تُناط بالهيئة المهام التالية وفق أحكام هذا القانون:\n - 1تلّق ي الكشوفات التي تردها والمتعلقة بالفساد ،استقصاء جرائم الفساد ،ودرسها وإحالتها عند\n المختصة .\n ّ التأديبية والقضائية\n ّ االقتضاء إلى سائر الهيئات الرقابية و\n -2رصد وضع الفساد وكلفته وأسبابه وجهود مكافحته والوقاية منه في ضوء القوانين النافذة\n االتفاقيات الثنائية والمتعددة األطراف الملزمة ووضع التقارير الخاصة أو\n ّ والسياسات المعتمدة و\n الرسمية وعلى موقعها االلكتروني."}, {"o": 11, "l": "المادة 73", "b": "ّ الدورية في هذه الشؤون ونشرها في الجريدة\nعفوا أو بناء لطلب المراجع المختصة ،في التشريعات والمراسيم والقرارات ومشاريعها\n - 3إبداء الرأيً ،\n والسياسات واالستراتيجيات المتعلقة بمكافحة الفساد والوقاية منه.\n -4المساهمة في نشر ثقافة النزاهة في اإلدارات والمؤسسات العامة والمجتمع والمعارف الالزمة\n لمكافحة الفساد والوقاية منه.\n أيضا المهام التي تنيطها بها القوانين كافة باإلضافة الى المهام التالية:\n ج -تتولى الهيئة ً\n -1تلّق ي التصاريح عن الذمة المالية وحفظها وإدارتها والتدقيق بها وفق أحكام قانون اإلثراء غير\n المشروع.\n - 2حماية كاشفي الفساد وتحفيزهم وفق أحكام قانون حماية كاشفي الفساد.\n - 3استالم الشكاوى المتعلقة بعدم تطبيق قانون الحق في الوصول الى المعلومات والتحقيق فيها\n واصدار ق اررات بشأنها ،إبداء المشورة للسلطات المختصة حول تنفيذ القانون ووضع تقرير سنوي\n بشأنه ونشره ،والمشاركة في تثقيف المجتمع لترسيخ هذا الحق .\n د -تمارس الهيئة مهامها في إطار مبادئ الحوكمة الرشيدة وتتعاون مع اإلدارات والمؤسسات العامة\n وهيئات المجتمع المدني والقطاع الخاص واإلعالم ومع المنظمات اإلقليمية والدولية ونظرائها من\n الدول األخرى.\n 11\n\f الصالحيات الخاصة باالستقصاء واالحالة\n ّ الفصل األول :المهام و\n المادة :19صالحيات الهيئة االستقصائية\n أ -تتمتع الهيئة بالصالحيات التالية:\nبناء على ما تتلقاه من كشوفات ،ولها ،خالفًا ألي نص آخر ،أن\n استقصاء جرائم الفساد ،عفوا أو ً\nتطلب مساعدة الضابطة العدلية ومعاونيها لجهة الحصول على المعلومات المتوافرة لديها مع\n االحتفاظ بسريتها.\nإذا ارتأت الهيئة خالل االستقصاءات التي تقوم بها ّأنه من الضروري التحقيق في حسابات مصرفية\nال إلى \"هيئة التحقيق الخاصة\" المنصوص عليها في القانون المعجل\n توجه طلبًا معل ً\n معينة ،لها أن ّ\nصالحياتها"}, {"o": 12, "l": "المادة 73", "b": "ّ رقم 2015/44المتعلق بمكافحة تبييض األموال وتمويل االرهاب لتمارس هذه األخيرة\nالمنصوص عليها في القانون المذكور .في حال قررت هيئة التحقيق الخاصة رفع السرّية المصرفية\nيتم ذلك أيضًا لصالح الهيئة .تبّلغ \"هيئة التحقيق الخاصة\" الى الهيئة الوطنية\n عن الحسابات المعنيةّ ،\n لمكافحة الفساد في اسرع وقت ممكن.\nب -ل لهيئة أن تفوض بعض صالحياتها في كل حالة على حدة ،الى أحد اعضائها أو احد العاملين\n المختصين لديها.\nج -مع مراعاة أحكام قانون السرية المصرفية وخالفًا ألحكام"}, {"o": 13, "l": "المادة 25", "b": "المادة 25من قانون االجراءات\nالضريبية ،إن االستحصال على معلومات أو مستندات تطلبها الهيئة بمعرض عملها االستقصائي أو\nتوجهها الى الجهات غير القضائية واجبة التنفيذ ،تحت طائلة غرامة تتراوح ما بين عشرة أضعاف\nوعشرين ضعفًا من الحد األدنى الرسمي لألجور يحكم بها على الشخص المعني الممتنع عن تنفيذ\nالقرار أو على من يعيق هذا التنفيذ ،بعد إنذاره خطيًا من قبل الهيئة بوجوب التنفيذ خالل مهلة خمسة\n ّأيام .\n د -ال يحول تغريم الشخص المعني دون مالحقته جزائيًا أو تأديبياً في حال توافر شروط هذه\n المالحقة ،سيما وفق احكام"}, {"o": 14, "l": "المادة 371", "b": "المادة 371عقوبات.\n المادة :20التدابير االحترازية\n تتمتع الهيئة بالصفة والصالحية للطلب من الجهات المختصة اتخاذ جميع التدابير االحت ارزية\n المتاحة ومنها:\n 12\n\f -1الطلب من قاضي االمور المستعجلة اصدار قرار رجائي معلل بمنع المشكو منه من السفر لفترة\nبناء لطلب الهيئة لمرة واحدة في حال توافر اسباب جدية تبرر\n ال تتجاوز ثالثة أشهر ،يمكن تجديدها ً\n تبلغ الهيئة الق اررات الصادرة بهذا الشأن.\n ذلكّ .\n -2الطلب من قاضي االمور المستعجلة ضبط أموال االشخاص المشتبه بهم ،ومنع التصرف بها،\nووضع اشارة منع تصرف على األموال غير المنقولة أو المنقولة الخاضعة للتسجيل بقرار معلل\nبناء لطلب الهيئة لمرة واحدة في حال توافر اسباب جدية تبرر ذلك.\n ولفترة ثالثة اشهر يمكن تجديدها ً\n تبلغ الهيئة الق اررات الصادرة بهذا الشأن.\n ّ\nمن \"هيئة التحقيق الخاصة\" المنصوص عليها في القانون رقم 2015/44تاريخ -3الطلب\n( 2015/11/24مكافحة تبييض االموال وتمويل االرهاب) اتخاذ االجراءات االحت ارزية المتاحة بما\nفيها تجميد الحساب او الحسابات المصرفية العائدة للمشكـو منه ولسائر االشخاص المشتبه بهم وفقًا\n لألصول القانونية المرعية في هذا الصدد.\n المادة :21صالحيات اإلحالة\n أ -بنتيجة اعمال االستقصاء تتخذ الهيئة أي من الق اررات التالية:\n تبين انه ال يستدعي المالحقة القضائية أو التأديبية أو أي تدبير آخر.\n -1حفظ الملف اذا ّ\n -2اإلحالة إلى النيابة العامة المختصة التي عليها ان تطلع الهيئة على سير االستقصاء والتحقيق\nاللذين تقوم بهما ونتيجتهما ،وإذا قررت النيابة العامة حفظ الملف ،للهيئة أن تطلب منها التوسع في\n التحقيق.\n -3االدعاء مبا شرة أمام القضاء المختص للمطالبة بمعاقبة المرتكبين والحكم بااللتزامات المدنّية\nال في الق اررات الصادرة بهذا الشأن ضمن المهل المنصوص عليها\n لصالح الدولة .وللهيئة الطعن اصو ً\n قانونًا."}, {"o": 15, "l": "المادة 371", "b": "-4التقدم بالدعاوى والمراجعات الالزمة امام الجهات القضائية أو االدارية المختصة ،للمطالبة\nبإعادة الحال إلى ما كانت عليه واسترداد األموال والتعويضات ،نتيجة اعمال فساد ثبتت صحتها\n بقرار اداري او قضائي مبرم.\n 13\n\fب -تتمتع الهيئة ،في القضايا المتعّلقة بالفساد ،بجميع الحقوق والصالحيات المعطاة للدولة وللمدعي\n الشخصي في قوانين أصول المحاكمات المدنية والجزائية والتأديبية وذلك في جميع مراحل التحقيق\n والمحاكمة.\n ج -تعفى الهيئة من جميع الرسوم والسلفات والكفاالت القضائية والتأديبية.\n المادة :22موجب السرية\nأ -تعتبر سرّية االستقصاءات التي تقوم بها الهيئة والمعلومات التي تتوافر لديها بشأنها والمداوالت\n المتعّلقة بها ،ويعاقب كل شخص يقوم بإفشاء ٍّ\nأي منها بالحبس حتى سنتين وبغرامة تتراوح بين\nخمسة وعشرين ضعفًا من الحد االدنى الرسمي لألجور وخمسة وسبعين ضعفًا أو بإحدى هاتين\n العقوبتين.\nب -يعاقب بالحبس حتى ثالث سنوات وبغرامة تتراوح بين أربعين ضعفًا من الحد االدنى الرسمي\nلألجور ومئة وعشرة أضعاف أو بإحدى هاتين العقوبتين أي شخص يقوم بتسريب معلومات علم بها\n خالل عمله في الهيئة.\n ج -ال تحول هذه المالحقات دون اتخاذ الهيئة أية تدابير تأديبية تنص عليها انظمتها الداخلية.\n الفصل الثاني :الصالحيات الخاصة بالرصد والتقييم\n المادة :23الرصد والتقييم\n أ -رصد حاالت الفساد وتوثيقها ومتابعتها بجميع الوسائل المتاحة لوضع حد لإلفالت من العقاب.\nب -تقييم القوانين والمراسيم والق اررات اإلدارية والمذكرات والتعاميم كافة ،على ضوء معايير مكافحة\n الفساد والوقاية منه.\nج -رصد التقدم ا لمحرز في تنفيذ التشريعات والمراسيم والسياسات واالستراتيجيات المتعلقة بمكافحة\n الفساد والوقاية منه.\nد -ت قييم مخاطر الفساد في القطاع العام وفق المنهجيات العلمية وتوفير االقتراحات والتوصيات\n الالزمة لمكافحة الفساد والوقاية منه.\n 14"}, {"o": 16, "l": "المادة 371", "b": "الفصل الثالث :الصالحيات الخاصة بإبداء الرأي\n المادة :24التقارير\nأ .تصدر الهيئة تقارير سنوية تتعلق بنشاطها تتضمن على األقل معلومات حول آلية عملها بما فيها\nالتكاليف واالهداف والقواعد واالنجازات والصعوبات التي اعترضت سير عملها وحساباتها المدققة،\nكما السياسات العامة المعتمدة ومشاريعها التي ُن ِفذت والتي لم تُنفذ وأسباب ذلك وأية اقتراحات تساهم\nفي تطوير عملها .ترفع الهيئة هذا التقرير إلى مقام كل من رئاسة الجمهورية ورئاسة مجلس النواب\nورئاسة مجلس الوزراء والنواب والوزراء وتنشر نسخة عنه في الجريدة الرسمية وعلى الموقع\n االلكتروني الخاص بها.\nب -تصدر الهيئة تقارير خاصة عن وضع الفساد في لبنان وكلفته وأسبابه والتقدم المحرز في\nمكافحته والوقاية منه وال توصيات الكفيلة بتعزيز هذه الجهود ،على أن تصدر أول تقرير شامل في\nهذا الخصوص في نهاية العام االول من واليتها ويليه تقارير دورية كل ستة اشهر .ترفع الهيئة هذه\nالتقارير إلى مقام كل من رئاسة الجمهورية ورئاسة مجلس النواب ورئاسة مجلس الوزراء والنواب\nوالوزراء وترسل نسخة منها إلى رئيس مجلس القضاء األعلى ورئيس مجلس شورى الدولة ورئيس\n ديوان المحاسبة .وتنشر نسخة عنها في الجريدة الرسمية وعلى الموقع االلكتروني الخاص بها.\nج -تقديم المشورة في معرض وضع التقارير المتوجبة على الدولة اللبنانية بموجب اتفاقيات دولية او\n اقليمية ،واقتراح التوصيات المستقلة بشأنها.\nد -للهيئة ان ت حث اإلدارات المعنية على تقديم التقارير المتوجبة في األوقات المحددة لها وضمن\n األصول القانونية.\n الفصل الرابع :الصالحيات االستشارية\n المادة :25\nعفوا أو بناء لطلب في جميع التشريعات والمراسيم والق اررات ومشاريعها والسياسات\n أ -إبداء الرأيً ،\n المتَبعة في ما يتعلق بمكافحة الفساد والوقاية منه.\nب -اقتراح نصوص أنظمة األخالقيات وقواعد السلوك والمناقبية الواجب توافرها لدى الموظفين"}, {"o": 17, "l": "المادة 371", "b": "ومتابعة اقرارها وحسن تنفيذها والترويج لها.\n ج -تستشار الهيئة وجوبا في وضع االستراتيجية الوطنية لمكافحة الفساد والوقاية منه.\n 15\n\f الفصل الخامس :الصالحيات الخاصة بنشر الثقافة\n المادة :26\nأ -وضع الدراسا ت واالبحاث وإصدار التقارير والنشرات والمطبوعات المتخصصة في مجال تعزيز\n النزاهة ومكافحة الفساد والوقاية منه وإنشاء قاعدة معلومات.\nب -توعية الرأي العام حول أسب اب الفساد ونتائجه وسبل مكافحته والوقاية منه بجميع الوسائل\nالمتاحة ووضع برامج من أجل التثقيف والترويج للنزاهة خاص ًة من خالل المؤسسات التربوية\n والجامعية واإلعالمية وهيئات المجتمع المدني واألهلي.\nحث و ازرة التربية والتعليم العالي وسائر الهيئات التربوية العامة الرسمية والخاصة ،والتعاون\n جّ -\nمعها ،على تضمين برامجها التربوية موادًا نظرية وتطبيقية في مجال النزاهة ومكافحة الفساد والوقاية\n منه ،وعلى تطوير هذه المواد والوسائل التربوية المرتبطة بها.\nد -تنظيم المؤتمرات والندوات والدورات التدريبية لمختلف الهيئات الرسمية والخاصة في جميع\n المواضيع الداخلة في اختصاصها.\n وختامية\n ّ انتقالية\n ّ الباب الرابع :أحكام\n المادة :27دقائق التطبيق\nبناء على اقتراح وزير ن\n تحدد دقائق تطبيق هذا القانو عند االقتضاء بمراسيم تتخذ في مجلس الوزراء ً\n العدل عفواً أو بطلب من الهيئة.\n المادة :28أحكام ختامية\n يعمل بهذا القانون فور نشره في الجريدة الرسمية.\n 16\n\f األسباب الموجبة\nتعتبر مسألة مكافحة الفساد في صدارة المسائل التي تتجه الدولة العصرية الحريصة على -1\nوتتحول هذه المسألة إلى تحد يواجه الدول النامية التي ما إن تعقد\n ّ تعزيز الشفافية إلى التصدي لها،\nطور السياسي واالقتصادي واالجتماعي حتى تصطدم بما يعيق مسيرتها ،ومن\n العزم على مواكبة الت ّ\nويسهم في إشاعة\n يكبد االقتصاد الوطني كلفة باهظة ويناقض مفاهيم الحكم الصالح ُ\n ذلك الفساد الذي ّ"}, {"o": 18, "l": "المادة 371", "b": "ثقافة سلبية هي ثقافة انتهاج السبل الملتوية وزعزعة هيبة القانون في سبيل الكسب السريع المجرد\n من كل مشروعية.\nلم تقف المنظمات الدولية والدول الساعية إلى تعزيز دولة القانون مكتوفة األيدي إزاء ظاهرة -2\nالتحري عنه\n الفساد ،فواجهتها باتفاقيات وقوانين وتدابير شتى رمت إلى تحديد مفاهيم الفساد وإلى ّ\nومالحقة مرتكبيه والسعي الحثيث إلى منعه .ولكنها تباينت أحياناً في تعريفه ،وفي تحديد مدى\nشموله القطاعين العام والخاص على السواء ،وفي إدراج العقوبات المناسبة المقابلة لألفعال المرتكبة\nأو عدم إدراجها في القوانين الخاصة بمكافحة الفساد ،وفي مجاالت أخرى .ولكنها أجمعت على\nالتصدي لها بالشكل الذي يناسب كل دولة ،في مرحلة معينة\n ّ اإلقرار بخطورة هذه الظاهرة ،وبوجوب\n تطورها.\n من مراحل ّ\nال بد ،في هذا المجال ،من ذكر النص األهم واألشمل المتعلق بالموضوع ،وهو اتفاقية األمم -3\nالمتحدة لمكافحة الفساد ،التي أقرتها الجمعية العامة لألمم المتحدة بتاريخ 2003/10/31وأصبحت\nنافذة بتاريخ ، 2005/12/14وانضمت إليها دول عديدة أجنبية وعربية ،ووافق عليها مجلس الوزراء\nفي جلسته المنعقدة بتاريخ ،2006/6/15وصدقها مجلس النواب في جلسته المنعقدة بتاريخ\n .2008/10/8\nال عن محاسن االنضمام إلى اتفاقية األمم المتحدة،\n في ضوء ذلك ،بات من الضروري ،فض ً -4\nفي حال حصول ذلك ،أن يبادر لبنان إلى إيالء هاجس مكافحة الفساد اهتمامًا بالغًا ،مع اإلشارة إلى\nأن اإلقرار باستشراء الفساد في المجتمع اللبناني ،وفي القطاع العام على وجه التخصيص ،هو حافز\n من الحوافز الدافعة إلى التصدي له.\n 17\n\f إن أبرز ما تضمنه مشروع القانون هو اآلتي: -5\nاالقتصار ،في هذه المرحلة ،على معالجة الموضوع في القطاع العام ،دون القطاع الخاص، أ-\n نظ ًار لخطورة استشراء الفساد في القطاع العام.\n ضبط األفعال التي تعتبر فسادًا. ب-"}, {"o": 19, "l": "المادة 371", "b": "االمتناع عن وضع عقوبات مقابلة لألفعال المعتبرة من قبيل الفساد ،طالما أن لهذه األفعال ج-\nعقوباتها المناسبة في القوانين األخرى التي عالجتها ( من ذلك ،مثالً ،قانون العقوبات ،وقانون\n اإلثراء غير المشروع)...\nالنص على إنشاء هيئة مستقلة تسمى \" الهيئة الوطنية لمكافحة الفساد\" ،وعلى كيفية د-\nتشكيلها ،وعلى تمتعها بالشخصية المعنوية وباالستقالل اإلداري والمالي حرصًا على تعزيز\n حصانتها ،وسوى ذلك من القواعد المتعلقة بسالمة عملها.\nتمكنها من العمل على تدارك الفساد وكشفه وعلى\n إيالء الهيئة بعض المهام العامة التي ّ هـ -\nتعزيز النزاهة والشفافية في القطاع العام ،وعلى تعميم ثقافة مكافحة الفساد في المجتمع على العموم،\n وفي المؤسسات التربوية على الخصوص.\nومن هذه المهام منع استغالل أو عرقلة حق المواطن في تحقيق الخدمات العامة ،وإسداء المشورة\nإلى اإلدارات العامة باتخاذ كل التدابير الالزمة لمكافحة الفساد ومن بينها التشديد على وجوب توافر\n الجدارة لدى التعيين في الوظائف العامة ،واإلسهام في التعاون الدولي في مجال مكافحة الفساد.\nإلزام اإلدارات العامة بتزويد الهيئة بالمستندات والمعلومات التي تراها مفيدة لحسن ممارسة و-\n مهامها.\n إيالؤها صالحية التقدم بشكوى أمام النيابة العامة لدى تثبتها من وقوع أفعال فساد قد ّ\nتشكل ز-\n جرائم معاقبًا عليها ،باعتبارها مؤتمنة على مكافحة الفساد.\nوفي هذه الصالحية ما يسمح للهيئة بتحويل بعض مهامها من مرتبة التوصيات والمراقبة العامة إلى\n مرتبة التصدي الفعلي آلفة الفساد.\nلهذه األسباب جرى وضع اقتراح القانون المرفق آملين من المجلس النيابي الكريم مناقشته\n وإق ارره.\n 18"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (95,'قوانين','قانون مكافحة تبييض الأموال وتمويل الإرهاب - رقم 44 24 تشرين الثاني 2015','2015-11-24','https://www.ppa.gov.lb/ar/pages/details/95','{"https://admin.ppa.gov.lb/storage/listing-pages/files/9hLLg88RTBibn9nKYxmMMJHs3FvfdKI33QQc-1760211051.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/9hLLg88RTBibn9nKYxmMMJHs3FvfdKI33QQc-1760211051.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=95),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "٤٩١\n قانون رقم ٤٤تاريخ ٢٠١٥/١١/٢٤\n مكافحة تبييض االموال وتمويل االرھاب\n مادة وحيدة:\nصدق مشروع القانون الوارد بالمرسوم رقم ٨٢٠٠تاريخ ٢٤أيار ٢٠١٢ -\n)تعديل القانون رقم ٣١٨تاريخ ،٢٠٠١/٤/٢٠مكافحة تبييض الأموال( كما عدلته\n اللجنة الفرعية المنبثقة عن اللجان النيابية المشتركة ومجلس النواب.\n يعمل بهذا القانون فور نشره في الجريدة الرسمية. -\n بيروت ،في ٢٤تشرين الثاني ٢٠١٥\n صدر عن مجلس الوزراء\n رئيس مجلس الوزراء\n الإمضاء :تمام سلام\nق /س /ت /٢٠١٥-١٢-٣١\n\f ٤٩٢\n قانون رقم ٤٤تاريخ ٢٠١٥/١١/٢٤\n مكافحة تبييض االموال وتمويل االرھاب\n المادة الأولى:\nيقُصد بالأموال غير المشروعة ،بمفهوم هذا القانون ،الأصول المادية أو غير المادية ،المنقولة أو\nغير المنقولة بما فيها الوثائق أو المستندات القانونية التي تثبت حق ملكية تلك الأصول أو أية\nحصة فيها ،الناتجة عن ارتكاب أو محاولة ارتكاب معاقباً عليها أو من الاشتراك في أي من الجرائم\n الآتية ،سواء حصلت هذه الجرائم في لبنان أو خارجه:\n -١زراعة أو تصنيع او الاتجار غير المشروع بالمخدرات والمؤثرات العقلية وفقاً للقوانين اللبنانية.\n -٢المشاركة في جمعيات غير مشروعة بقصد ارتكاب الجنايات والجنح.\n -٣الإرهاب وفقاً لأحكام القوانين اللبنانية.\n -٤تمويل الإرهاب أو الأعمال الإرهابية والأعمال المرتبطة بها )السفر -التنظيم -التدريب-\n التجنيد (...أو تمويل الأفراد أو المنظمات الارهابية وفقاً لأحكام القوانين اللبنانية.\n -٥الاتجار غير المشروع بالأسلحة.\n -٦الخطف بقوة السلاح أو بأي وسيلة أخرى.\n -٧استغلال المعلومات المميزة ٕوافشاء الأسرار وعرقلة حرية البيوع بالمزايدة والمضاربات غير\n المشروعة.\n -٨الحض على الفجور والتعرض للأخلاق والآداب العامة عن طريق عصابات منظمة.\n -٩الفساد بما في ذلك الرشوة وصرف النفوذ والاختلاس واستثمار الوظيفة ٕواساءة استعمال\n السلطة والإثراء غير المشروع."}, {"o": 1, "l": null, "b": "-١٠السرقة ٕواساءة الائتمان والاختلاس.\n -١١الاحتيال بما فيها جرائم الافلاس الاحتيالي.\n -١٢تزوير المستندات والأسناد العامة والخاصة بما فيها الشيكات وبطاقات الائتمان على أنواعها\n وتزييف العملة والطوابع وأوراق التمغة.\n -١٣التهريب وفقاً لأحكام قانون الجمارك.\n -١٤تقليد السلع والغش في الاتجار بها.\n -١٥القرصنة الواقعة على الملاحة الجوية والبحرية.\n -١٦الاتجار بالبشر وتهريب المهاجرين.\n -١٧الاستغلال الجنسي بما في ذلك الاستغلال الجنسي للأطفال.\n -١٨جرائم البيئة.\n -١٩الابتزاز.\n -٢٠القتل.\n\f٤٩٣\n -٢١التهرب الضريبي وفقاً للقوانين اللبنانية.\n المادة الثانية:\n يعتبر تبييض أموال كل فعل ُيقصد منه:\n -١إخفاء المصدر الحقيقي للأموال غير المشروعة أو إعطاء تبرير كاذب لهذا المصدر ،بأي\n وسيلة كانت ،مع العلم بأن الأموال موضوع الفعل غير مشروعة.\n -٢تحويل الأموال أو نقلها ،أو استبدالها أو توظيفها لشراء أموال منقولة أو غير منقولة أو للقيام\nبعمليات مالية بغرض إخفاء أو تمويه مصدرها غير المشروع أو بقصد مساعدة أي شخص\nمتورط في ارتكاب أي من الجرائم المنصوص عنها في المادة الاولى على الإفلات من\n الملاحقة مع العلم بأن الأموال موضوع الفعل غير مشروعة.\nإن جريمة تبييض الأموال هي جريمة مستقلة ولا تستلزم الإدانة بجرم أصلي ،كما أن إدانة\nالفاعل بالجرم الأصلي لا يحول دون ملاحقته بجرم تبييض الأموال في حال وجود اختلاف\n بالعناصر الجرمية.\n المادة الثالثة:\n يعاقب كل من أقدم أو حاول الاقدام أو حرض أو سهل أو تدخل أو اشترك:\n -١في عمليات تبييض أموال بالحبس من ثلاث إلى سبع سنوات وبغرامة لا تزيد عن مثلي المبلغ\n موضوع عملية التبييض.\n -٢في عمليات تمويل الارهاب أو الأعمال المرتبطة بها بالعقوبات المنصوص عليها في المادة\n ٣١٦مكرر والمواد ٢١٢لغاية ٢٢٢ضمناً من قانون العقوبات.\n المادة الرابعة:"}, {"o": 2, "l": null, "b": "على المصارف والمؤسسات المالية وشركات الايجار التمويلي والمؤسسات التي تصدر وتروج\nبطاقات الايفاء أو الائتمان والمؤسسات التي تتعاطى التحاويل النقدية إلكترونياً ومؤسسات الصرافة\nوالشركات التي تتعاطى الوساطة المالية وهيئات الاستثمار الجماعي وأية مؤسسات تخضع لترخيص\nأو لرقابة مصرف لبنان التقيد بالموجبات المعددة أدناه وبالنصوص التنظيمية التي تصدر عن\n مصرف لبنان لغايات تطبيق أحكام هذا القانون:\n -١تطبيق إجراءات العناية الواجبة على العملاء الدائمين )سواء كانوا أشخاصاً طبيعيين أو\nمعنويين أو بنية قانونية خاصة( لجهة التحقق من هويتهم بالاستناد إلى وثائق أو معلومات أو\n بيانات موثوقة.\n -٢تطبيق إجراءات العناية الواجبة على العملاء العابرين لجهة التحقق من هويتهم إذا كانت\n العملية أو سلسلة العمليات المنفذة تفوق قيمتها المبلغ الذي يحدده مصرف لبنان.\nق /س /ت /٢٠١٥-١٢-٣١\n\f ٤٩٤\n -٣تحديد هوية صاحب الحق الاقتصادي واتخاذ الخطوات اللازمة للتحقق منها بالاستناد إلى\n وثائق أو معلومات أو بيانات موثوقة.\n -٤الاحتفاظ بصور عن المستندات المتعلقة بالعمليات كافة وبالمعلومات أو بالبيانات أو بصور\nعن الوثائق المتعلقة بهوية المتعاملين لمدة خمس سنوات على الأقل بعد إنجاز العمليات أو\n انتهاء علاقة التعامل ،أيهما أطول.\n -٥القيام بالمراقبة المستمرة ومراجعة علاقات التعامل.\n -٦تطبيق الاجراءات المنصوص عليها في البنود من ١الى ٥أعلاه على العملاء الدائمين\nالمصرح عنها والمتعلقة بالتعرف\n ّ والعابرين عند نشوء شك حول صحة أو ملاءمة المعلومات\nعليهم ،أو عند نشوء شك بتبييض أموال أو تمويل إرهاب ،وذلك بمعزل عن أي سقوف أو\n استثناءات تحد من تطبيق هذه الاجراءات.\n -٧الأخذ بالمؤشرات التي تدل على احتمال وجود عمليات تبييض للأموال أو تمويل إرهاب\n ومبادىء الحيطة والحذر لكشف العمليات المشبوهة.\n المادة الخامسة:"}, {"o": 3, "l": null, "b": "على المؤسسات غير الخاضعة لقانون سرية المصارف الصادر بتاريخ ١٩٥٦/٩/٣سيما شركات\nالتأمين ،ونوادي القمار ،وتجار ووسطاء العقارات ،وتجار السلع ذات القيمة المرتفعة )حلى ،أحجار\nكريمة ،ذهب ،تحف فنية ،آثار قديمة( ،مسك سجلات بالعمليـات الت ــي تفوق قيمتها مبلغ تحدده\nهيئة التحقيق الخاصة )\"الهيئة\"( ،المنشأة بموجب المادة السادسة من هذا القانون ،ويتوجب عليهم\nالتقيد بالموجبات المنصوص عليها في المادة الرابعة وبالنصوص التنظيمية وبالتوصيات التي\n تصدر عن \"الهيئة\" لغايات تطبيق أحكام هذا القانون.\nعلى المحاسبين المجازين وكتاب العدل تطبيق هذه الموجبات عند إعدادهم أو تنفيذهم لصالح\n عملائهم أي من الخدمات التالية:\n -بيع وشراء العقارات.\n -إدارة أموال العملاء المنقولة وغير المنقولة سيما عمليات تكوين الأموال وعمليات الاستثمار\n المشترك.\n -إدارة الحسابات المصرفية وحسابات الأوراق المالية.\n -تنظيم المساهمات الخاصة بإنشاء الشركات أو إدارتها.\n -إنشاء أو إدارة أشخاص معنويين أو أية بنية قانونية خاصة ،وبيع وشراء مؤسسات فردية أو\n شركات تجارية.\nأما المحامون فتسري عليهم ،عند قيامهم بالخدمات المبينة آنفاً ،نفس الموجبات المبينة أعلاه ،على\nأن تحدد أصول تطبيق هذه الموجبات بموجب آلية تضعها نقابتا المحامين في بيروت وط اربلس\n تأخذ بعين الاعتبار خصوصية مهنة المحاماة وأنظمتها.\n\f٤٩٥\n المادة السادسة:\nتنشأ لدى مصرف لبنان هيئة مستقلة ،ذات طابع قضائي ،تتمتع بالشخصية المعنوية ،غير خاضعة\n في ممارسة أعمالها لسلطة المصرف وتسمى فيما يلي \"هيئة التحقيق الخاصة\" أو \"الهيئة \".\n -١تتألف \"هيئة التحقيق الخاصة\" من:\n رئيساً * حاكم مصرف لبنان وفي حال تعذر حضوره ،من ينتدبه من بين نوابه\n * القاضي المعين في الهيئة المصرفية العليا ،وفي حال تعذر حضوره،\n قاض رديف يعينه مجلس القضاء الاعلى لمدة تعادل مدة تعيين\n عضواً القاضي الاصيل"}, {"o": 4, "l": null, "b": "* رئيس لجنة الرقابة على المصارف ،وفي حال تعذر حضوره ،من ينتدبه\n عضواً من بين أعضاء اللجنة المذكورة\n بناء على إنهاء\n * عضو أصيل وعضو رديف يعينهما مجلس الوزراء ً\n حاكم مصرف لبنان ،على أن تتوفر فيهما خبرة لا تقل عن ١٥سنة في\n عضواً مجال القانون المالي أو المصرفي\n -٢مهمة \"هيئة التحقيق الخاصة\":\n -تلقي الابلاغات وطلبات المساعدة ٕواجراء التحقيقات في العمليات التي يشتبه بأنها تشكل\nجرائم تبييض أموال أو جرائم تمويل إرهاب وتقرير مدى جدية الأدلة والقرائن على ارتكاب\nهذه الجرائم أو إحداها واتخاذ القرار المناسب بشأنها سيما التجميد الاحترازي المؤقت\nللحسابات و/أو للعمليات المشتبه بها وذلك لمدة أقصاها سنة قابلة للتمديد لستة اشهر\nاضافية ولمرة واحدة في ما خص طلبات المساعدة الواردة من الخارج ولمدة أقصاها ستة\nاشهر قابلة للتمديد لثلاثة اشهر اضافية ولمرة واحدة بالنسبة للابلاغات وطلبات المساعدة\n الواردة من الداخل.\n -التحقق من قيام المعنيين المشار إليهم في المادتين الرابعة والخامسة بالتقيد بالموجبات\nالمنصوص عليها في هذا القانون والنصوص التنظيمية الصادرة بالاستناد اليه باستثناء\nالمحامين والمحاسبين المجازين وكتاب العدل ومع مراعاة أحكام الفقرة الثانية من المادة\n السابعة عشرة من هذا القانون.\n -جمع وحفظ المعلومات الواردة من المعنيين المشار اليهم في المادتين الرابعة والخامسة\nوالمعلومات الواردة من السلطات الرسمية اللبنانية أو الاجنبية وأية معلومات أخرى مجمعة\n وتبادلها مع نظيراتها بصفتها المرجع الصالح والمركز الرسمي للقيام بذلك.\n -إصدار النصوص التنظيمية المتعلقة بتطبيق أحكام هذا القانون للمعنيين المشار إليهم في\n المادة الخامسة ٕواصدار توصيات للجهات المعنية كافة.\nق /س /ت /٢٠١٥-١٢-٣١\n\f ٤٩٦\n ُ -٣يحصر \"بالهيئة\" ،بعد إجراء التدقيق والتحليل اللازمين ،حق تقرير:"}, {"o": 5, "l": null, "b": "• التجميد النهائي للحسابات و/أو العمليات المعنية و/أو رفع السرية المصرفية لصالح\nالمراجع القضائية المختصة ولصالح الهيئة المصرفية العليا بشخص رئيسها عن الحسابات\n أو العمليات التي يشتبه بأنها تتعلق بتبييض أموال أو بتمويل إرهاب.\n• إبقاء الحسابات المشتبه بها قيد المتابعة ) (Traceableل ــ\"الهيئة\" الرجوع ،بشكل جزئي أو\n كلي ،عن أي قرار تتخذه وذلك في حال توفرت لديها معطيات جديدة بهذا الخصوص.\n -٤ل ــ\"الهيئة\" الحق:\nأ -بوضع إشارة على القيود والسجلات ،العائدة لأموال منقولة أو غير منقولة ،تفيد بأن هذه\nالأموال هي موضوع تحقيق من قبل \"الهيئة\" وتبقى هذه الاشارة قائمة لحين زوال أسباب\n الشبهات أو صدور قرار نهائي بشأنها،\nب -أن تطلب من النائب العام التمييزي اتخاذ إجراءات احت ارزية في ما يتعلق بالاموال\nالمنقولة وغير المنقولة التي لا يوجد بشأنها أية قيود أو سجلات بهدف تقييد التصرف\n بها وذلك لحين صدور قرار قضائي نهائي بشأنها،\nوذلك في حال الاشتباه بأن هذه الأموال تتعلق بتبييض أموال أو تمويل إرهاب ،و/أو طيلة فترة\nالتجميد الاحترازي المؤقت للحسابات و/أو للعمليات المشتبه بها كما هو منصوص عليه في\nالبند ) (٢من هذه المادة و/أو طيلة فترة التجميد النهائي لهذه الحسابات و/أو العمليات كما هو\n منصوص عليه في البند ) (٣من المادة نفسها.\n -٥لــ\"الهيئة\" أن تطلب من الاشخاص والجهات المعنية الرسمية والخاصة اتخاذ الاجراءات اللازمة\nلمنع التصرف بأموال منقولة أو غير منقولة عائدة للأسماء المدرجة أو التي تدرج على اللوائح\nالوطنية التي تصدرها السلطات اللبنانية المختصة أو أية لوائح أخرى تعممها بموضوع الارهاب\n وتمويل الارهاب والاعمال المرتبطة بهم.\n على الاشخاص والجهات المعنية الرسمية والخاصة أن تستجيب دون أي تأخير لهذا الطلب.\n -٦تجتمع \"الهيئة\" ،بدعوة من رئيسها ،مرتين في الشهر على الأقل وكلما دعت الحاجة ولا تكون"}, {"o": 6, "l": null, "b": "اجتماعاتها قانونية إلا بحضور ثلاثة أعضاء على الأقل.\n -٧تتخذ \"الهيئة\" ق ارراتها بأكثرية أصوات الأعضاء الحاضرين ٕواذا تعادلت الأصوات يكون صوت\n الرئيس مرجحاً.\n -٨تعين \"الهيئة\" أميناً عاماً لها ،على أن يكون متفرغاً للأعمال التي تكلفه بها وينفذ ق ارراتها\nويشرف مباشرة على المستخدمين لديها والمتعاقدين معها وعلى الاشخاص الذين تنتدبهم لمهمة\nمعينة ،دون أن يعتد تجاه أي منهم بأحكام القانون الصادر بتاريخ ١٩٥٦/٩/٣المتعلق بسرية\n المصارف.\n -٩يخضع أعضاء \"الهيئة\" والعاملون لديها والمتعاقدون معها والمنتدبون من قبلها لموجب الحفاظ\n على السرية.\n\f٤٩٧\n -١٠تضع \"الهيئة\" نظاماً لسير عملها ،ونظاماً للمستخدمين لديها والمتعاقدين معها الخاضعين\n للقانون الخاص.\n -١١يتحمل مصرف لبنان نفقات \"الهيئة\" والأجهزة التابعة لها من ضمن الموازنة التي تضعها على\n أن تحظى بموافقة المجلس المركزي لمصرف لبنان.\n المادة السابعة:\nعلى المعنيين المشار إليهم في المادتين الرابعة والخامسة من هذا القانون ،بمن فيهم المحاسبين\nالمجازين وكتاب العدل ،عند إعدادهم أو تنفيذهم معاملات لصالح عملائهم تتعلق بالأنشطة المعددة\nفي المادة الخامسة ،إبلاغ رئيس \"الهيئة\" فو اًر عن تفاصيل العمليات المنفذة أو التي جرت محاولة\n تنفيذها والتي يشتبهون بأنها تتعلق بتبييض أموال أو بتمويل إرهاب.\nأما المحامون فتسري عليهم الموجبات المبينة في الفقرة السابقة وفقاً لآلية تضعها نقابتا المحامين في\n بيروت وطرابلس وتأخذ بعين الاعتبار خصوصية مهنة المحاماة وأنظمتها.\nعلى المراقبين العاملين لدى لجنة الرقابة على المصارف إبلاغ رئيس \"الهيئة\" بواسطة رئيس اللجنة\nعن العمليات التي يطلعون عليها بمناسبة قيامهم بمهامهم والتي يشتبهون بأنها تتعلق بتبييض أموال\n أو بتمويل إرهاب.\nعلى مفوضي المراقبة لدى المعنيين بالمادة الرابعة من هذا القانون إبلاغ رئيس \"الهيئة\" فو اًر عن"}, {"o": 7, "l": null, "b": "تفاصيل العمليات التي يطلعون عليها بمناسبة قيامهم بعملهم والتي يشتبهون بأنها تخفي تبييض\n أموال أو تمويل إرهاب.\n المادة الثامنة:\n -١تجتمع \"الهيئة\" بعد تلقيها المعلومات من المعنيين المشار إليهم في المادة السابعة أعلاه أو بعد\n تلقيها المعلومات من السلطات الرسمية اللبنانية أو الأجنبية.\n -٢بعد تقييم وتحليل المعلومات المتوفرة عن الحالة المعروضة ،تتخذ \"الهيئة\" ق ار اًر إما بأخذ العلم\nأو بإجراء التحقيق اللازم بشأنها سيما من خلال التدقيق في الحسابات أو العمليات أو التحقق\nمن الاموال المشتبه بها .تقوم \"الهيئة\" بتحقيقاتها بواسطة من تنتدبه من أعضائها أو المسؤولين\nالمعنيين لديها أو بواسطة أمينها العام أو من تعينه من بين مفوضي المراقبة ويقوم كل من\nهؤلاء بمهامه شرط التقيد بالسرية ودون أن يعتّد تجاهه بأحكام القانون الصادر بتاريخ\n ١٩٥٦/٩/٣المتعلق بسرية المصارف.\n -٣وبعد استكمال أعمال التدقيق والتحليل ،تتخذ \"الهيئة\" ق ارراتها وفقاً لأحكام البنود ٢و ٣و ٤من\n المادة السادسة من هذا القانون.\nق /س /ت /٢٠١٥-١٢-٣١\n\f ٤٩٨\n -٤عند تقرير رفع السرية المصرفية عن الحسابات المعنية و/أو تجميدها بصورة نهائية و/أو\nتقرير طلب الاستمرار بمنع التصرف بالأموال ،ترسل \"الهيئة\" نسخة طبق الأصل عن قرارها\nإلى كل من النائب العام التمييزي ٕوالى الهيئة المصرفية العليا بشخص رئيسها ٕوالى صاحب\nالعلاقة ٕوالى الجهات المعنية بهذا القرار ،محلية أو خارجية ،وذلك إما مباشرةً ٕواما بواسطة\n المرجع الذي وردت المعلومات عن طريقه.\n -٥في حال قرر النائب العام لدى محكمة التمييز حفظ الأوراق بقضايا تبييض الأموال وعدم\nالسير بالدعوى العامة تعتبر الحسابات المجمدة وسائر الأموال محررة ويجري إبلاغ قرار\nالحفظ إلى \"هيئة التحقيق الخاصة\" ،ولا يجوز لــ\"الهيئة\" أن تبقي على رفع السرية المصرفية"}, {"o": 8, "l": null, "b": "والتجميد ومنع التصرف بالأموال وعليها أن تبلغ فو اًر المصارف والجهات المعنية الأخرى\nبذلك .إذا تبين لها قبل تنفيذها القرار وجود أدلة أو قرائن جديدة من شأنها أن تبرر الإبقاء\nعلى التجميد ومنع التصرف بالأموال ورفع السرية المصرفية فعلى \"الهيئة\" أن ترسل تقري اًر\nمعللاً مرفقاً بالمستندات المتضمنة هذه الأدلة أو القرائن إلى النائب العام لدى محكمة التمييز\n الذي له أن يقرر عند الاقتضاء التوسع بالتحقيق على ضوء هذه المعطيات.\n -٦وفي حال صدور قرار مبرم بمنع المحاكمة عن قاضي التحقيق أو عن الهيئة الاتهامية كما\nفي حال صدور حكم أو قرار مبرم بإبطال التعقبات أو بالبراءة بحق أصحاب الحسابات\nالمجمدة والاموال الممنوع التصرف بها تصبح الحسابات والاموال محررة ويجري إبلاغ نسخة\nعن الحكم أو القرار الصادر الى \"هيئة التحقيق الخاصة\" بواسطة النائب العام لدى محكمة\nالتمييز وعلى \"الهيئة\" أن تبلغ الحكم أو القرار الى المصارف والجهات المعنية الاخرى بذلك،\nولا يعود لــ\"الهيئة\" أن ترفع السرية المصرفية مجدداً أو أن تعيد التجميد ومنع التصرف بشأن\nالحسابات والاموال المشمولة بقرار منع المحاكمة إلا عن طريق اتباع الآلية المنصوص عليها\n في المادة ١٢٧من قانون أصول المحاكمات الجزائية.\n المادة التاسعة:\nلرئيس \"الهيئة\" أو لمن ينتدبه أن يخابر مباشرةً السلطات اللبنانية أو الأجنبية كافة )القضائية -\nالإدارية -المالية والأمنية( بغية طلب معلومات أو الاطلاع على تفاصيل التحقيقات التي تكون قد\nأجرتها حول الأمور المرتبطة أو المتصلة بتحقيقات تجريها \"الهيئة\" .وعلى السلطات اللبنانية المعنية\n أن تستجيب لطلب المعلومات فو اًر دون الاعتداد تجاه \"الهيئة\" بأي موجب سرية.\n المادة العاشرة:\nلرئيس \"الهيئة\" أو لمن ينتدبه الطلب مباشرةً من المعنيين المشار إليهم في المادتين الرابعة والخامسة"}, {"o": 9, "l": null, "b": "تزويد \"الهيئة\" بالمستندات والمعلومات الضرورية كافة للقيام بمهامها وعلى هؤلاء أن يستجيبوا لهذا\n الطلب ضمن مهلة معقولة.\n\f٤٩٩\n المادة الحادية عشرة:\nيحظر على الملزمين بموجب الإبلاغ وعلى أعضاء مجلس إدارتهم ومسؤوليهم وموظفيهم الإفادة أو\nالإيحاء لأي كان عن تقديم أو النية بتقديم إبلاغ عن عملية مشبوهة أو معلومات ذات صلة لـ \"هيئة\nالتحقيق الخاصة\" ،أو عن قيام \"الهيئة بالاستعلام عن العملاء أو بالتدقيق في عملياتهم أو في\n حساباتهم.\n المادة الثانية عشرة:\nيتمتع كل من رئيس \"الهيئة\" وأعضائها والعاملين لديها أو المنتدبين من قبلها بالحصانة ضمن نطاق\nعملهم بحيث لا يجوز الادعاء عليهم أو على أحدهم أو ملاحقتهم بأي مسؤولية مدنية أو جزائية\nتتعلقان بقيام أي منهم بمهامه ومنها الجرائم المنصوص عليها في القانون الصادر بتاريخ\n ١٩٥٦/٩/٣والمتعلق بسرية المصارف إلا بحال إفشاء السرية المصرفية.\nكما يتمتع المعنيون المشار إليهم في المادتين الرابعة والخامسة والعاملون لديهم والمراقبون العاملون\nلدى لجنة الرقابة على المصارف ومفوضو المراقبة بالحصانة عينها عندما يقومون بتنفيذ الموجبات\nالملقاة على عاتقهم بموجب هذا القانون أو بموجب ق اررات \"الهيئة\" وخاصةً عند قيامهم بحسن نية\n بإبلاغ \"الهيئة\" عن تفاصيل العمليات التي يشتبهون بأنها تتعلق بتبييض أموال أو بتمويل إرهاب.\n المادة الثالثة عشرة:\nحدها الأقصى مئة مليون ليرة لبنانية أو بإحدى هاتين\n يعاقب بالحبس من شهرين إلى سنة وبغرامة ّ\nالعقوبتين كل من يخالف أحكام المواد الرابعة والخامسة والسابعة والعاشرة والحادية عشرة من هذا\n القانون.\nل ـ \"الهيئة\" أن توجه تنبيهاً إلى الجهات التي تخالف أحكام النصوص التنظيمية الصادرة لتطبيق\nأحكام هذا القانون ،وأن تطلب تقارير منتظمة منها عن التدابير التي تتخذها تصحيحاً لأوضاعها،"}, {"o": 10, "l": null, "b": "كما يمكنها إحالة هذه الجهات إلى الهيئة المصرفية العليا فيما خص المعنيين في المادة الرابعة\n ومراسلة سلطات الوصاية أو الإشراف بشأن المخالفين المعنيين في المادة الخامسة.\nللهيئة المصرفية العليا فرض غرامة مالية على المحالين إليها لعدم تقيدهم بالنصوص التنظيمية\nالصادرة لتطبيق أحكام هذا القانون على أن لا تزيد عن مايتي ضعف الحد الادنى الرسمي للأجور،\n وتستوفى هذه الغرامات لصالح مصرف لبنان.\nولا يحول ما تقدم دون تطبيق العقوبات الادارية المنصوص عليها في المادة ٢٠٨من قانون النقد\nوالتسليف بالنسبة للمعنيين المشار إليهم في المادة الرابعة ،كما لا يحول دون تطبيق العقوبات\n المنصوص عليها في سائر القوانين أو الأنظمة بالنسبة للمعنيين المشار إليهم في المادة الخامسة.\n المادة الرابعة عشرة:\nق /س /ت /٢٠١٥-١٢-٣١\n\f ٥٠٠\nتصادر لمصلحة الدولة الأموال المنقولة وغير المنقولة التي يثبت بموجب حكم نهائي أنها متعلقة\nمحصلة بنتيجتها ما لم يثبت أصحابها ،قضائياً ،حقوقهم\n ّ بجريمة تبييض أموال أو تمويل إرهاب أو\n الشرعية بشأنها.\nيمكن اقتسام الأموال التي جرت مصادرتها مع دول أخرى عندما تكون المصادرة ناتجة بصورة\nمنسق جرى بين السلطات اللبنانية المعنية وبين الجهة أو الجهات\n مباشرة عن تحقيقات أو تعاون ّ\n الأجنبية المعنية.\n المادة الخامسة عشرة:\nتلغى التحفظات المنصوص عليها في الفقرات /-٤-٣-٢/من المادة الاولى من القانون رقم ٤٢٦\nتاريخ ١٩٩٥/٥/١٥المتعلق بالاجازة بإبرام اتفاقية الامم المتحدة لمكافحة الاتجار غير المشروع\nبالمخدرات والمؤثرات العقلية لسنة ،١٩٨٨كما تلغى المادة ١٣٢من القانون رقم ٦٧٣تاريخ\n ١٩٩٨/٣/١٦المتعلق بالمخدرات والمؤثرات العقلية والسلائف.\n المادة السادسة عشرة:\nلا يعتد ،فور نفاذ هذا القانون ،بجميع الاحكام المخالفة أو التي لا تأتلف مع مضمونه ولا سيما تلك"}, {"o": 11, "l": null, "b": "الواردة في قانون سرية المصارف الصادر بتاريخ ١٩٥٦/٩/٣وفي القانون رقم ٦٧٣تاريخ\n ١٩٩٨/٣/١٦المتعلق بالمخدرات والمؤثرات العقلية والسلائف.\n المادة السابعة عشرة) :أحكام ختامية(\nعلى مفوضي مراقبة المصارف والمؤسسات المالية وسائر الشركات والمؤسسات المنصوص عليها\nفي المادة الرابعة من هذا القانون التحقق من تقيد هذه الشركات والمؤسسات كافة بأحكام هذا القانون\n وبالنصوص التنظيمية الصادرة بالاستناد إليه ٕوابلاغ رئيس \"الهيئة\" عن أية مخالفة بهذا الشأن.\nتناط بو ازرة العدل وبكل من نقابتي المحامين في بيروت وطرابلس ونقابة المحاسبين المجازين مهمة\nالتحقق من تقيد كتاب العدل والمحامين والمحاسبين المجازين ،كل فيما خصه ،بالإجراءات\n المنصوص عليها في هذا القانون وفي النصوص التنظيمية الصادرة بالاستناد إليه.\n المادة الثامنة عشرة:\n يعمل بهذا القانون فور نشره في الجريدة الرسمية."}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (96,'قوانين','القانون رقم 324 تاريخ 12/2/2024 - زيادة رسم الطابع المالي','2024-02-12','https://www.ppa.gov.lb/ar/pages/details/96','{"https://admin.ppa.gov.lb/storage/listing-pages/files/TLPh8wJTIpqDmEHA5YT0unxjLhKbZvIW1BuI-1760211256.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/TLPh8wJTIpqDmEHA5YT0unxjLhKbZvIW1BuI-1760211256.pdf"}','ocr') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=96),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "لاله لجشمهورتة ١ للجنايّة\nا بي 0-7 0 عر\n0 « لا هبه\n1 0 0\n7 الم بير جه ا\n- 3 7 و\nالسنة 5 5 ١ ملحق العدد لا - الخميس في ١١ شباط ٠١174\n- م\nالصتم الال\n- له - اث د *« .< ئ\nموانين ست م اتتراعيت: ناسيم ارات\nتُقبّل طلبّات الإشتراك خلال شَهِرَي تشرين الثاني وكانون الأول\nتُقبَل الإعلاناث الرسميّة والخاصة قبل أسبُوع مِنْ موعد النشر\nالإشتراك السنوي\nداخل لبنان\nالقطاع الخاص 19,000.٠0٠٠ ليرة لبنانية خارج لبنان 01,20٠,0٠٠ ليرة لبنانية\nالقطاع العام ,7,08٠:٠:,:0٠٠ ليرة لبنانية شمن العدد ٠٠٠6,٠5\"89؟ ليرة لبنانية\n7754/9/١8 ا/ الجريدة الرسمية فهرس ملحق العدد ٠\nفهرس العدد\nقوانين صفحة\n١ ٠7١515 الموازنة العامة للعام 7٠١74 شباط سنة ١١ قانون رقم 75\" تاريخ\n0 الل هلدا\nهد\nبيروت - شارع عمر منيمته\n١1/444441 هاتف:\n١1/409351 فاكس:\nرمف مصعدعم!. بيصيو\n0 الجريدة الرسمية ملحق العدد 7١74/7/١8 /\nالمادة السادسة والستون: تعديل التعرفات الواردة في الجداول الملحفة بالمرسسوم\nالاشتراعي رقم /1” تاريخ 1171/1/0 (قانون رسم الطايع المالي!\nتعدل التعرفات الواردة في الجداول الملحقة بالمرسوم الاشتراعي رفم 7 تاربخ\n7/0 (قابدون رسم الطابع المالي):\nجدول رقم ١\n- في الصبكوك والكدابات المبادرة عن الدولة والبلدياث والمؤوسسات العامة والمقدمة\nإلها\nأولا: في الرخص والإجازات:\nأتخضع الرخص والإجازات الصادرة عن الدولة والبلديات؛ أيا كان شكلهاء لرسم\nالطابع المالي المقطوع أو النسبي وفقا للتعريفات التالية:.\nالرقم\nالمنسلسل نوع الرخصبة أو الإجازة تعرفة الرسم ل.ل.\n١ رخصة امتياز(بما في ذلك دفاتر الشروط المتعلقة بالامتياز) ...,...,”4\n1 رخصة تلقيب عن منجم أو استثمار ملنجم تعبرء مركم\n3 رخصة تأسيس شركة مغفلة فلدرء و4\nبمعدل واحد بالمئة من قيمة البدل السنوي لرخصة إشفال الاملاك العمومية,\nعلى ان لاتقل قيمسة الرسم عن خمسة عشر مليون لهرة لبنانية"}, {"o": 1, "l": null, "b": ".00..٠( ل.ل)عن كل ترخيص ولا تزيد عن خمسماية مليون ليرة لبنانية\n(تتتيمنءرءءة لبل).\nيؤدي هذا الرسم سلفاً وقبل إعطاء الرخصة عن السنة الأولى ولاحقا خلال مبلة\nخمسة ايام عمل من تاربخ كل تجديد صريح أو ضمني. وتطبق هذه المعدلات اعتبارا\nمن سنة 7074.\nتخفض الى النصف قيمة الرسم اذا كانت رخصة الإشغال تتناول مرور خطوط جر\nمياه الشرب والري او خطوط تصريف المياه المبتذلة في الاملاك العمومية التي تمر\nفها خطوط سكك الحديد. شرط ان لا يقل الرسم عن الحد الادنى المذكور اعلاه.\n3 الجريدة الرسمية - ملحق العدد / - 7174/1/١6\nلا الإفادات والبيانات الي يقدمها الافراد إلى الإدارات العامة والبلديات\nبناء على طلبها.\nثالثا: في الطلبات والعرائض والاستدعاءات:\nأ- تخضع الطلبات والعرائض والاستدعاءات التي تقدم لدوائر الدولة أو البلديات\nأو المؤسسات العامة لرسم الطابع المالي المقطوع وفقا للتعريفات التالية:\nالرقم المتسلسل2 نوع الشهادة أو الإفادة أو البيان تعرفة الرسم ل.ل.\nف طلب تسجيل محضر عقد لدى الدوائر العقاربة لتعرفة؟\nلزنا الطلب أو التعهد المقدم للاشتراك في الصفقة العمومية\n(مناقصة عمومية وغيرها). يشمل هذا الرسم كافة المستندات\nيفنا كل طلب آخر أو عريضة أو استدعاء أو عرض اسعار ١٠٠,١٠لءل.\nب - نعفى من الرسم الطلبات و العرائض والاستدعاءات التالي بهانها:\nارفنا الطلبات والعرائض والاستدعاءات الواردة بالبريد من الخارج.\nنا طلبات الانخراط أو التطوع في الجيش.\nإزانا الاستدعاءات والعرائض المتضمنة شكاوى أو مراجعات أو معلومات\nبحق إحدى الإدارات العامة أو البلديات أو المصالح المستقلة\nوالمؤسسات العامة التابعة للدولة أو للبلديات أو بحق أحد الأشخاص\n. الحقيقيين أو المعنوبين المنتمين إلى هذه الهيئات سواء أقدمت إلى\nالتفتيش المركزي أو إلى الإدارات المعنية.\nرابعا: في المعاملات القضائية:"}, {"o": 2, "l": null, "b": "أ- تخضع المعاملات القضائية التالي بيانهاء عندما لا تتضمن ذكر أي مبلغ من المال»\nلرسم الطابع المالي المقطوع وفقا للتعريفات التالية:\nالرقم المنتسلسل نوع المعاملات القضائية تعرفة الرسم ل.ل.\nعا كل صبك تسوبة أو اتفاق أو تحكيم أو صلح وافقي\nيقدم للمحاكم 000"}]$j$::jsonb) e;
